TYPES = {
    'sqlite': {'ID': 'INTEGER PRIMARY KEY AUTOINCREMENT', 'K': 'TEXT', 'T': 'TEXT',
               'B': 'TEXT', 'N': 'REAL', 'I': 'INTEGER'},
    # Compared byte for byte, as SQLite and PostgreSQL compare (1.0.44): with
    # the default collation novák@x.cz was novak@x.cz, and one person's
    # token was written over another's.
    'mariadb': {'ID': 'BIGINT AUTO_INCREMENT PRIMARY KEY', 'K': 'VARCHAR(190) COLLATE utf8mb4_bin',
                'T': 'TEXT', 'B': 'MEDIUMTEXT', 'N': 'DOUBLE', 'I': 'BIGINT'},
    'postgres': {'ID': 'BIGSERIAL PRIMARY KEY', 'K': 'TEXT', 'T': 'TEXT', 'B': 'TEXT',
                 'N': 'DOUBLE PRECISION', 'I': 'BIGINT'},
}

TABLES = [name for name, _ in SCHEMA]


class RawSql(str):
    """A statement sent as it is, with no parameters (1.0.94): a conninfo
    with the password inside it, where a `?` of the password became `%s`
    and CREATE SUBSCRIPTION failed with "tuple index out of range"."""


def _qmarks(sql):
    """`?` as `%s`, for the two engines whose drivers want that. Nothing in
    the SQL this program writes has a `?` or a `%` inside a quoted string."""
    return sql.replace('%', '%%').replace('?', '%s')


def db_tls_args(engine, mode=None, ca=None):
    """How the connection to the database server is encrypted (1.0.33):
    as the driver decides, unless `db_tls` says otherwise. The settings of
    the connection asked for, not the running ones (1.0.36): a change was
    tried with the old values, then the service could not start."""
    mode = str((CONFIG.get('db_tls') if mode is None else mode) or '')
    ca = str((CONFIG.get('db_tls_ca') if ca is None else ca) or '')
    if not mode:
        return {}
    if engine == 'postgres':
        out = {'sslmode': mode}
        if ca:
            out['sslrootcert'] = ca
        return out
    import ssl as _ssl
    if mode == 'require':
        return {'ssl': {'check_hostname': False, 'verify_mode': _ssl.CERT_NONE}}
    # verify_mode True, not CERT_REQUIRED (1.0.36): pymysql took the number
    # with no authority file for "check nothing". True with no file checks
    # against the system's authorities.
    got = {'ssl': {'check_hostname': mode == 'verify-full', 'verify_mode': True}}
    if ca:
        got['ssl']['ca'] = ca
    return got


DB_RESTORING = threading.Event()


class _Lane(object):
    """One connection to the database and the lock it is used under."""
    __slots__ = ('conn', 'lock', 'in_tx', 'failed_until', 'down_until', 'down_said')

    def __init__(self):
        self.conn = None
        self.lock = threading.RLock()
        self.in_tx = False
        self.failed_until = 0.0
        self.down_until = 0.0
        self.down_said = ''


class Db(object):
    """One database, of whichever engine."""

    # How long one statement may take, and one wait for a row another holds
    # (1.0.101): with no limit, one statement waiting on a lock or on a line
    # that dropped held every request behind this connection's lock - every
    # sign-in of the whole server, the health check too. 0: none.
    STATEMENT_S = 120
    LOCK_S = 10

    def __init__(self, engine='sqlite', host='', port=0, name='otp', user='otp',
                 password='', timeout=10, path=None, tls=None, tls_ca=None, statement_s=None):
        self.engine = engine if engine in TYPES else 'sqlite'
        self.statement_s = self.STATEMENT_S if statement_s is None else int(statement_s)
        # [fd00::1] as written in a URL is fd00::1 to the drivers. (1.0.36)
        host = str(host or '').strip()
        if host.startswith('[') and host.endswith(']'):
            host = host[1:-1]
        self.host, self.port, self.name = host, int(port or 0), name
        self.user, self.password, self.timeout = user, password, int(timeout or 10)
        self.path = Path(path) if path else DB_FILE
        self.tls, self.tls_ca = tls, tls_ca
        self._lanes = {'main': _Lane()}
        self._lanes_lock = threading.Lock()
        self._tls = threading.local()
        self.lanes_on = False
        self.connect()

    # ---- lanes: RADIUS on a connection of its own (1.0.136) ---------------------
    # Every statement goes one at a time through a connection and its lock.
    # With one connection for everything, a slow page (the overview over a
    # month, uncached: 29 s under load) held every sign-in behind it, and the
    # VPN timed out. Once the daemon turns lanes on, the RADIUS threads (their
    # names start with 'radius') have their own connection and lock: nothing
    # the pages, the console, the backups or the ticks do waits in front of
    # them. A lane whose connection cannot be made falls back to the main one
    # for a minute.
    LANE_RETRY_S = 60
    RADIUS_LANES = 4

    def _lane(self):
        """The lane of this thread's statement: the one pinned for the call it
        is in, or the one it would take."""
        pinned = getattr(self._tls, 'lane', None)
        return pinned if pinned is not None else self._pick()

    def _pick(self):
        """Which lane a new call of this thread takes - chosen once, before
        any lock is taken, and kept for the whole call (1.0.136): chosen again
        at each look, one call took one lane's lock and used the other's
        connection, and two RADIUS threads could wait on each other for good."""
        main = self._lanes['main']
        if not self.lanes_on or not threading.current_thread().name.startswith('radius'):
            return main
        # A copy put back holds the database whole, RADIUS too (as before
        # the lanes): its writes would collide with the rows coming in.
        # This database's own (1.0.139): a move loading another database sent
        # RADIUS off its lane for the whole of it.
        if getattr(self, 'restoring', False):
            return main
        # A few connections for RADIUS on a database server (1.0.150): one,
        # every sign-in waited for the one before it there - about 125 a
        # second, and one row held by a lock stopped them all. Each RADIUS
        # thread keeps to one of them. SQLite writes one at a time anyway.
        key = 'radius'
        if self.engine != 'sqlite' and self.RADIUS_LANES > 1:
            tail = threading.current_thread().name.rsplit('-', 1)[-1]
            key = 'radius%d' % ((int(tail) if tail.isdigit() else 0) % self.RADIUS_LANES)
        lane = self._lanes.get(key)
        if lane is None:
            with self._lanes_lock:
                lane = self._lanes.setdefault(key, _Lane())
        if lane.conn is None and time.time() < lane.failed_until:
            return main
        return lane

    @contextlib.contextmanager
    def _pinned(self):
        """The call's lane pinned for everything under it. A RADIUS lane
        without a connection makes one first - under its own lock only;
        when it cannot while the main one works, the call goes to the main
        lane (and RADIUS with it for a minute). Never the main lock taken
        while the RADIUS lane's is held."""
        if getattr(self._tls, 'lane', None) is not None:
            yield
            return
        lane = self._pick()
        main = self._lanes['main']
        if lane is not main and lane.conn is None:
            with lane.lock:
                if lane.conn is None:
                    if time.time() < lane.failed_until:
                        lane = main
                    elif time.time() < lane.down_until:
                        # Tried a moment ago and the database did not answer:
                        # said at once, and no minute on the main lane for it
                        # (a restart of the database is not a lane gone bad).
                        raise DbError(lane.down_said or 'the database is not answering')
                    else:
                        self._tls.lane = lane
                        try:
                            self.connect()
                        except DbError:
                            # The database away altogether: said so, as the
                            # main lane would (no minute on the main lane).
                            if main.conn is None or time.time() < main.down_until:
                                raise
                            lane.failed_until = time.time() + self.LANE_RETRY_S
                            log_sparing('db-lane', 'RADIUS shares the main database '
                                        'connection for a minute: its own could not be made',
                                        'warn')
                            lane = main
                        finally:
                            self._tls.lane = None
        self._tls.lane = lane
        try:
            yield
        finally:
            self._tls.lane = None

    @property
    def lock(self):
        return self._lane().lock

    @property
    def conn(self):
        return self._lane().conn

    @conn.setter
    def conn(self, value):
        self._lane().conn = value

    @property
    def in_tx(self):
        return self._lane().in_tx

    @in_tx.setter
    def in_tx(self, value):
        self._lane().in_tx = value

    # ---- the connection ----------------------------------------------------
    def where(self):
        if self.engine == 'sqlite':
            return str(self.path)
        return '%s@%s:%s/%s' % (self.user, self.host or 'localhost',
                                self.port or {'mariadb': 3306, 'postgres': 5432}[self.engine],
                                self.name)

    # A database that does not answer is tried again at most every 2 s
    # (1.0.136): each try waits up to db_timeout_s under the lane's lock, and
    # every request behind it waited for its own try in turn - one request
    # answered every 10 s, the queue full, the health check stuck.
    DOWN_RETRY_S = 2

    def connect(self):
        lane = self._lane()
        with lane.lock:
            if lane.conn is None and time.time() < lane.down_until:
                raise DbError(lane.down_said or 'the database is not answering')
            try:
                self._connect()
                lane.down_until = 0.0
            except DbError as e:
                lane.down_until = time.time() + self.DOWN_RETRY_S
                lane.down_said = str(e)
                raise

    # RADIUS's own lane waits less (1.0.149): a VPN gives up on an answer in
    # 5 to 15 s; a statement there that waited 120 s held every sign-in behind
    # it. Past these it is no answer, and the VPN asks the other node.
    RADIUS_STATEMENT_S = 5
    RADIUS_LOCK_S = 2
    RADIUS_SQLITE_BUSY_S = 3

    def _connect(self):
        quick = self._lane() is not self._lanes['main']
        stmt_s = min(self.statement_s or self.RADIUS_STATEMENT_S, self.RADIUS_STATEMENT_S) \
            if quick else self.statement_s
        lock_s = self.RADIUS_LOCK_S if quick else self.LOCK_S
        with self.lock:
            if self.engine == 'sqlite':
                self.path.parent.mkdir(parents=True, exist_ok=True)
                # RADIUS's lane waits 3 s for the file (1.0.149), not 30: past
                # that, no answer, and the VPN asks the other node.
                conn = sqlite3.connect(str(self.path), check_same_thread=False,
                                       isolation_level=None,
                                       timeout=self.RADIUS_SQLITE_BUSY_S if quick else 30)
                conn.row_factory = sqlite3.Row
                try:
                    conn.execute('PRAGMA journal_mode=WAL')
                    conn.execute('PRAGMA synchronous=NORMAL')
                    # The log of the file shrunk back after a big write (1.0.149):
                    # it stayed at its largest - 1.3 GB beside a 1 GB database.
                    conn.execute('PRAGMA journal_size_limit=67108864')
                except sqlite3.Error:
                    pass
                self.conn = conn
            elif self.engine == 'mariadb':
                try:
                    import pymysql
                    import pymysql.cursors
                except ImportError:
                    raise DbError('MariaDB is chosen and its Python driver is not installed: '
                                  'dnf install python3-PyMySQL (or pip install PyMySQL)')
                try:
                    self.conn = pymysql.connect(
                        host=self.host or 'localhost', port=self.port or 3306,
                        user=self.user, password=self.password, database=self.name,
                        charset='utf8mb4', autocommit=True,
                        connect_timeout=self.timeout,
                        # A line that drops without a word no longer holds
                        # every request behind the lock for hours (1.0.57).
                        read_timeout=(stmt_s + 4) if quick else (
                            max(30, self.statement_s + 10) if self.statement_s else 300),
                        write_timeout=60,
                        cursorclass=pymysql.cursors.DictCursor,
                        **db_tls_args('mariadb', self.tls, self.tls_ca))
                except Exception as e:
                    raise DbError('MariaDB at %s could not be reached: %s' % (self.where(), e))
                for sql in ('SET SESSION innodb_lock_wait_timeout = %d' % lock_s,
                            'SET SESSION max_statement_time = %d' % stmt_s):
                    try:
                        with self.conn.cursor() as cur:
                            cur.execute(sql)
                    except Exception:                   # noqa: BLE001
                        pass            # MySQL, or an older MariaDB: without it
            else:
                try:
                    import psycopg2
                    import psycopg2.extras
                except ImportError:
                    raise DbError('PostgreSQL is chosen and its Python driver is not installed: '
                                  'dnf install python3-psycopg2 (or pip install psycopg2-binary)')
                try:
                    self.conn = psycopg2.connect(
                        host=self.host or 'localhost', port=self.port or 5432,
                        user=self.user, password=self.password, dbname=self.name,
                        connect_timeout=self.timeout,
                        # TCP keepalives (1.0.57): a connection lost in a
                        # failover or a firewall is found dead in ~20 s, not
                        # when the kernel gives up, with every request
                        # waiting behind it.
                        keepalives=1, keepalives_idle=10, keepalives_interval=3,
                        keepalives_count=3,
                        # ...and a line that drops while a statement is out:
                        # given up after 30 s, not the kernel's 15 min.
                        tcp_user_timeout=10000 if quick else 30000,
                        options='-c lock_timeout=%d -c statement_timeout=%d' % (
                            lock_s * 1000, stmt_s * 1000),
                        **db_tls_args('postgres', self.tls, self.tls_ca))
                    self.conn.autocommit = True
                    self.conn.set_client_encoding('UTF8')
                except Exception as e:
                    raise DbError('PostgreSQL at %s could not be reached: %s' % (self.where(), e))

    def close(self, lane_only=False):
        """Every lane's connection closed - or, from within a statement that
        lost its own, only the current lane's."""
        lanes = [self._lane()] if lane_only else list(self._lanes.values())
        for lane in lanes:
            with lane.lock:
                try:
                    if lane.conn:
                        lane.conn.close()
                except Exception:
                    pass
                lane.conn = None

    # ---- asking --------------------------------------------------------------
    def _run(self, sql, args, fetch):
        if self.engine == 'sqlite':
            cur = self.conn.execute(sql, tuple(args or ()))
            rows = [dict(r) for r in cur.fetchall()] if fetch else None
            return rows, cur.rowcount, cur.lastrowid
        if self.engine == 'mariadb':
            cur = self.conn.cursor()
            try:
                if isinstance(sql, RawSql):
                    cur.execute(str(sql))
                else:
                    cur.execute(_qmarks(sql), tuple(args or ()))
                rows = [dict(r) for r in cur.fetchall()] if fetch else None
                return rows, cur.rowcount, cur.lastrowid
            finally:
                cur.close()
        import psycopg2.extras
        cur = self.conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        try:
            # PostgreSQL takes no NUL in a text (1.0.59): a RADIUS name with
            # one in it broke the request, and its write-down, every time.
            if isinstance(sql, RawSql):
                cur.execute(str(sql))
            else:
                cur.execute(_qmarks(sql), tuple(a.replace('\x00', '\ufffd')
                                                if isinstance(a, str) and '\x00' in a else a
                                                for a in (args or ())))
            rows = [dict(r) for r in cur.fetchall()] if (fetch or cur.description) else None
            return rows, cur.rowcount, rows[0].get('id') if (rows and not fetch) else None
        finally:
            cur.close()

    def _gone(self, e):
        """Whether an error is the server having gone away, which one new
        connection mends."""
        said = str(e).lower()
        return any(w in said for w in ('gone away', 'lost connection', 'server closed',
                                       'connection already closed', 'terminating connection',
                                       'broken pipe', 'connection reset', 'not connected',
                                       'interfaceerror', 'cursor already closed',
                                       'connection has been closed',
                                       'connection is closed', 'ssl connection has been closed',
                                       # tcp_user_timeout ran out (1.0.149): the line dropped
                                       'could not receive data', 'connection timed out',
                                       'server closed the connection'))

    def query(self, sql, args=(), fetch=True):
        # While this node is rebuilt from the other, nothing but the rebuild
        # writes (1.0.57): a sign-in or a code written meanwhile took an id
        # the copy then met again, and replication stopped on it for good.
        reb = globals().get('HA_REBUILDING')
        with self._pinned(), self.lock:
            # Looked at under the lock (1.0.59): a write that had passed the
            # look and was waiting for the lock went in after the tables were
            # emptied. Every kind of write, not only the three words.
            if reb is not None and reb.is_set() and \
                    globals().get('HA_REBUILDER', [None])[0] != threading.get_ident() and \
                    sql.lstrip()[:8].upper().startswith(('INSERT', 'UPDATE', 'DELETE', 'WITH',
                                                         'TRUNCATE', 'REPLACE')):
                raise DbError('this node is being rebuilt from the other one; try again in a '
                              'few minutes')
            if self.conn is None:
                self.connect()
            try:
                return self._run(sql, args, fetch)
            except Exception as e:
                if self.engine == 'sqlite' or not (self._gone(e) or
                                                   type(e).__name__ == 'InterfaceError'):
                    raise
                if getattr(self, 'in_tx', False):
                    # Half a transaction is gone with the connection; going on
                    # on a new one would commit the second half alone. (1.0.36)
                    self.close(lane_only=True)
                    raise
                # A connection that is gone is made again - and the statement
                # run once more only where that cannot do it twice (1.0.33): a
                # read, or a connection known closed before it was sent. A
                # write whose answer was lost may have been done; done again,
                # a code just used up would be refused as used.
                self.close(lane_only=True)
                self.connect()
                said = str(e).lower()
                unsent = type(e).__name__ == 'InterfaceError' or any(
                    w in said for w in ('connection already closed', 'not connected',
                                        'cursor already closed'))
                if sql.lstrip()[:6].upper() in ('SELECT', 'WITH  ', 'SHOW  ') or \
                        sql.lstrip().upper().startswith(('SELECT', 'WITH', 'SHOW', 'EXPLAIN')) \
                        or unsent:
                    return self._run(sql, args, fetch)
                raise

    def rows(self, sql, args=()):
        return self.query(sql, args, True)[0]

    def row(self, sql, args=()):
        got = self.rows(sql, args)
        return got[0] if got else None

    def value(self, sql, args=(), default=None):
        got = self.row(sql, args)
        if not got:
            return default
        return list(got.values())[0]

    def run(self, sql, args=()):
        return self.query(sql, args, False)[1]

    def upsert(self, table, key, row):
        """One row by its primary key, made or changed in one statement
        (1.0.57): SELECT-then-INSERT on two nodes at once put the same key in
        twice, and replication then stopped on the duplicate."""
        keys = list(row.keys())
        cols = ', '.join(keys)
        marks = ', '.join('?' for _ in keys)
        rest = [k for k in keys if k != key]
        if self.engine == 'mariadb':
            sql = 'INSERT INTO %s (%s) VALUES (%s) ON DUPLICATE KEY UPDATE %s' % (
                table, cols, marks, ', '.join('%s = VALUES(%s)' % (k, k) for k in rest))
        else:
            sql = 'INSERT INTO %s (%s) VALUES (%s) ON CONFLICT (%s) DO UPDATE SET %s' % (
                table, cols, marks, key, ', '.join('%s = excluded.%s' % (k, k) for k in rest))
        return self.run(sql, tuple(row[k] for k in keys))

    def insert(self, table, row):
        keys = list(row.keys())
        sql = 'INSERT INTO %s (%s) VALUES (%s)' % (table, ', '.join(keys),
                                                   ', '.join('?' for _ in keys))
        if self.engine == 'postgres':
            sql += ' RETURNING id'
            return self.query(sql, [row[k] for k in keys], False)[2]
        return self.query(sql, [row[k] for k in keys], False)[2]

    def update(self, table, ident, row):
        keys = list(row.keys())
        if not keys:
            return 0
        return self.run('UPDATE %s SET %s WHERE id = ?' % (table, ', '.join('%s = ?' % k
                                                                          for k in keys)),
                        [row[k] for k in keys] + [ident])

    @contextlib.contextmanager
    def unlimited(self):
        """No time limit on this connection's statements meanwhile: the
        tables made and the columns added at start - an index made on a
        large log may take minutes."""
        if self.engine == 'sqlite' or not self.statement_s:
            yield
            return
        off, on = (('SET statement_timeout = 0', 'SET statement_timeout = %d' % (
            self.statement_s * 1000)) if self.engine == 'postgres' else (
            'SET SESSION max_statement_time = 0',
            'SET SESSION max_statement_time = %d' % self.statement_s))
        with self.lock:
            try:
                self.run(RawSql(off))
            except Exception:                           # noqa: BLE001
                pass
            try:
                yield
            finally:
                try:
                    self.run(RawSql(on))
                except Exception:                       # noqa: BLE001
                    pass

    # ---- the tables ----------------------------------------------------------
    def make_tables(self):
        with self.unlimited():
            self._make_tables()

    def _make_tables(self):
        types = TYPES[self.engine]
        for _name, ddl in SCHEMA:
            sql = ddl.format(**types)
            if self.engine == 'mariadb':
                sql += ' DEFAULT CHARSET=utf8mb4'
            self.run(sql)
        for sql in INDEXES:
            if self.engine == 'mariadb':
                # MariaDB knows IF NOT EXISTS on an index from 10.1.4 on, and
                # wants a length on nothing here: every indexed column is a
                # VARCHAR(190) or a number.
                try:
                    self.run(sql)
                except Exception as e:
                    if 'Duplicate key name' in str(e):
                        continue
                    # MySQL has no IF NOT EXISTS on an index (1.0.44).
                    if '1064' not in str(e) and 'syntax' not in str(e).lower():
                        raise
                    try:
                        self.run(sql.replace(' IF NOT EXISTS', ''))
                    except Exception as e2:
                        if 'Duplicate key name' not in str(e2):
                            raise
            else:
                self.run(sql)
        if self.engine == 'mariadb':
            self._mariadb_bin_names()
        self.add_missing_columns()
        if self.engine == 'postgres':
            self._pg_keep_used()
        if self.value('SELECT v FROM meta WHERE k = ?', ('schema',)) is None:
            self.run('INSERT INTO meta (k, v) VALUES (?, ?)', ('schema', str(SCHEMA_VERSION)))

    def _pg_keep_used(self):
        """Two replicating nodes (1.0.57, 1.0.59). Logical replication sends
        the whole row with every UPDATE, so the other node's later write of
        anything in a token's row carried its older values of everything
        else over the newer ones: a code or a recovery code used up came
        back, a token switched off came back on, a lockout was lost, new
        recovery codes never got across. Each group of a token's columns -
        the key, the state, the lockout, the recovery codes - now carries the
        time it was last changed on the node that changed it, and where a row
        comes in from the other node the newer of each group is kept; the
        last code step only ever goes up, and recovery codes of the same
        issue used on either node stay used.

        A row made on both nodes under the same name (1.0.59) - a token
        enrolled on each at once, a meta key both wrote first - stopped
        replication for good on the duplicate. Where one comes in that is
        already here, the same one of the two is kept on both nodes."""
        try:
            self.run("""CREATE OR REPLACE FUNCTION otp_codes(t text) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path FROM CURRENT
AS $f$ SELECT COALESCE(NULLIF($1, ''), '[]')::jsonb $f$""")
            # The schema it is made in kept with each function (1.0.59): the
            # replication's apply worker runs with an empty search_path, and
            # "meta" or otp_codes() were not found there - replication stopped.
            self.run("""CREATE OR REPLACE FUNCTION otp_keep_used() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE
  now_ double precision := extract(epoch FROM clock_timestamp());
  same_key boolean;
BEGIN
  IF current_setting('session_replication_role') <> 'replica' THEN
    IF TG_OP = 'INSERT' THEN
      NEW.key_at := COALESCE(NEW.key_at, now_);
      NEW.state_at := COALESCE(NEW.state_at, now_);
      NEW.lock_at := COALESCE(NEW.lock_at, now_);
      NEW.scratch_at := COALESCE(NEW.scratch_at, now_);
      RETURN NEW;
    END IF;
    IF NEW.secret IS DISTINCT FROM OLD.secret
       OR NEW.pending_secret IS DISTINCT FROM OLD.pending_secret
       OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.dest IS DISTINCT FROM OLD.dest THEN
      NEW.key_at := now_;
    END IF;
    IF NEW.state IS DISTINCT FROM OLD.state THEN
      NEW.state_at := now_;
    END IF;
    IF NEW.failures IS DISTINCT FROM OLD.failures
       OR NEW.locked_until IS DISTINCT FROM OLD.locked_until
       OR NEW.fail_times IS DISTINCT FROM OLD.fail_times THEN
      NEW.lock_at := now_;
    END IF;
    BEGIN
      -- Issued (a code that was not there before), not merely used.
      IF NEW.scratch IS DISTINCT FROM OLD.scratch
         AND NOT (otp_codes(OLD.scratch) @> otp_codes(NEW.scratch)) THEN
        NEW.scratch_at := now_;
      END IF;
    EXCEPTION WHEN others THEN
      NEW.scratch_at := now_;
    END;
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  END IF;
  IF NEW.key_at IS NULL AND NEW.state_at IS NULL AND NEW.lock_at IS NULL
     AND NEW.scratch_at IS NULL THEN
    -- From a node still on a version before these times (a rolling
    -- upgrade, 1.0.62): taken as it comes, as then, and the code step
    -- never goes down.
    IF NEW.secret IS NOT DISTINCT FROM OLD.secret THEN
      NEW.last_step := GREATEST(COALESCE(NEW.last_step, 0), COALESCE(OLD.last_step, 0));
    END IF;
    RETURN NEW;
  END IF;
  same_key := NEW.secret IS NOT DISTINCT FROM OLD.secret;
  IF COALESCE(NEW.key_at, 0) < COALESCE(OLD.key_at, 0) THEN
    NEW.secret := OLD.secret; NEW.digits := OLD.digits; NEW.period := OLD.period;
    NEW.algorithm := OLD.algorithm; NEW.issuer := OLD.issuer; NEW.label := OLD.label;
    NEW.pending_secret := OLD.pending_secret; NEW.pending_scratch := OLD.pending_scratch;
    NEW.pending_at := OLD.pending_at; NEW.pending_by := OLD.pending_by;
    NEW.created := OLD.created; NEW.created_by := OLD.created_by;
    NEW.activated := OLD.activated;
    NEW.kind := OLD.kind; NEW.dest := OLD.dest;     -- how codes go, with the key (1.0.76)
    NEW.last_step := CASE WHEN same_key
                          THEN GREATEST(COALESCE(NEW.last_step, 0), COALESCE(OLD.last_step, 0))
                          ELSE OLD.last_step END;
    NEW.key_at := OLD.key_at;
  ELSIF NEW.secret IS NOT DISTINCT FROM OLD.secret THEN
    NEW.last_step := GREATEST(COALESCE(NEW.last_step, 0), COALESCE(OLD.last_step, 0));
  END IF;
  IF COALESCE(NEW.state_at, 0) < COALESCE(OLD.state_at, 0) THEN
    NEW.state := OLD.state; NEW.state_at := OLD.state_at;
  END IF;
  IF COALESCE(NEW.lock_at, 0) < COALESCE(OLD.lock_at, 0) THEN
    NEW.failures := OLD.failures; NEW.fail_times := OLD.fail_times;
    NEW.locked_until := OLD.locked_until; NEW.lock_at := OLD.lock_at;
  END IF;
  BEGIN
    IF COALESCE(NEW.scratch_at, 0) < COALESCE(OLD.scratch_at, 0) THEN
      NEW.scratch := OLD.scratch; NEW.scratch_sealed := OLD.scratch_sealed;
      NEW.scratch_left := OLD.scratch_left; NEW.scratch_at := OLD.scratch_at;
    ELSIF COALESCE(NEW.scratch_at, 0) = COALESCE(OLD.scratch_at, 0)
          AND NEW.scratch IS DISTINCT FROM OLD.scratch THEN
      -- The same issue: what was used on either node stays used.
      IF COALESCE(OLD.scratch_left, 0) < COALESCE(NEW.scratch_left, 0) THEN
        NEW.scratch_sealed := OLD.scratch_sealed;
      END IF;
      NEW.scratch := (SELECT COALESCE(jsonb_agg(e), '[]'::jsonb)::text
                        FROM jsonb_array_elements(otp_codes(NEW.scratch)) e
                       WHERE otp_codes(OLD.scratch) @> jsonb_build_array(e));
      NEW.scratch_left := jsonb_array_length(NEW.scratch::jsonb);
    END IF;
  EXCEPTION WHEN others THEN NULL;
  END;
  RETURN NEW;
END $f$""")
            self.run("""CREATE OR REPLACE FUNCTION otp_same_key() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE
  col text := TG_ARGV[0];
  key text;
  here text;
  came text;
BEGIN
  IF current_setting('session_replication_role') <> 'replica' THEN
    RETURN NEW;
  END IF;
  key := row_to_json(NEW) ->> col;
  EXECUTE format('SELECT row_to_json(t)::text FROM %I.%I t WHERE %I = $1',
                 TG_TABLE_SCHEMA, TG_TABLE_NAME, col) INTO here USING key;
  IF here IS NULL THEN
    RETURN NEW;
  END IF;
  came := row_to_json(NEW)::text;
  -- Byte order on both nodes (1.0.94): under a language's collation the
  -- two could pick different winners and stay different for good.
  IF came COLLATE "C" > here COLLATE "C" THEN
    EXECUTE format('DELETE FROM %I.%I WHERE %I = $1', TG_TABLE_SCHEMA, TG_TABLE_NAME, col)
       USING key;
    RETURN NEW;
  END IF;
  RETURN NULL;
END $f$""")
            if not self.value("SELECT 1 FROM pg_trigger WHERE tgname = 'otp_keep_used' AND "
                              "tgrelid = 'tokens'::regclass"):
                self.run('CREATE TRIGGER otp_keep_used BEFORE UPDATE ON tokens '
                         'FOR EACH ROW EXECUTE FUNCTION otp_keep_used()')
            if not self.value("SELECT 1 FROM pg_trigger WHERE tgname = 'otp_keep_made' AND "
                              "tgrelid = 'tokens'::regclass"):
                self.run('CREATE TRIGGER otp_keep_made BEFORE INSERT ON tokens '
                         'FOR EACH ROW EXECUTE FUNCTION otp_keep_used()')
            self.run('ALTER TABLE tokens ENABLE ALWAYS TRIGGER otp_keep_used')
            self.run('ALTER TABLE tokens ENABLE ALWAYS TRIGGER otp_keep_made')
            for table, col in (('tokens', 'name'), ('accounts', 'name'), ('clients', 'name'),
                               ('realms', 'name'), ('directories', 'name'), ('meta', 'k'),
                               ('settings', 'k'), ('sessions', 'token_hash')):
                trg = 'otp_same_%s' % table
                if not self.value("SELECT 1 FROM pg_trigger WHERE tgname = ? AND "
                                  "tgrelid = ?::regclass", (trg, table)):
                    # The name sorts after otp_keep_made: that one fills the
                    # times first.
                    self.run("CREATE TRIGGER %s BEFORE INSERT ON %s FOR EACH ROW EXECUTE "
                             "FUNCTION otp_same_key('%s')" % (trg, table, col))
                self.run('ALTER TABLE %s ENABLE ALWAYS TRIGGER %s' % (table, trg))
        except Exception as e:                          # noqa: BLE001
            log('the guard of used codes between two nodes could not be put in: %s'
                % str(e).split('\n')[0], 'warn')

    def _mariadb_bin_names(self):
        """Tables made before 1.0.44 compared names ignoring case and
        accents: their VARCHAR columns made byte for byte, once."""
        try:
            rows = self.rows("SELECT TABLE_NAME AS t, COLUMN_NAME AS c, IS_NULLABLE AS n, "
                             "CHARACTER_MAXIMUM_LENGTH AS l FROM information_schema.COLUMNS "
                             "WHERE TABLE_SCHEMA = DATABASE() AND DATA_TYPE = 'varchar' "
                             "AND COLLATION_NAME <> 'utf8mb4_bin'")
        except Exception as e:                          # noqa: BLE001
            log('the names could not be checked for their collation: %s' % e, 'warn')
            return
        for r in rows:
            r = {k.lower(): v for k, v in r.items()}
            if r['t'] not in TABLES:
                continue
            try:
                self.run('ALTER TABLE %s MODIFY %s VARCHAR(%d) CHARACTER SET utf8mb4 '
                         'COLLATE utf8mb4_bin%s' % (r['t'], r['c'], int(r['l'] or 190),
                                                    ' NOT NULL' if r['n'] == 'NO' else ''))
            except Exception as e:                      # noqa: BLE001
                log('%s.%s stays compared without case: %s' % (r['t'], r['c'], e), 'warn')

    def tables(self):
        """The tables that are there, whatever made them."""
        if self.engine == 'sqlite':
            return [r['name'] for r in self.rows(
                "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%'")]
        if self.engine == 'mariadb':
            return [list(r.values())[0] for r in self.rows(
                'SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE()')]
        return [r['tablename'] for r in self.rows(
            "SELECT tablename FROM pg_tables WHERE schemaname = current_schema()")]

    def insert_many(self, table, keys, rows):
        """Many rows at once, in one transaction - a copy of a million rows
        is minutes this way and hours a row at a time."""
        if not rows:
            return 0
        sql = 'INSERT INTO %s (%s) VALUES (%s)' % (table, ', '.join(keys),
                                                   ', '.join('?' for _ in keys))
        with self._pinned(), self.lock:
            if self.conn is None:
                self.connect()
            if self.engine == 'sqlite' and getattr(self, 'in_tx', False):
                self.conn.executemany(sql, rows)
            elif self.engine == 'sqlite':
                self.conn.execute('BEGIN')
                try:
                    self.conn.executemany(sql, rows)
                    self.conn.execute('COMMIT')
                except Exception:
                    self.conn.execute('ROLLBACK')
                    raise
            elif self.engine == 'mariadb':
                cur = self.conn.cursor()
                try:
                    cur.executemany(_qmarks(sql), rows)
                finally:
                    cur.close()
            else:
                import psycopg2.extras
                cur = self.conn.cursor()
                try:
                    # No NUL in a text here either (1.0.94): an old SQLite
                    # row with one stopped the whole move to PostgreSQL.
                    rows = [tuple(a.replace('\x00', '\ufffd') if isinstance(a, str) and '\x00' in a
                                  else a for a in r) for r in rows]
                    psycopg2.extras.execute_batch(cur, _qmarks(sql), rows, page_size=500)
                finally:
                    cur.close()
        return len(rows)

    def columns(self, table):
        if self.engine == 'sqlite':
            return [r['name'] for r in self.rows('PRAGMA table_info(%s)' % table)]
        if self.engine == 'mariadb':
            return [r.get('COLUMN_NAME') or r.get('column_name') for r in self.rows(
                'SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = '
                'DATABASE() AND TABLE_NAME = ?', (table,))]
        return [r['column_name'] for r in self.rows(
            'SELECT column_name FROM information_schema.columns WHERE table_name = ? '
            'AND table_schema = current_schema()', (table,))]

    def add_missing_columns(self):
        with self.unlimited():
            return self._add_missing_columns()

    def _add_missing_columns(self):
        """A column added in a later version, added to a database made by an
        earlier one. Read off the CREATE statements above, so there is one
        place a column is declared."""
        types = TYPES[self.engine]
        for name, ddl in SCHEMA:
            have = set(c.lower() for c in self.columns(name))
            body = ddl.format(**types).split('(', 1)[1].rsplit(')', 1)[0]
            for piece in re.split(r',\s*(?=[a-z_]+ )', body):
                piece = piece.strip()
                col = piece.split(' ', 1)[0].lower()
                if not col or col in have or col == 'id':
                    continue
                kind = piece.split(' ', 2)[1] if ' ' in piece else 'TEXT'
                kind = re.sub(r'\s*(NOT NULL|UNIQUE|PRIMARY KEY).*$', '', piece.split(' ', 1)[1])
                try:
                    self.run('ALTER TABLE %s ADD COLUMN %s %s' % (name, col, kind))
                except Exception as e:
                    log('could not add the column %s.%s: %s' % (name, col, e), 'warn')

    def size(self):
        try:
            if self.engine == 'sqlite':
                return sum(os.path.getsize(str(self.path) + s) for s in ('', '-wal')
                           if os.path.exists(str(self.path) + s))
            if self.engine == 'mariadb':
                return int(self.value(
                    'SELECT SUM(data_length + index_length) FROM information_schema.TABLES '
                    'WHERE table_schema = DATABASE()') or 0)
            return int(self.value('SELECT pg_database_size(current_database())') or 0)
        except Exception:
            return 0

    def version(self):
        try:
            if self.engine == 'sqlite':
                return 'SQLite ' + sqlite3.sqlite_version
            if self.engine == 'mariadb':
                return 'MariaDB ' + str(self.value('SELECT VERSION()'))
            return str(self.value('SELECT version()')).split(' on ')[0]
        except Exception as e:
            return '? (%s)' % e


def open_db(conf=None):
    """The database the settings name."""
    c = conf or CONFIG
    return Db(c.get('db_engine') or 'sqlite', c.get('db_host') or '', c.get('db_port') or 0,
              c.get('db_name') or 'otp', c.get('db_user') or 'otp', c.get('db_password') or '',
              c.get('db_timeout_s') or 10, tls=c.get('db_tls') or '',
              tls_ca=c.get('db_tls_ca') or '')


# ---------------------------------------------------------------------------
# A copy of everything, in a shape any of the three engines takes back
# ---------------------------------------------------------------------------
def machine_info():
    """The machine a copy was made on (1.0.63): its config.json - the
    database it opens, its name, its place in a cluster - with the
    password left out, and where it is. Only to be read: a copy put back
    never writes it, as the file belongs to the machine and not to the data."""
    try:
        with open(str(CONFIG_FILE), encoding='utf-8') as f:
            raw = json.load(f)
        if not isinstance(raw, dict):
            raw = {}
    except (OSError, ValueError):
        raw = {k: FILE_CONFIG.get(k) for k in (FILE_KEYS or ())}
    conf = {k: ('(set - not kept in the copy)' if (k in SECRET_KEYS or 'password' in k) and v
                else v) for k, v in sorted(raw.items())}
    out = {'config_file': str(CONFIG_FILE), 'config': conf, 'host': socket.getfqdn()}
    try:
        out['node'] = node_name()
    except Exception:                                   # noqa: BLE001
        pass
    for k in ('ha_mode', 'ha_slot', 'ha_peer', 'db_engine', 'db_host', 'db_port', 'db_name'):
        out.setdefault('in_use', {})[k] = CONFIG.get(k)
    if not out['in_use'].get('db_port'):
        # 0 is "the engine's own" (1.0.66): said as the number it is.
        out['in_use']['db_port'] = {'postgres': 5432, 'mariadb': 3306}.get(
            CONFIG.get('db_engine'), 0)
    return out


DAEMON_DB = [None]       # the daemon's own database, once it runs (1.0.150)


def dump_tables(db, out, tables=None, child=False):
    """Every row of every table, as JSON a line, gzipped. The first line says
    what it is; each table starts with a line naming it."""
    if not child and tables is None and db is DAEMON_DB[0]:
        return _dump_tables_child(out)
    import gzip
    # A file already open may be given (1.0.101): root writing into a
    # folder the service's account can write opens it itself, never by name.
    with gzip.open(out if hasattr(out, 'write') else str(out), 'wt', encoding='utf-8') as f:
        f.write(json.dumps({'otp': __version__, 'schema': SCHEMA_VERSION,
                            'made': time.time(), 'engine': db.engine,
                            'machine': machine_info()}, default=str) + '\n')
        for table in (tables or TABLES):
            f.write(json.dumps({'table': table}) + '\n')
            last = 0
            while True:
                if table in ('meta', 'settings'):
                    # Not the pieces of an uploaded package (1.0.57): up to
                    # 90 MB read whole into memory with every copy.
                    rows = (db.rows("SELECT * FROM meta WHERE k NOT LIKE 'upgrade:piece:%'")
                            if table == 'meta' else db.rows('SELECT * FROM settings')) \
                        if last == 0 else []
                    last = 1
                else:
                    rows = db.rows('SELECT * FROM %s WHERE id > ? ORDER BY id LIMIT 2000'
                                   % table, (last,))
                    if rows:
                        last = rows[-1]['id']
                for r in rows:
                    f.write(json.dumps(r, default=str) + '\n')
                if not rows or table in ('meta', 'settings'):
                    break
    return out


def _dump_tables_child(out):
    """dump_tables of the daemon's database by `otp --dump-copy`, a process of
    its own (1.0.150): in the daemon, the minutes of a big copy held Python's
    one lock against RADIUS - a third fewer sign-ins answered meanwhile."""
    opened = not hasattr(out, 'write')
    f = open(str(out), 'wb') if opened else out
    try:
        try:
            f.flush()
        except (OSError, ValueError):
            pass
        env = dict(os.environ)
        r = subprocess.run([sys.executable, '-I', os.path.abspath(__file__), '--dump-copy'],
                           stdout=f.fileno(), stderr=subprocess.PIPE, env=env,
                           timeout=6 * 3600)
        if r.returncode != 0:
            raise DbError('the copy could not be made: %s'
                          % r.stderr.decode('utf-8', 'replace').strip()[-300:])
    finally:
        if opened:
            f.close()
    return out


def load_tables(db, src, keep_logs=True, say=None):
    """Put a copy made by `dump_tables` back, over whatever is there.
    `say(table, done)` hears how far it has got, a batch at a time."""
    import gzip
    db.make_tables()
    # All of it or none of it (1.0.33): a copy that broke off half-way left
    # the tokens empty, and everybody locked out. The database is held for
    # the whole of it - a restore is not something done while people sign in.
    DB_RESTORING.set()
    db.restoring = True
    try:
        return _load_tables_held(db, src, keep_logs, say, gzip)
    finally:
        db.restoring = False
        DB_RESTORING.clear()


def _load_tables_held(db, src, keep_logs, say, gzip):
    # RADIUS's own lane waits for it too (1.0.136): DB_RESTORING sends its
    # statements to the main lane, whose lock this holds.
    with db.lock:
        if db.conn is None:
            db.connect()
        db.run('START TRANSACTION' if db.engine == 'mariadb' else 'BEGIN')
        db.in_tx = True
        try:
            counts = _load_tables(db, src, keep_logs, say, gzip)
            db.in_tx = False
            db.run('COMMIT')
        except BaseException:
            db.in_tx = False
            try:
                db.run('ROLLBACK')
            except Exception:                           # noqa: BLE001
                pass
            raise
    if db.engine == 'postgres':
        for table in TABLES:
            if table in ('meta', 'settings'):
                continue
            try:
                db.run("SELECT setval(pg_get_serial_sequence('%s', 'id'), "
                       "COALESCE((SELECT MAX(id) FROM %s), 0) + 1, false)" % (table, table))
            except Exception:
                pass
        # Odd or even again at once (1.0.94): MAX+1 can be the other node's
        # parity, and a row written before the caller set it collided there.
        if CONFIG.get('ha_mode') == 'replicated':
            try:
                ha_sequences(db, int(CONFIG.get('ha_slot') or 1))
            except Exception as e:                      # noqa: BLE001
                log('the numbering could not be set after loading: %s' % e, 'warn')
    return counts


META_TRANSIENT = ('db_job:', 'node:', 'maint:', 'upgrade:', 'radtest:', 'hatls:node:')


def _load_tables(db, src, keep_logs, say, gzip):
    counts = {}
    batch, keys, table, have = [], None, None, set()

    def flush():
        if table and batch:
            db.insert_many(table, keys, batch)
            counts[table] += len(batch)
            if say:
                say(table, counts[table])
        del batch[:]

    with gzip.open(str(src), 'rt', encoding='utf-8') as f:
        head = json.loads(f.readline() or '{}')
        if 'otp' not in head and 'opt' not in head:      # 'opt': before 1.0.37's new name
            raise DbError('%s is not a copy made by otp' % src)
        for line in f:
            got = json.loads(line)
            if set(got.keys()) == {'table'}:
                flush()
                keys = None
                table = got['table']
                if table not in TABLES or (not keep_logs and table in ('radius_log', 'otp_log')):
                    table = None
                    continue
                if table == 'meta':
                    # What is going on here now stays (1.0.44): maintenance,
                    # heartbeats, upgrades and jobs are this machine's, not
                    # the copy's - and in a cluster the delete would reach
                    # the other node too.
                    db.run('DELETE FROM meta WHERE ' + ' AND '.join(
                        "k NOT LIKE '%s%%'" % p.replace("'", "") for p in META_TRANSIENT))
                else:
                    db.run('DELETE FROM %s' % table)
                have = set(c.lower() for c in db.columns(table))
                counts[table] = 0
                if say:
                    say(table, 0)
                continue
            if not table:
                continue
            row = {k: v for k, v in got.items() if k.lower() in have}
            if table == 'meta':
                # What only the running service means is not carried over
                # (1.0.37): the copy made at the start of a move held the
                # move itself as "going on", and the database moved into
                # showed it going on for ever - every button that waits for
                # a job stayed grey. Heartbeats, maintenance and upgrades
                # are of the machine that wrote them, too.
                if str(row.get('k') or '').startswith(META_TRANSIENT):
                    continue
                db.run('DELETE FROM meta WHERE k = ?', (row.get('k'),))
            these = sorted(row.keys())
            if keys is not None and these != keys:
                flush()
            keys = these
            batch.append([row[k] for k in keys])
            if len(batch) >= 1000:
                flush()
        flush()
    return counts


# ---------------------------------------------------------------------------
# Active Directory, over LDAP
# ---------------------------------------------------------------------------
# Taken whole from isemon, where it has been signing people in against Active
# Directory for a long time: enough of LDAP to bind, search and page, written
# out so that nothing has to be installed, and refusing on the wire to send
# anything that would change a directory.
LDAP_TIMEOUT = 12.0
LDAP_MAX_MESSAGE = 8 * 1024 * 1024

# The result codes worth telling apart.
LDAP_OK = 0
LDAP_NO_SUCH_OBJECT = 32
LDAP_BAD_CREDENTIALS = 49
# busy, unavailable, unwilling to answer now, other: another server may (1.0.59)
LDAP_TRY_ANOTHER = (51, 52, 80)
LDAP_SAYS = {
    0: 'success',
    1: 'the directory had an operations error',
    32: 'there is no such object under that base',
    34: 'the distinguished name is not well formed',
    48: 'that server will not take this kind of authentication',
    49: 'the name or the password was not accepted',
    50: 'that account may not read what was asked for',
    53: 'the server is unwilling to do that (a blank password, or an account '
        'that must change it)',
}

# Active Directory answers every one of these with the same code 49 and the
# same sentence, with the reason hidden in a hex number at the end of it:
# "data 52e" is a wrong password and "data 533" is a disabled account, and
# telling somebody to check their password when their account is disabled is
# how an afternoon gets wasted.
AD_REASONS = {
    '525': 'there is no such account',
    '52e': 'the password is not right',
    '530': 'that account may not sign in at this time of day',
    '531': 'that account may not sign in from this machine',
    '532': 'the password has expired',
    '533': 'the account is disabled',
    '568': 'the directory ran out of room for the groups this account is in',
    '701': 'the account has expired',
    '773': 'the password must be changed before this account can be used',
    '775': 'the account is locked out',
}


def ad_reason(said):
    """What Active Directory meant, in plain words - or what it said, when
    the hex number is not one of the known ones. What it said in full
    travels beside this as the error's `detail`, for whoever hovers over
    the sentence and wants the whole of it."""
    m = re.search(r'data ([0-9a-fA-F]{3})', str(said or ''))
    if not m:
        return str(said or '')
    return AD_REASONS.get(m.group(1).lower()) or str(said)


class Refused(ValueError):
    """A plain sentence for the person, with the whole of what happened
    kept beside it. The sentence is what the sign-in page shows; the detail
    is what appears when somebody hovers over it - "the password is not
    right" first, and the directory's own "80090308: LdapErr: DSID-..."
    only for whoever wants to read it."""

    def __init__(self, words, detail=''):
        super(Refused, self).__init__(words)
        self.detail = str(detail or '')


# The matching rule Active Directory uses for "in this group, or in a group
# inside it". It is the only way to see nested membership without walking
# the tree, and walking the tree over a slow link is how a sign-in takes ten
# seconds.
LDAP_IN_CHAIN = '1.2.840.113556.1.4.1941'


def _ber_len(n):
    if n < 0x80:
        return bytes([n])
    body = b''
    while n:
        body = bytes([n & 0xFF]) + body
        n >>= 8
    return bytes([0x80 | len(body)]) + body


def _ber(tag, body):
    return bytes([tag]) + _ber_len(len(body)) + body


def _ber_int(value, tag=0x02):
    value = int(value)
    if value == 0:
        return _ber(tag, b'\x00')
    body = b''
    negative = value < 0
    n = value if not negative else -value - 1
    while n:
        body = bytes([(n & 0xFF) ^ (0xFF if negative else 0)]) + body
        n >>= 8
    if not body:
        body = b'\x00'
    top = body[0]
    if negative and not top & 0x80:
        body = b'\xff' + body
    elif not negative and top & 0x80:
        body = b'\x00' + body
    return _ber(tag, body)


def _ber_str(text, tag=0x04):
    if isinstance(text, bytes):
        return _ber(tag, text)
    return _ber(tag, str(text or '').encode('utf-8'))


def _ber_bool(value, tag=0x01):
    return _ber(tag, b'\xff' if value else b'\x00')


class BerMalformed(ValueError):
    """Not an answer cut short, but one that can never be read (1.0.59):
    said at once, not waited on until the deadline."""


def _ber_read(data, at=0):
    """One tag, its body, and where the next one starts."""
    if at + 2 > len(data):
        raise ValueError('the answer stopped in the middle')
    tag = data[at]
    length = data[at + 1]
    at += 2
    if length & 0x80:
        count = length & 0x7F
        if count == 0 or count > 4:
            raise BerMalformed('the answer has a length this does not understand')
        if at + count > len(data):
            raise ValueError('the answer stopped in the middle')
        length = int.from_bytes(data[at:at + count], 'big')
        at += count
    if length > LDAP_MAX_MESSAGE:
        raise BerMalformed('the answer says it is longer than this will read')
    if at + length > len(data):
        raise ValueError('the answer is longer than it says it is')
    return tag, data[at:at + length], at + length


def _ber_int_of(body):
    if not body:
        # An INTEGER with no octets is no integer (1.0.101): read as 0 it
        # made a reply with an empty resultCode a successful bind.
        raise BerMalformed('an INTEGER with no value')
    value = int.from_bytes(body, 'big')
    if body[0] & 0x80:
        value -= 1 << (8 * len(body))
    return value


def ldap_escape(text):
    r"""A value going into a TEXT filter, with the four characters that mean
    something else written the way RFC 4515 says to write them.

    Not for the filters this program sends. Those are built as BER, where an
    assertion value goes on the wire as raw bytes and nothing in it means
    anything else - so there is nothing to escape, and escaping anyway
    CORRUPTS the value: `CN=Novak\, Jan` became `CN=Novak\5c, Jan`, which
    read as a distinguished name is a different name, and somebody who was an
    administrator only through a group inside a group was refused. A name
    with a bracket in it - `(VPN)`, which Active Directory allows - was never
    found at all. Kept for the debug log, which is text.
    """
    out = []
    for ch in str(text or ''):
        if ch in '\\*()' or ch == '\x00':
            out.append('\\%02x' % ord(ch))
        else:
            out.append(ch)
    return ''.join(out)


def ldap_equal(attr, value):
    """(attr=value), as BER."""
    return _ber(0xA3, _ber_str(attr) + _ber_str(value))


def ldap_present(attr):
    """(attr=*)"""
    return _ber_str(attr, tag=0x87)


def ldap_contains(attr, value):
    """(attr=*value*)"""
    return _ber(0xA4, _ber_str(attr) + _ber(0x30, _ber_str(value, tag=0x81)))


def ldap_and(*parts):
    return _ber(0xA0, b''.join(parts))


def ldap_or(*parts):
    return _ber(0xA1, b''.join(parts))


# Active Directory's "this bit is set in this number" rule, which is the
# only way to ask it for the accounts whose pre-authentication is off or
# whose account is disabled.
LDAP_BITS = '1.2.840.113556.1.4.803'


def ldap_bits(attr, value):
    """(attr:1.2.840.113556.1.4.803:=value)"""
    return _ber(0xA9, _ber_str(LDAP_BITS, tag=0x81)
                + _ber_str(attr, tag=0x82) + _ber_str(str(int(value)), tag=0x83))


def ldap_in_chain(attr, value):
    """(attr:1.2.840.113556.1.4.1941:=value) - Active Directory's "or in a
    group inside it"."""
    return _ber(0xA9, _ber_str(LDAP_IN_CHAIN, tag=0x81)
                + _ber_str(attr, tag=0x82) + _ber_str(value, tag=0x83))


# What each filter tag is, in the words RFC 4515 writes them in. Used for
# nothing but the debug log.
LDAP_FILTER_JOIN = {0xA0: '&', 0xA1: '|', 0xA2: '!'}
LDAP_FILTER_SIGN = {0xA3: '=', 0xA5: '>=', 0xA6: '<=', 0xA8: '~='}


def ldap_filter_words(ber, deep=0):
    """A filter that has been built as BER, written back out as text.

    Only ever for the log. The filters go on to the wire as BER and are
    built that way, so a debug line saying what was asked has either to be
    passed down through every caller - a second argument on a dozen
    functions, which would go out of step with the real one the first time
    somebody changed a filter and forgot the words beside it - or read back
    off the thing that was actually sent. This reads it back: what appears
    in the log is what went to the directory, and it cannot say otherwise.

    Nothing secret is ever in a filter - a name, a group, a flag - and the
    one thing that is secret, the password on a bind, is not a filter and
    never reaches this.
    """
    try:
        tag, body, _ = _ber_read(ber)
    except (ValueError, IndexError):
        return '(?)'
    if deep > 12:
        return '(…)'
    if tag in LDAP_FILTER_JOIN:
        out, at = [], 0
        while at < len(body):
            try:
                _t, one, nxt = _ber_read(body, at)
            except (ValueError, IndexError):
                break
            # Put the tag and the length back on the piece that was read
            # out, so each one goes round again as a filter in its own
            # right rather than as a body with no head.
            out.append(ldap_filter_words(_ber(_t, one), deep + 1))
            at = nxt
        return '(%s%s)' % (LDAP_FILTER_JOIN[tag], ''.join(out))
    if tag == 0x87:                                    # present
        return '(%s=*)' % body.decode('utf-8', 'replace')
    if tag in LDAP_FILTER_SIGN:
        try:
            _t, attr, at = _ber_read(body)
            _t, value, _ = _ber_read(body, at)
        except (ValueError, IndexError):
            return '(?)'
        return '(%s%s%s)' % (attr.decode('utf-8', 'replace'), LDAP_FILTER_SIGN[tag],
                             value.decode('utf-8', 'replace'))
    if tag == 0xA4:                                    # substrings
        try:
            _t, attr, at = _ber_read(body)
            _t, parts, _ = _ber_read(body, at)
        except (ValueError, IndexError):
            return '(?)'
        bits, where, first, last = [], 0, '', ''
        while where < len(parts):
            try:
                _t, one, where = _ber_read(parts, where)
            except (ValueError, IndexError):
                break
            text = one.decode('utf-8', 'replace')
            if _t == 0x80:
                first = text
            elif _t == 0x82:
                last = text
            else:
                bits.append(text)
        return '(%s=%s*%s%s)' % (attr.decode('utf-8', 'replace'), first,
                                 '*'.join(bits) + ('*' if bits else ''), last)
    if tag == 0xA9:                                    # extensible match
        rule, attr, value = '', '', ''
        where = 0
        while where < len(body):
            try:
                _t, one, where = _ber_read(body, where)
            except (ValueError, IndexError):
                break
            text = one.decode('utf-8', 'replace')
            if _t == 0x81:
                rule = text
            elif _t == 0x82:
                attr = text
            elif _t == 0x83:
                value = text
        return '(%s:%s:=%s)' % (attr, rule, value)
    return '(?)'


LDAP_SCOPE_WORDS = {0: 'that entry only', 1: 'one level down', 2: 'everything below'}

# Attributes never written to the log, whatever the debug switches say. None
# of these is ever asked for by this program; they are named here because a
# debug log is a file somebody copies into a ticket, and "it cannot happen"
# is not a reason to leave the door open. See the rule the FreeRADIUS reading
# follows for the same reason: a password never reaches a row or a log.
LDAP_NEVER_LOG = ('userpassword', 'unicodepwd', 'dbcspwd', 'lmpwdhistory',
                  'ntpwdhistory', 'supplementalcredentials', 'msds-keycredentiallink',
                  'clearpassword', 'currentvalue', 'msds-managedpassword',
                  'trustauthincoming', 'trustauthoutgoing')


def ldap_entry_words(entries, most=6, wide=400):
    """What came back, short enough to be a line in a log.

    A search for the disabled accounts on a big domain is a thousand entries
    and nobody wants a thousand lines; a search that found one is exactly
    what somebody turned the debug on to see. So: the first few, whole, and
    a count of the rest.
    """
    out = []
    for one in list(entries)[:max(1, int(most))]:
        said = []
        for name in sorted((one.get('attrs') or {})):
            if name.lower() in LDAP_NEVER_LOG:
                said.append('%s=(not logged)' % name)
                continue
            values = (one.get('attrs') or {}).get(name) or []
            said.append('%s=%s' % (name, '|'.join(str(v) for v in values)))
        line = one.get('dn') or '(no dn)'
        if said:
            line += ' [' + '; '.join(said) + ']'
        out.append(line[:wide] + ('…' if len(line) > wide else ''))
    rest = len(entries) - len(out)
    if rest > 0:
        out.append('and %d more' % rest)
    return ' · '.join(out)


def describe_certificate(pem):
    """What a pasted certificate is, in words, or None if it is not one.

    Somebody importing a certificate authority wants to see that the right
    one landed - the name on it and when it runs out - and not a green tick
    that means "the text was saved". Python can read a certificate without
    any package being installed; what it cannot do without one is read it
    from a string, so it goes through a file that exists for a moment.
    """
    text = str(pem or '').strip()
    if '-----BEGIN CERTIFICATE-----' not in text:
        return None
    folder = None
    try:
        folder = tempfile.mkdtemp(prefix='otp-ca-')
        where = os.path.join(folder, 'ca.pem')
        with open(where, 'w', encoding='utf-8') as f:
            f.write(text if text.endswith('\n') else text + '\n')
        said = ssl._ssl._test_decode_cert(where)     # noqa: SLF001 - the only way in
        def one(pairs):
            out = {}
            for row in pairs or ():
                for key, value in row:
                    out[key] = value
            return out
        subject, issuer = one(said.get('subject')), one(said.get('issuer'))
        return {
            'subject': subject.get('commonName') or subject.get('organizationName') or '',
            'issuer': issuer.get('commonName') or issuer.get('organizationName') or '',
            'from': said.get('notBefore') or '',
            'until': said.get('notAfter') or '',
            'self_signed': subject == issuer,
            'count': text.count('-----BEGIN CERTIFICATE-----'),
        }
    except Exception:
        return None
    finally:
        if folder:
            shutil.rmtree(folder, ignore_errors=True)


PEM_BLOCK = re.compile(r'-----BEGIN CERTIFICATE-----\s+[A-Za-z0-9+/=\s]+?-----END CERTIFICATE-----')


def split_certificates(pem):
    """Each certificate of a bundle, as its own PEM block, in order."""
    return [m.group(0).strip() for m in PEM_BLOCK.finditer(str(pem or ''))]


def describe_certificates(pem):
    """Every certificate of a bundle, one by one: who it is, who signed it,
    when it runs out and its fingerprint - so that one of several chains can
    be told apart from another and taken out by itself. (1.0.11)"""
    out = []
    for block in split_certificates(pem):
        said = describe_certificate(block) or {}
        try:
            fp = hashlib.sha256(ssl.PEM_cert_to_DER_cert(block)).hexdigest()
        except Exception:                               # noqa: BLE001
            fp = hashlib.sha256(block.encode()).hexdigest()
        said = dict(said, fingerprint=fp, readable=bool(said))
        said.pop('count', None)
        out.append(said)
    return out


class LdapError(RuntimeError):
    """Something the person setting this up needs to read."""

    def __init__(self, said, code=None, detail=''):
        # The directory ends its own error text with a NUL. It means nothing
        # to anybody, and a database server refuses to store it.
        said = str(said).replace('\x00', '')
        super(LdapError, self).__init__(said)
        self.code = code
        # What the directory said, word for word, when `said` is the plain
        # reading of it. Empty when `said` already is the whole of it.
        self.detail = str(detail or '').replace('\x00', '')

    def whole(self):
        """Everything known about this, for a tooltip: the detail when there
        is one, the sentence itself otherwise."""
        return self.detail or str(self)


class LdapUnreachable(LdapError):
    """The directory could not be asked at all.

    Different from the directory saying no, and the difference decides
    whether a sign-in may fall back to a local account. A domain controller
    being rebooted must not lock everybody out of this dashboard; a domain
    account being disabled must not be got round by an old local password.
    Anything that happens before there is an answer about the person - the
    connection, the TLS, the account this reads the directory with - is this
    one.
    """


class Ldap(object):
    """One conversation with a directory.

    Opened, asked, closed. Nothing is kept between sign-ins: a pooled
    connection to a domain controller that has been restarted is a sign-in
    that fails for no reason anybody can see.
    """

    # How many pages one search may take. A directory of a hundred thousand
    # groups at a thousand a page is a hundred; two hundred is room to spare
    # and a floor under a server whose paging cookie never empties.
    PAGES_MOST = 200

    def __init__(self, host, port=389, tls='none', ca_pem='', verify=True,
                 timeout=LDAP_TIMEOUT, weak=False):
        self.host = str(host or '').strip()
        self.weak = bool(weak)
        self.port = int(port or 389)
        self.tls = str(tls or 'none').strip().lower()
        self.ca_pem = str(ca_pem or '')
        self.verify = bool(verify)
        self.timeout = float(timeout or LDAP_TIMEOUT)
        self.sock = None
        self.next_id = 1
        self.buffer = b''
        # The controls that came with the last message read; the paging
        # cookie is taken out of them.
        self.last_controls = b''

    # ---- the wire ---------------------------------------------------------
    def open(self):
        if not self.host:
            raise LdapError('no directory server has been given')
        try:
            self.sock = socket.create_connection((self.host, self.port), self.timeout)
        except OSError as e:
            raise LdapError('%s:%d could not be reached: %s'
                            % (self.host, self.port, str(e)[:120]))
        self.sock.settimeout(self.timeout)
        if self.tls == 'ldaps':
            self.sock = self._wrap(self.sock)
        elif self.tls == 'starttls':
            self._start_tls()
        if debugging('ldap'):
            log('ldap %s:%d open, %s' % (self.host, self.port,
                                         {'ldaps': 'over TLS',
                                          'starttls': 'over TLS after STARTTLS'}
                                         .get(self.tls, 'in the clear')), 'debug')
        return self

    def _context(self):
        ctx = ssl.create_default_context()
        if self.ca_pem.strip():
            try:
                ctx.load_verify_locations(cadata=self.ca_pem)
            except (ssl.SSLError, ValueError) as e:
                raise LdapError('the certificate authority could not be read: %s'
                                % str(e)[:120])
        if self.weak:
            # Old domain controllers (1.0.77): a 1024-bit RSA key, a SHA-1
            # signature, TLS 1.0 - refused at OpenSSL's default level
            # ("EE certificate key too weak", "ca md too weak"). Level 0 takes
            # them; the certificate is still checked against the authority
            # and the server's name, unless that check is off as well.
            try:
                ctx.set_ciphers('DEFAULT:@SECLEVEL=0')
            except ssl.SSLError:
                ctx.set_ciphers('ALL:@SECLEVEL=0')
            try:
                ctx.minimum_version = ssl.TLSVersion.TLSv1
            except (ValueError, AttributeError):
                pass
            # And an old authority's certificate without the extensions
            # Python 3.13 insists on (key usage, a critical basicConstraints):
            # still a chain to that authority, checked.
            ctx.verify_flags &= ~getattr(ssl, 'VERIFY_X509_STRICT', 0)
        if not self.verify:
            # Deliberate, and said out loud wherever it is switched on: a
            # directory reached without checking its certificate is a
            # directory anybody on the path can pretend to be.
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
        return ctx

    def _wrap(self, sock):
        try:
            return self._context().wrap_socket(sock, server_hostname=self.host)
        except ssl.SSLCertVerificationError as e:
            said = str(e.verify_message or e)[:120]
            if 'too weak' in said and not self.weak:
                raise LdapError('the server’s certificate was not accepted: %s. Its key or its '
                                'signature is older than OpenSSL takes by default (a 1024-bit '
                                'key, SHA-1): switch on "Take old, weak certificates" for this '
                                'directory - or better, give the server a new certificate.'
                                % said)
            raise LdapError('the server’s certificate was not accepted: %s. Import the '
                            'certificate authority that signed it, or switch the check off '
                            'if this is a test.' % said)
        except (ssl.SSLError, OSError) as e:
            said = str(e)[:160]
            if not self.weak and any(w in said.lower() for w in (
                    'too small', 'too weak', 'legacy', 'unsupported protocol', 'sslv3',
                    'no protocols available', 'version')):
                raise LdapError('TLS to %s:%d did not start: %s - an old server (a weak key, '
                                'TLS 1.0): switch on "Take old, weak certificates" for this '
                                'directory' % (self.host, self.port, said))
            raise LdapError('TLS to %s:%d did not start: %s'
                            % (self.host, self.port, said))

    def _start_tls(self):
        """The extended operation that turns a plain connection into a
        secure one, on the same port."""
        body = _ber_str(self.START_TLS_OID, tag=0x80)
        tag, answer = self._ask(_ber(0x77, body))
        if tag != 0x78:
            raise LdapError('the server did not answer the StartTLS request')
        code, said = self._result_of(answer)
        if code != LDAP_OK:
            raise LdapError('StartTLS was refused: %s' % (said or LDAP_SAYS.get(code, code)),
                            code)
        # Nothing may be left in the read buffer from BEFORE the connection
        # was made secure. Whatever arrived in plain text after the StartTLS
        # reply used to sit there and be read back as if it had come over
        # TLS - so somebody on the path could append a forged "bind
        # succeeded" to the server's reply, the real handshake would then
        # complete, and the next bind - a person signing in with any
        # password at all - would be answered by the forgery. RFC 4511
        # says the same thing: a client MUST NOT have outstanding data at
        # this point, and the honest thing to do with any is to refuse.
        if self.buffer:
            many = len(self.buffer)
            # Thrown away, and the connection with it: nothing may ever be
            # read off this socket again.
            self.buffer = b''
            try:
                self.sock.close()
            except Exception:
                pass
            raise LdapError('%s sent %d byte(s) in the clear after agreeing to TLS, '
                            'which is not something a directory does' % (self.host, many))
        self.sock = self._wrap(self.sock)
        self.buffer = b''

    def close(self):
        if self.sock:
            try:
                self._send(_ber(0x42, b''))          # unbindRequest, politely
            except Exception:
                pass
            try:
                self.sock.close()
            except Exception:
                pass
            self.sock = None

    def __enter__(self):
        return self.open()

    def __exit__(self, *_):
        self.close()

    # The only four things this program may ever say to a directory, as the
    # tags they go on to the wire as.
    #
    #   0x60 bind      - sign in
    #   0x63 search    - ask
    #   0x42 unbind    - go away
    #   0x77 extended  - StartTLS, and nothing else is sent
    #
    # THIS PROGRAM NEVER CHANGES ANYTHING IN ACTIVE DIRECTORY. Not an
    # attribute, not a group, not a password, not an account: it reads, and
    # that is the whole of it. That is not a promise about what the code
    # happens to do today - it is checked here, on the way out, on every
    # message: an add (0x68), a modify (0x66), a delete (0x4A), a rename
    # (0x6C) or a compare (0x6E) cannot leave this program even if somebody
    # writes the code to build one. A check reads this list and another
    # proves the socket refuses each of them.
    MAY_SAY = (0x60, 0x63, 0x42, 0x77)
    START_TLS_OID = '1.3.6.1.4.1.1466.20037'
    WRITES = {0x66: 'modify', 0x68: 'add', 0x4A: 'delete', 0x6C: 'rename',
              0x6D: 'rename', 0x6E: 'compare'}

    def _send(self, op, controls=b''):
        tag = op[0] if op else 0
        if tag not in self.MAY_SAY:
            raise LdapError(
                'this program only ever READS a directory, and something tried to '
                'send it a %s. Nothing was sent.'
                % self.WRITES.get(tag, 'message of kind 0x%02X' % tag))
        # An extended operation is a door to anything the server offers -
        # a password change is one of them (1.3.6.1.4.1.4203.1.11.1). The
        # only one this program has any business sending is StartTLS, so
        # the only one it may send is StartTLS, by name.
        # The whole message, byte for byte: the name being somewhere inside
        # it let a password change through that carried it as its value.
        if tag == 0x77 and op != _ber(0x77, _ber_str(self.START_TLS_OID, tag=0x80)):
            raise LdapError('this program only ever READS a directory, and something '
                            'tried to send it an extended operation that is not '
                            'StartTLS. Nothing was sent.')
        mid = self.next_id
        self.next_id += 1
        try:
            self.sock.sendall(_ber(0x30, _ber_int(mid) + op + controls))
        except OSError as e:
            # The line gone, not the directory saying no (1.0.44).
            raise LdapUnreachable('the connection to %s failed: %s' % (self.host, str(e)[:100]))
        return mid

    def _read_message(self):
        """One whole LDAP message off the wire.

        The controls come back too. Only one is read here and it is the one
        that matters on a real domain: how to ask for the next page.
        """
        while True:
            try:
                tag, body, end = _ber_read(self.buffer)
                self.buffer = self.buffer[end:]
                if tag != 0x30:
                    raise LdapError('the server sent something that is not an LDAP message')
                # The message is whole by now (1.0.98): what does not read
                # inside it is damaged, not "not all here yet" - that waited
                # the whole timeout for bytes that were never coming.
                try:
                    _mid_tag, mid_body, at = _ber_read(body)
                    op_tag, op_body, after = _ber_read(body, at)
                except ValueError as e:
                    raise BerMalformed('a message whose inside does not read (%s)' % e)
                self.last_controls = body[after:]
                mid = _ber_int_of(mid_body)
                if mid == 0 and op_tag == 0x78:
                    # A Notice of Disconnection (RFC 4511 4.4.1, 1.0.59): the
                    # server is going away - the next one is asked now, not
                    # after the whole timeout.
                    raise LdapUnreachable('%s said it is closing the connection' % self.host)
                return mid, op_tag, op_body
            except BerMalformed as e:
                raise LdapError('%s sent an answer that does not read: %s' % (self.host, e))
            except ValueError:
                pass                                  # not all here yet
            # One deadline for the whole answer (1.0.33): a server that sends
            # a byte at a time, or answers to other message IDs, kept the
            # worker that asked for as long as it liked.
            left = getattr(self, '_deadline', 0) - time.time()
            if getattr(self, '_deadline', 0) and left <= 0:
                raise LdapUnreachable('%s did not finish answering within %d s'
                                % (self.host, int(self.timeout * 3)))
            try:
                if getattr(self, '_deadline', 0):
                    self.sock.settimeout(max(0.05, min(self.timeout, left)))
                more = self.sock.recv(65536)
            except socket.timeout:
                raise LdapUnreachable('%s did not answer within %d s'
                                      % (self.host, int(self.timeout)))
            except OSError as e:
                raise LdapUnreachable('the connection to %s failed: %s'
                                      % (self.host, str(e)[:100]))
            if not more:
                raise LdapUnreachable('%s closed the connection' % self.host)
            if len(self.buffer) + len(more) > LDAP_MAX_MESSAGE:
                raise LdapError('the server sent more than this will read')
            self.buffer += more

    def _ask(self, op):
        mid = self._send(op)
        self._deadline = time.time() + self.timeout * 3
        try:
            while True:
                got_id, tag, body = self._read_message()
                if got_id == mid:
                    return tag, body
        finally:
            # Left set, the old deadline ran out under the next search on the
            # same connection, which then failed at once. (1.0.36)
            self._deadline = 0

    @staticmethod
    def _result_of(body):
        """resultCode and the message beside it, out of any LDAPResult."""
        tag, code_body, at = _ber_read(body)
        code = _ber_int_of(code_body)
        said = ''
        try:
            _t, _matched, at = _ber_read(body, at)
            _t, message, _ = _ber_read(body, at)
            said = message.decode('utf-8', 'replace').strip()
        except ValueError:
            pass
        return code, said

    # ---- what it is asked -------------------------------------------------
    def bind(self, dn='', password=''):
        try:
            return self._bind(dn, password)
        except (ValueError, IndexError) as e:
            # An answer that does not read is the directory failing, not this
            # program (1.0.33).
            raise LdapError('%s sent an answer that does not read: %s' % (self.host, e))

    def _bind(self, dn='', password=''):
        """A simple bind. An empty password is refused here rather than on
        the server: many directories take one as an anonymous bind and
        answer "yes", which would turn a blank password into a sign-in."""
        if dn and not str(password or ''):
            raise LdapError('a password is needed', LDAP_BAD_CREDENTIALS)
        # The name only. The password is the one thing in this program that
        # is never written anywhere, debug or no debug, and a bind is where
        # it would be easiest to write by accident.
        if debugging('ldap'):
            log('ldap %s: signing in as %s (the password is never logged)'
                % (self.host, dn or 'nobody — anonymous'), 'debug')
        op = _ber(0x60, _ber_int(3) + _ber_str(dn)
                  + _ber_str(password, tag=0x80))
        tag, body = self._ask(op)
        if tag != 0x61:
            raise LdapError('the server did not answer the sign-in')
        code, said = self._result_of(body)
        if code != LDAP_OK:
            plain = ad_reason(said) or LDAP_SAYS.get(code, 'the directory said %d' % code)
            raise LdapError(plain, code,
                            detail='%s (result %d)' % (said, code) if said else '')
        return True

    # Simple paged results: the control every directory of any size needs.
    # Active Directory will not hand back more than its MaxPageSize - a
    # thousand entries by default - however large a size limit is asked for.
    # It answers with a cookie instead, and the next page is asked for by
    # handing that cookie back. Without it, a domain with three thousand
    # groups looked like a domain with a thousand, and nobody could tell
    # which thousand.
    PAGED_OID = '1.2.840.113556.1.4.319'
    PAGE_SIZE = 500

    def _paging_control(self, cookie=b'', size=None):
        # `size=0` with the cookie is how a paged search is given up on
        # (RFC 2696): the server lets the result set go. Anything else with
        # the cookie asks for the next page.
        inner = _ber(0x30, _ber_int(self.PAGE_SIZE if size is None else int(size))
                     + _ber_str(cookie))
        return _ber(0xA0, _ber(0x30, _ber_str(self.PAGED_OID) + _ber_str(inner)))

    def _paging_cookie(self, controls):
        """The cookie out of a searchResDone, or b'' when there is no more."""
        if not controls:
            return b''
        try:
            tag, body, _ = _ber_read(controls)         # [0] controls
            at = 0
            while at < len(body):
                _t, one, at = _ber_read(body, at)
                _t, oid, where = _ber_read(one)
                if oid.decode('utf-8', 'replace') != self.PAGED_OID:
                    continue
                while where < len(one):
                    _t, value, where = _ber_read(one, where)
                    if _t != 0x04:                     # criticality, skip it
                        continue
                    _t, inner, _ = _ber_read(value)
                    _t, _size, deep = _ber_read(inner)
                    _t, cookie, _ = _ber_read(inner, deep)
                    return cookie
        except (ValueError, IndexError):
            return b''
        return b''

    def search(self, base, filter_ber, attrs=(), scope=2, limit=200, paged=False):
        try:
            return self._search(base, filter_ber, attrs, scope, limit, paged)
        except (ValueError, IndexError) as e:
            raise LdapError('%s sent an answer that does not read: %s' % (self.host, e))
        finally:
            self._deadline = 0

    def _search(self, base, filter_ber, attrs=(), scope=2, limit=200, paged=False):
        """Entries under `base` matching `filter_ber`.

        scope 0 = that entry, 1 = one level down, 2 = everything below.
        Referrals are skipped: Active Directory answers a search at the
        domain root with one per other partition, and following them needs
        credentials for those partitions.

        `paged` asks the directory for it a page at a time and keeps going
        until it says there is no more, which is the only way to see past a
        thousand of anything on Active Directory. `limit` is then how many
        this will hold rather than how many the directory will send.
        """
        want = b''.join(_ber_str(a) for a in attrs)
        cap = max(0, int(limit))
        out = []
        cookie = b''
        # With the LDAP debug on, what is being asked and what came back.
        # Two lines rather than one - the question goes into the log BEFORE
        # the directory is asked, so a search that never answers is still in
        # there with the question that hung it, which is the whole reason
        # anybody turns this on.
        loud = debugging('ldap')
        began = time.time()
        if loud:
            log('ldap %s: %s under %s, %s, wanting %s%s'
                % (self.host, ldap_filter_words(filter_ber), base or '(root)',
                   LDAP_SCOPE_WORDS.get(int(scope), 'scope %d' % scope),
                   ', '.join(attrs) if attrs else 'everything',
                   ', a page at a time' if paged else ''), 'debug')
        # A page count as well as the two exits below. A directory that hands
        # back a cookie with no entries in it - broken, or hostile - would
        # otherwise keep this thread here for ever.
        pages = 0
        while True:
            pages += 1
            if pages > self.PAGES_MOST:
                # What was read so far is the answer, said to be cut short -
                # NOT nothing. This used to fall out of the loop with no
                # return at all, so a search over more than a hundred
                # thousand entries came back as `None`, the caller read that
                # as "nought of them", and a big domain's count of switched-
                # off accounts was written down as zero.
                log('%s: one search ran to %d pages (%s entries) and was cut short there'
                    % (self.host, pages - 1, len(out)), 'warn')
                self._let_go(base, scope, filter_ber, want, cookie)
                return out
            asked = 0 if paged else cap
            op = _ber(0x63,
                      _ber_str(base) + _ber_int(scope, tag=0x0A) + _ber_int(0, tag=0x0A)
                      + _ber_int(asked) + _ber_int(int(self.timeout))
                      + _ber_bool(False) + filter_ber + _ber(0x30, want))
            mid = self._send(op, self._paging_control(cookie) if paged else b'')
            # Per page (1.0.36), and never past the whole search's (1.0.59):
            # a server handing out page after page slowly held a RADIUS
            # worker for as long as two hundred pages took.
            self._deadline = min(time.time() + self.timeout * 3, began + self.timeout * 6)
            if self._deadline <= time.time():
                raise LdapUnreachable('%s did not finish the search within %d s'
                                      % (self.host, int(self.timeout * 6)))
            done = False
            while not done:
                got_id, tag, body = self._read_message()
                if got_id != mid:
                    continue
                if tag == 0x64:                        # searchResEntry
                    if not cap or len(out) < cap:
                        out.append(self._entry_of(body))
                elif tag == 0x73:                      # searchResRef
                    continue
                elif tag == 0x65:                      # searchResDone
                    code, said = self._result_of(body)
                    if code not in (LDAP_OK, 4, LDAP_NO_SUCH_OBJECT):
                        raise LdapError(said or LDAP_SAYS.get(
                            code, 'the directory said %d' % code), code)
                    cookie = self._paging_cookie(self.last_controls) if paged else b''
                    done = True
                else:
                    raise LdapError('the server sent an answer this does not understand')
            self._deadline = 0
            if not paged or not cookie or (cap and len(out) >= cap):
                # A search that is being given up on mid-way is abandoned
                # properly, so the directory is not left holding the page.
                if paged and cookie:
                    self._let_go(base, scope, filter_ber, want, cookie)
                if loud:
                    log('ldap %s: %d entr%s in %d ms%s%s'
                        % (self.host, len(out), 'y' if len(out) == 1 else 'ies',
                           int((time.time() - began) * 1000),
                           ' over %d pages' % pages if pages > 1 else '',
                           (' — ' + ldap_entry_words(out)) if out else ''), 'debug')
                return out

    def _let_go(self, base, scope, filter_ber, want, cookie):
        """Tell the directory to drop a paged search that will not be finished.

        RFC 2696: the same search again, with the cookie and a page size of
        NOUGHT. Sent with the ordinary page size - which is what this did -
        it is not an abandon at all but a request for another five hundred
        entries, whose reply then sits unread on the connection; and a
        directory allows only so many open result sets per connection, so
        the tenth search that stopped early made the eleventh fail.
        """
        try:
            mid = self._send(_ber(0x63,
                                  _ber_str(base) + _ber_int(scope, tag=0x0A)
                                  + _ber_int(0, tag=0x0A) + _ber_int(0)
                                  + _ber_int(int(self.timeout)) + _ber_bool(True)
                                  + filter_ber + _ber(0x30, want)),
                             self._paging_control(cookie, size=0))
            # ...and its one-line answer read, so it is not left lying on
            # the connection for the next search to trip over.
            self._deadline = time.time() + self.timeout
            for _ in range(50):
                got_id, tag, _body = self._read_message()
                if got_id == mid and tag == 0x65:
                    break
        except (OSError, LdapError, ValueError):
            pass
        finally:
            self._deadline = 0

    @staticmethod
    def _entry_of(body):
        tag, dn_body, at = _ber_read(body)
        entry = {'dn': dn_body.decode('utf-8', 'replace'), 'attrs': {}}
        tag, attrs_body, _ = _ber_read(body, at)
        inner = 0
        while inner < len(attrs_body):
            _t, one, inner = _ber_read(attrs_body, inner)
            _t, name, where = _ber_read(one)
            _t, values, _ = _ber_read(one, where)
            got = []
            deep = 0
            while deep < len(values):
                _t, value, deep = _ber_read(values, deep)
                got.append(value.decode('utf-8', 'replace'))
            entry['attrs'][name.decode('utf-8', 'replace')] = got
        return entry



# ---------------------------------------------------------------------------
# RADIUS, the protocol (RFC 2865, 2866, 2869, 3579, 5997)
# ---------------------------------------------------------------------------
# A packet is a code, an identifier, a length, sixteen bytes of authenticator
# and a run of attributes, each a type, a length and a value. The dictionary
# below names the attributes a VPN concentrator and a token server actually
# use; anything else is kept and written down by its number, the way
# FreeRADIUS writes an attribute it has no name for.

ACCESS_REQUEST, ACCESS_ACCEPT, ACCESS_REJECT = 1, 2, 3
ACCOUNTING_REQUEST, ACCOUNTING_RESPONSE = 4, 5
ACCESS_CHALLENGE, STATUS_SERVER = 11, 12
CODE_WORDS = {1: 'Access-Request', 2: 'Access-Accept', 3: 'Access-Reject',
              4: 'Accounting-Request', 5: 'Accounting-Response', 11: 'Access-Challenge',
              12: 'Status-Server'}

# number: (name, type) - types: string, octets, integer, ipaddr, date, ipv6addr
RADIUS_ATTRS = {
    1: ('User-Name', 'string'), 2: ('User-Password', 'octets'),
    3: ('CHAP-Password', 'octets'), 4: ('NAS-IP-Address', 'ipaddr'),
    5: ('NAS-Port', 'integer'), 6: ('Service-Type', 'integer'),
    7: ('Framed-Protocol', 'integer'), 8: ('Framed-IP-Address', 'ipaddr'),
    9: ('Framed-IP-Netmask', 'ipaddr'), 10: ('Framed-Routing', 'integer'),
    11: ('Filter-Id', 'string'), 12: ('Framed-MTU', 'integer'),
    13: ('Framed-Compression', 'integer'), 14: ('Login-IP-Host', 'ipaddr'),
    18: ('Reply-Message', 'string'), 22: ('Framed-Route', 'string'),
    24: ('State', 'octets'), 25: ('Class', 'string'), 26: ('Vendor-Specific', 'octets'),
    27: ('Session-Timeout', 'integer'), 28: ('Idle-Timeout', 'integer'),
    29: ('Termination-Action', 'integer'), 30: ('Called-Station-Id', 'string'),
    31: ('Calling-Station-Id', 'string'), 32: ('NAS-Identifier', 'string'),
    33: ('Proxy-State', 'octets'), 40: ('Acct-Status-Type', 'integer'),
    41: ('Acct-Delay-Time', 'integer'), 42: ('Acct-Input-Octets', 'integer'),
    43: ('Acct-Output-Octets', 'integer'), 44: ('Acct-Session-Id', 'string'),
    45: ('Acct-Authentic', 'integer'), 46: ('Acct-Session-Time', 'integer'),
    47: ('Acct-Input-Packets', 'integer'), 48: ('Acct-Output-Packets', 'integer'),
    49: ('Acct-Terminate-Cause', 'integer'), 50: ('Acct-Multi-Session-Id', 'string'),
    52: ('Acct-Input-Gigawords', 'integer'), 53: ('Acct-Output-Gigawords', 'integer'),
    55: ('Event-Timestamp', 'date'), 60: ('CHAP-Challenge', 'octets'),
    61: ('NAS-Port-Type', 'integer'), 62: ('Port-Limit', 'integer'),
    64: ('Tunnel-Type', 'tagint'), 65: ('Tunnel-Medium-Type', 'tagint'),
    66: ('Tunnel-Client-Endpoint', 'tagstr'), 67: ('Tunnel-Server-Endpoint', 'tagstr'),
    77: ('Connect-Info', 'string'), 79: ('EAP-Message', 'octets'),
    80: ('Message-Authenticator', 'octets'), 81: ('Tunnel-Private-Group-Id', 'tagstr'),
    85: ('Acct-Interim-Interval', 'integer'), 87: ('NAS-Port-Id', 'string'),
    88: ('Framed-Pool', 'string'), 95: ('NAS-IPv6-Address', 'ipv6addr'),
    101: ('Error-Cause', 'integer'),
}
RADIUS_NUMBERS = {v[0].lower(): (k, v[1]) for k, v in RADIUS_ATTRS.items()}

# The values worth naming. Everything else is written as its number.
RADIUS_VALUES = {
    'Service-Type': {1: 'Login-User', 2: 'Framed-User', 5: 'Outbound-User',
                     6: 'Administrative-User', 7: 'NAS-Prompt-User', 8: 'Authenticate-Only',
                     10: 'Call-Check'},
    'NAS-Port-Type': {0: 'Async', 5: 'Virtual', 15: 'Ethernet', 19: 'Wireless-802.11'},
    'Acct-Status-Type': {1: 'Start', 2: 'Stop', 3: 'Interim-Update', 7: 'Accounting-On',
                         8: 'Accounting-Off'},
    'Framed-Protocol': {1: 'PPP', 2: 'SLIP'},
    'Tunnel-Type': {3: 'L2TP', 13: 'VLAN'},
    'Tunnel-Medium-Type': {1: 'IPv4', 6: '802'},
    'Acct-Authentic': {1: 'RADIUS', 2: 'Local', 3: 'Remote'},
    'Acct-Terminate-Cause': {1: 'User-Request', 2: 'Lost-Carrier', 4: 'Idle-Timeout',
                             5: 'Session-Timeout', 6: 'Admin-Reset', 10: 'NAS-Request'},
}

# Vendor attributes: (vendor, number) -> (name, type).
VENDORS = {9: 'Cisco', 311: 'Microsoft', 3076: 'Cisco-VPN3000'}
VSA_ATTRS = {
    (9, 1): ('Cisco-AVPair', 'string'),
    (3076, 25): ('ASA-Group-Policy', 'string'),
    (3076, 85): ('ASA-Tunnel-Group-Lock', 'string'),
    (3076, 146): ('ASA-TunnelGroupName', 'string'),
    (3076, 150): ('ASA-ClientType', 'integer'),
    (3076, 151): ('ASA-SessionType', 'integer'),
    (3076, 152): ('ASA-SessionSubtype', 'integer'),
}
VSA_NUMBERS = {v[0].lower(): (k, v[1]) for k, v in VSA_ATTRS.items()}

# What may be put into an answer by name, with how it is written. Listed so
# that a realm's reply lines are checked when they are saved rather than when
# somebody first signs in.
REPLY_ATTRS = ('Reply-Message', 'Class', 'Filter-Id', 'Session-Timeout', 'Idle-Timeout',
               'Service-Type', 'Framed-IP-Address', 'Framed-IP-Netmask', 'Framed-Pool',
               'Acct-Interim-Interval', 'Tunnel-Type', 'Tunnel-Medium-Type',
               'Tunnel-Private-Group-Id', 'Cisco-AVPair', 'ASA-Group-Policy',
               'ASA-Tunnel-Group-Lock')


class RadiusError(ValueError):
    pass


def _value_words(name, kind, raw):
    """One attribute's value, as FreeRADIUS writes it in a detail file."""
    try:
        if kind == 'string':
            return raw.decode('utf-8', 'replace')
        if kind in ('integer', 'date'):
            if len(raw) != 4:
                return '0x' + raw.hex()
            n = struct.unpack('>I', raw)[0]
            return RADIUS_VALUES.get(name, {}).get(n, str(n))
        if kind == 'ipaddr':
            return socket.inet_ntoa(raw) if len(raw) == 4 else '0x' + raw.hex()
        if kind == 'ipv6addr':
            return socket.inet_ntop(socket.AF_INET6, raw) if len(raw) == 16 else '0x' + raw.hex()
        if kind == 'tagint':
            if len(raw) == 4:
                n = struct.unpack('>I', b'\x00' + raw[1:])[0]
                return RADIUS_VALUES.get(name, {}).get(n, str(n))
        if kind == 'tagstr':
            if raw and raw[0] < 0x20:
                raw = raw[1:]
            return raw.decode('utf-8', 'replace')
    except (ValueError, OSError, struct.error):
        pass
    return '0x' + raw.hex()


def _value_bytes(name, kind, value):
    text = str(value).strip()
    if kind == 'string':
        return text.encode('utf-8')
    if kind == 'integer' or kind == 'date':
        names = {v.lower(): k for k, v in RADIUS_VALUES.get(name, {}).items()}
        names.update(globals().get('RADIUS_VALUE_ALIASES', {}).get(name, {}))
        n = names.get(text.lower())
        if n is None:
            try:
                n = int(text)
            except ValueError:
                raise RadiusError('%s takes a number%s, not %r' % (
                    name, (' or one of ' + ', '.join(RADIUS_VALUES[name].values()))
                    if name in RADIUS_VALUES else '', text))
        return struct.pack('>I', n)
    if kind == 'ipaddr':
        try:
            return socket.inet_aton(str(ipaddress.IPv4Address(text)))
        except ValueError:
            raise RadiusError('%s takes an IPv4 address, not %r' % (name, text))
    if kind == 'tagint':
        names = {v.lower(): k for k, v in RADIUS_VALUES.get(name, {}).items()}
        names.update(globals().get('RADIUS_VALUE_ALIASES', {}).get(name, {}))
        n = names.get(text.lower())
        if n is None:
            try:
                n = int(text)
            except ValueError:
                raise RadiusError('%s takes a number, not %r' % (name, text))
        if not 0 <= n <= 0xFFFFFF:
            # Three bytes after the tag (1.0.59): 16777229 went out as 13.
            raise RadiusError('%s takes a number from 0 to 16777215, not %r' % (name, text))
        return b'\x00' + struct.pack('>I', n)[1:]
    if kind == 'tagstr':
        return text.encode('utf-8')
    if kind == 'octets':
        if text.lower().startswith('0x'):
            return bytes.fromhex(text[2:])
        return text.encode('utf-8')
    return text.encode('utf-8')


# Vendors whose attributes are not one byte of type and one of length, and
# attributes that are salted (1.0.59): by number they would go out wrong.
VSA_ODD_VENDORS = {24757: 'WiMAX', 429: 'USR', 4846: 'Lucent', 8164: 'Starent'}
VSA_SALTED = {(311, 16), (311, 17)}


def attr_bytes(name, value):
    """`Name = value` as the bytes of one attribute (a vendor one wrapped in
    Vendor-Specific)."""
    out = _attr_bytes(name, value)
    # An attribute is never empty (RFC 2865 5, 1.0.59): some NAS throw the
    # whole answer away for one.
    if (out[0] != 26 and len(out) <= 2) or (out[0] == 26 and len(out) <= 8):
        raise RadiusError('%s has no value: an attribute is never sent empty' % name)
    return out


def _attr_bytes(name, value):
    key = str(name).strip().lower()
    if key in RADIUS_NUMBERS:
        num, kind = RADIUS_NUMBERS[key]
        body = _value_bytes(RADIUS_ATTRS[num][0], kind, value)
        if len(body) > 253:
            raise RadiusError('%s is longer than one attribute may be (253 bytes)' % name)
        return bytes([num, len(body) + 2]) + body
    if key in VSA_NUMBERS:
        (vendor, num), kind = VSA_NUMBERS[key]
        body = _value_bytes(VSA_ATTRS[(vendor, num)][0], kind, value)
        if len(body) > 247:
            raise RadiusError('%s is longer than one attribute may be' % name)
        sub = bytes([num, len(body) + 2]) + body
        inner = struct.pack('>I', vendor) + sub
        return bytes([26, len(inner) + 2]) + inner
    # Any other vendor's attribute, by its numbers (1.0.57): a string, or
    # 0x... bytes.
    m = re.match(r'^vendor-(\d{1,10})-attr-(\d{1,3})\Z', key)
    if m and 0 < int(m.group(1)) < 2 ** 32 and 0 < int(m.group(2)) < 256:
        if int(m.group(1)) in VSA_ODD_VENDORS:
            raise RadiusError('%s: %s attributes are not laid out as one byte of type and one of '
                              'length - this server cannot send them by number'
                              % (name, VSA_ODD_VENDORS[int(m.group(1))]))
        if (int(m.group(1)), int(m.group(2))) in VSA_SALTED:
            raise RadiusError('%s is a salted key (MS-MPPE): it cannot be sent by number' % name)
        body = _value_bytes(name, 'octets', value)
        if len(body) > 247:
            raise RadiusError('%s is longer than one attribute may be' % name)
        inner = struct.pack('>I', int(m.group(1))) + bytes([int(m.group(2)), len(body) + 2]) + body
        return bytes([26, len(inner) + 2]) + inner
    raise RadiusError('%s is not an attribute this server knows how to send. It knows: %s'
                      % (name, ', '.join(REPLY_ATTRS)))


def reply_lines(text):
    """A realm's or a group's reply, `Name = value` a line, as pairs. Raises
    RadiusError naming the line that will not do."""
    out = []
    for n, line in enumerate(str(text or '').splitlines(), 1):
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        m = re.match(r'^([A-Za-z0-9-]+)\s*:?\+?=\s*(.*)\Z', line)
        if not m:
            raise RadiusError('line %d, %r: write it as Name = value' % (n, line[:60]))
        value = m.group(2).strip()
        if len(value) >= 2 and value[0] == value[-1] == '"':
            value = value[1:-1]
        # Only what an answer may carry (1.0.33): not a Message-Authenticator,
        # a User-Password or a State written into a realm's reply.
        if m.group(1) not in REPLY_ATTRS and not re.match(r'^Vendor-\d{1,10}-Attr-\d{1,3}\Z',
                                                          m.group(1), re.I):
            raise RadiusError('line %d: %s is not something an answer carries here - one of %s'
                              % (n, m.group(1), ', '.join(REPLY_ATTRS)))
        try:
            attr_bytes(m.group(1), value)
        except (struct.error, ValueError) as e:
            raise RadiusError('line %d: %s' % (n, e))
        out.append((m.group(1), value))
    return out


class Packet(object):
    """One RADIUS packet, read or being made."""

    def __init__(self, code=0, ident=0, authenticator=b'\x00' * 16, raw=b''):
        self.code = code
        self.ident = ident
        self.authenticator = authenticator
        self.attrs = []                       # [(number, bytes)] as they came
        self.raw = raw

    @classmethod
    def parse(cls, data):
        if len(data) < 20:
            raise RadiusError('shorter than a RADIUS packet can be')
        code, ident, length = struct.unpack('>BBH', data[:4])
        if length < 20 or length > 4096 or length > len(data):
            raise RadiusError('the length it gives (%d) is not the length it has' % length)
        pkt = cls(code, ident, data[4:20], data[:length])
        at = 20
        while at < length:
            if at + 2 > length:
                raise RadiusError('an attribute is cut off')
            kind, size = data[at], data[at + 1]
            if size < 2 or at + size > length:
                raise RadiusError('an attribute says it is %d bytes long' % size)
            pkt.attrs.append((kind, data[at + 2:at + size]))
            at += size
        return pkt

    def get(self, number):
        for k, v in self.attrs:
            if k == number:
                return v
        return None

    def all(self, number):
        return [v for k, v in self.attrs if k == number]

    def text(self, number):
        got = self.get(number)
        return got.decode('utf-8', 'replace') if got is not None else ''

    def vsa(self):
        """[(vendor, number, bytes)] out of every Vendor-Specific."""
        out = []
        for raw in self.all(26):
            if len(raw) < 6:
                continue
            vendor = struct.unpack('>I', raw[:4])[0]
            at = 4
            while at + 2 <= len(raw):
                num, size = raw[at], raw[at + 1]
                if size < 2 or at + size > len(raw):
                    break
                out.append((vendor, num, raw[at + 2:at + size]))
                at += size
        return out

    def words(self, secret=None):
        """Every attribute as (Name, value), in order, the way FreeRADIUS
        writes them in a detail file. Passwords are never in it."""
        out = []
        for num, raw in self.attrs:
            if num == 26:
                continue
            name, kind = RADIUS_ATTRS.get(num, ('Attr-%d' % num, 'octets'))
            # Passwords, CHAP, EAP and Tunnel-Password: never written down
            # (1.0.57) - an MS-CHAPv2 or EAP exchange in the log is enough to
            # crack the password offline.
            if num in (2, 3, 60, 69, 79):
                out.append((name, '<suppressed>'))
                continue
            if num == 80:
                out.append((name, '0x' + raw.hex()))
                continue
            out.append((name, _value_words(name, kind, raw)))
        for vendor, num, raw in self.vsa():
            name, kind = VSA_ATTRS.get((vendor, num), (None, 'octets'))
            if vendor == 311 and num in (1, 2, 11, 16, 17, 25, 26):
                # Microsoft's MS-CHAP challenge, responses and MPPE keys.
                out.append((name or 'Vendor-311-Attr-%d' % num, '<suppressed>'))
                continue
            if name and (vendor, num) != (3076, 146):
                out.append((name, _value_words(name, kind, raw)))
            else:
                # As FreeRADIUS 2 writes an attribute it has no name for -
                # which is also how isemon reads the ASA's tunnel group.
                out.append(('Vendor-%d-Attr-%d' % (vendor, num), '0x' + raw.hex()))
        return out

    # ---- the passwords and the signatures ------------------------------------
    def password(self, secret):
        """User-Password, undone (RFC 2865 5.2)."""
        raw = self.get(2)
        if raw is None:
            return None
        if len(raw) % 16 or not raw:
            raise RadiusError('the User-Password is not a multiple of sixteen bytes')
        out = b''
        last = self.authenticator
        for at in range(0, len(raw), 16):
            block = raw[at:at + 16]
            pad = hashlib.md5(secret + last).digest()
            out += bytes(a ^ b for a, b in zip(block, pad))
            last = block
        return out.rstrip(b'\x00').decode('utf-8', 'replace')

    def message_authenticator_ok(self, secret, zero_authenticator=False):
        """True where it is right, False where it is wrong, None where there is
        none. Over the packet with the attribute's value as sixteen noughts -
        and, for an Accounting-Request (RFC 5080 2.2.4), the Request
        Authenticator as noughts too."""
        at = 20
        data = bytearray(self.raw)
        if zero_authenticator:
            data[4:20] = b'\x00' * 16
        found = None
        while at < len(data):
            kind, size = data[at], data[at + 1]
            if kind == 80:
                # One, of the one right length - anything else is wrong, not
                # missing (1.0.33): a mangled one was taken for none at all.
                if size != 18 or found is not None:
                    return False
                found = bytes(data[at + 2:at + 18])
                data[at + 2:at + 18] = b'\x00' * 16
            at += size
        if found is None:
            return None
        want = hmac.new(secret, bytes(data), hashlib.md5).digest()
        return hmac.compare_digest(found, want)

    def accounting_ok(self, secret):
        """An Accounting-Request's authenticator (RFC 2866 3)."""
        data = self.raw[:4] + b'\x00' * 16 + self.raw[20:]
        return hmac.compare_digest(hashlib.md5(data + secret).digest(), self.authenticator)


def build_reply(request, code, pairs, secret, with_ma=True):
    """An answer to `request`: its identifier, the attributes in `pairs`
    (already bytes), a Message-Authenticator where asked for (RFC 3579 3.2),
    and the Response Authenticator over all of it."""
    body = b''.join(pairs)
    # Every Proxy-State of the request back, unchanged and in order (RFC 2865
    # 5.33; 1.0.44): a proxy in between throws away an answer without it.
    for ps in (request.all(33) or []):
        body += bytes([33, len(ps) + 2]) + bytes(ps)
    if with_ma:
        # First, as the BlastRADIUS advice has it (1.0.33).
        body = bytes([80, 18]) + b'\x00' * 16 + body
    length = 20 + len(body)
    if length > 4096:
        raise RadiusError('the answer is longer than a RADIUS packet may be')
    head = struct.pack('>BBH', code, request.ident, length)
    if with_ma:
        ma = hmac.new(secret, head + request.authenticator + body, hashlib.md5).digest()
        body = body[:2] + ma + body[18:]
    auth = hashlib.md5(head + request.authenticator + body + secret).digest()
    return head + auth + body


def build_request(code, ident, pairs, secret, password=None, with_ma=True):
    """A request, as a client sends one - for `otp --radtest` and the test
    page. `password` goes in as User-Password, hidden the RFC 2865 way."""
    authenticator = secrets.token_bytes(16) if code != ACCOUNTING_REQUEST else b'\x00' * 16
    body = b''.join(pairs)
    if password is not None:
        pw = str(password).encode('utf-8')
        if len(pw) > 128:
            # RFC 2865 5.2 (1.0.59): past 128 bytes it was out of the rules,
            # past 240 the attribute's length broke.
            raise RadiusError('the password is longer than RADIUS carries (128 bytes)')
        pw += b'\x00' * ((16 - len(pw) % 16) % 16 or (16 if not pw else 0))
        out, last = b'', authenticator
        for at in range(0, len(pw), 16):
            pad = hashlib.md5(secret + last).digest()
            block = bytes(a ^ b for a, b in zip(pw[at:at + 16], pad))
            out += block
            last = block
        body += bytes([2, len(out) + 2]) + out
    if with_ma and code in (ACCESS_REQUEST, STATUS_SERVER):
        body += bytes([80, 18]) + b'\x00' * 16
    head = struct.pack('>BBH', code, ident, 20 + len(body))
    if code == ACCOUNTING_REQUEST:
        authenticator = hashlib.md5(head + b'\x00' * 16 + body + secret).digest()
    elif with_ma and code in (ACCESS_REQUEST, STATUS_SERVER):
        ma = hmac.new(secret, head + authenticator + body, hashlib.md5).digest()
        body = body[:-16] + ma
    return head + authenticator + body, authenticator


def reply_ok(reply, request_auth, secret):
    """Whether an answer really came from a server holding the secret."""
    if len(reply) < 20:
        return False
    # Up to the length the header says (1.0.59), as RFC 2865 3 reads it:
    # what pads the datagram after it is not the answer.
    size = struct.unpack('>H', reply[2:4])[0]
    if size < 20 or size > len(reply):
        return False
    reply = reply[:size]
    want = hashlib.md5(reply[:4] + request_auth + reply[20:] + secret).digest()
    if not hmac.compare_digest(want, reply[4:20]):
        return False
    # Its Message-Authenticator, where it has one, is right too (1.0.59) -
    # over the answer with the request's authenticator in its place.
    try:
        pkt = Packet.parse(reply[:4] + request_auth + reply[20:])
    except Exception:                                   # noqa: BLE001 - malformed
        return False
    return pkt.message_authenticator_ok(secret) is not False


def radius_ask(server, port, secret, user, password, nas_ip='127.0.0.1', timeout=5.0,
               tries=2, extra=(), code=ACCESS_REQUEST):
    """Ask a RADIUS server, the way radtest does. Returns (code, [(Name,
    value)], took_ms) or raises RadiusError."""
    secret_b = str(secret).encode('utf-8')
    pairs = []
    if user is not None:
        pairs.append(attr_bytes('User-Name', user))
    pairs.append(bytes([4, 6]) + socket.inet_aton(nas_ip))
    pairs.append(bytes([5, 6]) + struct.pack('>I', 0))
    for name, value in extra:
        pairs.append(attr_bytes(name, value))
    ident = secrets.randbelow(256)
    data, auth = build_request(code, ident, pairs, secret_b,
                               password=password if code == ACCESS_REQUEST else None)
    family = socket.AF_INET6 if ':' in str(server) else socket.AF_INET
    sock = socket.socket(family, socket.SOCK_DGRAM)
    sock.settimeout(float(timeout))
    began = time.time()
    try:
        bad = False
        for _ in range(max(1, int(tries))):
            sock.sendto(data, (server, int(port)))
            # One deadline per try (1.0.57): a stream of other packets reset
            # the timeout on every one and the wait never ended; a forged
            # answer is skipped, not taken for the server's.
            until = time.time() + float(timeout)
            reply = None
            while time.time() < until:
                sock.settimeout(max(0.05, until - time.time()))
                try:
                    got, src = sock.recvfrom(4096)
                except socket.timeout:
                    break
                if len(got) < 20 or got[1] != ident or got[0] not in (
                        ACCESS_ACCEPT, ACCESS_REJECT, ACCESS_CHALLENGE, ACCOUNTING_RESPONSE):
                    continue
                if not reply_ok(got, auth, secret_b):
                    bad = True
                    continue
                reply = got
                break
            if reply is None:
                continue
            pkt = Packet.parse(reply)
            return pkt.code, pkt.words(), int((time.time() - began) * 1000)
        if bad:
            raise RadiusError('an answer came, and it was not signed with that secret')
        raise RadiusError('no answer from %s:%s in %d tries of %.0f s - wrong secret, a '
                          'firewall, or this address is not one of its clients'
                          % (server, port, tries, timeout))
    finally:
        sock.close()


