def text_message(mid):
    return next((m for m in TEXT_MESSAGES if m['id'] == mid), None)


def text_defaults(group, lang):
    if group == 'token':
        return dict(MAIL_WORDS.get(lang) or MAIL_WORDS['cs'])
    return dict(CODE_TEXTS.get(lang) or CODE_TEXTS['cs'])


def text_saved(store, mid, lang):
    """What is saved for one message in one language: {'f': {...}, 'at', 'by'}."""
    try:
        got = json.loads(store.get_meta('texts:%s:%s' % (mid, lang)) or 'null')
    except ValueError:
        got = None
    if not isinstance(got, dict) or not isinstance(got.get('f'), dict):
        return {'f': {}, 'at': None, 'by': None}
    return got


def texts_for(group, lang):
    """The words of one group (code: the mails of codes, the SMS and the
    second window; token: the token's mail) in one language - the defaults
    with what was changed on the pages over them. Read again every few
    seconds; if the database cannot be asked, the defaults, never nothing."""
    lang = lang if lang in TEXT_LANGS else 'cs'
    key = (group, lang)
    now = time.time()
    with TEXT_LOCK:
        got = TEXT_CACHE.get(key)
        if got and now - got[0] < TEXT_CACHE_S:
            return dict(got[1])
    words = text_defaults(group, lang)
    store = HA_STORE.get('store')
    if store is not None:
        try:
            for m in TEXT_MESSAGES:
                if m['group'] != group:
                    continue
                keys = {f[0] for f in m['fields']}
                for k, v in text_saved(store, m['id'], lang)['f'].items():
                    if k in keys and isinstance(v, str):
                        words[k] = v
        except Exception as e:                          # noqa: BLE001
            log_sparing('texts', 'the message texts could not be read - the defaults are used: '
                        '%s' % str(e).split('\n')[0][:200], 'warn')
            return text_defaults(group, lang)
    with TEXT_LOCK:
        TEXT_CACHE[key] = (now, words)
    return dict(words)


def texts_forget():
    with TEXT_LOCK:
        TEXT_CACHE.clear()


# ---- what may be written ---------------------------------------------------------
class _RichClean(_html_parser.HTMLParser):
    """HTML of a text in a mail, kept to what mail programs show alike: bold,
    italic, underline, a colour, a link, a line break. Everything else goes,
    its text stays."""
    COLOR = re.compile(r'\s*(#[0-9a-fA-F]{3}|#[0-9a-fA-F]{6}|rgb\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,'
                       r'\s*\d{1,3}\s*\))\s*\Z')

    def __init__(self):
        _html_parser.HTMLParser.__init__(self, convert_charrefs=True)
        self.out = []
        self.stack = []

    @staticmethod
    def _style(attrs):
        st = {}
        for part in str(dict(attrs).get('style') or '').split(';'):
            k, _, v = part.partition(':')
            if k.strip():
                st[k.strip().lower()] = v.strip().lower()
        return st

    def _open_styled(self, st, color=None):
        opened = []
        c = color or st.get('color')
        if c and self.COLOR.match(c):
            self.out.append('<span style="color:%s">' % c.strip())
            opened.append('span')
        if st.get('font-weight') in ('bold', 'bolder', '600', '700', '800', '900'):
            self.out.append('<b>')
            opened.append('b')
        if st.get('font-style') == 'italic':
            self.out.append('<i>')
            opened.append('i')
        if 'underline' in (st.get('text-decoration') or '') + (st.get('text-decoration-line') or ''):
            self.out.append('<u>')
            opened.append('u')
        return opened

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == 'br':
            self.out.append('<br>')
            return
        if tag in ('b', 'strong'):
            self.out.append('<b>')
            self.stack.append((tag, ['b']))
        elif tag in ('i', 'em'):
            self.out.append('<i>')
            self.stack.append((tag, ['i']))
        elif tag == 'u':
            self.out.append('<u>')
            self.stack.append((tag, ['u']))
        elif tag == 'a':
            href = str(dict(attrs).get('href') or '').strip()
            if re.match(r'(https?://|mailto:)[^\s"<>]+\Z', href, re.I):
                self.out.append('<a href="%s" style="color:#1d4ed8">' % html.escape(href, quote=True))
                self.stack.append((tag, ['a']))
            else:
                self.stack.append((tag, []))
        elif tag in ('span', 'font'):
            st = self._style(attrs)
            self.stack.append((tag, self._open_styled(
                st, dict(attrs).get('color') if tag == 'font' else None)))
        elif tag in ('div', 'p'):
            # A new paragraph typed in the editor is a line break here.
            if self.out and not self.out[-1].endswith('<br>'):
                self.out.append('<br>')
            self.stack.append((tag, []))
        else:
            self.stack.append((tag, []))

    def handle_endtag(self, tag):
        tag = tag.lower()
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] == tag:
                while len(self.stack) > i:
                    _t, opened = self.stack.pop()
                    for o in reversed(opened):
                        self.out.append('</%s>' % o)
                return

    def handle_startendtag(self, tag, attrs):
        if tag.lower() == 'br':
            self.out.append('<br>')

    def handle_data(self, data):
        if any(t in ('script', 'style', 'title', 'head') for t, _o in self.stack):
            return
        self.out.append(html.escape(data, quote=False))

    def result(self):
        while self.stack:
            _t, opened = self.stack.pop()
            for o in reversed(opened):
                self.out.append('</%s>' % o)
        text = ''.join(self.out)
        text = re.sub(r'(<br>)+\Z', '', text)
        return re.sub(r'\A(<br>)+', '', text).strip()


def text_rich_clean(value):
    p = _RichClean()
    p.feed(str(value or ''))
    p.close()
    return p.result()


def text_samples(lang='cs'):
    site = str(CONFIG.get('site_name') or socket.gethostname())
    return {'code': '482913', 'minutes': max(1, int(CONFIG.get('code_ttl_s') or 300) // 60),
            'site': site, 'name': 'Jan Novák' if lang == 'cs' else 'Jan Novak',
            'account': 'jan.novak@example.cz', 'dest': 'j•••@example.cz',
            'digits': int(CONFIG.get('totp_digits') or 6), 'period': 30, 'by': 'admin'}


def text_check(field, value):
    """A field's new text, cleaned, or ValueError saying what is wrong."""
    key, kind, label, allowed, _where = field
    if value is not None and not isinstance(value, str):
        raise ValueError('%s: a piece of text' % label)
    value = str(value if value is not None else '')
    value = value.replace('\r\n', '\n').replace('\r', '\n')
    if kind != 'text':
        value = value.replace('\n', ' ')
    value = ''.join(c for c in value if c in '\n\t' or ord(c) >= 32)
    if kind == 'rich':
        value = text_rich_clean(value)
    else:
        value = value.strip() if kind == 'line' else value.strip('\n ')
    if len(value) > TEXT_MOST[kind]:
        raise ValueError('%s: at most %d characters' % (label, TEXT_MOST[kind]))
    try:
        parts = list(string.Formatter().parse(value))
    except ValueError:
        raise ValueError('%s: a { or } on its own - write it twice, {{ or }}' % label)
    for _lit, name, spec, conv in parts:
        if name is None:
            continue
        if name in allowed and (spec or conv):
            raise ValueError('%s: write {%s} with nothing after its name' % (label, name))
        if name not in allowed:
            raise ValueError('%s: {%s} is not something this text can have - it can have %s'
                             % (label, name, ', '.join('{%s}' % a for a in allowed) or 'none'))
    try:
        value.format(**text_samples())
    except (ValueError, IndexError, KeyError) as e:
        raise ValueError('%s: a { or } on its own - write it twice, {{ or }} (%s)' % (label, e))
    if field[4] == 'prompt' and len(value.format(**text_samples()).encode('utf-8')) > 253:
        raise ValueError('%s: longer than RADIUS carries (253 bytes)' % label)
    if field[4] in ('subject', 'sms', 'prompt') and not value.strip():
        raise ValueError('%s cannot be empty' % label)
    return value


# ---- what the editor shows -------------------------------------------------------
TEXT_MARK = '⟦f:%s⟧'


def text_words(mid, lang, fields=None, mark=False):
    """The words of a message's group with those of the editor (`fields`,
    not yet saved) over the saved ones; `mark`: each field of this message
    as a mark the editor puts its box in."""
    m = text_message(mid)
    w = texts_for(m['group'], lang)
    for k, v in (fields or {}).items():
        if any(f[0] == k for f in m['fields']):
            w[k] = v
    if mark:
        for f in m['fields']:
            w[f[0]] = TEXT_MARK % f[0]
    return w


def text_render(store, mid, lang, fields=None, mark=False):
    """A message as it would go out, with sample values: the mail's HTML,
    its subject and its text; the SMS; the second window's lines."""
    m = text_message(mid)
    w = text_words(mid, lang, fields, mark)
    smp = text_samples(lang)
    out = {'id': mid, 'lang': lang}
    if m['kind'] == 'mail' and m['group'] == 'code':
        out['html'] = code_mail_html(smp['code'], m['purpose'], lang, smp['account'], smp['name'],
                                     w=w)
        sub = w[code_purpose(m['purpose'])['subject']]
        body = w[code_purpose(m['purpose'])['body']]
        out['subject'] = sub.format(**smp)
        out['text'] = body.format(**smp)
    elif m['kind'] == 'mail':
        picture = {'issuer': smp['site'], 'digits': smp['digits'], 'period': smp['period'],
                   'secret': 'JBSWY3DPEHPK3PXP', 'secret_spaced': 'JBSW Y3DP EHPK 3PXP',
                   'label': smp['account'], 'uri': 'otpauth://totp/example?secret=JBSWY3DPEHPK3PXP'}
        msg = token_mail('preview@example.cz', smp['account'], picture,
                         codes=['10473829', '58261047', '39182754', '74629103', '21857364'],
                         lang=lang, display=smp['name'], by=smp['by'], pending=True, w=w)
        page = msg.get_payload()[1].get_payload()[0].get_content()
        # The pictures it carries, in the page itself for the preview.
        for part in msg.get_payload()[1].get_payload()[1:]:
            cid = str(part['Content-ID'] or '').strip('<>')
            data = base64.b64encode(part.get_payload(decode=True)).decode('ascii')
            page = page.replace('cid:%s' % cid, 'data:image/png;base64,%s' % data)
        out['html'] = page
        out['subject'] = str(msg['Subject'])
        out['text'] = msg.get_payload()[0].get_content()
    elif m['kind'] == 'sms':
        text = w[m['fields'][0][0]].format(**smp)
        out['sms'] = sms_plain(text)
        out['sms_written'] = text
    else:
        out['lines'] = {f[0]: w[f[0]].format(**dict(smp, dest=(
            '+420 6•• ••• 456' if f[0] == 'ask_sms' else smp['dest']))) for f in m['fields']}
    return out


def text_state(store, mid=None):
    """Every message, its fields, their defaults and what is saved now."""
    out = []
    for m in TEXT_MESSAGES:
        if mid and m['id'] != mid:
            continue
        one = {'id': m['id'], 'kind': m['kind'], 'title': m['title'], 'says': m['says'],
               'short': m.get('short') or m['title'],
               'fields': [], 'saved': {}}
        for lang in TEXT_LANGS:
            sv = text_saved(store, m['id'], lang)
            one['saved'][lang] = {'at': sv.get('at'), 'by': sv.get('by'),
                                  'changed': sorted(k for k in sv['f']
                                                    if any(f[0] == k for f in m['fields']))}
        for key, kind, label, allowed, where in m['fields']:
            f = {'key': key, 'kind': kind, 'label': label, 'where': where,
                 'placeholders': list(allowed), 'default': {}, 'value': {}}
            for lang in TEXT_LANGS:
                d = text_defaults(m['group'], lang).get(key, '')
                f['default'][lang] = d
                f['value'][lang] = text_saved(store, m['id'], lang)['f'].get(key, d)
            one['fields'].append(f)
        out.append(one)
    return out


def text_save(store, mid, lang, fields, by, was_at=None):
    """The fields of a message in one language saved; those equal to their
    default are not kept (so a default changed in a later version reaches
    them). Refused if somebody else saved it meanwhile (`was_at`)."""
    m = text_message(mid)
    if not m or lang not in TEXT_LANGS:
        raise ValueError('no such message or language')
    k = 'texts:%s:%s' % (mid, lang)
    raw = store.get_meta(k)
    now = text_saved(store, mid, lang)
    if was_at is not None and (now.get('at') or 0) != (was_at or 0):
        raise TextConflict('%s changed these words meanwhile (%s) - load them again'
                           % (now.get('by') or 'somebody', stamp(now.get('at'))))
    defaults = text_defaults(m['group'], lang)
    keep = dict(now['f'])
    for f in m['fields']:
        if f[0] not in fields:
            continue
        v = text_check(f, fields[f[0]])
        if v == defaults.get(f[0]):
            keep.pop(f[0], None)
        else:
            keep[f[0]] = v
    new = {'f': keep, 'at': time.time(), 'by': by}
    if raw is None:
        store.set_meta(k, json.dumps(new))
    elif not store.db.run('UPDATE meta SET v = ? WHERE k = ? AND v = ?', (json.dumps(new), k, raw)):
        raise TextConflict('somebody saved these words at the same moment - load them again')
    texts_forget()
    return new


def text_reset(store, mid, lang, keys=None):
    """A message in one language - or only `keys` of it - back to its default."""
    m = text_message(mid)
    if not m or lang not in TEXT_LANGS:
        raise ValueError('no such message or language')
    k = 'texts:%s:%s' % (mid, lang)
    if not keys:
        store.db.run('DELETE FROM meta WHERE k = ?', (k,))
    else:
        for _round in range(8):
            raw = store.get_meta(k)
            if raw is None:
                break
            now = text_saved(store, mid, lang)
            for key in keys:
                now['f'].pop(key, None)
            if store.db.run('UPDATE meta SET v = ? WHERE k = ? AND v = ?',
                            (json.dumps(dict(now, at=time.time())), k, raw)):
                break
    texts_forget()


class TextConflict(ValueError):
    pass


import ftplib
import tarfile


# ---------------------------------------------------------------------------
# Backups to another machine (1.0.109)
# ---------------------------------------------------------------------------
# One file that brings any loss back - one server or a cluster, onto a
# machine installed from nothing: the whole database (an engine-independent
# copy: tokens, settings, accounts, certificates, the web address, the
# firewall, the texts, the logs), the key that opens the tokens, the machine's
# config.json and the files it names, a manifest with the checksum of each,
# and RESTORE.md - the exact steps. Locked with a password kept in the
# settings (openssl enc, AES-256-CBC, PBKDF2-SHA256: opened with otp, or with
# openssl alone on any machine). RESTORE.md and a .sha256 also go beside it,
# not locked, so the steps can be read before anything is opened.
#
# Where they go: a folder (an NFS or other mount), FTP, FTPS (explicit or
# implicit), SFTP, SCP or SMB, each with its name and password, SSH keys made
# here or brought, the server's host key or certificate checked, a client
# certificate for FTPS. Each node makes and sends its own (its config.json is
# its own); old ones are taken away as kept-count and age say.
RB_KINDS = ('folder', 'ftp', 'ftps', 'sftp', 'scp', 'smb')
RB_KIND_WORDS = {'folder': 'a folder', 'ftp': 'FTP', 'ftps': 'FTPS', 'sftp': 'SFTP',
                 'scp': 'SCP (ssh)', 'smb': 'SMB (Windows share, Samba)'}
RB_PORTS = {'ftp': 21, 'ftps': 21, 'sftp': 22, 'scp': 22, 'smb': 445}
RB_SEALED = ('password', 'key', 'client_key', 'key_pass')
RB_BIND = 'rbackup'
RB_LOCK = threading.Lock()
RB_JOB = {'running': False, 'what': '', 'says': '', 'done': 0, 'whole': 0, 'error': '',
          'began': 0, 'ended': 0, 'result': None, 'by': ''}
RB_ITER = 600000
RB_NAME_RE = re.compile(r'^otp-backup-(?P<site>[A-Za-z0-9_.-]+?)-(?P<node>[A-Za-z0-9_.-]+)-'
                        r'(?P<stamp>\d{8}-\d{6})\.tar\.gz(?P<enc>\.enc)?\Z')
RB_TIMEOUT = 60


class RbError(Exception):
    pass


def rb_clean(text, what, most=200, pattern=None, empty=True):
    t = str(text if text is not None else '').strip()
    if not t and empty:
        return ''
    if len(t) > most or re.search(r'[\x00-\x1f\x7f]', t):
        raise ValueError('%s: at most %d characters, one line' % (what, most))
    if pattern and t and not re.match(pattern, t):
        raise ValueError('%s: %r is not one' % (what, t[:60]))
    return t


def rb_slug(text):
    return re.sub(r'[^A-Za-z0-9_.]+', '_', str(text or 'otp')).strip('_.')[:40] or 'otp'


# ---- the destinations ---------------------------------------------------------------
def rb_targets(store):
    try:
        got = json.loads(store.get_meta('rbackup:targets') or '[]')
    except ValueError:
        got = []
    return [t for t in got if isinstance(t, dict) and t.get('id')]


def rb_put_targets(store, targets):
    store.set_meta('rbackup:targets', json.dumps(targets))


def rb_target(store, tid):
    return next((t for t in rb_targets(store) if t['id'] == str(tid)), None)


def rb_secret(t, k):
    v = t.get(k) or ''
    return (unseal_secret(v, bind=RB_BIND) or '') if v else ''


def ssh_fingerprints(lines):
    """The SHA256 fingerprints of known_hosts lines, as ssh-keygen says them."""
    if not lines.strip() or not shutil.which('ssh-keygen'):
        return []
    got = subprocess.run(['ssh-keygen', '-lf', '-'], input=lines, capture_output=True,
                         text=True, timeout=20)
    return [x.strip() for x in got.stdout.splitlines() if x.strip()]


def rb_view(t):
    """A destination as the pages see it: nothing secret, what it has said."""
    out = {k: v for k, v in t.items() if k not in RB_SEALED}
    for k in RB_SEALED:
        out['has_' + k] = bool(t.get(k))
    out['kind_words'] = RB_KIND_WORDS.get(t.get('kind'), t.get('kind'))
    if t.get('password'):
        out['password'] = secret_shown(rb_secret(t, 'password'), last=True)
    if t.get('hostkey'):
        out['hostkey_fp'] = ssh_fingerprints(t['hostkey'])
    if t.get('client_cert'):
        try:
            out['client_cert_info'] = cert_info(t['client_cert'])
        except Exception:                               # noqa: BLE001
            out['client_cert_info'] = None
    if t.get('ca'):
        try:
            out['ca_info'] = cert_info(t['ca'])
        except Exception:                               # noqa: BLE001
            out['ca_info'] = None
    return out


def rb_checked(data, old=None):
    """A destination as typed on the pages, checked; secrets left out or as
    dots keep what was there."""
    old = dict(old or {})
    if not isinstance(data, dict):
        raise ValueError('a destination is an object')
    kind = str(data.get('kind') or old.get('kind') or '')
    if kind not in RB_KINDS:
        raise ValueError('the kind is one of %s' % ', '.join(RB_KINDS))
    t = {'id': old.get('id') or secrets.token_hex(6), 'kind': kind}
    t['name'] = rb_clean(data.get('name'), 'the name', 60) or \
        ('%s %s' % (RB_KIND_WORDS[kind], data.get('host') or data.get('path') or '')).strip()
    t['enabled'] = 1 if data.get('enabled', old.get('enabled', 1)) else 0
    t['path'] = rb_clean(data.get('path'), 'the folder', 400)
    if kind == 'folder':
        if not t['path'].startswith('/'):
            raise ValueError('the folder is a whole path on this machine (/mnt/backup/otp)')
        if re.search(r'(^|/)\.\.(/|$)', t['path']):
            raise ValueError('the folder has no .. in it')
    else:
        t['host'] = rb_clean(data.get('host'), 'the server', 253,
                             r'^[A-Za-z0-9][A-Za-z0-9.:_-]*\Z', empty=False)
        try:
            port = int(data.get('port') or RB_PORTS.get(kind) or 0)
        except (TypeError, ValueError):
            raise ValueError('the port is a number')
        if kind == 'ftps' and data.get('implicit') and not data.get('port'):
            port = 990
        if not 1 <= port <= 65535:
            raise ValueError('the port is 1 to 65535')
        t['port'] = port
        t['user'] = rb_clean(data.get('user'), 'the account', 128, r'^[^\s:@/\\]+\Z') or ''
        # Nothing a tool on the way reads as more (1.0.136): smbclient takes
        # ; as the next command whatever the quotes, ssh a leading - as an
        # option of its own.
        if t['user'].startswith('-'):
            raise ValueError('the account does not begin with -')
        if re.search(r'[;"]', t['path']) or t['path'].lstrip().startswith('-'):
            raise ValueError('the folder has no ; or " in it, and does not begin with -')
        if kind != 'smb' and re.search(r'(^|/)\.\.(/|$)', t['path']):
            raise ValueError('the folder has no .. in it')
        if kind == 'scp' and re.search(r'[^A-Za-z0-9._/~+@%=,-]', t['path']):
            # scp before OpenSSH 9 hands the far path to the shell there
            # (1.0.139): $( ), `, |, & and spaces ran or broke.
            raise ValueError('the folder (SCP) is letters, digits and . _ / ~ + @ % = , - '
                             'only - use SFTP for any other')
    pw = data.get('password')
    # The saved password goes only to the server it was saved for (1.0.149):
    # with another server typed in, Try it sent it there - to whoever the
    # administrator chose. Typed again for a new one.
    moved = bool(old) and (old.get('kind') != kind or
                           str(old.get('host') or '').lower() != str(t.get('host') or '').lower() or
                           int(old.get('port') or 0) != int(t.get('port') or 0))
    if (pw is None or is_masked(pw)) and moved and old.get('password'):
        raise ValueError('the server changed: type the password again')
    if pw is None or is_masked(pw):
        t['password'] = old.get('password') or ''
    else:
        pw = str(pw)
        if len(pw) > 512 or '\n' in pw or '\x00' in pw:
            raise ValueError('the password is one line, at most 512 characters')
        t['password'] = seal_secret(pw, bind=RB_BIND) if pw else ''
    if kind in ('sftp', 'scp'):
        for k in ('key', 'pub', 'ssh_cert', 'hostkey', 'key_pass'):
            if k in old:
                t[k] = old[k]
        if data.get('ssh_cert') is not None:
            c = str(data.get('ssh_cert') or '').strip()
            if c and not re.match(r'^[a-z0-9@.-]+-cert-v01@openssh\.com AAAA[A-Za-z0-9+/=]+( .*)?\Z',
                                  c):
                raise ValueError('the SSH certificate is the one line of a ...-cert.pub file')
            t['ssh_cert'] = c
    if kind in ('ftp', 'ftps'):
        t['passive'] = 0 if data.get('passive', old.get('passive', 1)) in (0, '0', False) else 1
    if kind == 'ftps':
        t['implicit'] = 1 if data.get('implicit', old.get('implicit')) else 0
        check = str(data.get('tls_check') or old.get('tls_check') or 'system')
        if check not in ('system', 'ca', 'pin', 'none'):
            raise ValueError('the server certificate is checked against system, ca, pin or none')
        t['tls_check'] = check
        for k in ('ca', 'pin', 'client_cert', 'client_key'):
            if k in old:
                t[k] = old[k]
        if data.get('ca') is not None:
            ca = str(data.get('ca') or '').strip()
            if ca and not PEM_CERT.search(ca):
                raise ValueError('the authority is a PEM certificate (-----BEGIN CERTIFICATE-----)')
            t['ca'] = '\n'.join(m.group(0) for m in PEM_CERT.finditer(ca)) + '\n' if ca else ''
        if data.get('pin') is not None:
            pin = re.sub(r'[^0-9A-Fa-f]', '', str(data.get('pin') or '')).lower()
            if pin and len(pin) != 64:
                raise ValueError('the pinned fingerprint is SHA-256: 64 hex digits')
            t['pin'] = pin
        if check == 'ca' and not t.get('ca'):
            raise ValueError('checked against an authority: give its certificate')
        if check == 'pin' and not t.get('pin'):
            raise ValueError('pinned: the fingerprint is needed - Try it shows the server\'s')
    if kind == 'smb':
        t['share'] = rb_clean(data.get('share'), 'the share', 80, r'^[^\\/:*?"<>|;-][^\\/:*?"<>|;]*\Z',
                              empty=False)
        t['domain'] = rb_clean(data.get('domain'), 'the domain', 64, r'^[A-Za-z0-9._-]+\Z')
        t['smb_encrypt'] = 1 if data.get('smb_encrypt', old.get('smb_encrypt', 1)) else 0
        if re.search(r'(^|[\\/])\.\.([\\/]|$)', t['path']):
            raise ValueError('the folder has no .. in it')
    for k in ('last', 'made'):
        if k in old:
            t[k] = old[k]
    return t


def rb_save(store, data, by):
    with RB_LOCK:
        targets = rb_targets(store)
        old = next((x for x in targets if x['id'] == str(data.get('id') or '')), None)
        if data.get('id') and not old:
            raise ValueError('no such destination')
        t = rb_checked(data, old)
        if old:
            targets = [t if x['id'] == t['id'] else x for x in targets]
        else:
            t['made'] = time.time()
            if len(targets) >= 20:
                raise ValueError('20 destinations at most')
            targets.append(t)
        rb_put_targets(store, targets)
    store.add_event('settings', '%s %s the backup destination %s (%s)' % (
        by, 'changed' if old else 'added', t['name'], RB_KIND_WORDS[t['kind']]), who=by)
    return t


def rb_set_fields(store, tid, by, said, **fields):
    with RB_LOCK:
        targets = rb_targets(store)
        t = next((x for x in targets if x['id'] == str(tid)), None)
        if not t:
            raise ValueError('no such destination')
        for k, v in fields.items():
            if v is None:
                t.pop(k, None)
            else:
                t[k] = v
        rb_put_targets(store, targets)
    if said:
        store.add_event('settings', '%s: the backup destination %s - %s' % (by, t['name'], said),
                        who=by)
    return t


def rb_delete(store, tid, by):
    with RB_LOCK:
        targets = rb_targets(store)
        t = next((x for x in targets if x['id'] == str(tid)), None)
        if not t:
            raise ValueError('no such destination')
        rb_put_targets(store, [x for x in targets if x['id'] != t['id']])
    store.add_event('settings', '%s took away the backup destination %s' % (by, t['name']),
                    'warn', who=by)


# ---- keys and certificates ----------------------------------------------------------
def ssh_keygen(comment):
    if not shutil.which('ssh-keygen'):
        raise ValueError('ssh-keygen is not on this machine (dnf install openssh-clients)')
    with tempfile.TemporaryDirectory(prefix='otp-key-') as d:
        path = os.path.join(d, 'k')
        got = subprocess.run(['ssh-keygen', '-q', '-t', 'ed25519', '-N', '', '-C', comment,
                              '-f', path], capture_output=True, text=True, timeout=30)
        if got.returncode != 0:
            raise ValueError('ssh-keygen: %s' % (got.stderr or got.stdout).strip()[:200])
        with open(path) as f:
            private = f.read()
        with open(path + '.pub') as f:
            public = f.read().strip()
    return private, public


def ssh_public_of(private, passphrase=''):
    """The public half of a private key given - and that it is one."""
    if not shutil.which('ssh-keygen'):
        raise ValueError('ssh-keygen is not on this machine (dnf install openssh-clients)')
    private = str(private or '').replace('\r\n', '\n').strip() + '\n'
    if 'PRIVATE KEY-----' not in private:
        raise ValueError('that is not a private key (-----BEGIN OPENSSH PRIVATE KEY----- or '
                         'another PEM private key)')
    with tempfile.TemporaryDirectory(prefix='otp-key-') as d:
        path = os.path.join(d, 'k')
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write(private)
        # The passphrase through SSH_ASKPASS, not on the command line where
        # `ps` shows it (1.0.136).
        env = dict(os.environ, DISPLAY=':0', SSH_ASKPASS_REQUIRE='force')
        if passphrase:
            ask = os.path.join(d, 'ask')
            with open(ask, 'w') as f:
                f.write('#!/bin/sh\nprintf "%s\\n" "$OTP_RB_SECRET"\n')
            os.chmod(ask, 0o700)
            env.update(SSH_ASKPASS=ask, OTP_RB_SECRET=passphrase)
            argv = ['ssh-keygen', '-y', '-f', path]
        else:
            argv = ['ssh-keygen', '-y', '-P', '', '-f', path]
        got = subprocess.run(argv, capture_output=True, text=True, timeout=20, env=env,
                             stdin=subprocess.DEVNULL)
    if got.returncode != 0:
        said = (got.stderr or got.stdout).strip()
        if 'passphrase' in said.lower() or 'incorrect' in said.lower():
            raise ValueError('the key is locked with a passphrase: give it too')
        raise ValueError('ssh-keygen does not read it: %s' % said[:200])
    return private, got.stdout.strip()


def rb_client_cert_make(cn, days=1825):
    """A key and a self-signed client certificate for FTPS."""
    key = new_key('ec')
    with tempfile.TemporaryDirectory(prefix='otp-crt-') as d:
        kf = os.path.join(d, 'k.pem')
        with open(kf, 'w') as f:
            f.write(key)
        os.chmod(kf, 0o600)
        cn = re.sub(r'[^A-Za-z0-9.@_-]', '', str(cn or 'otp-backup'))[:64] or 'otp-backup'
        crt = _openssl(['req', '-new', '-x509', '-key', kf, '-days', str(int(days)), '-subj',
                        '/CN=' + cn, '-addext', 'extendedKeyUsage=clientAuth',
                        '-addext', 'keyUsage=critical,digitalSignature'],
                       what='the certificate').decode()
    return key, crt


def rb_client_cert_given(text, password=''):
    """A client certificate brought: PEM (certificate and key, in any order)
    or PFX (base64 of it, with its password)."""
    text = str(text or '').strip()
    if 'BEGIN' in text:
        certs = [m.group(0) for m in PEM_CERT.finditer(text)]
        m = re.search(r'-----BEGIN (?:[A-Z ]*)PRIVATE KEY-----[\s\S]+?-----END (?:[A-Z ]*)'
                      r'PRIVATE KEY-----', text)
        if not certs or not m:
            raise ValueError('a client certificate needs its certificate and its private key')
        key = m.group(0) + '\n'
        if 'ENCRYPTED' in key:
            key = _openssl(['pkey', '-passin', 'env:OTP_PW'], key.encode(),
                           env={'OTP_PW': password}, what='the key (its password)').decode()
        if _pub_of_key(key).strip() != _pub_of_cert(certs[0]).strip():
            raise ValueError('the key is not the one of this certificate')
        return key, '\n'.join(certs) + '\n'
    try:
        pfx = base64.b64decode(text, validate=False)
    except (binascii.Error, ValueError):
        raise ValueError('neither PEM nor PFX')
    with tempfile.TemporaryDirectory(prefix='otp-pfx-') as d:
        pf = os.path.join(d, 'c.pfx')
        with open(pf, 'wb') as f:
            f.write(pfx)
        both = ''
        for extra in ([], ['-legacy']):
            try:
                both = _openssl(['pkcs12', '-in', pf, '-nodes', '-passin', 'env:OTP_PW'] + extra,
                                env={'OTP_PW': password}, what='the PFX (its password?)').decode()
                break
            except ValueError:
                if extra:
                    raise
    return rb_client_cert_given(both)


# ---- the transports ------------------------------------------------------------------
class RbFolder(object):
    def __init__(self, t):
        self.t = t
        self.dir = t['path']

    def open(self):
        try:
            os.makedirs(self.dir, exist_ok=True)
        except OSError as e:
            raise RbError('the folder %s cannot be made: %s' % (self.dir, e))
        if not os.access(self.dir, os.W_OK):
            raise RbError('the otp account may not write into %s' % self.dir)

    def put(self, local, name):
        part = os.path.join(self.dir, '.%s.part' % name)
        shutil.copyfile(local, part)
        os.chmod(part, 0o640)
        os.replace(part, os.path.join(self.dir, name))

    def get(self, name, local):
        shutil.copyfile(os.path.join(self.dir, rb_safe_name(name)), local)

    def list(self):
        out = []
        for e in os.scandir(self.dir):
            if e.is_file() and not e.name.startswith('.'):
                st = e.stat()
                out.append({'name': e.name, 'size': st.st_size, 'mtime': st.st_mtime})
        return out

    def delete(self, name):
        os.unlink(os.path.join(self.dir, rb_safe_name(name)))

    def close(self):
        pass


def rb_safe_name(name):
    name = str(name or '')
    if not re.match(r'^[A-Za-z0-9][A-Za-z0-9_.-]{0,200}\Z', name):
        raise RbError('not a file name of a backup: %r' % name[:80])
    return name


class _ImplicitFTP_TLS(ftplib.FTP_TLS):
    """FTPS on its own port (990): TLS from the first byte."""
    def connect(self, host='', port=0, timeout=-999, source_address=None):
        if host:
            self.host = host
        if port > 0:
            self.port = port
        if timeout != -999:
            self.timeout = timeout
        self.sock = socket.create_connection((self.host, self.port), self.timeout)
        self.af = self.sock.family
        self.sock = self.context.wrap_socket(self.sock, server_hostname=self.host)
        self.file = self.sock.makefile('r', encoding=self.encoding)
        self.welcome = self.getresp()
        return self.welcome


class _ReuseMixin(object):
    """The data connection resumes the control connection's TLS session:
    vsftpd, ProFTPD and FileZilla Server refuse one that does not (522)."""
    def ntransfercmd(self, cmd, rest=None):
        conn, size = ftplib.FTP.ntransfercmd(self, cmd, rest)
        if self._prot_p:
            conn = self.context.wrap_socket(conn, server_hostname=self.host,
                                            session=self.sock.session)
        return conn, size


class RbFtpTls(_ReuseMixin, ftplib.FTP_TLS):
    pass


class RbFtpTlsImplicit(_ReuseMixin, _ImplicitFTP_TLS):
    pass


class RbFtp(object):
    def __init__(self, t):
        self.t = t
        self.ftp = None
        self.tmp = None
        self.seen = {}

    def _context(self):
        t = self.t
        check = t.get('tls_check') or 'system'
        if check == 'ca':
            ctx = ssl.create_default_context(cadata=t.get('ca') or '')
        elif check == 'system':
            ctx = ssl.create_default_context()
        else:
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
        if t.get('client_cert') and t.get('client_key'):
            self.tmp = tempfile.mkdtemp(prefix='otp-ftps-')
            cf, kf = os.path.join(self.tmp, 'c.pem'), os.path.join(self.tmp, 'k.pem')
            with open(cf, 'w') as f:
                f.write(t['client_cert'])
            fd = os.open(kf, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, 'w') as f:
                f.write(rb_secret(t, 'client_key'))
            ctx.load_cert_chain(cf, kf)
        return ctx

    def open(self):
        t = self.t
        try:
            if t['kind'] == 'ftps':
                cls = RbFtpTlsImplicit if t.get('implicit') else RbFtpTls
                self.ftp = cls(context=self._context(), timeout=RB_TIMEOUT)
                self.ftp.connect(t['host'], int(t['port']))
                if not t.get('implicit'):
                    self.ftp.auth()
                der = self.ftp.sock.getpeercert(True)
                fp = hashlib.sha256(der).hexdigest() if der else ''
                self.seen = {'fingerprint': fp}
                try:
                    pem = ssl.DER_cert_to_PEM_cert(der)
                    self.seen['cert'] = cert_info(pem)
                except Exception:                       # noqa: BLE001
                    pass
                if (t.get('tls_check') == 'pin') and fp != (t.get('pin') or ''):
                    raise RbError('the server answers with another certificate than the one '
                                  'pinned (SHA-256 %s)' % fp)
            else:
                self.ftp = ftplib.FTP(timeout=RB_TIMEOUT)
                self.ftp.connect(t['host'], int(t['port']))
            self.ftp.login(t.get('user') or 'anonymous', rb_secret(t, 'password'))
            if t['kind'] == 'ftps':
                self.ftp.prot_p()
            self.ftp.set_pasv(bool(t.get('passive', 1)))
            self._cd(t.get('path') or '')
        except ssl.SSLCertVerificationError as e:
            raise RbError('the server\'s certificate is not trusted: %s - check it against '
                          'its authority, or pin it' % e.verify_message)
        except ftplib.error_perm as e:
            raise RbError('the FTP server said: %s' % str(e)[:200])
        except (OSError, EOFError, ftplib.Error) as e:
            raise RbError(str(e)[:200] or e.__class__.__name__)

    def _cd(self, path):
        if not path:
            return
        if path.startswith('/'):
            self.ftp.cwd('/')
        for part in [p for p in path.split('/') if p]:
            try:
                self.ftp.cwd(part)
            except ftplib.error_perm:
                self.ftp.mkd(part)
                self.ftp.cwd(part)

    def put(self, local, name):
        with open(local, 'rb') as f:
            self.ftp.storbinary('STOR .%s.part' % name, f, blocksize=262144)
        try:
            self.ftp.delete(name)
        except ftplib.error_perm:
            pass
        self.ftp.rename('.%s.part' % name, name)

    def get(self, name, local):
        with open(local, 'wb') as f:
            self.ftp.retrbinary('RETR %s' % rb_safe_name(name), f.write, blocksize=262144)

    def list(self):
        out = []
        try:
            for name, facts in self.ftp.mlsd(facts=['type', 'size', 'modify']):
                if facts.get('type') == 'file':
                    m = facts.get('modify') or ''
                    try:
                        mt = datetime.strptime(m[:14], '%Y%m%d%H%M%S').replace(
                            tzinfo=timezone.utc).timestamp()
                    except ValueError:
                        mt = 0
                    out.append({'name': name, 'size': int(facts.get('size') or 0), 'mtime': mt})
            return out
        except ftplib.error_perm:
            pass
        for name in self.ftp.nlst():
            name = name.rsplit('/', 1)[-1]
            if name in ('.', '..'):
                continue
            try:
                size = self.ftp.size(name) or 0
            except ftplib.error_perm:
                continue            # a folder
            out.append({'name': name, 'size': size, 'mtime': 0})
        return out

    def delete(self, name):
        self.ftp.delete(rb_safe_name(name))

    def close(self):
        try:
            if self.ftp:
                self.ftp.quit()
        except Exception:                               # noqa: BLE001
            try:
                self.ftp.close()
            except Exception:                           # noqa: BLE001
                pass
        if self.tmp:
            shutil.rmtree(self.tmp, ignore_errors=True)


def ssh_keyscan(host, port):
    """The server's host keys, as known_hosts lines - and their fingerprints."""
    if not shutil.which('ssh-keyscan'):
        raise ValueError('ssh-keyscan is not on this machine (dnf install openssh-clients)')
    got = subprocess.run(['ssh-keyscan', '-T', '10', '-p', str(int(port)), host],
                         capture_output=True, text=True, timeout=30)
    lines = [x for x in got.stdout.splitlines() if x.strip() and not x.startswith('#')]
    if not lines:
        raise ValueError('%s:%s did not show a host key: %s' % (
            host, port, (got.stderr or '').strip().splitlines()[-1:] or 'no answer'))
    return '\n'.join(lines) + '\n', ssh_fingerprints('\n'.join(lines) + '\n')


class RbSsh(object):
    """SFTP (the sftp program) or SCP (scp, and ssh for the list and the
    deleting) - OpenSSH itself, the server's host key checked against the one
    trusted on the pages, a key of its own or a password."""
    def __init__(self, t):
        self.t = t
        self.d = None

    def open(self):
        t = self.t
        tools = ['ssh'] + (['sftp'] if t['kind'] == 'sftp' else ['scp'])
        for tool in tools:
            if not shutil.which(tool):
                raise RbError('%s is not on this machine (dnf install openssh-clients)' % tool)
        if not t.get('hostkey'):
            raise RbError('the server\'s host key is not trusted yet: Try it, then trust the '
                          'fingerprint it shows')
        self.d = tempfile.mkdtemp(prefix='otp-ssh-')
        kh = os.path.join(self.d, 'known_hosts')
        with open(kh, 'w') as f:
            f.write(t['hostkey'])
        self.opts = ['-o', 'StrictHostKeyChecking=yes', '-o', 'UserKnownHostsFile=' + kh,
                     '-o', 'GlobalKnownHostsFile=/dev/null', '-o', 'ConnectTimeout=20',
                     '-o', 'ServerAliveInterval=15', '-o', 'ServerAliveCountMax=4',
                     '-o', 'LogLevel=ERROR', '-o', 'IdentitiesOnly=yes', '-F', '/dev/null']
        key = rb_secret(t, 'key')
        if key:
            kf = os.path.join(self.d, 'id')
            fd = os.open(kf, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, 'w') as f:
                f.write(key if key.endswith('\n') else key + '\n')
            self.opts += ['-i', kf]
            if t.get('ssh_cert'):
                cf = os.path.join(self.d, 'id-cert.pub')
                with open(cf, 'w') as f:
                    f.write(t['ssh_cert'] + '\n')
                self.opts += ['-o', 'CertificateFile=' + cf]
        else:
            self.opts += ['-o', 'IdentityFile=/dev/null']
        # A password (or the key's passphrase) through SSH_ASKPASS: never on
        # a command line, never in a file of the otp account's.
        self.env = dict(os.environ, DISPLAY=':0', SSH_ASKPASS_REQUIRE='force')
        # Each prompt its own answer (1.0.139): with a password and a key that
        # has a passphrase, the password went to the key, and the key failed.
        pw = rb_secret(t, 'password') or rb_secret(t, 'key_pass')
        kp = rb_secret(t, 'key_pass') or rb_secret(t, 'password')
        ask = os.path.join(self.d, 'ask')
        with open(ask, 'w') as f:
            f.write('#!/bin/sh\ncase "$1" in\n  *assphrase*) printf "%s\\n" "$OTP_RB_KEYPASS";;\n'
                    '  *) printf "%s\\n" "$OTP_RB_SECRET";;\nesac\n')
        os.chmod(ask, 0o700)
        self.env.update(SSH_ASKPASS=ask, OTP_RB_SECRET=pw, OTP_RB_KEYPASS=kp)
        auths = ['publickey'] if key else []
        if rb_secret(t, 'password'):
            auths += ['password', 'keyboard-interactive']
        if not auths:
            raise RbError('neither a key nor a password is set')
        self.opts += ['-o', 'PreferredAuthentications=' + ','.join(auths),
                      '-o', 'NumberOfPasswordPrompts=1']
        if rb_secret(t, 'password') or rb_secret(t, 'key_pass'):
            # sftp -b asks ssh for batch mode, which takes no password; the
            # first value given wins, and this comes first.
            self.opts += ['-o', 'BatchMode=no']
        host = str(t['host']).strip('[]')
        self.dest = '%s@%s' % (t.get('user') or 'root', host)
        # scp and sftp read user@host:path - an IPv6 address in brackets
        # there (1.0.146), ssh takes it bare.
        self.rdest = '%s@[%s]' % (t.get('user') or 'root', host) if ':' in host else self.dest
        self.dir = (t.get('path') or '').rstrip('/') or '.'
        # Signed in and the folder made, at once - the errors said here.
        if t['kind'] == 'sftp':
            parts = [p for p in self.dir.split('/') if p and p != '.']
            cmds = []
            acc = '/' if self.dir.startswith('/') else ''
            for p in parts:
                acc = (acc + '/' + p) if acc not in ('', '/') else (acc + p)
                cmds.append('-mkdir "%s"' % acc)
            cmds.append('cd "%s"' % self.dir)
            self._sftp(cmds)
        else:
            self._ssh('mkdir -p -- %s && test -w %s' % (shlex_quote(self.dir),
                                                        shlex_quote(self.dir)))

    def _run(self, args, what, stdin=None, timeout=3600):
        got = subprocess.run(args, input=stdin, capture_output=True, text=True,
                             timeout=timeout, env=self.env, start_new_session=True)
        if got.returncode != 0:
            said = (got.stderr or got.stdout or '').strip().splitlines()
            said = [x for x in said if x.strip() and not x.startswith('Warning: Permanently')]
            tail = ' / '.join(said[-3:])[:300] or 'it said nothing (exit %d)' % got.returncode
            if 'Host key verification failed' in tail or 'REMOTE HOST IDENTIFICATION' in tail:
                tail = ('the server shows another host key than the one trusted - if it was '
                        'reinstalled on purpose, Try it and trust the new one')
            elif 'Permission denied' in tail:
                tail = 'the server did not let the account in (%s)' % tail
            raise RbError('%s: %s' % (what, tail))
        return got.stdout

    def _ssh(self, command):
        return self._run(['ssh'] + self.opts + ['-p', str(int(self.t['port'])), self.dest,
                                                command], 'ssh')

    def _sftp(self, cmds, timeout=3600):
        batch = os.path.join(self.d, 'batch')
        with open(batch, 'w') as f:
            f.write('\n'.join(cmds) + '\n')
        return self._run(['sftp'] + self.opts + ['-P', str(int(self.t['port'])), '-b', batch,
                                                 self.rdest], 'sftp', timeout=timeout)

    def put(self, local, name):
        name = rb_safe_name(name)
        if self.t['kind'] == 'sftp':
            self._sftp(['cd "%s"' % self.dir, 'put "%s" ".%s.part"' % (local, name),
                        '-rm "%s"' % name, 'rename ".%s.part" "%s"' % (name, name)])
        else:
            self._run(['scp'] + self.opts + ['-P', str(int(self.t['port'])), '-q', local,
                                             '%s:%s/.%s.part' % (self.rdest, self.dir, name)],
                      'scp')
            self._ssh('mv -f -- %s %s' % (shlex_quote('%s/.%s.part' % (self.dir, name)),
                                          shlex_quote('%s/%s' % (self.dir, name))))

    def get(self, name, local):
        name = rb_safe_name(name)
        if self.t['kind'] == 'sftp':
            self._sftp(['cd "%s"' % self.dir, 'get "%s" "%s"' % (name, local)])
        else:
            self._run(['scp'] + self.opts + ['-P', str(int(self.t['port'])), '-q',
                                             '%s:%s/%s' % (self.rdest, self.dir, name), local],
                      'scp')

    def list(self):
        if self.t['kind'] == 'sftp':
            text = self._sftp(['cd "%s"' % self.dir, 'ls -ln'])
        else:
            text = self._ssh('LC_ALL=C ls -ln -- %s' % shlex_quote(self.dir))
        out = []
        for line in text.splitlines():
            f = line.split(None, 8)
            if len(f) == 9 and f[0].startswith('-'):
                name = f[8].rsplit('/', 1)[-1]
                try:
                    out.append({'name': name, 'size': int(f[4]), 'mtime': 0})
                except ValueError:
                    pass
        return out

    def delete(self, name):
        name = rb_safe_name(name)
        if self.t['kind'] == 'sftp':
            self._sftp(['cd "%s"' % self.dir, 'rm "%s"' % name])
        else:
            self._ssh('rm -f -- %s' % shlex_quote('%s/%s' % (self.dir, name)))

    def close(self):
        if self.d:
            shutil.rmtree(self.d, ignore_errors=True)


class RbSmb(object):
    """SMB through smbclient: an authentication file of its own (never the
    password on a command line), SMB2 at least, SMB3 encryption when asked."""
    def __init__(self, t):
        self.t = t
        self.d = None

    def open(self):
        t = self.t
        if not shutil.which('smbclient'):
            raise RbError('smbclient is not on this machine (dnf install samba-client)')
        self.d = tempfile.mkdtemp(prefix='otp-smb-')
        auth = os.path.join(self.d, 'auth')
        fd = os.open(auth, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write('username = %s\npassword = %s\n' % (t.get('user') or 'guest',
                                                       rb_secret(t, 'password')))
            if t.get('domain'):
                f.write('domain = %s\n' % t['domain'])
        self.args = ['smbclient', '//%s/%s' % (t['host'], t['share']), '-A', auth,
                     '-p', str(int(t['port'])), '--option=client min protocol=SMB2',
                     '-t', str(RB_TIMEOUT)]
        if t.get('smb_encrypt'):
            self.args += ['--client-protection=encrypt']
        self.dir = (t.get('path') or '').replace('/', '\\').strip('\\')
        cmds = []
        acc = ''
        for p in [x for x in self.dir.split('\\') if x]:
            acc = (acc + '\\' + p) if acc else p
            cmds.append('mkdir "%s"' % acc)
        self._run(cmds + ['cd "\\%s"' % self.dir, 'ls'], ignore=('NT_STATUS_OBJECT_NAME_COLLISION',))

    def _run(self, cmds, ignore=(), timeout=3600):
        got = subprocess.run(self.args + ['-c', '; '.join(cmds)], capture_output=True, text=True,
                             timeout=timeout, cwd=self.d, start_new_session=True)
        text = (got.stdout or '') + (got.stderr or '')
        bad = [x for x in text.splitlines() if 'NT_STATUS_' in x and
               not any(i in x for i in ignore)]
        if got.returncode != 0 or bad:
            said = ' / '.join((bad or text.strip().splitlines() or ['no answer'])[-2:])[:300]
            if 'NT_STATUS_LOGON_FAILURE' in said:
                said = 'the server did not take the account and password (%s)' % said
            elif 'NT_STATUS_BAD_NETWORK_NAME' in said:
                said = 'there is no share %s on %s' % (self.t['share'], self.t['host'])
            elif 'protection' in said.lower() and 'unknown' in said.lower():
                said = ('this smbclient does not know --client-protection: switch "SMB3 '
                        'encryption required" off or install a newer samba-client')
            raise RbError('smbclient: %s' % said)
        return got.stdout or ''

    def _cd(self):
        return 'cd "\\%s"' % self.dir

    def put(self, local, name):
        name = rb_safe_name(name)
        self._run([self._cd(), 'put "%s" ".%s.part"' % (local, name), 'del "%s"' % name,
                   'rename ".%s.part" "%s"' % (name, name)], ignore=('NT_STATUS_NO_SUCH_FILE',
                                                                   'NT_STATUS_OBJECT_NAME_NOT_FOUND'))

    def get(self, name, local):
        self._run([self._cd(), 'get "%s" "%s"' % (rb_safe_name(name), local)])

    def list(self):
        out = []
        for line in self._run([self._cd(), 'ls']).splitlines():
            m = re.match(r'^\s\s(.+?)\s+([ADHNRS]*)\s+(\d+)\s+(\w{3} \w{3}\s+\d+ [\d:]+ \d{4})\s*$',
                         line)
            if m and 'D' not in m.group(2) and m.group(1) not in ('.', '..'):
                try:
                    mt = datetime.strptime(re.sub(r'\s+', ' ', m.group(4)),
                                           '%a %b %d %H:%M:%S %Y').timestamp()
                except ValueError:
                    mt = 0
                out.append({'name': m.group(1), 'size': int(m.group(3)), 'mtime': mt})
        return out

    def delete(self, name):
        self._run([self._cd(), 'del "%s"' % rb_safe_name(name)])

    def close(self):
        if self.d:
            shutil.rmtree(self.d, ignore_errors=True)


def rb_said(e):
    """An error in words, whatever library raised it."""
    if isinstance(e, EOFError):
        return 'the server closed the connection'
    if isinstance(e, socket.timeout):
        return 'the server did not answer in time'
    if isinstance(e, ssl.SSLCertVerificationError):
        return ('the server\'s certificate is not trusted: %s - check it against its authority, '
                'or pin it' % e.verify_message)
    if isinstance(e, ftplib.Error):
        return 'the FTP server said: %s' % str(e)[:300]
    return scrub_secret(str(e) or e.__class__.__name__)[:400]


def rb_transport(t):
    return {'folder': RbFolder, 'ftp': RbFtp, 'ftps': RbFtp, 'sftp': RbSsh, 'scp': RbSsh,
            'smb': RbSmb}[t['kind']](t)


def rb_try(t):
    """Signed in, a small file written, seen in the list, taken away again."""
    out = {'ok': False, 'steps': []}
    began = time.time()
    tr = rb_transport(t)
    try:
        tr.open()
        out['steps'].append('signed in, the folder is there')
        if getattr(tr, 'seen', None):
            out['server_cert'] = tr.seen
        name = 'otp-try-%s-%s.txt' % (rb_slug(node_name()), secrets.token_hex(4))
        with tempfile.NamedTemporaryFile('w', prefix='otp-try-', delete=False) as f:
            f.write('otp %s on %s tried this destination at %s - this file is taken away again\n'
                    % (__version__, node_name(), datetime.now().isoformat(timespec='seconds')))
            local = f.name
        try:
            tr.put(local, name)
        finally:
            os.unlink(local)
        out['steps'].append('a file written')
        names = [x['name'] for x in tr.list()]
        if name not in names:
            raise RbError('the file written is not in the list the server gives')
        out['steps'].append('it is in the list (%d file(s) there)' % len(names))
        tr.delete(name)
        out['steps'].append('taken away again')
        out['ok'] = True
    except Exception as e:                              # noqa: BLE001
        out['error'] = rb_said(e)
        if getattr(tr, 'seen', None):
            out['server_cert'] = tr.seen
    finally:
        tr.close()
    out['secs'] = round(time.time() - began, 1)
    return out


# ---- the backup itself -----------------------------------------------------------------
def rb_password():
    # Sealed in config.json like the other passwords: until 1.0.139 the sealed
    # text itself locked the backups - not the password typed, so a new
    # machine could not open them.
    pw = str(CONFIG.get('rbackup_password') or '')
    return (unseal_secret(pw) or '') if pw else ''


def rb_password_old():
    """What locked the backups made here before 1.0.139: the sealed text."""
    pw = str(CONFIG.get('rbackup_password') or '')
    return pw if pw.startswith((SEALED, SEALED2)) else ''


def rb_files_named():
    """Files config.json names that live outside the database: the
    authority of a database on another machine."""
    out = []
    for k in ('db_tls_ca',):
        p = str(CONFIG.get(k) or '')
        if p and os.path.isfile(p):
            out.append(p)
    return out


def rb_restore_md(m):
    """RESTORE.md: the exact steps, filled in with what this backup is."""
    enc = m.get('encrypted')
    name = m['file']
    tar = name[:-4] if enc else name
    ha = m.get('ha_mode') == 'replicated'
    site, node, ver = m.get('site') or 'otp', m.get('node') or '?', m.get('otp') or '?'
    lines = [
        '# Restoring otp from %s' % name, '',
        '| | |', '|---|---|',
        '| Made | %s |' % m.get('made_words'),
        '| Installation | %s |' % site,
        '| Node | %s (%s) |' % (node, m.get('host') or ''),
        '| otp | %s |' % ver,
        '| Database | %s |' % m.get('engine_words'),
        '| Cluster | %s |' % (('two nodes, replicated - this is node %s of 2; the other was %s'
                               % (m.get('ha_slot'), m.get('ha_peer'))) if ha else
                              ('two nodes, one shared database' if m.get('ha_mode') == 'shared'
                               else 'one server')),
        '| Locked | %s |' % ('yes - AES-256-CBC, PBKDF2-SHA256, %d rounds (openssl enc)'
                             % RB_ITER if enc else '**no** - anybody with the file has every '
                             'token: keep it as you would the server'),
        '| Tokens | %s |' % m.get('tokens', '?'),
        '', 'Everything is in it: the whole database (tokens and their recovery codes, the RADIUS',
        'clients, realms, directories, accounts, every setting, the certificates and keys of the',
        'pages, the web address, the firewall, the message texts, the logs), the key that opens',
        'the tokens (`secrets.key`) and this machine\'s `/etc/otp/config.json`.', '',
        'Keep the password of the backups apart from the backups (a password vault): without it',
        'the file cannot be opened - by anybody.', '',
        '## 0. Check the file', '', '```bash',
        'sha256sum -c %s.sha256          # "%s: OK"' % (name, name), '```', '',
    ]
    if enc:
        lines += ['## 1. Open it', '',
                  'otp opens it by itself (step 3). With openssl alone, on any machine:', '',
                  '```bash',
                  'openssl enc -d -aes-256-cbc -pbkdf2 -iter %d -md sha256 -in %s -out %s'
                  % (RB_ITER, name, tar),
                  '# it asks for the password of the backups',
                  'tar tzf %s                    # what is inside' % tar, '```', '']
    else:
        lines += ['## 1. It is not locked', '', '```bash',
                  'tar tzf %s' % tar, '```', '']
    lines += [
        'Inside: `otp-copy.json.gz` (the database, in a shape SQLite, MariaDB and PostgreSQL',
        'all take), `secrets.key`, `config.json`, `manifest.json` (a checksum of each file),',
        'this file, and the files config.json names (`files/`).', '',
        '## 2. A machine to put it on', '',
        'AlmaLinux / Rocky / RHEL 9 (or the machine it came from). Install otp **%s or newer**' % ver,
        'from its package - the same way as the first time:', '', '```bash',
        'tar xzf otp-%s.tar.gz && cd otp-%s' % (ver, ver),
        './install.sh                     # SQLite unless you choose otherwise',
        '```', '',
        'The backup goes into whichever database the new machine uses - SQLite after a plain',
        'install is fine. PostgreSQL (needed again for a cluster) can be chosen afterwards:',
        '`./install.sh --with-db postgres --yes`, then *Settings → The database → Try it → Set it',
        'up → Carry everything across → Start using it* (PostgreSQL 16 or later).', '',
        '## 3. Put it back', '', '```bash',
        'otp --restore-bundle %s          # shows what is in it, asks for the password' % name,
        'otp --restore-bundle %s --yes    # puts it back' % name,
        'systemctl restart otp', '```', '',
        'The password may come from a file instead (`--passphrase-file FILE`, one line) or from',
        'the environment (`OTP_BACKUP_PASSWORD`).', '',
        'What it does: a copy of what the new machine has is made first; then the database is',
        'replaced with the one in the backup, `secrets.key` is put in place and the node keeps',
        'its name (`%s`). The new machine\'s own database connection in config.json stays as' % node,
        'it is - it belongs to the new machine. The other files config.json named are in `files/`.',
        '',
    ]
    if ha:
        lines += [
            '## 4. A cluster of two', '',
            '- **One node lost, the other alive:** do not put this back. Install the lost node',
            '  again and join it to the living one - it copies every row from it:',
            '  `otp --ha-bundle FILE` on the living node, `otp --ha-join FILE` on the new one',
            '  (docs/high-availability.md, "When a node is lost").',
            '- **Both lost:** put this backup back on one new machine (steps 2-3). It comes back as',
            '  one server with everything. Move it to PostgreSQL (step 2), then make it two again:',
            '  `otp --ha-setup --ha-peer ADDRESS-OF-THE-SECOND --node-name %s` on it; on the' % node,
            '  second `./install.sh --with-db postgres --yes` and `otp --ha-join FILE`',
            '  (docs/high-availability.md, "Building it - replicated"). The web address, the',
            '  firewall, the certificates of the pages and the encrypted link between the',
            '  databases come back by themselves from the database.',
            '- Each node sends its own backups; either node\'s newest is the whole cluster\'s data.',
            '',
        ]
    lines += [
        '## %d. Check it' % (5 if ha else 4), '', '```bash',
        'otp --status                     # tokens, clients, realms, the database',
        'otp --radtest NAME CODE          # one sign-in', '```', '',
        'Then sign in to the pages with an account from the backup. RADIUS clients, DNS and a',
        'load balancer point at the new machine\'s address if it has another one',
        '(docs/renaming-and-readdressing.md).', '',
        '## By hand, without --restore-bundle', '', '```bash',
        'systemctl stop otp',
        'install -o otp -g otp -m 0600 secrets.key /var/lib/otp/secrets.key',
        'otp --restore otp-copy.json.gz --yes',
        'systemctl start otp', '```', '',
        '---', 'Made by otp %s on %s. The whole subject: docs/backup-and-recovery.md and' % (
            __version__, node),
        'docs/remote-backups.md in the package.', '']
    return '\n'.join(lines)


def rb_manifest(store, base, tokens='?'):
    """What a backup made now is: the head of its manifest and of RESTORE.md."""
    pw = rb_password()
    m = {'otp': __version__, 'made': time.time(),
         'made_words': datetime.now().strftime('%Y-%m-%d %H:%M:%S %Z').strip(),
         'site': CONFIG.get('site_name') or 'otp', 'node': node_name(),
         'host': socket.getfqdn(), 'engine': store.db.engine,
         'engine_words': ENGINE_WORDS.get(store.db.engine, store.db.engine),
         'ha_mode': CONFIG.get('ha_mode') or '', 'ha_slot': CONFIG.get('ha_slot'),
         'ha_peer': CONFIG.get('ha_peer') or '', 'tokens': tokens,
         'encrypted': bool(pw), 'iter': RB_ITER if pw else 0,
         'file': base + ('.tar.gz.enc' if pw else '.tar.gz'), 'files': {}}
    return m


def rb_restore_guide(store):
    """RESTORE.md as a backup made now would carry it (1.0.110) - for reading
    on the pages before anything is lost. No secret is in it."""
    site = rb_slug(CONFIG.get('site_name') or 'otp')
    node = rb_slug(node_name())
    try:
        tokens = int(store.db.value('SELECT COUNT(*) FROM tokens') or 0)
    except Exception:                                   # noqa: BLE001
        tokens = '?'
    base = 'otp-backup-%s-%s-%s' % (site, node, datetime.now().strftime('%Y%m%d-%H%M%S'))
    m = rb_manifest(store, base, tokens)
    return {'md': rb_restore_md(m), 'name': 'RESTORE-%s-%s.md' % (site, node),
            'file': m['file']}


def rb_build(store, work, progress=None):
    """The backup, built in `work`: (path of the file to send, its name,
    manifest, RESTORE.md text)."""
    def say(n, t):
        if progress:
            progress(n, 6, t)
    stamp_ = datetime.now().strftime('%Y%m%d-%H%M%S')
    site = rb_slug(CONFIG.get('site_name') or 'otp')
    node = rb_slug(node_name())
    base = 'otp-backup-%s-%s-%s' % (site, node, stamp_)
    inner = os.path.join(work, 'in')
    os.makedirs(inner, mode=0o700)
    say(1, 'the database is copied')
    copy = os.path.join(inner, 'otp-copy.json.gz')
    with open(copy, 'wb') as f:
        dump_tables(store.db, f)
    key = sealing_key()
    if not key:
        raise RbError('this machine has no key that opens the tokens - nothing worth sending')
    with open(os.path.join(inner, 'secrets.key'), 'w') as f:
        f.write(key.hex() + '\n')
    try:
        shutil.copyfile(str(CONFIG_FILE), os.path.join(inner, 'config.json'))
    except OSError as e:
        raise RbError('%s cannot be read: %s' % (CONFIG_FILE, e))
    extra = rb_files_named()
    if extra:
        os.makedirs(os.path.join(inner, 'files'))
        for p in extra:
            shutil.copyfile(p, os.path.join(inner, 'files', os.path.basename(p)))
    say(2, 'what is in it is counted')
    try:
        tokens = int(store.db.value('SELECT COUNT(*) FROM tokens') or 0)
    except Exception:                                   # noqa: BLE001
        tokens = '?'
    pw = rb_password()
    m = rb_manifest(store, base, tokens)
    for root, _dirs, files in os.walk(inner):
        for n in sorted(files):
            p = os.path.join(root, n)
            h = hashlib.sha256()
            with open(p, 'rb') as f:
                for chunk in iter(lambda: f.read(1 << 20), b''):
                    h.update(chunk)
            m['files'][os.path.relpath(p, inner)] = {'sha256': h.hexdigest(),
                                                    'bytes': os.path.getsize(p)}
    md = rb_restore_md(m)
    with open(os.path.join(inner, 'RESTORE.md'), 'w') as f:
        f.write(md)
    with open(os.path.join(inner, 'manifest.json'), 'w') as f:
        json.dump(m, f, indent=2, default=str)
    say(3, 'packed')
    tar = os.path.join(work, base + '.tar.gz')
    with tarfile.open(tar, 'w:gz', compresslevel=6) as tf:
        for n in sorted(os.listdir(inner)):
            tf.add(os.path.join(inner, n), arcname='%s/%s' % (base, n))
    shutil.rmtree(inner, ignore_errors=True)
    out = tar
    if pw:
        say(4, 'locked with the password of the backups')
        out = tar + '.enc'
        _openssl(['enc', '-aes-256-cbc', '-pbkdf2', '-iter', str(RB_ITER), '-md', 'sha256',
                  '-salt', '-in', tar, '-out', out, '-pass', 'env:OTP_RB_PASS'],
                 env={'OTP_RB_PASS': pw}, what='locking it')
        os.unlink(tar)
    h = hashlib.sha256()
    with open(out, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    m['sha256'] = h.hexdigest()
    m['bytes'] = os.path.getsize(out)
    with open(os.path.join(work, m['file'] + '.sha256'), 'w') as f:
        f.write('%s  %s\n' % (m['sha256'], m['file']))
    with open(os.path.join(work, base + '-RESTORE.md'), 'w') as f:
        f.write(md)
    return out, m, md


def rb_companions(name):
    m = RB_NAME_RE.match(name)
    if not m:
        return []
    base = name.split('.tar.gz')[0]
    return [name + '.sha256', base + '-RESTORE.md']


def rb_retain(tr, keep, days, now=None):
    """This node's backups at a destination beyond what is kept, taken away -
    never the newest."""
    now = now or time.time()
    mine = rb_slug(node_name())
    files = tr.list()
    names = set(x['name'] for x in files)
    ours = []
    for x in files:
        m = RB_NAME_RE.match(x['name'])
        if m and m.group('node') == mine and m.group('site') == rb_slug(
                CONFIG.get('site_name') or 'otp'):
            try:
                when = datetime.strptime(m.group('stamp'), '%Y%m%d-%H%M%S').timestamp()
            except ValueError:
                continue
            ours.append((when, x['name']))
    ours.sort(reverse=True)
    gone = []
    for i, (when, name) in enumerate(ours):
        if i == 0:
            continue
        if (keep and i >= keep) or (days and now - when > days * 86400):
            for n in [name] + [c for c in rb_companions(name) if c in names]:
                try:
                    tr.delete(n)
                except Exception:                       # noqa: BLE001
                    pass
            gone.append(name)
    return gone


def rb_run(store, by, only=None, progress=None):
    """Made once, sent to every destination switched on (or the ones asked):
    the result of each, kept in the history."""
    targets = [t for t in rb_targets(store)
               if (only and t['id'] in only) or (not only and t.get('enabled'))]
    if not targets:
        raise RbError('no destination is switched on')
    # Never sent unlocked (1.0.136): it holds the key every token is sealed
    # with, the whole database and config.json - whoever reads the share
    # could unseal every token.
    if not rb_password():
        raise RbError('the backups have no password: set one (Settings - Backups - '
                      'Backups to other machines) - unlocked, a copy would hand the key of '
                      'every token to whoever can read the destination')
    work = tempfile.mkdtemp(prefix='otp-rbackup-', dir=str(STATE_DIR))
    os.chmod(work, 0o700)
    began = time.time()
    run = {'at': began, 'by': by, 'node': node_name(), 'targets': [], 'ok': False}
    try:
        path, m, _md = rb_build(store, work, progress)
        run.update(file=m['file'], bytes=m['bytes'], encrypted=m['encrypted'],
                   tokens=m['tokens'])
        sha = os.path.join(work, m['file'] + '.sha256')
        md = os.path.join(work, m['file'].split('.tar.gz')[0] + '-RESTORE.md')
        for i, t in enumerate(targets):
            if progress:
                progress(5, 6, 'sent to %s (%d of %d)' % (t['name'], i + 1, len(targets)))
            one = {'id': t['id'], 'name': t['name'], 'kind': t['kind'], 'ok': False}
            t0 = time.time()
            tr = rb_transport(t)
            try:
                tr.open()
                tr.put(path, m['file'])
                tr.put(sha, os.path.basename(sha))
                tr.put(md, os.path.basename(md))
                got = {x['name']: x['size'] for x in tr.list()}
                if got.get(m['file']) not in (None, m['bytes']):
                    raise RbError('the server holds %s bytes of it, not %s' % (
                        got.get(m['file']), m['bytes']))
                one['ok'] = True
                try:
                    one['taken_away'] = rb_retain(tr, int(CONFIG.get('rbackup_keep') or 0),
                                                  int(CONFIG.get('rbackup_keep_days') or 0))
                except Exception as e:                  # noqa: BLE001
                    one['retain_error'] = str(e)[:200]
            except Exception as e:                      # noqa: BLE001
                one['error'] = rb_said(e)
            finally:
                tr.close()
            one['secs'] = round(time.time() - t0, 1)
            run['targets'].append(one)
            rb_set_fields(store, t['id'], '', '', last={
                'at': time.time(), 'ok': one['ok'], 'error': one.get('error') or '',
                'file': m['file'], 'bytes': m['bytes']})
        run['ok'] = all(x['ok'] for x in run['targets'])
    except (RbError, OSError, ValueError, subprocess.SubprocessError) as e:
        run['error'] = scrub_secret(str(e))[:400]
    finally:
        shutil.rmtree(work, ignore_errors=True)
    run['secs'] = round(time.time() - began, 1)
    rb_history_add(store, run)
    good = [x['name'] for x in run['targets'] if x['ok']]
    bad = ['%s (%s)' % (x['name'], x.get('error')) for x in run['targets'] if not x['ok']]
    store.add_event('backups', 'a backup of %s (%s) %s%s%s' % (
        node_name(), human_bytes(run.get('bytes') or 0), ('went to ' + ', '.join(good))
        if good else 'went nowhere', ('; not to ' + '; '.join(bad)) if bad else '',
        ('; ' + run['error']) if run.get('error') else ''),
        'info' if run['ok'] else 'bad', who=by)
    log('remote backup: %s' % ('sent to ' + ', '.join(good) if good else 'not sent')
        + (' - failed: ' + '; '.join(bad) if bad else '')
        + (' - ' + run['error'] if run.get('error') else ''), 'info' if run['ok'] else 'warn')
    return run


def human_bytes(n):
    n = float(n or 0)
    for unit in ('B', 'kB', 'MB', 'GB'):
        if n < 1024 or unit == 'GB':
            return ('%d %s' % (n, unit)) if unit == 'B' else ('%.1f %s' % (n, unit))
        n /= 1024.0
    return '%d B' % n


def rb_history(store):
    try:
        got = json.loads(store.get_meta('rbackup:runs') or '[]')
    except ValueError:
        got = []
    return [x for x in got if isinstance(x, dict)]


def rb_history_forget(store, at=None, file=None):
    """One line off the list (at and file), or all of it (1.0.110). The
    backups themselves stay where they went."""
    with RB_LOCK:
        runs = rb_history(store)
        if at is None:
            left = []
        else:
            left = [r for r in runs if not (abs(float(r.get('at') or 0) - float(at)) < 0.001 and
                                           str(r.get('file') or '') == str(file or ''))]
        store.set_meta('rbackup:runs', json.dumps(left, default=str))
        return len(runs) - len(left)


def rb_history_add(store, run):
    with RB_LOCK:
        runs = [run] + rb_history(store)
        store.set_meta('rbackup:runs', json.dumps(runs[:60], default=str))


def rb_job_start(store, by, only=None):
    """In a thread of its own; the page follows RB_JOB."""
    with RB_LOCK:
        if RB_JOB['running']:
            raise ValueError('a backup is being made already')
        RB_JOB.update(running=True, what='backup', says='starting', done=0, whole=6, error='',
                      began=time.time(), ended=0, result=None, by=by)

    def progress(done, whole, says):
        RB_JOB.update(done=done, whole=whole, says=says)

    def work():
        try:
            RB_JOB['result'] = rb_run(store, by, only, progress)
            if RB_JOB['result'].get('error'):
                RB_JOB['error'] = RB_JOB['result']['error']
        except Exception as e:                          # noqa: BLE001
            RB_JOB['error'] = scrub_secret(str(e))[:400]
            log('remote backup failed: %s' % e, 'error')
        finally:
            RB_JOB.update(running=False, ended=time.time())
    threading.Thread(target=work, name='rbackup', daemon=True).start()
    return dict(RB_JOB)


def rb_due(store, last_day):
    """Whether the scheduled backup is due now; the day it is for."""
    if not CONFIG.get('rbackup'):
        return None
    try:
        hh, mm = (int(x) for x in str(CONFIG.get('rbackup_at') or '04:00').split(':', 1))
    except ValueError:
        hh, mm = 4, 0
    now = datetime.now()
    if (now.hour, now.minute) < (hh, mm):
        return None
    if str(CONFIG.get('rbackup_every') or 'daily') == 'weekly' and \
            now.isoweekday() != int(CONFIG.get('rbackup_day') or 7):
        return None
    today = now.strftime('%Y-%m-%d')
    return today if today != last_day else None


RB_NOW_LIVE_S = 900


def rb_now_ask_others(store, by):
    """Back up now on the other nodes too (1.0.149), as the schedule does: each
    node makes its own. Asked in a row of the asking node's own per node
    asked - 'rbackup:now:NODE@@ASKER' - so only one node ever writes it."""
    if not CONFIG.get('ha_mode'):
        return []
    asked = []
    ident = secrets.token_hex(6)
    for n in ha_nodes(store):
        if n.get('me') or not n.get('alive'):
            continue
        store.set_meta(node_key('rbackup:now', n['name']),
                       json.dumps({'id': ident, 'at': time.time(), 'by': by,
                                   'from': node_name()}))
        asked.append(n['name'])
    return asked


def rb_now_asked(daemon):
    """A Back up now asked of this node by another; started once each."""
    store = daemon.store
    done_k = 'rbackup:nowdone:' + node_name()
    try:
        done = set(json.loads(store.get_meta(done_k) or '[]'))
    except ValueError:
        done = set()
    for r in node_key_rows(store, 'rbackup:now', node_name()):
        try:
            ask = json.loads(r['v'] or '{}')
        except ValueError:
            continue
        ident = str(ask.get('id') or '')
        if not ident or ident in done or time.time() - float(ask.get('at') or 0) > RB_NOW_LIVE_S:
            continue
        if RB_JOB['running']:
            return                      # asked again at the next tick
        store.set_meta(done_k, json.dumps(sorted(done | {ident})[-20:]))
        rb_job_start(store, '%s (Back up now on %s)' % (ask.get('by') or 'otp',
                                                        ask.get('from') or '?'))
        return


def rb_tick(daemon):
    """Once a minute from the daemon's loop: the scheduled backup, this node's."""
    store = daemon.store
    if CONFIG.get('ha_mode'):
        try:
            rb_now_asked(daemon)
        except Exception as e:                          # noqa: BLE001
            log_sparing('rb-now:' + str(e)[:60], 'Back up now asked by the other node: %s'
                        % e, 'warn', 600)
    day = rb_due(store, getattr(daemon, '_rb_day', ''))
    if not day or RB_JOB['running']:
        return
    # Marked done only once the database said whether it is this run's
    # (1.0.146): the database away just then left the day without a backup.
    claimed = claim_once(store, 'rbackup_day:' + node_name(), day)
    daemon._rb_day = day
    if not claimed:
        return
    if not any(t.get('enabled') for t in rb_targets(store)):
        return
    rb_job_start(store, 'otp (scheduled)')


# ---- putting one back -----------------------------------------------------------------
def rb_open(path, password, work):
    """A backup file opened into `work`: its folder and its manifest - every
    file checked against the checksum the manifest has."""
    src = path
    with open(path, 'rb') as f:
        head = f.read(8)
    if head.startswith(b'Salted__'):
        if not password:
            raise RbError('the backup is locked: its password is needed')
        src = os.path.join(work, 'b.tar.gz')
        tries = [password]
        if password == rb_password() and rb_password_old():
            tries.append(rb_password_old())             # made here before 1.0.139
        for n, pw in enumerate(tries):
            try:
                _openssl(['enc', '-d', '-aes-256-cbc', '-pbkdf2', '-iter', str(RB_ITER), '-md',
                          'sha256', '-in', path, '-out', src, '-pass', 'env:OTP_RB_PASS'],
                         env={'OTP_RB_PASS': pw}, what='opening it')
                break
            except ValueError:
                if n == len(tries) - 1:
                    raise RbError('the password does not open it (or the file is damaged)')
    elif not head.startswith(b'\x1f\x8b'):
        raise RbError('that is not a backup of otp (neither locked nor a .tar.gz)')
    elif password:
        # Backups are always locked: an unlocked one where a password is in
        # play was put there by somebody else - its database, its accounts,
        # its key (1.0.139).
        raise RbError('the backup is not locked, and backups of otp always are - it was not '
                      'made by otp; not put in')
    out = os.path.join(work, 'x')
    os.makedirs(out, mode=0o700)
    with tarfile.open(src, 'r:gz') as tf:
        members = tf.getmembers()
        tops = set()
        for mb in members:
            parts = mb.name.split('/')
            if mb.name.startswith('/') or '..' in parts or not (mb.isfile() or mb.isdir()):
                raise RbError('the archive has a file it may not have: %r' % mb.name[:100])
            tops.add(parts[0])
        if len(tops) != 1:
            raise RbError('the archive is not one backup')
        # Unpacked only when it fits (1.0.136): a small file that unpacks to
        # more than the disk has would fill /var/lib/otp, the database's too.
        total = sum(mb.size for mb in members if mb.isfile())
        try:
            free = shutil.disk_usage(work).free
        except OSError:
            free = None
        if free is not None and total > free - 512 * 1024 * 1024:
            raise RbError('unpacked it is %s, more than there is room for here (%s free)'
                          % (human_bytes(total), human_bytes(max(0, free))))
        for mb in members:
            if mb.isfile():
                dst = os.path.join(out, *mb.name.split('/'))
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with tf.extractfile(mb) as s, open(dst, 'wb') as d:
                    shutil.copyfileobj(s, d)
    top = os.path.join(out, tops.pop())
    try:
        with open(os.path.join(top, 'manifest.json')) as f:
            m = json.load(f)
    except (OSError, ValueError):
        raise RbError('there is no manifest in it')
    for rel, want in (m.get('files') or {}).items():
        p = os.path.join(top, *rel.split('/'))
        h = hashlib.sha256()
        try:
            with open(p, 'rb') as f:
                for chunk in iter(lambda: f.read(1 << 20), b''):
                    h.update(chunk)
        except OSError:
            raise RbError('%s is missing from it' % rel)
        if h.hexdigest() != want.get('sha256'):
            raise RbError('%s is damaged (its checksum is not the one in the manifest)' % rel)
    return top, m


def rb_restore(store, path, password, by, keep_node_name=False, need_admin=True):
    """Everything in a backup put back on this machine: the database, the key
    of the tokens, the node's name. The connection to the database in
    config.json stays this machine's."""
    work = tempfile.mkdtemp(prefix='otp-putback-', dir=str(STATE_DIR))
    os.chmod(work, 0o700)
    try:
        top, m = rb_open(path, password, work)
        got = db_file_restore(store, os.path.join(top, 'otp-copy.json.gz'), by,
                              key_file=os.path.join(top, 'secrets.key'),
                              from_name=os.path.basename(str(path)), need_admin=need_admin)
        said = [got.get('key') or '']
        old_name = node_name()
        if m.get('node') and not keep_node_name and m['node'] != old_name and \
                not CONFIG.get('ha_mode'):
            write_file_settings({'node_name': m['node']})
            CONFIG['node_name'] = m['node']
            try:
                node_carry(store, old_name, m['node'], by=by)
            except Exception:                           # noqa: BLE001
                pass
            said.append('this machine is node %s again (it was %s)' % (m['node'], old_name))
        store.add_event('backups', '%s put back the backup %s (made %s on %s, otp %s)' % (
            by, os.path.basename(str(path)), m.get('made_words'), m.get('node'), m.get('otp')),
            'warn', who=by)
        return {'manifest': m, 'safety': got.get('safety'), 'said': [x for x in said if x]}
    finally:
        shutil.rmtree(work, ignore_errors=True)


def rb_fetch(store, tid, name, dst):
    t = rb_target(store, tid)
    if not t:
        raise ValueError('no such destination')
    if not RB_NAME_RE.match(str(name or '')):
        raise ValueError('not a backup of otp: %r' % str(name)[:80])
    tr = rb_transport(t)
    try:
        tr.open()
        tr.get(name, dst)
    finally:
        tr.close()


def rb_remote_list(store, tid):
    t = rb_target(store, tid)
    if not t:
        raise ValueError('no such destination')
    tr = rb_transport(t)
    try:
        tr.open()
        files = tr.list()
    finally:
        tr.close()
    names = set(x['name'] for x in files)
    out = []
    for x in files:
        m = RB_NAME_RE.match(x['name'])
        if not m:
            continue
        try:
            when = datetime.strptime(m.group('stamp'), '%Y%m%d-%H%M%S').timestamp()
        except ValueError:
            when = x.get('mtime') or 0
        out.append({'name': x['name'], 'bytes': x['size'], 'when': when,
                    'node': m.group('node'), 'site': m.group('site'),
                    'encrypted': bool(m.group('enc')),
                    'mine': m.group('node') == rb_slug(node_name()),
                    'sha256': (x['name'] + '.sha256') in names})
    out.sort(key=lambda x: -x['when'])
    return out


# ---------------------------------------------------------------------------
# Two servers, both answering: high availability, active/active (1.0.13)
# ---------------------------------------------------------------------------
# Both nodes open the same PostgreSQL and keep nothing that matters anywhere
# else, so that a load balancer may send any request - a RADIUS packet, a
# page, the second half of an enrolment - to either, round robin and without
# stickiness:
#
#   * every setting, client, realm, directory and token is in the database,
#     and a node that sees another node's change (`conf_serial`) reads it in
#     within five seconds;
#   * a sign-in is a row in the database, and so is what belongs to it (the
#     "Edit the columns" switch); a job's progress (a move, an erase) is in
#     the database too, so the bar keeps moving whichever node is asked;
#   * a code is used up with one conditional UPDATE, and a row of its own in
#     token_once that nothing ever writes over (1.0.101). With two
#     replicating databases (ha_mode "replicated") a node also looks in the
#     other node's database before it lets a code in - so the same code sent
#     to both nodes at the same moment is let in once, not once on each, and
#     a used recovery code does not come back when replication writes an
#     older copy of the token's row. Only while the other node's database
#     cannot be reached at all is a code checked against this node's rows
#     alone (said in the log);
#   * the nightly dump is claimed by one node, with one conditional UPDATE;
#   * the key that seals the tokens is the same file on both, carried to the
#     second node once in a bundle locked with a passphrase.
#
# Each node writes a heartbeat into the database every fifteen seconds; the
# pages show the nodes and how long since each was heard from.

HA_KIND = 'otp-ha-join'
HA_STORE = {'store': None}
HEARTBEAT_S = 15


def node_name():
    return this_node_name()


def node_address():
    """The address this machine uses to reach the outside - what a peer would
    use to reach it."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            s.connect(('192.0.2.1', 9))
            return s.getsockname()[0]
        finally:
            s.close()
    except OSError:
        return ''


# Set while this node is rebuilt from the other (1.0.44): it answers nothing
# and writes nothing until every row has come over.
HA_REBUILDING = threading.Event()
HA_REBUILD_LOCK = 7_011_959     # pg advisory lock: one rebuild in the cluster (1.0.59)
HA_REBUILDER = [None]          # the thread that rebuilds; the only one that writes meanwhile


FW_NOW_SENT = {}


def fw_now_publish(store, asked=False):
    """This node's whole firewall into its row for the other node's pages
    (1.0.71): when root read it again, and every 10 minutes all the same -
    a row lost on the way (a rebuild, a restore) was never written again.
    The other node's page may ask for it to be read again: 'fw:ask:<node>'."""
    me = node_name()
    try:
        ask = float(store.get_meta('fw:ask:' + me) or 0)
    except (TypeError, ValueError):
        ask = 0
    if ask and ask > FW_NOW_SENT.get('asked', 0):
        FW_NOW_SENT['asked'] = ask
        fw_now_ask(wait=0)              # root reads it within a second or two
    got = fw_now_read()
    at = got.get('full_at')
    if not at:
        return
    if FW_NOW_SENT.get('at') == at and time.time() - FW_NOW_SENT.get('when', 0) < 600:
        return
    store.set_meta('fw:now:' + me, json.dumps({'full': got.get('full') or {}, 'full_at': at}))
    FW_NOW_SENT.update(at=at, when=time.time())


def heartbeat(store, daemon=None):
    if HA_REBUILDING.is_set():
        return {}                       # nothing written while the rows come over (1.0.44)
    beat = {'at': time.time(), 'version': __version__, 'address': node_address(),
            'host': socket.gethostname(), 'started': daemon.started if daemon else None,
            'radius': list(getattr(getattr(daemon, 'radius', None), 'bound', []) or []),
            'engine': store.db.engine,
            'maintenance': bool(maintenance_now(store).get('on')),
            # What its own settings are in effect (1.0.67), its config.json's
            # among them, for the other node's pages to show as they are.
            'own': {k: (CONFIG.get(k) if not isinstance(CONFIG.get(k), bytes) else '')
                    for k in NODE_KEYS},
            'own_file': sorted(k for k in NODE_KEYS if k in (FILE_KEYS or ()))}
    try:
        beat['software'] = software_info(store)  # for the other node's About (1.0.99)
    except Exception:                                   # noqa: BLE001
        pass
    try:
        beat['web'] = web_state(store)          # TLS and the web address (1.0.47)
        # The whole firewall goes in a row of its own, when it changed
        # (1.0.67) - not into a heartbeat written every 15 s.
        for k in ('full', 'full_at', 'full_backend'):
            (beat['web'].get('fw') or {}).pop(k, None)
        fw_now_publish(store)
    except Exception:                                   # noqa: BLE001
        pass
    beat['mid'] = machine_id()
    name_clash_check(store, beat)
    store.set_meta('node:' + node_name(), json.dumps(beat))
    return beat


# Two machines with one name (1.0.110): both wrote the same heartbeat row, so
# the other looked gone and the web address "on both". Each row now carries
# the machine it came from; a row from another machine, fresh, under this
# node's name is said loudly - in the log, on every page and in --ha-status.
NAME_CLASH = {}
NAME_CLASH_SEEN = []


def machine_id():
    """This installation: the machine's id, its host name and where its state
    is - a VM cloned with its machine-id still tells itself apart by its
    host name."""
    got = ''
    for f in ('/etc/machine-id', '/var/lib/dbus/machine-id'):
        try:
            got = Path(f).read_text().strip()
        except OSError:
            continue
        if got:
            break
    return hashlib.sha256(('%s|%s|%s' % (got, socket.gethostname(), STATE_DIR)).encode()
                          ).hexdigest()[:24]


def name_clash_check(store, beat):
    try:
        was = json.loads(store.get_meta('node:' + node_name()) or '{}')
    except ValueError:
        was = {}
    now = time.time()
    other = was.get('mid')
    if other and other != beat['mid'] and now - float(was.get('at') or 0) < HEARTBEAT_S * 3:
        # Seen twice before it is said: once is this machine's own row from
        # before a new host name, overwritten by the beat after this one.
        NAME_CLASH_SEEN.append(now)
        del NAME_CLASH_SEEN[:-2]
        if len(NAME_CLASH_SEEN) < 2:
            return
        first = not NAME_CLASH
        NAME_CLASH.update(name=node_name(), address=was.get('address') or '?',
                          host=was.get('host') or '?', at=now)
        if first or now - NAME_CLASH.get('said', 0) > 600:
            NAME_CLASH['said'] = now
            log('two machines call themselves %s: this one (%s, %s) and %s (%s) - give '
                'one of them its own name: otp --set node_name=NAME on it, then systemctl '
                'restart otp (docs/renaming-and-readdressing.md)'
                % (node_name(), beat.get('address'), beat.get('host'), NAME_CLASH['address'],
                   NAME_CLASH['host']), 'error')
    elif now - (NAME_CLASH_SEEN or [0])[-1] > HEARTBEAT_S * 4:
        NAME_CLASH.clear()
        del NAME_CLASH_SEEN[:]


def name_clash_words():
    if not NAME_CLASH or NAME_CLASH.get('name') != node_name():
        return ''
    return ('two machines call themselves %s: this one and %s (%s) - each node needs a name '
            'of its own (otp --set node_name=NAME on one of them, then systemctl restart otp)'
            % (NAME_CLASH['name'], NAME_CLASH['address'], NAME_CLASH['host']))


def node_name_taken(store, want):
    """Another machine, answering now, already called want? (1.0.110)"""
    want = str(want or '').strip()
    if not want or want == node_name():
        return None
    mine = machine_id()
    for n in ha_nodes(store):
        if n['name'] == want and n.get('alive') and n.get('mid', '') != mine:
            return n
    return None


def ha_nodes(store):
    out = []
    try:
        rows = store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'node:%'")
    except Exception:                                   # noqa: BLE001
        rows = []
    now = time.time()
    for r in rows:
        try:
            beat = json.loads(r['v'] or '{}')
        except ValueError:
            continue
        name = r['k'][5:]
        age = now - float(beat.get('at') or 0)
        beat.update(name=name, age=age, me=name == node_name(),
                    alive=age < HEARTBEAT_S * 3)
        out.append(beat)
    out.sort(key=lambda b: (not b['me'], b['name']))
    return out


def ha_forget(store, name):
    if name == node_name():
        raise ValueError('this is the node answering: it would write itself back at once')
    store.db.run('DELETE FROM meta WHERE k = ?', ('node:' + name,))


def ha_lead(store):
    """Whether this node is the one of a replicated pair that does what one
    node does for both (1.0.147): the first by name of the nodes heard from,
    this one when it hears no other."""
    if CONFIG.get('ha_mode') != 'replicated':
        return True
    alive = sorted(n['name'] for n in ha_nodes(store) if n.get('alive') or n.get('me'))
    return not alive or alive[0] == node_name()


def claim_once(store, key, value):
    """True for exactly one node: the one whose conditional UPDATE changed the
    row. A key not there yet is made first; two nodes making it at the same
    moment cannot both insert it (it is the primary key).

    Two replicated databases are two tables, though: each node's INSERT went
    in, and replication then stopped on the other's for good; each UPDATE
    took the day too. A key of both nodes (not one of this node's own,
    'NAME:NODE') is claimed by one node alone since 1.0.147 - see ha_lead -
    so only that one ever writes its row."""
    if CONFIG.get('ha_mode') == 'replicated' and not key.endswith(':' + node_name()) and \
            not ha_lead(store):
        return False
    if store.get_meta(key) is None:
        try:
            store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)', (key, ''))
        except Exception:                               # noqa: BLE001
            pass
    return bool(store.db.run('UPDATE meta SET v = ? WHERE k = ? AND (v IS NULL OR v <> ?)',
                             (str(value), key, str(value))))


def sub_connection_set(store, sub, conninfo):
    """ALTER SUBSCRIPTION ... CONNECTION, its password kept out of PostgreSQL's
    log (1.0.136) and the text as it is - a ? in a password was taken for a
    parameter (1.0.139). Raises ValueError, the password scrubbed."""
    for quiet in ("SET log_statement = 'none'", "SET log_min_error_statement = 'panic'"):
        try:
            store.db.run(quiet)
        except Exception:                               # noqa: BLE001
            pass
    try:
        store.db.run(RawSql("ALTER SUBSCRIPTION %s CONNECTION '%s'"
                            % (sub, conninfo.replace("'", "''"))))
    except Exception as e:                              # noqa: BLE001
        raise ValueError('the subscription %s could not be changed: %s'
                         % (sub, scrub_secret(str(e).split('\n')[0][:300])))
    finally:
        for back in ('RESET log_statement', 'RESET log_min_error_statement'):
            try:
                store.db.run(back)
            except Exception:                           # noqa: BLE001
                pass


# ---- a job's progress, where both nodes can read it ------------------------------
def job_publish(job):
    store = HA_STORE.get('store')
    if not store or HA_REBUILDING.is_set():
        return
    try:
        store.set_meta('db_job:' + node_name(), json.dumps(dict(job, node=node_name(),
                                                                at=time.time()),
                                                           default=str))
    except Exception:                                   # noqa: BLE001
        pass


def job_read():
    """The job as the database has it - this node's, or the other's."""
    if DB_JOB.get('running') or DB_JOB.get('ended'):
        here = dict(DB_JOB, node=node_name())
    else:
        here = None
    store = HA_STORE.get('store')
    there = None
    if store:
        try:
            for r in store.db.rows("SELECT v FROM meta WHERE k LIKE 'db!_job:%' ESCAPE '!'"):
                one = json.loads(r['v'] or 'null')
                # Going on, by the word of a node that has not said so for
                # five minutes - or of this node, which is not running it:
                # it ended with the process that ran it (1.0.37).
                if one and one.get('running') and (
                        time.time() - float(one.get('at') or one.get('began') or 0) > 300 or
                        (one.get('node') == node_name() and not DB_JOB.get('running'))):
                    one = dict(one, running=False, ended=float(one.get('at') or 0),
                               error=one.get('error') or 'it stopped with the service that '
                               'ran it (restarted, or the database was changed)')
                if one and (not there or float(one.get('began') or 0) >
                            float(there.get('began') or 0)):
                    there = one
        except Exception:                               # noqa: BLE001
            there = None
    if here and (not there or float(here.get('began') or 0) >= float(there.get('began') or 0)):
        return here
    return there or dict(DB_JOB)


# ---- the bundle that carries a cluster to its second node --------------------------
def _bundle_key(passphrase, salt):
    return hashlib.scrypt(str(passphrase).encode('utf-8'), salt=salt, n=2 ** 15, r=8, p=1,
                          maxmem=64 * 1024 * 1024, dklen=32)


def bundle_lock(data, passphrase, kind=None):
    salt = secrets.token_bytes(16)
    key = _bundle_key(passphrase, salt)
    raw = json.dumps(data).encode('utf-8')
    nonce = secrets.token_bytes(16)
    hide = hmac.new(key, b'hide', hashlib.sha256).digest()
    sign = hmac.new(key, b'sign', hashlib.sha256).digest()
    body = bytes(a ^ b for a, b in zip(raw, _seal_stream(hide, nonce, len(raw))))
    # Format 2 (1.0.101): what kind of bundle it is is signed too, so a
    # backup of tokens cannot be handed in as a cluster's bundle, nor the
    # other way round.
    tag = hmac.new(sign, (kind or HA_KIND).encode('utf-8') + b'\n' + salt + nonce + body,
                   hashlib.sha256).digest()
    return {'kind': kind or HA_KIND, 'format': 2, 'made': time.time(), 'from': node_name(),
            'version': __version__,
            'locked': base64.b64encode(salt + nonce + body + tag).decode('ascii')}


def bundle_open(bundle, passphrase, kinds=None):
    if isinstance(bundle, str):
        try:
            bundle = json.loads(bundle)
        except ValueError:
            raise ValueError('that is not a bundle made by otp --ha-bundle: it is not JSON')
    if not isinstance(bundle, dict) or bundle.get('kind') not in (kinds or (HA_KIND, 'opt-ha-join')):
        raise ValueError('that is not a bundle made by otp --ha-bundle')
    try:
        raw = base64.b64decode(bundle.get('locked') or '')
    except (ValueError, TypeError):
        raise ValueError('the bundle is damaged')
    if len(raw) < 16 + 16 + 32:
        raise ValueError('the bundle is damaged')
    salt, nonce, body, tag = raw[:16], raw[16:32], raw[32:-32], raw[-32:]
    key = _bundle_key(passphrase, salt)
    sign = hmac.new(key, b'sign', hashlib.sha256).digest()
    signed = salt + nonce + body
    if int(bundle.get('format') or 1) >= 2:
        signed = str(bundle.get('kind')).encode('utf-8') + b'\n' + signed
    if not hmac.compare_digest(tag, hmac.new(sign, signed, hashlib.sha256).digest()):
        raise ValueError('the passphrase is not the one the bundle was locked with')
    hide = hmac.new(key, b'hide', hashlib.sha256).digest()
    data = json.loads(bytes(a ^ b for a, b in zip(body, _seal_stream(hide, nonce, len(body))))
                      .decode('utf-8'))
    data['_from'] = bundle.get('from')
    data['_made'] = bundle.get('made')
    return data


def ha_passphrase():
    words = 'abcdefghijkmnopqrstuvwxyz23456789'
    return '-'.join(''.join(secrets.choice(words) for _ in range(5)) for _ in range(5))


def ha_checks(store):
    """What has to be true before a second node can join, each with its
    answer: the database, its address as the other node will see it, the
    key."""
    db = store.db
    host = str(CONFIG.get('db_host') or '')
    local = host in ('', 'localhost', '127.0.0.1', '::1')
    mode = CONFIG.get('ha_mode') or ''
    out = [
        {'key': 'engine', 'ok': db.engine == 'postgres',
         'says': 'the database is PostgreSQL' if db.engine == 'postgres' else
         'the database is %s: a cluster needs PostgreSQL, which both nodes open - move to it '
         'first (Settings → The database)' % ENGINE_WORDS.get(db.engine, db.engine)},
        {'key': 'key', 'ok': bool(sealing_key()),
         'says': 'the key that seals the tokens is there' if sealing_key() else
         'the key that seals the tokens is missing'},
    ]
    if mode == 'replicated' and db.engine == 'postgres':
        # Made two already (1.0.43): each node has its own PostgreSQL here,
        # and the other node never opens it - nothing to warn of.
        out.append({'key': 'address', 'ok': True,
                    'says': 'this node is one of two already: each has its own PostgreSQL '
                            'and they replicate to each other'})
        return out
    out += [
        {'key': 'address', 'ok': not local or db.engine != 'postgres',
         'warn': local and db.engine == 'postgres',
         'says': ('PostgreSQL is reached at %s, which the other node can use as well' % host)
         if not local else ('PostgreSQL is on this machine (%s): the other node reaches it at '
                            'this machine\'s address - it has to listen there and let the other '
                            'node in (otp --ha-setup does both, as root)' % (host or 'localhost'))},
    ]
    return out


def ha_bundle_data(store, peer_db_host='', with_tls=None):
    """What the second node needs and nothing else: how to open the
    database, the key that opens the tokens, and the name of the cluster."""
    if store.db.engine != 'postgres':
        raise ValueError('a cluster needs PostgreSQL: move to it first (Settings → The database)')
    key = sealing_key()
    if not key:
        raise ValueError('the key that seals the tokens is missing')
    db = {k: CONFIG.get(k) for k in DB_KEYS}
    host = str(db.get('db_host') or '')
    if peer_db_host:
        db['db_host'] = peer_db_host
    elif host in ('', 'localhost', '127.0.0.1', '::1'):
        db['db_host'] = node_address()
    data = {'db': db, 'key': key.hex(), 'cluster': CONFIG.get('site_name') or 'otp',
            'peer': {'name': node_name(), 'address': node_address()}}
    if with_tls:
        data['tls'] = with_tls
    return data


def ha_join(data, name='', even_if_data=False, by=''):
    """This node into the cluster: the database's address into config.json and
    the key beside it. The daemon starts again on it afterwards."""
    db = data.get('db') or {}
    if db.get('db_engine') != 'postgres':
        raise ValueError('the bundle does not name a PostgreSQL')
    # Every value checked as the settings are (1.0.57) before it goes into
    # config.json: they reach command lines, option files and pg_hba.conf.
    try:
        db = {k: check_setting(k, v) for k, v in db.items() if k in DB_KEYS}
        if name:
            name = check_setting('node_name', name)
    except BadSetting as e:
        raise ValueError('the bundle or the name will not do: %s' % e)
    key_hex = str(data.get('key') or '')
    if not re.match(r'^[0-9a-f]{64}\Z', key_hex):
        raise ValueError('the bundle holds no key')
    got = db_try(db)
    if not got.get('reached'):
        raise ValueError('the database in the bundle cannot be reached from here: %s'
                         % (got.get('trouble') or 'no answer'))
    now = sealing_key()
    if now and now.hex() != key_hex and not even_if_data:
        # This node has a key of its own: whatever it sealed would be lost.
        store = HA_STORE.get('store')
        mine = 0
        if store and store.db.engine == 'sqlite':
            try:
                mine = int(store.db.value('SELECT COUNT(*) FROM tokens') or 0)
            except Exception:                           # noqa: BLE001
                mine = 0
        if mine:
            raise ValueError('this node holds %d token(s) of its own, sealed with another key; '
                             'joining replaces both its database and its key. Say so to go on '
                             '(--discard-local, or tick it on the page)' % mine)
    if now and now.hex() != key_hex:
        backup = sealing_key_path().with_name('secrets.key.before-join')
        write_replacing(backup, now.hex() + '\n', 0o600)
    write_replacing(sealing_key_path(), key_hex + '\n', 0o600)
    changes = {k: db.get(k) for k in DB_KEYS if k in db}
    if name:
        changes['node_name'] = name
    write_file_settings(changes)
    return {'where': db_where(db), 'rows': got.get('rows'), 'peer': data.get('peer') or {},
            'message': 'this node joins the cluster: it starts again on %s' % db_where(db)}


# ---- the PostgreSQL side, as root on the machine it runs on ------------------------
def pg_local_admin(sql, secret=False):
    """A statement run as the postgres account on this machine (root only).
    The SQL goes in on standard input, never on the command line, where
    every process on the machine could read it; `secret` marks one that
    carries a password, which is then kept out of PostgreSQL's own log."""
    for runner in (['runuser', '-u', 'postgres', '--'], ['su', '-s', '/bin/sh', 'postgres', '-c']):
        if not shutil.which(runner[0]):
            continue
        if runner[0] == 'su':
            args = runner + ['psql -XAtq -v ON_ERROR_STOP=1 -f -']
        else:
            args = runner + ['psql', '-XAtq', '-v', 'ON_ERROR_STOP=1', '-f', '-']
        got = subprocess.run(args, capture_output=True, text=True, timeout=30,
                             input=pg_script(sql, secret))
        if got.returncode == 0:
            return got.stdout.strip()
        raise ValueError(scrub_secret((got.stderr or got.stdout).strip()[:300]) or 'psql failed')
    raise ValueError('neither runuser nor su is here')


PG_QUIET = "SET log_statement = 'none'; SET log_min_error_statement = 'panic';\n"


def pg_script(sql, secret=False):
    """The statement as psql reads it from its standard input - for one with
    a password in it, after switching the logging of statements off for the
    session, so the password lands in no log."""
    return (PG_QUIET if secret else '') + str(sql).rstrip().rstrip(';') + ';\n'


def shlex_quote(s):
    import shlex
    return shlex.quote(s)


def peer_address(text):
    """The other node's address - one address, never a range: ValueError
    otherwise."""
    said = str(text or '').strip()
    if not said:
        raise ValueError('the other node\'s address is needed')
    try:
        return ipaddress.ip_address(said)
    except ValueError:
        raise ValueError('%s is not an address (one address, not a range or a name)' % said)


def peer_net(text):
    """That address as the one-address network pg_hba.conf takes."""
    a = peer_address(text)
    return '%s/%d' % (a, 32 if a.version == 4 else 128)


def pg_open_to(peer, db_name, db_user):
    """PostgreSQL on this machine listening beyond localhost and letting the
    other node's address in for this one database and account. Returns what
    was done, in words."""
    # Both go into pg_hba.conf as root: a name with a space or a new line
    # in config.json wrote a line of its own there (1.0.139).
    for what, v in (('db_name', db_name), ('db_user', db_user)):
        if not DB_IDENT.fullmatch(str(v or '')):
            raise ValueError('%s is letters, digits and _ only, starting with a letter' % what)
    done = []
    listen = pg_local_admin('SHOW listen_addresses')
    if listen not in ('*', '0.0.0.0') and '*' not in listen.split(','):
        pg_local_admin("ALTER SYSTEM SET listen_addresses = '*'")
        done.append("listen_addresses = '*' (was %s) - takes effect at the next start" % listen)
    hba = pg_local_admin('SHOW hba_file')
    line = 'host    %s    %s    %s    scram-sha-256' % (db_name, db_user, peer_net(peer))
    try:
        text = Path(hba).read_text()
    except OSError as e:
        raise ValueError('%s could not be read: %s' % (hba, e))
    if line not in text:
        # In front of whatever is there: pg_hba.conf is read top down, and a
        # "reject" or an "ident" line further up would win otherwise.
        Path(hba).write_text('# otp high availability: the other node (%s)\n%s\n%s'
                             % (datetime.now().strftime('%Y-%m-%d'), line, text))
        done.append('%s: %s' % (hba, line))
    pg_local_admin('SELECT pg_reload_conf()')
    return done


# ---------------------------------------------------------------------------
# Replicated: a PostgreSQL on each node, each replicating to the other (1.0.14)
# ---------------------------------------------------------------------------
# Each node opens only its own PostgreSQL, on this machine, and goes on alone
# when the other is gone. The two replicate both ways with PostgreSQL's own
# logical replication: a publication of every table on each (inserts, updates
# and deletes - never TRUNCATE, so that a node being rebuilt cannot empty the
# other), and on each a subscription to the other with `origin = none`, so
# that what came from the other is not sent back to it. PostgreSQL 16 or
# later on both.
#
# Rows made on both at once never collide: the numbering of every table goes
# up in twos, odd on node 1 and even on node 2.
#
# A node that was away comes back by itself: what it missed waited in its
# replication slot on the other (up to max_slot_wal_keep_size). A node that
# was lost - or reinstalled - is rebuilt from the living one: its tables
# emptied, every row copied over by the subscription, and the other node's
# subscription to it made afresh.

HA_PUB = 'otp_pub'
# Before 1.0.37 the program was called opt, and its replication objects so:
# a publication and subscriptions are renamed at the upgrade, a slot keeps
# its name until it is next made (a rebuild) - so both are looked for.
HA_PUB_OLD = 'opt_pub'
HA_SLOT_KEEP = '16GB'


def ha_sub_name(slot):
    """The subscription that brings node `slot`'s rows in (and its slot on
    node `slot`)."""
    return 'otp_from_%d' % int(slot)


def ha_sub_names(slot):
    return ['otp_from_%d' % int(slot), 'opt_from_%d' % int(slot)]


def ha_sub_here(db, slot):
    """The subscription for node `slot` as it is called in `db`."""
    for name in ha_sub_names(slot):
        if db.value('SELECT 1 FROM pg_subscription WHERE subname = ?', (name,)):
            return name
    return ha_sub_name(slot)


def pg_admin(sql, port=5432, db='postgres', secret=False):
    """A statement as the postgres account on this machine (root only). As
    pg_local_admin: the SQL on standard input, a `secret` one unlogged."""
    for runner in (['runuser', '-u', 'postgres', '--'], ['sudo', '-u', 'postgres']):
        if shutil.which(runner[0]):
            got = subprocess.run(runner + ['psql', '-XAtq', '-p', str(int(port)), '-d', db,
                                           '-v', 'ON_ERROR_STOP=1', '-f', '-'],
                                 capture_output=True, text=True, timeout=120,
                                 input=pg_script(sql, secret))
            if got.returncode == 0:
                return got.stdout.strip()
            raise ValueError(scrub_secret((got.stderr or got.stdout).strip()[:400])
                             or 'psql failed')
    raise ValueError('neither runuser nor sudo is on this machine')


def pg_local_running(port=5432):
    try:
        return pg_admin('SELECT 1', port) == '1'
    except Exception:                                   # noqa: BLE001
        return False


def pg_install_local(major, say):
    """PostgreSQL `major` on this machine, installed, initialised and running."""
    if shutil.which('dnf'):
        say('installing PostgreSQL %s (dnf)' % major)
        subprocess.run(['dnf', '-y', 'module', 'reset', 'postgresql'], capture_output=True)
        subprocess.run(['dnf', '-y', 'module', 'enable', 'postgresql:%s' % major],
                       capture_output=True)
        got = subprocess.run(['dnf', '-y', 'install', 'postgresql-server', 'postgresql',
                              'postgresql-contrib'], capture_output=True, text=True)
        if got.returncode != 0:
            raise ValueError('dnf could not install PostgreSQL %s: %s'
                             % (major, (got.stderr or got.stdout).strip()[-300:]))
        if not Path('/var/lib/pgsql/data/PG_VERSION').exists():
            subprocess.run(['postgresql-setup', '--initdb'], capture_output=True)
        subprocess.run(['systemctl', 'enable', '--now', 'postgresql'], capture_output=True)
    elif shutil.which('apt-get'):
        say('installing PostgreSQL %s (apt)' % major)
        got = subprocess.run(['apt-get', 'install', '-y', 'postgresql-%s' % major,
                              'postgresql-client-%s' % major], capture_output=True, text=True)
        if got.returncode != 0:
            got = subprocess.run(['apt-get', 'install', '-y', 'postgresql'],
                                 capture_output=True, text=True)
        if got.returncode != 0:
            raise ValueError('apt could not install PostgreSQL: %s'
                             % (got.stderr or got.stdout).strip()[-300:])
    else:
        raise ValueError('install PostgreSQL %s on this machine first' % major)
    for _ in range(30):
        if pg_local_running():
            return
        time.sleep(1)
    raise ValueError('PostgreSQL was installed but does not answer')


def pg_restart_local(port=5432):
    unit = tune_restart_unit()
    if unit:
        subprocess.run(['systemctl', 'restart', unit], capture_output=True)
    elif shutil.which('pg_lsclusters'):
        for line in subprocess.run(['pg_lsclusters', '-h'], capture_output=True,
                                   text=True).stdout.splitlines():
            f = line.split()
            if len(f) >= 3 and f[2] == str(port):
                subprocess.run(['pg_ctlcluster', f[0], f[1], 'restart'], capture_output=True)
    else:
        raise ValueError('PostgreSQL could not be restarted: no service of it was found')
    for _ in range(60):
        if pg_local_running(port):
            return
        time.sleep(1)
    raise ValueError('PostgreSQL did not come back after its restart')


def pg_prepare_local(port, peer, name, user, password, say):
    """PostgreSQL on this machine ready to replicate with `peer`: logical
    WAL, listening on the network, the peer let in, the account able to
    replicate and to subscribe, the database there. True when it has to be
    restarted for it."""
    major = int(pg_admin('SHOW server_version_num', port)) // 10000
    if major < 16:
        raise ValueError('PostgreSQL %d is here; replicating both ways needs 16 or later '
                         '(dnf module enable postgresql:16, then upgrade it)' % major)
    restart = False
    for key, want in (('wal_level', 'logical'), ('listen_addresses', '*'),
                      ('max_slot_wal_keep_size', HA_SLOT_KEEP)):
        now = pg_admin('SHOW %s' % key, port)
        if key == 'max_slot_wal_keep_size' and now not in ('-1',) and now.upper() == want:
            continue
        if now != want:
            pg_admin("ALTER SYSTEM SET %s = '%s'" % (key, want), port)
            say('%s = %s (was %s)' % (key, want, now))
            if key != 'max_slot_wal_keep_size':
                restart = True
    if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{0,62}', user) or \
            not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{0,62}', name):
        raise ValueError('the database and its account are letters, digits and _')
    lit = "'%s'" % str(password).replace("'", "''")
    if pg_admin("SELECT 1 FROM pg_roles WHERE rolname = '%s'" % user, port) != '1':
        pg_admin('CREATE ROLE %s LOGIN PASSWORD %s' % (user, lit), port, secret=True)
        say('the account %s was made' % user)
    else:
        pg_admin('ALTER ROLE %s LOGIN PASSWORD %s' % (user, lit), port, secret=True)
    pg_admin('ALTER ROLE %s REPLICATION' % user, port)
    pg_admin('GRANT pg_create_subscription TO %s' % user, port)
    if pg_admin("SELECT 1 FROM pg_database WHERE datname = '%s'" % name, port) != '1':
        # UTF-8 whatever the cluster was made with: one made under LANG=C is
        # SQL_ASCII, and every name with an accent would come back unreadable.
        pg_admin("CREATE DATABASE %s OWNER %s ENCODING 'UTF8' TEMPLATE template0 "
                 "LC_COLLATE 'C.UTF-8' LC_CTYPE 'C.UTF-8'" % (name, user), port)
        say('the database %s was made' % name)
    pg_admin('GRANT CREATE ON DATABASE %s TO %s' % (name, user), port)
    hba = pg_admin('SHOW hba_file', port)
    text = Path(hba).read_text()
    added = []
    for who in sorted(set(([peer] if peer else []) + ['127.0.0.1'])):
        line = 'host    %s    %s    %s    scram-sha-256' % (name, user, peer_net(who))
        # Taken over TLS only already (1.0.104): no plain line put back in front.
        if line not in text and ('hostssl' + line[4:]) not in text:
            added.append(line)
    if added:
        # In front of whatever is there: pg_hba.conf is read top down, and a
        # "reject" or an "ident" line further up would win otherwise.
        Path(hba).write_text('# otp high availability (%s)\n%s\n%s'
                             % (datetime.now().strftime('%Y-%m-%d'), '\n'.join(added), text))
        say('%s: %s' % (hba, '; '.join(added)))
    pg_admin('SELECT pg_reload_conf()', port)
    return restart, major


def pg_publication(port, name):
    if pg_admin("SELECT 1 FROM pg_publication WHERE pubname = '%s'" % HA_PUB_OLD, port, name) == '1':
        pg_admin('ALTER PUBLICATION %s RENAME TO %s' % (HA_PUB_OLD, HA_PUB), port, name)
    if pg_admin("SELECT 1 FROM pg_publication WHERE pubname = '%s'" % HA_PUB, port, name) != '1':
        pg_admin("CREATE PUBLICATION %s FOR ALL TABLES WITH (publish = 'insert, update, delete')"
                 % HA_PUB, port, name)


def ha_conninfo(host, port, name, user, password):
    def q(v):
        return "'%s'" % str(v).replace('\\', '\\\\').replace("'", "\\'")
    tls = ''
    mode, ca = ha_link_tls()
    if mode:
        # The other node's link encrypted as the database's own is (1.0.33),
        # or as its own setting says (1.0.104).
        tls = ' sslmode=%s' % q(mode)
        if ca:
            tls += ' sslrootcert=%s' % q(ca)
    return 'host=%s port=%d dbname=%s user=%s password=%s connect_timeout=10%s' % (
        q(host), int(port), q(name), q(user), q(password), tls)


def ha_drop_sub(db, sub):
    """A subscription taken away without asking the other side for its slot
    (which may be gone with a lost node) - under its name now or before."""
    names = ha_sub_names(sub.rsplit('_', 1)[1]) if sub[:9] in ('otp_from_', 'opt_from_') \
        else [sub]
    for one in names:
        if db.value('SELECT 1 FROM pg_subscription WHERE subname = ?', (one,)):
            db.run('ALTER SUBSCRIPTION %s DISABLE' % one)
            db.run('ALTER SUBSCRIPTION %s SET (slot_name = NONE)' % one)
            db.run('DROP SUBSCRIPTION %s' % one)


def ha_drop_slot(db, slot_name):
    if slot_name[:9] in ('otp_from_', 'opt_from_'):
        gone = False
        for one in ha_sub_names(slot_name.rsplit('_', 1)[1]):
            gone = _ha_drop_slot(db, one) or gone
        return gone
    return _ha_drop_slot(db, slot_name)


def _ha_drop_slot(db, slot_name):
    got = db.row('SELECT active, active_pid FROM pg_replication_slots WHERE slot_name = ?',
                 (slot_name,))
    if not got:
        return False
    if got.get('active') and got.get('active_pid'):
        db.value('SELECT pg_terminate_backend(?)', (int(got['active_pid']),))
        time.sleep(1)
    db.value('SELECT pg_drop_replication_slot(?)', (slot_name,))
    return True


def ha_sequences(db, slot):
    """Every table numbered in twos: odd on node 1, even on node 2."""
    slot = int(slot)
    for table in TABLES:
        if table in ('meta', 'settings'):
            continue                    # keyed by name, not numbered
        seq = db.value("SELECT pg_get_serial_sequence(?, 'id')", (table,))
        if not seq:
            continue
        top = int(db.value('SELECT COALESCE(MAX(id), 0) FROM %s' % table) or 0)
        start = top + 1
        while start % 2 != slot % 2:
            start += 1
        db.run('ALTER SEQUENCE %s INCREMENT BY 2' % seq)
        # The next nextval() is `start`.
        db.value('SELECT setval(?, ?, false)', (seq, start))


def ha_sequences_check(db, slot):
    """Every hour, and once at start (1.0.59): a table whose next number is
    not above every row in it - rows put back on the other node, a database
    restored from an older snapshot - would hand out a number the other
    node already has, and replication stops on it. Moved past them, on this
    node's side of odd and even."""
    fixed = []
    for table in TABLES:
        if table in ('meta', 'settings'):
            continue
        seq = db.value("SELECT pg_get_serial_sequence(?, 'id')", (table,))
        if not seq:
            continue
        st = db.row('SELECT last_value, is_called FROM %s' % seq)
        inc = int(db.value('SELECT increment_by FROM pg_sequences WHERE '
                           "schemaname || '.' || sequencename = ? OR sequencename = ?",
                           (seq, seq.split('.')[-1])) or 1)
        nxt = int(st['last_value']) + (inc if st['is_called'] else 0)
        top = int(db.value('SELECT COALESCE(MAX(id), 0) FROM %s' % table) or 0)
        if nxt > top and inc == 2 and nxt % 2 == int(slot) % 2:
            continue
        if inc == 2 and nxt % 2 == int(slot) % 2:
            # (1.0.61) Only behind the other node's rows - the usual thing where one
            # node takes more of the traffic, and harmless: moved past them
            # quietly, so no number of its own can ever meet a row put back.
            start = top + 1 + ((int(slot) - top - 1) % 2)
            db.value('SELECT setval(?, ?, false)', (seq, start))
            continue
        start = top + 1
        while start % 2 != int(slot) % 2:
            start += 1
        db.run('ALTER SEQUENCE %s INCREMENT BY 2' % seq)
        db.value('SELECT setval(?, ?, false)', (seq, max(start, nxt if nxt % 2 == int(slot) % 2
                                                      else start)))
        fixed.append(table)
    if fixed:
        log('the numbering of %s was behind the rows in it, or on the other node\'s side: '
            'moved on' % ', '.join(fixed), 'warn')
    return fixed


def ha_wait_copied(db, sub, say, seconds=3600):
    t0 = time.time()
    while time.time() - t0 < seconds:
        left = db.rows("SELECT c.relname AS t, r.srsubstate AS s FROM pg_subscription_rel r "
                       "JOIN pg_subscription s ON s.oid = r.srsubid "
                       "JOIN pg_class c ON c.oid = r.srrelid WHERE s.subname = ? "
                       "AND r.srsubstate <> 'r'", (sub,))
        if not left and db.value('SELECT COUNT(*) FROM pg_subscription_rel r JOIN '
                                 'pg_subscription s ON s.oid = r.srsubid WHERE s.subname = ?',
                                 (sub,)):
            return True
        say('copying: %s still to come' % ', '.join(sorted(x['t'] for x in left)[:6]))
        time.sleep(2)
    raise ValueError('the copy from the other node did not finish in %d s' % seconds)


def ha_subscribe(db, sub, conninfo, copy_data):
    """A subscription made on `db`. The statement carries the password of
    the account in its conninfo, so it is kept out of PostgreSQL's log for
    the session, and out of any error that comes back."""
    # Tried from here first (1.0.44): the SETs below need a superuser, which
    # the otp account is not, so a CREATE SUBSCRIPTION that fails - the
    # other node unreachable, a wrong password - would be written to
    # PostgreSQL's log with the password in it. What fails here is never
    # sent.
    try:
        import psycopg2
        probe = psycopg2.connect(conninfo + ' connect_timeout=10')
        probe.close()
    except ImportError:
        pass
    except Exception as e:                              # noqa: BLE001
        raise ValueError('the other node\'s database cannot be reached from here, so the '
                         'subscription %s was not made: %s'
                         % (sub, scrub_secret(str(e).split('\n')[0][:300])))
    for quiet in ("SET log_statement = 'none'", "SET log_min_error_statement = 'panic'"):
        try:
            db.run(quiet)
        except Exception:                               # noqa: BLE001
            pass                                        # not a superuser: logged as usual
    try:
        db.run(RawSql("CREATE SUBSCRIPTION %s CONNECTION '%s' PUBLICATION %s WITH (copy_data = %s, "
                      "origin = none)" % (sub, conninfo.replace("'", "''"), HA_PUB,
                                          'true' if copy_data else 'false')))
    except Exception as e:                              # noqa: BLE001
        raise ValueError('the subscription %s could not be made: %s'
                         % (sub, scrub_secret(str(e).split('\n')[0][:300])))
    finally:
        for back in ('RESET log_statement', 'RESET log_min_error_statement'):
            try:
                db.run(back)
            except Exception:                           # noqa: BLE001
                pass


HA_REBUILD_FAILED_WHY = ('a rebuild from the other node failed half way - its tables are '
                         'not whole: rebuild it again (Settings → High availability)')


def ha_rebuild(local, remote, *args):
    """Never two at once (1.0.59): both nodes rebuilding from each other
    emptied both. The same lock is taken in both databases - the other
    node's rebuild holds it in its own and in this one."""
    held = []
    try:
        for db in (local, remote):
            if not db.value('SELECT pg_try_advisory_lock(?)', (HA_REBUILD_LOCK,)):
                raise ValueError('a rebuild is running already (on this node or the other one)')
            held.append(db)
        return _ha_rebuild(local, remote, *args)
    finally:
        for db in held:
            try:
                db.value('SELECT pg_advisory_unlock(?)', (HA_REBUILD_LOCK,))
            except Exception:                           # noqa: BLE001
                pass


def _ha_rebuild(local, remote, my_slot, peer_slot, my_host, my_port, peer_host, peer_port,
                name, user, password, say):
    """This node rebuilt from the other: both subscriptions made afresh, this
    node's tables emptied and every row copied over. What this node held is
    replaced by what the other holds."""
    mine_on_peer = ha_sub_name(my_slot)       # on the peer: brings my rows to it
    theirs_here = ha_sub_name(peer_slot)      # here: brings the peer's rows to me
    say('the other node stops taking rows from this one')
    ha_drop_sub(remote, mine_on_peer)
    ha_drop_slot(local, mine_on_peer)
    say('this node stops taking rows from the other')
    ha_drop_sub(local, theirs_here)
    ha_drop_slot(remote, theirs_here)
    say('this node\'s tables emptied')
    local.make_tables()
    # Nothing written here while the rows come over (1.0.44): the heartbeat
    # and the job's own progress wrote rows the copy then met again, and it
    # stopped on a duplicate key for good.
    HA_REBUILDER[0] = threading.get_ident()    # before the flag (1.0.59)
    HA_REBUILDING.set()
    done = False
    try:
        local.run('TRUNCATE %s RESTART IDENTITY' % ', '.join(TABLES))
        say('every row copied from the other node')
        ha_subscribe(local, theirs_here, ha_conninfo(peer_host, peer_port, name, user, password),
                     copy_data=True)
        ha_wait_copied(local, theirs_here, say)
        ha_sequences(local, my_slot)
        # The other node's subscription - and with it the point it starts
        # from - made before this node writes anything again (1.0.57): what
        # was written in between never went over.
        say('the other node takes this one\'s rows from now on')
        ha_subscribe(remote, mine_on_peer, ha_conninfo(my_host, my_port, name, user, password),
                     copy_data=False)
        done = True
    finally:
        # Odd or even again whatever happened (1.0.57): RESTART IDENTITY
        # left them at 1 with the other node's numbering.
        try:
            ha_sequences(local, my_slot)
        except Exception as e:                          # noqa: BLE001
            log('the numbering could not be set again: %s' % e, 'warn')
        HA_REBUILDER[0] = None
        HA_REBUILDING.clear()
        # Failed after its tables were emptied (1.0.94): the node stays out of
        # service, not back answering every person "no such token" with
        # nothing replicating - until a rebuild goes through.
        store = HA_STORE.get('store')
        if store is not None:
            try:
                row = maintenance_row(store)
                if not done:
                    maintenance_set(store, True, HA_REBUILD_FAILED_WHY, 'the rebuild')
                elif row.get('on') and row.get('why') == HA_REBUILD_FAILED_WHY:
                    maintenance_set(store, False, '', 'the rebuild')
            except Exception as e:                      # noqa: BLE001
                log('maintenance after the rebuild could not be written: %s' % e, 'error')
    rows = sum(int(local.value('SELECT COUNT(*) FROM %s' % t) or 0) for t in TABLES)
    return {'rows': rows}


def ha_repl_state(store):
    """Both directions, as this node's PostgreSQL sees them."""
    db = store.db
    out = {'mode': CONFIG.get('ha_mode') or '', 'slot': CONFIG.get('ha_slot') or 0,
           'peer': CONFIG.get('ha_peer') or '', 'incoming': [], 'outgoing': []}
    if out['mode'] != 'replicated' or db.engine != 'postgres':
        return out
    try:
        for r in db.rows(
                'SELECT s.subname AS name, s.subenabled AS enabled, st.pid AS pid, '
                'EXTRACT(EPOCH FROM st.last_msg_receipt_time) AS last_msg, '
                'EXTRACT(EPOCH FROM st.latest_end_time) AS latest_end, '
                'COALESCE(ss.apply_error_count, 0) AS apply_errors, '
                'COALESCE(ss.sync_error_count, 0) AS sync_errors '
                'FROM pg_subscription s LEFT JOIN pg_stat_subscription st '
                'ON st.subid = s.oid AND st.relid IS NULL '
                'LEFT JOIN pg_stat_subscription_stats ss ON ss.subid = s.oid '
                # Only this database's (1.0.57): the catalog is the server's.
                'WHERE s.subdbid = (SELECT oid FROM pg_database WHERE datname = '
                'current_database())'):
            r['running'] = bool(r.get('pid'))
            out['incoming'].append(r)
        for r in db.rows(
                "SELECT slot_name AS name, active, wal_status, "
                "pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn) AS behind "
                "FROM pg_replication_slots WHERE slot_name LIKE 'o__!_from!_%' ESCAPE '!' "
                "AND database = current_database()"):
            r['behind'] = int(float(r.get('behind') or 0))
            out['outgoing'].append(r)
    except Exception as e:                              # noqa: BLE001
        out['trouble'] = str(e).split('\n')[0][:300]
    healthy = bool(out['incoming']) and all(x['enabled'] and x['running'] for x in
                                            out['incoming']) and bool(out['outgoing']) and \
        all(x['wal_status'] not in ('lost',) for x in out['outgoing'])
    out['healthy'] = healthy
    out['lost'] = any(x.get('wal_status') == 'lost' for x in out['outgoing'])
    return out


def ha_peer_columns():
    """Columns of a later version added to the other node's tables too."""
    try:
        far = ha_peer_db()
    except Exception as e:                              # noqa: BLE001
        log('the other node\'s database could not be reached to add new columns: %s'
            % str(e).split('\n')[0][:200], 'warn')
        return
    try:
        far.add_missing_columns()
    except Exception as e:                              # noqa: BLE001
        log('new columns could not be added on the other node: %s' % e, 'warn')
    finally:
        try:
            far.close()
        except Exception:                               # noqa: BLE001
            pass


# ---- used once, on either node (1.0.101) -------------------------------------
# A code's time step, a recovery code, an answered question: each is written
# as a row of its own in token_once, by this node under its own number, and
# never changed - so replication, which writes whole rows, cannot write an
# older copy over it. And with two replicating databases, a node that takes
# one also looks in the other node's database for that node's row, after
# writing its own: of two nodes asked for the same code at the same moment,
# at least one sees the other's row - so it is never let in twice. (One may
# refuse it when both see each other; the next code then goes through.)
ONCE_PEER = {'db': None, 'down_until': 0.0, 'said': 0.0}
ONCE_PEER_LOCK = threading.Lock()
ONCE_KEEP_S = {'step': 3 * 86400, 'chal': 3 * 86400, 'scratch': 800 * 86400}


def once_node():
    return int(CONFIG.get('ha_slot') or 1) if CONFIG.get('ha_mode') == 'replicated' else 0


def once_key(kind, name, value):
    h = hashlib.sha256(('%s\n%s' % (norm_name(name), value)).encode('utf-8')).hexdigest()
    return '%s:%s' % (kind, h[:48])


def _once_peer_has(k, me):
    """Whether the other node's database has the other node's row for `k`:
    True, False, or None when it cannot be asked just now. Asked on a
    connection of its own with a 2 s limit, and waited for 2.5 s at most
    (1.0.101): a peer that drops packets without a word must not hold every
    sign-in that was let in."""
    with ONCE_PEER_LOCK:
        if ONCE_PEER['down_until'] > time.time():
            return None
        db = ONCE_PEER['db']
    got = {}

    def ask():
        nonlocal db
        try:
            if db is None:
                db = db_open(ha_peer_conf(timeout=2), statement_s=2)
                with ONCE_PEER_LOCK:
                    if ONCE_PEER['db'] is None:
                        ONCE_PEER['db'] = db
            got['v'] = bool(db.value('SELECT 1 FROM token_once WHERE k = ? AND node <> ?',
                                     (k, me)))
        except Exception as e:                          # noqa: BLE001
            got['e'] = e
    t = threading.Thread(target=ask, name='once-peer', daemon=True)
    t.start()
    t.join(2.5)
    if 'v' in got:
        return got['v']
    e = got.get('e') or TimeoutError('no answer within 2.5 s')
    with ONCE_PEER_LOCK:
        was, ONCE_PEER['db'] = ONCE_PEER['db'], None
        ONCE_PEER['down_until'] = time.time() + 20
        say = ONCE_PEER['said'] < time.time() - 300
        if say:
            ONCE_PEER['said'] = time.time()
    if was is not None and not t.is_alive():
        try:
            was.close()
        except Exception:                               # noqa: BLE001
            pass
    if say:
        log('the other node\'s database cannot be asked whether a code was used there '
            '(%s): codes are checked against this node\'s rows alone until it can'
            % str(e).split('\n')[0][:200], 'warn')
    return None


def once_take(store, kind, name, value):
    """True if this is the first use of it anywhere; False if it was used
    before, here or on the other node. A database error here raises: the
    request then goes unanswered, never let in."""
    k = once_key(kind, name, value)
    me = once_node()
    db = store.db
    if db.engine == 'mariadb':
        sql = 'INSERT IGNORE INTO token_once (k, node, ts) VALUES (?, ?, ?)'
    elif db.engine == 'sqlite':
        sql = 'INSERT OR IGNORE INTO token_once (k, node, ts) VALUES (?, ?, ?)'
    else:
        sql = 'INSERT INTO token_once (k, node, ts) VALUES (?, ?, ?) ON CONFLICT DO NOTHING'
    if not db.run(sql, (k, me, time.time())):
        return False                    # this node took it already
    if db.value('SELECT 1 FROM token_once WHERE k = ? AND node <> ?', (k, me)):
        return False                    # the other node took it, and it came over
    if me and CONFIG.get('ha_mode') == 'replicated' and CONFIG.get('ha_peer'):
        if _once_peer_has(k, me):
            return False                # the other node took it, not over yet
    return True


def once_tidy(store):
    """Rows no longer needed: a time step or a question long past."""
    t = time.time()
    for r in store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'scratchguard:%'"):
        try:
            last = max([float(x) for x in json.loads(r['v'] or '[]')] or [0])
        except (ValueError, TypeError):
            last = 0
        if t - last > 86400:
            store.db.run('DELETE FROM meta WHERE k = ? AND v = ?', (r['k'], r['v']))
    for kind, keep in ONCE_KEEP_S.items():
        store.db.run('DELETE FROM token_once WHERE substr(k, 1, ?) = ? AND ts < ?',
                     (len(kind) + 1, kind + ':', t - keep))


def ha_peer_db():
    return db_open(ha_peer_conf())


def ha_control(store, act, by=''):
    """Replication worked by hand: paused, resumed, switched off, refreshed.
    `in` is what this node takes from the other (its own subscription);
    `out` is what the other takes from this one (the other's subscription,
    reached over its PostgreSQL). (1.0.14)"""
    if CONFIG.get('ha_mode') != 'replicated':
        raise ValueError('this node does not replicate')
    slot = int(CONFIG.get('ha_slot') or 1)
    peer_slot = 3 - slot
    here = store.db
    sub_in = ha_sub_here(here, peer_slot)
    said = []

    def on_peer(fn):
        try:
            far = ha_peer_db()
        except Exception as e:                          # noqa: BLE001
            raise ValueError('the other node\'s PostgreSQL cannot be reached: %s'
                             % str(e).split('\n')[0][:200])
        try:
            return fn(far)
        finally:
            far.close()

    def has(db, sub):
        return bool(db.value('SELECT 1 FROM pg_subscription WHERE subname = ?', (sub,)))

    if act in ('pause_in', 'pause'):
        if has(here, sub_in):
            here.run('ALTER SUBSCRIPTION %s DISABLE' % sub_in)
            said.append('this node takes nothing from the other for now')
    if act in ('pause_out', 'pause'):
        def p(far):
            sub_out = ha_sub_here(far, slot)
            if has(far, sub_out):
                far.run('ALTER SUBSCRIPTION %s DISABLE' % sub_out)
                said.append('the other node takes nothing from this one for now')
        on_peer(p)
    if act in ('resume_in', 'resume'):
        if has(here, sub_in):
            here.run('ALTER SUBSCRIPTION %s ENABLE' % sub_in)
            said.append('this node takes the other\'s rows again, from where it stopped')
    if act in ('resume_out', 'resume'):
        def r(far):
            sub_out = ha_sub_here(far, slot)
            if has(far, sub_out):
                far.run('ALTER SUBSCRIPTION %s ENABLE' % sub_out)
                said.append('the other node takes this one\'s rows again, from where it '
                            'stopped')
        on_peer(r)
    if act == 'refresh':
        if has(here, sub_in):
            here.run('ALTER SUBSCRIPTION %s REFRESH PUBLICATION WITH (copy_data = false)'
                     % sub_in)
        said.append('the list of tables taken from the other was read again')
    if act == 'stop':
        # Both directions taken away; both nodes go on alone, each with what
        # it has. Joining them again is a rebuild of one from the other.
        ha_drop_sub(here, sub_in)
        try:
            on_peer(lambda far: (ha_drop_sub(far, ha_sub_name(slot)), ha_drop_slot(far, sub_in)))
        except ValueError as e:
            said.append('the other node could not be reached (%s): take its subscription '
                        'away there with otp --ha-stop' % e)
        ha_drop_slot(here, ha_sub_name(slot))
        said.append('replication is off: each node goes on alone with what it has')
    if not said:
        raise ValueError('nothing to do: %s' % act)
    store.add_event('settings', '%s: replication - %s' % (by or 'command line', '; '.join(said)),
                    'warn', who=by or 'command line')
    return {'message': '; '.join(said)}


def ha_resync_job(store, by):
    """This node rebuilt from the other, as a job the pages can follow."""
    if CONFIG.get('ha_mode') != 'replicated':
        raise ValueError('this node does not replicate')

    def work(progress):
        steps = []

        def say(t):
            steps.append(t)
            progress(len(steps), 8, t)
        progress(0, 8, 'making a copy of what is here first')
        copy = make_backup(store, 'before rebuilding from the other node, by %s' % by)
        remote = ha_peer_db()
        try:
            got = ha_rebuild(store.db, remote, int(CONFIG.get('ha_slot') or 2),
                             3 - int(CONFIG.get('ha_slot') or 2),
                             CONFIG.get('ha_address') or node_address(),
                             int(CONFIG.get('db_port') or 5432), CONFIG.get('ha_peer'),
                             int(CONFIG.get('ha_peer_port') or 5432), CONFIG.get('db_name'),
                             CONFIG.get('db_user'), CONFIG.get('db_password'), say)
        finally:
            remote.close()
        store._clients = store._realms = None
        store.set_meta('conf_serial', '%.6f:%s' % (time.time(), node_name()))
        store.add_event('settings', '%s rebuilt this node from the other: %d row(s); what it '
                        'held is in %s' % (by, got['rows'], copy.name), 'warn', who=by)
        progress(8, 8, 'done')
        return {'rows': got['rows'], 'copy': copy.name, 'where': CONFIG.get('ha_peer')}
    return db_job('rebuilding this node from the other', work)


def bytes_words(n):
    n = float(n or 0)
    for unit in ('B', 'kB', 'MB', 'GB', 'TB'):
        if n < 1024 or unit == 'TB':
            return ('%d %s' % (n, unit)) if unit == 'B' else ('%.1f %s' % (n, unit))
        n /= 1024.0


# ---------------------------------------------------------------------------
# Maintenance, and a new version put in from the pages (1.0.37)
# ---------------------------------------------------------------------------
# Maintenance is per node: the node stops answering RADIUS (the VPN goes to
# the other one, as it would to a node that is down) and /healthz says 503
# (the load balancer takes it out). The pages go on working, so the node can
# be looked at and brought back.
#
# An upgrade: the package goes into the database, in pieces (so the other
# node of a cluster has it too), and a plan says which nodes, in which
# order. Each node does its own turn when it comes - maintenance on, a
# moment for the balancer to notice, the package handed to root
# (otp_upgrade.py, by otp-upgrade.path), and after its restart its own
# check before it leaves maintenance. Then the next one.
#
# Every row has ONE node that writes it (the plan: the one that started it;
# `upgrade:node:X` and `maint:X`: node X - or, for maintenance, the pages,
# which only ever UPDATE it). Replicated, a newer version may add a column,
# and the older node then takes nothing more from it until it is upgraded
# too; so a node's own rows are also written straight into the other's
# database - an UPDATE of a row both have, never an INSERT, which the
# replication arriving later would then collide with.
UPGRADE_DIR = STATE_DIR / 'upgrade'
UPGRADE_HELPER = Path(os.environ.get('OTP_UPGRADE_HELPER',
                                     str(Path(__file__).resolve().parent / 'otp_upgrade.py')))
UPGRADE_MOST = 64 * 1024 * 1024
UPGRADE_PIECE = 40000                       # base64 characters in one meta row
UPGRADE_DRAIN_S = int(os.environ.get('OTP_UPGRADE_DRAIN_S', '20'))
UPGRADE_TIMEOUT_S = 30 * 60
MAINT_CACHE = {'at': 0.0, 'row': None}
RESTORE_RUNNING = threading.Event()
RESTORE_WHY = ['']


def _meta_json(store, k):
    try:
        got = store.get_meta(k)
        return json.loads(got) if got else None
    except (ValueError, TypeError):
        return None


def _peer_update(k, v):
    """The same row changed in the other node's database too - UPDATE only."""
    if CONFIG.get('ha_mode') != 'replicated' or not CONFIG.get('ha_peer'):
        return False
    try:
        far = ha_peer_db()
    except Exception:                                   # noqa: BLE001
        return False
    try:
        return bool(far.run('UPDATE meta SET v = ? WHERE k = ?', (v, k)))
    except Exception:                                   # noqa: BLE001
        return False
    finally:
        try:
            far.close()
        except Exception:                               # noqa: BLE001
            pass


def _row_write(store, k, data, mine=True, mirror=True):
    """A row of this node's own (made here if need be), or someone else's
    (only ever UPDATEd)."""
    v = json.dumps(data, default=str)
    if store.db.value('SELECT k FROM meta WHERE k = ?', (k,)) is None:
        if not mine:
            raise ValueError('that node has not been heard of here yet')
        store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)', (k, v))
    else:
        store.db.run('UPDATE meta SET v = ? WHERE k = ?', (v, k))
    if mirror:
        _peer_update(k, v)


# ---- maintenance ---------------------------------------------------------------------
def maintenance_row(store, name=None):
    return _meta_json(store, 'maint:' + (name or node_name())) or {'on': False}


def maintenance_now(store):
    """This node's maintenance, read at most every two seconds - asked for
    every RADIUS packet."""
    if HA_REBUILDING.is_set():
        return {'on': True, 'why': 'rebuilt from the other node'}
    if RESTORE_RUNNING.is_set():
        # A backup put back (1.0.149): RADIUS waited for the whole of it with
        # the database held, or met tables being made again and refused. Room
        # given back in a cluster too (1.0.150): VACUUM FULL holds each table
        # shut - the other node answers meanwhile.
        return {'on': True, 'why': RESTORE_WHY[0] or 'a backup is being put back'}
    now = time.time()
    if now - MAINT_CACHE['at'] > 2:
        MAINT_CACHE['at'] = now
        try:
            MAINT_CACHE['row'] = maintenance_row(store)
        except Exception:                               # noqa: BLE001
            pass                                        # the last one known stands
    return MAINT_CACHE['row'] or {'on': False}


def maintenance_ensure(store):
    """The row of this node, made by this node: the pages only change it."""
    if HA_REBUILDING.is_set():
        return
    try:
        if store.get_meta('maint:' + node_name()) is None:
            store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)',
                         ('maint:' + node_name(), json.dumps({'on': False})))
    except Exception:                                   # noqa: BLE001
        pass


def maintenance_set(store, on, why='', by='', name=None):
    name = name or node_name()
    row = {'on': bool(on), 'why': str(why or '')[:200], 'by': str(by or '')[:100],
           'at': time.time()}
    _row_write(store, 'maint:' + name, row, mine=(name == node_name()))
    MAINT_CACHE['at'] = 0
    store.add_event('starting and stopping', '%s: %s%s' % (
        name, 'in maintenance' if on else 'back in service',
        (' - ' + why) if why and on else ''), 'warn' if on else 'info', who=by or None)
    return row


# ---- the package --------------------------------------------------------------------
def upgrade_inspect(path):
    """What the package is, asked of otp_upgrade.py - the same check root
    makes again before putting it in."""
    if not UPGRADE_HELPER.exists():
        raise ValueError('otp_upgrade.py is not installed beside otp.py; upgrade once on the '
                         'command line (install.sh --upgrade)')
    try:
        r = subprocess.run([sys.executable, '-I', str(UPGRADE_HELPER), '--inspect', str(path)],
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=300)
        got = json.loads(r.stdout.decode('utf-8', 'replace') or '{}')
    except (OSError, ValueError, subprocess.SubprocessError) as e:
        raise ValueError('the package could not be checked: %s' % e)
    if not got.get('ok'):
        raise ValueError(got.get('said') or 'the package was refused')
    return got


def upgrade_store_package(store, path, info, by):
    """The package into the database in pieces, the one before taken out."""
    raw = Path(path).read_bytes()
    sha = hashlib.sha256(raw).hexdigest()
    text = base64.b64encode(raw).decode('ascii')
    pieces = [text[i:i + UPGRADE_PIECE] for i in range(0, len(text), UPGRADE_PIECE)]
    old = _meta_json(store, 'upgrade:pkg') or {}
    # Every other package's pieces out, not only the last one's (1.0.44).
    store.db.run("DELETE FROM meta WHERE k LIKE 'upgrade:piece:%' AND k NOT LIKE ?",
                 ('upgrade:piece:%s:%%' % sha[:16],))
    for i, one in enumerate(pieces):
        k = 'upgrade:piece:%s:%04d' % (sha[:16], i)
        if store.get_meta(k) is None:
            store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)', (k, one))
    meta = {'sha': sha, 'version': info['version'], 'bytes': len(raw), 'pieces': len(pieces),
            'signed_by': info.get('signed_by'), 'changelog': info.get('changelog', ''),
            'by': by, 'at': time.time()}
    store.set_meta('upgrade:pkg', json.dumps(meta))
    return meta


def upgrade_package_file(store, meta):
    """The package back out of the database, to the folder root takes it
    from - from the other node's database when this one has not all of it
    yet."""
    UPGRADE_DIR.mkdir(mode=0o750, exist_ok=True)
    out = UPGRADE_DIR / ('otp-%s.tar.gz' % meta['version'])

    def pieces_of(db):
        rows = db.rows("SELECT k, v FROM meta WHERE k LIKE ? ESCAPE '!' ORDER BY k",
                       ('upgrade:piece:%s:%%' % meta['sha'][:16],))
        return [r['v'] for r in rows]
    got = pieces_of(store.db)
    if len(got) != int(meta['pieces']) and CONFIG.get('ha_mode') == 'replicated':
        far = ha_peer_db()
        try:
            got = pieces_of(far)
        finally:
            far.close()
    if len(got) != int(meta['pieces']):
        raise ValueError('the package has not all arrived in this node\'s database')
    raw = base64.b64decode(''.join(got))
    if hashlib.sha256(raw).hexdigest() != meta['sha']:
        raise ValueError('the package in the database is damaged')
    tmp = out.with_suffix('.part')
    try:
        tmp.unlink()
    except OSError:
        pass
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o640)
    with os.fdopen(fd, 'wb') as f:
        f.write(raw)
    os.replace(str(tmp), str(out))
    return out


# ---- the plan ------------------------------------------------------------------------
def upgrade_nodes_now(store):
    """The nodes an upgrade goes over: every one heard from lately, or this
    one alone."""
    nodes = [n for n in ha_nodes(store) if n.get('alive')]
    if not nodes:
        nodes = [{'name': node_name(), 'version': __version__, 'me': True, 'alive': True}]
    return nodes


def upgrade_plan(store):
    plan = _meta_json(store, 'upgrade:plan')
    if not plan:
        return None
    plan['steps'] = []
    plan['drain_s'] = UPGRADE_DRAIN_S
    for name in plan.get('order') or []:
        row = _meta_json(store, 'upgrade:node:' + name) or {}
        if row.get('id') != plan.get('id'):
            row = {'state': 'waiting'}
        row['name'] = name
        plan['steps'].append(row)
    states = [s.get('state') for s in plan['steps']]
    if any(s == 'failed' for s in states):
        plan['state'] = 'failed'
    elif states and all(s == 'done' for s in states):
        plan['state'] = 'done'
    elif plan.get('cancelled'):
        plan['state'] = 'cancelled'
    else:
        plan['state'] = 'running'
    return plan


def upgrade_checks(store, meta, pages=False):
    """What must be so before an upgrade starts - (ok, [why not]). A package
    to go back to (1.0.143) is looked at again as it was when it was taken."""
    why = []
    if not meta:
        return False, ['no package has been sent yet']
    down = bool(meta.get('downgrade'))
    if down:
        why += downgrade_why_not(store, meta['version'])
        if pages and not CONFIG.get('upgrade_downgrade'):
            # Switched off since it was fetched (1.0.146): not started from the pages.
            why.append('going back to an older version is switched off (Settings → Upgrades)')
    nodes = upgrade_nodes_now(store)
    for n in ha_nodes(store):
        if not n.get('alive'):
            why.append('%s has not been heard from for %d s - bring it back, or forget it '
                       '(Settings - High availability)' % (n['name'], int(n.get('age') or 0)))
    for n in nodes:
        have = str(n.get('version') or '')
        try:
            if have and not down and tuple(int(x) for x in have.split('.')) > \
                    tuple(int(x) for x in meta['version'].split('.')):
                why.append('%s runs %s, newer than %s' % (n['name'], have, meta['version']))
        except ValueError:
            pass
    if CONFIG.get('ha_mode') == 'replicated':
        rep = ha_repl_state(store)
        if not rep.get('healthy'):
            why.append('the replication is not running both ways - see Settings - High '
                       'availability')
    plan = upgrade_plan(store)
    if plan and plan['state'] == 'running':
        why.append('an upgrade is going on already')
    return not why, why


def upgrade_start(store, by, pages=False):
    meta = _meta_json(store, 'upgrade:pkg')
    ok, why = upgrade_checks(store, meta, pages)
    if not ok:
        raise ValueError('; '.join(why))
    names = [n['name'] for n in upgrade_nodes_now(store)]
    me = node_name()
    # The others first and this node last: the pages it shows stay up the
    # longest, and the first node is the one somebody can look at while it
    # is done.
    order = sorted(n for n in names if n != me) + ([me] if me in names else [])
    ident = '%d-%s' % (int(time.time()), secrets.token_hex(4))
    for name in order:
        k = 'upgrade:node:' + name
        if store.get_meta(k) is None:
            # Made here, for every node, before anything else: from then on
            # each node only UPDATEs its own.
            store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)',
                         (k, json.dumps({'state': 'none'})))
    plan = {'id': ident, 'version': meta['version'], 'sha': meta['sha'], 'order': order,
            'by': by, 'at': time.time(), 'from': me, 'downgrade': bool(meta.get('downgrade'))}
    store.set_meta('upgrade:plan', json.dumps(plan))
    store.add_event('starting and stopping', '%s started %s %s: %s, one at a time' % (
        by, 'going back to' if plan['downgrade'] else 'the upgrade to', meta['version'],
        ', '.join(order)), 'warn', who=by)
    return upgrade_plan(store)


def upgrade_cancel(store, by):
    plan = _meta_json(store, 'upgrade:plan')
    if not plan:
        raise ValueError('no upgrade is going on')
    plan['cancelled'] = {'by': by, 'at': time.time()}
    store.set_meta('upgrade:plan', json.dumps(plan))
    _peer_update('upgrade:plan', json.dumps(plan))
    store.add_event('starting and stopping', '%s stopped the upgrade to %s: the nodes not '
                    'begun stay as they are' % (by, plan.get('version')), 'warn', who=by)


def _my_step(store, plan, **fields):
    k = 'upgrade:node:' + node_name()
    row = _meta_json(store, k) or {}
    if row.get('id') != plan['id']:
        row = {'id': plan['id']}
    row.update(fields)
    row['at'] = time.time()
    _row_write(store, k, row, mine=False)
    return row


def _helper_status():
    try:
        fd = os.open(str(UPGRADE_DIR / 'status.json'), os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, 'rb') as f:
            return json.loads(f.read(1 << 20).decode('utf-8'))
    except (OSError, ValueError):
        return {}


def upgrade_log_tail(lines=200):
    try:
        fd = os.open(str(UPGRADE_DIR / 'last.log'), os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, 'rb') as f:
            text = f.read(4 << 20).decode('utf-8', 'replace')
        return text.splitlines()[-lines:]
    except OSError:
        return []


def upgrade_tick(daemon):
    """This node's part of the plan, every few seconds."""
    store = daemon.store
    if HA_REBUILDING.is_set():
        return
    plan = upgrade_plan(store)
    # A cancelled plan is still finished where a node has begun (1.0.44):
    # one that drains goes back into service, one that installs is checked
    # and comes back - it never stays in maintenance for good.
    if plan and plan['state'] == 'failed':
        _back_after_marked(store, plan)
    if not plan or plan['state'] not in ('running', 'cancelled'):
        return
    me = node_name()
    if store.get_meta('upgrade:node:' + me) is None:
        return                          # its row has not come over from the other node yet
    steps = plan['steps']
    turn = next((s for s in steps if s.get('state') != 'done'), None)
    if turn and turn['name'] != me and turn.get('state') in ('draining', 'installing',
                                                             'checking'):
        # The node whose turn it is gone for longer than an upgrade takes
        # (1.0.59): marked failed from here, or the plan ran for ever and
        # stopped every new upload and start until somebody cancelled it.
        alive = any(n.get('name') == turn['name'] and n.get('alive')
                    for n in ha_nodes(store))
        if not alive and now_minus(turn.get('at')) > UPGRADE_TIMEOUT_S + 300 and \
                not _peer_still_at_it(turn):
            row = dict(turn)
            row.pop('name', None)
            row.update({'state': 'failed', 'at': time.time(), 'marked_by': me,
                        'said': 'not heard from for %d min while %s - marked failed by %s'
                                % (UPGRADE_TIMEOUT_S // 60 + 5, turn.get('state'), me)})
            try:
                _row_write(store, 'upgrade:node:' + turn['name'], row, mine=False)
                store.add_event('starting and stopping', 'the upgrade of %s to %s failed: '
                                'the node has not been heard from' % (turn['name'],
                                                                      plan['version']), 'bad')
            except Exception as e:                      # noqa: BLE001
                log('the upgrade of %s could not be marked failed: %s' % (turn['name'], e),
                    'warn')
        return
    if not turn or turn['name'] != me:
        return
    state = turn.get('state')
    now = time.time()
    if plan.get('cancelled') and state in ('waiting', 'none', None, 'cancelled'):
        return
    if plan.get('cancelled') and state == 'draining':
        if not turn.get('was_maint'):
            maintenance_set(store, False, by=plan.get('by') or '')
        _my_step(store, plan, state='cancelled', said='cancelled before it was installed; '
                 'back in service')
        return
    if state in ('waiting', 'none', None) and len(steps) > 1:
        # Never both out at once (1.0.44): the others have to be alive and
        # in service before this one leaves.
        for n in ha_nodes(store):
            if n['name'] == me or n['name'] not in [x['name'] for x in steps]:
                continue
            if not n.get('alive') or maintenance_row(store, n['name']).get('on'):
                if turn.get('said') != 'waiting for %s to be in service' % n['name']:
                    _my_step(store, plan, state='waiting',
                             said='waiting for %s to be in service' % n['name'])
                return
    if state in ('waiting', 'none', None):
        was = maintenance_row(store)
        alone = len(steps) == 1
        maintenance_set(store, True, 'upgrade to %s' % plan['version'], plan.get('by') or '')
        _my_step(store, plan, state='draining', was_maint=bool(was.get('on')),
                 began=now, said='in maintenance; the balancer and the VPN go to the other '
                 'node' if not alone else 'in maintenance')
        if not alone:
            return
        state = 'draining'
        turn = _meta_json(store, 'upgrade:node:' + me)
    if state == 'draining':
        if len(steps) > 1 and now - float(turn.get('at') or 0) < UPGRADE_DRAIN_S:
            return
        meta = _meta_json(store, 'upgrade:pkg') or {}
        try:
            if meta.get('sha') != plan['sha']:
                raise ValueError('the package in the database is not the one this upgrade '
                                 'was started with')
            path = upgrade_package_file(store, meta)
            req = {'id': plan['id'], 'file': path.name, 'sha': plan['sha'],
                   'version': plan['version'], 'by': plan.get('by'), 'at': now,
                   'downgrade': bool(plan.get('downgrade'))}
            tmp = UPGRADE_DIR / 'request.part'
            try:
                tmp.unlink()
            except OSError:
                pass
            fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o640)
            with os.fdopen(fd, 'w') as f:
                json.dump(req, f)
            os.replace(str(tmp), str(UPGRADE_DIR / 'request.json'))
        except Exception as e:                          # noqa: BLE001
            _upgrade_failed(store, plan, turn, 'the package could not be handed over: %s' % e)
            return
        _my_step(store, plan, state='installing', asked=now,
                 said='handed to root (otp-upgrade.service)')
        log('the upgrade to %s is handed to otp-upgrade.service' % plan['version'])
        return
    if state == 'installing':
        if __version__ == plan['version'] and float(daemon.started or 0) > \
                float(turn.get('asked') or 0):
            _my_step(store, plan, state='checking', said='restarted as %s' % __version__)
            state = 'checking'
            turn = _meta_json(store, 'upgrade:node:' + me)
        else:
            got = _helper_status()
            if got.get('id') == plan['id'] and got.get('state') == 'failed':
                _upgrade_failed(store, plan, turn, got.get('said') or
                                'install.sh ended with %s' % got.get('rc'),
                                tail=got.get('tail'))
                return
            if not (UPGRADE_DIR / 'request.json').exists() and \
                    not (UPGRADE_DIR / 'request.taken').exists() and \
                    got.get('id') != plan['id'] and now - float(turn.get('asked') or now) > 120:
                _upgrade_failed(store, plan, turn, 'otp-upgrade.service never took the request '
                                '- is otp-upgrade.path installed and running? (install.sh '
                                '--upgrade once on the command line puts it in)')
                return
            if now - float(turn.get('asked') or now) > UPGRADE_TIMEOUT_S:
                _upgrade_failed(store, plan, turn, 'it has not come back as %s in %d min'
                                % (plan['version'], UPGRADE_TIMEOUT_S // 60))
                return
            # How far install.sh is (1.0.67): its sections, "==> ...", for the
            # bar on the pages - written when one more has begun.
            if got.get('id') == plan['id'] and got.get('state') == 'running':
                parts = [x[4:].strip() for x in upgrade_log_tail(400) if x.startswith('==> ')]
                if parts and len(parts) != int(turn.get('part') or 0):
                    _my_step(store, plan, part=len(parts), part_words=parts[-1][:120],
                             asked=turn.get('asked'))
            return
    if state == 'checking':
        trouble = []
        try:
            store.db.value('SELECT 1')
        except Exception as e:                          # noqa: BLE001
            trouble.append('the database: %s' % e)
        if not getattr(getattr(daemon, 'radius', None), 'bound', None):
            trouble.append('RADIUS is not listening')
        got = _helper_status()
        if got.get('id') == plan['id'] and got.get('state') == 'running':
            if now - float(turn.get('at') or now) < 600:
                return                  # install.sh is still finishing (the firewall, its checks)
            # Not done just because it took long (1.0.44).
            trouble.append('install.sh has not said it finished in 10 min (see '
                           'journalctl -u otp-upgrade)')
        if got.get('id') == plan['id'] and got.get('state') == 'failed':
            trouble.append(got.get('said') or 'install.sh ended with %s' % got.get('rc'))
        if CONFIG.get('ha_mode') == 'replicated':
            ha_refresh_tables(store)
        if trouble:
            _upgrade_failed(store, plan, turn, '; '.join(trouble), tail=got.get('tail'))
            return
        if not turn.get('was_maint'):
            maintenance_set(store, False, by=plan.get('by') or '')
        _my_step(store, plan, state='done', said='%s, checked, back in service' % __version__,
                 tail=(got.get('tail') or [])[-12:])
        store.add_event('starting and stopping', '%s is upgraded to %s' % (me, __version__))
        log('upgraded to %s and back in service' % __version__)
        if all((s.get('state') == 'done') or s['name'] == me for s in steps):
            store.add_event('starting and stopping', 'the upgrade to %s is done on every node'
                            % plan['version'])


def _peer_still_at_it(turn):
    """Its own row read in its own database (1.0.61): while it runs the new
    version, what it writes does not come over to this one - its heartbeat
    looks stale, and a node that was fine was marked failed."""
    try:
        far = ha_peer_db()
    except Exception:                                   # noqa: BLE001
        return False                    # not reachable either: gone indeed
    try:
        row = json.loads(far.value('SELECT v FROM meta WHERE k = ?',
                                   ('upgrade:node:' + turn['name'],)) or '{}')
        beat = json.loads(far.value('SELECT v FROM meta WHERE k = ?',
                                    ('node:' + turn['name'],)) or '{}')
        return row.get('state') == 'done' or now_minus(row.get('at')) < 600 or \
            now_minus(beat.get('at')) < 120
    except Exception:                                   # noqa: BLE001
        return False
    finally:
        try:
            far.close()
        except Exception:                               # noqa: BLE001
            pass


def _back_after_marked(store, plan):
    """A node the other one marked failed while it drained, come back on
    its old version (1.0.61): taken out of the maintenance the upgrade put
    it in, once - nothing else would."""
    me = node_name()
    row = _meta_json(store, 'upgrade:node:' + me) or {}
    if row.get('id') != plan.get('id') or row.get('state') != 'failed' or \
            not row.get('marked_by') or row.get('back') or __version__ == plan.get('version'):
        return
    if not row.get('was_maint'):
        try:
            maintenance_set(store, False, by=plan.get('by') or '')
        except Exception:                               # noqa: BLE001
            return
    row['back'] = True
    try:
        _row_write(store, 'upgrade:node:' + me, row, mine=False)
    except Exception:                                   # noqa: BLE001
        pass
    log('back in service: the upgrade had been marked failed by %s while this node waited'
        % row.get('marked_by'), 'warn')


def now_minus(at):
    try:
        return time.time() - float(at or time.time())
    except (TypeError, ValueError):
        return 0.0


def _upgrade_failed(store, plan, turn, said, tail=None):
    # Already running the new version and its checks failed (1.0.59): kept
    # in maintenance - it is the broken version that would be put in service.
    # Only once it has started again as that version (1.0.61): the same
    # version put in again, failing before anything was installed, left a
    # working node out.
    broken_new = __version__ == plan.get('version') and turn.get('state') == 'checking'
    if broken_new:
        said = '%s - left in maintenance: it runs %s, which did not pass its checks' % (
            said, __version__)
    _my_step(store, plan, state='failed', said=str(said)[:500], tail=(tail or [])[-40:])
    # Back in service where it still runs as it did: a failed upgrade must
    # not leave a working node out.
    if not turn.get('was_maint') and not broken_new:
        try:
            maintenance_set(store, False, by=plan.get('by') or '')
        except Exception:                               # noqa: BLE001
            pass
    store.add_event('starting and stopping', 'the upgrade of %s to %s failed: %s'
                    % (node_name(), plan['version'], said), 'bad')
    log('the upgrade to %s failed: %s' % (plan['version'], said), 'error')


def ha_refresh_tables(store):
    """The list of tables taken from the other node read again, here and
    there: a version that adds a table needs it, and it costs nothing when
    none was added. Where the other node does not have the table yet (it
    is still the older version) its half fails, and it is done again when
    that node comes back upgraded."""
    try:
        ha_control(store, 'refresh', by='the upgrade')
    except Exception as e:                              # noqa: BLE001
        log('reading the tables of the other node again: %s' % e, 'warn')
    slot = int(CONFIG.get('ha_slot') or 1)
    try:
        far = ha_peer_db()
        try:
            far.run('ALTER SUBSCRIPTION %s REFRESH PUBLICATION WITH (copy_data = false)'
                    % ha_sub_here(far, slot))
        finally:
            far.close()
    except Exception as e:                              # noqa: BLE001
        log('the other node could not read this one\'s tables again yet: %s'
            % str(e).split('\n')[0][:200], 'info')
# ---- new versions from the web (1.0.123) ---------------------------------------------
# Settings → Upgrades → upgrade_url is asked once a day (upgrade_check) and when
# Look now is pressed, for otp-X.Y.Z.tar.gz: a GitHub folder through GitHub's
# API, any other page by the links in it, or one package's own address. The
# newest one newer than what runs here is offered (any newer one there can be
# chosen instead, 1.0.142); one click fetches it, and it
# goes the road of a package sent by hand - its signature checked, kept in the
# database for every node, and the upgrade begun. Nothing is put in by itself.
ONLINE_PKG_RE = re.compile(r'(?:^|/)(otp-(\d+)\.(\d+)\.(\d+)\.tar\.gz)(?:\?|#|$)')
ONLINE_EVERY_S = 86400
ONLINE_WORK = {'busy': False, 'at': 0.0}
ONLINE_LOCK = threading.Lock()


def _online_get(url, limit=4 * 1024 * 1024, accept='*/*', timeout=30):
    if not str(url).startswith('https://'):
        raise ValueError('only https:// addresses are asked: %s' % url)
    req = urllib.request.Request(url, headers={
        'User-Agent': 'otp/%s (+upgrade check)' % __version__, 'Accept': accept})
    ctx = ssl.create_default_context()
    with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
        final = r.geturl()
        if not str(final).startswith('https://'):
            raise ValueError('it was sent on to an address that is not https: %s' % final)
        data = r.read(limit + 1)
        if len(data) > limit:
            raise ValueError('the answer from %s is bigger than %d MB' % (url, limit >> 20))
        return data, r.headers.get('Content-Type') or '', final


def _online_ver(m):
    return tuple(int(x) for x in m.group(2, 3, 4))


# Where the releases were before 1.0.138: a value saved as it was the default
# then is taken as the new place.
ONLINE_URL_OLD = 'https://github.com/falco81/Utils/tree/main/otp'


def online_url():
    url = str(CONFIG.get('upgrade_url') or '').strip()
    return DEFAULTS['upgrade_url'] if url.rstrip('/') == ONLINE_URL_OLD else url


def online_list(url):
    """The packages at `url`: [{'name', 'version', 'url', 'bytes'}], newest first."""
    url = str(url or '').strip()
    if not url:
        raise ValueError('no address to look at (Settings → Upgrades)')
    found = {}

    def add(name, link, size=None):
        m = ONLINE_PKG_RE.search('/' + name)
        if not m or not str(link).startswith('https://'):
            return
        found[m.group(1)] = {'name': m.group(1), 'version': '%d.%d.%d' % _online_ver(m),
                             'v': _online_ver(m), 'url': link, 'bytes': size}

    gh = re.match(r'^https://github\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+)'
                  r'(?:/tree/([^/]+)(?:/(.*?))?)?/?$', url)
    m1 = ONLINE_PKG_RE.search(urllib.parse.urlparse(url).path)
    if m1:
        # One package's own address - a GitHub page of it read as the file.
        link = url
        b = re.match(r'^https://github\.com/([^/]+)/([^/]+)/blob/(.+)$', url)
        if b:
            link = 'https://raw.githubusercontent.com/%s/%s/%s' % b.groups()
        add(m1.group(1), link)
    elif gh:
        owner, repo, ref, folder = gh.group(1), gh.group(2), gh.group(3), gh.group(4) or ''
        api = 'https://api.github.com/repos/%s/%s/contents/%s' % (
            owner, repo, urllib.parse.quote(folder.strip('/')))
        if ref:
            api += '?ref=' + urllib.parse.quote(ref)
        try:
            data, _ct, _f = _online_get(api, accept='application/vnd.github+json')
            items = json.loads(data.decode('utf-8'))
        except Exception as e:                          # noqa: BLE001
            # GitHub's API refused (60 questions an hour without an account,
            # or not let through): the folder's own page, read for the names.
            try:
                data, _ct, _f = _online_get(url)
            except Exception:                           # noqa: BLE001
                raise ValueError('GitHub did not answer: %s' % (getattr(e, 'reason', None) or e))
            items = []
            base = 'https://raw.githubusercontent.com/%s/%s/%s/%s' % (
                owner, repo, ref or 'HEAD', (folder.strip('/') + '/') if folder.strip('/') else '')
            for name in set(re.findall(r'otp-\d+\.\d+\.\d+\.tar\.gz',
                                       data.decode('utf-8', 'replace'))):
                items.append({'type': 'file', 'name': name, 'download_url': base + name})
        if isinstance(items, dict):
            items = [items]
        for it in items if isinstance(items, list) else []:
            if isinstance(it, dict) and it.get('type') == 'file' and it.get('download_url'):
                add(str(it.get('name') or ''), str(it['download_url']), it.get('size'))
    else:
        data, ct, final = _online_get(url)
        text = data.decode('utf-8', 'replace')
        try:
            items = json.loads(text) if 'json' in ct or text.lstrip()[:1] in '[{' else None
        except ValueError:
            items = None
        if isinstance(items, list):
            for it in items:
                if isinstance(it, dict):
                    link = it.get('download_url') or it.get('url') or ''
                    add(str(it.get('name') or link), urllib.parse.urljoin(final, str(link)),
                        it.get('size'))
        else:
            for href in re.findall(r'''href\s*=\s*["']([^"']+)["']''', text, re.I):
                link = urllib.parse.urljoin(final, html.unescape(href))
                mm = ONLINE_PKG_RE.search(urllib.parse.urlparse(link).path)
                if mm:
                    add(mm.group(1), link)
    out = sorted(found.values(), key=lambda x: x['v'], reverse=True)
    for x in out:
        x.pop('v', None)
    return out


def _ver_tuple(v):
    try:
        return tuple(int(x) for x in str(v).split('.')[:3])
    except ValueError:
        return (0, 0, 0)


def online_look(store, by=''):
    """Asks the address now; what it found goes into meta 'upgrade:online'."""
    url = online_url()
    row = {'at': time.time(), 'url': url, 'by': by, 'node': node_name(), 'here': __version__}
    try:
        got = online_list(url)
        row['packages'] = got[:10]
        newest = got[0] if got else None
        row['newest'] = newest
        row['newer'] = bool(newest and _ver_tuple(newest['version']) > _ver_tuple(__version__))
        if row['newer']:
            was = _meta_json(store, 'upgrade:online') or {}
            if ((was.get('newest') or {}).get('version') != newest['version']):
                store.add_event('starting and stopping', 'otp %s is out (%s) - Settings → '
                                'Upgrades' % (newest['version'], url), 'info')
    except Exception as e:                              # noqa: BLE001
        row['error'] = str(getattr(e, 'reason', None) or e).split('\n')[0][:300]
    store.set_meta('upgrade:online', json.dumps(row, default=str))
    return row


def online_tick(daemon):
    """Once a day, from whichever node it falls to first."""
    if not CONFIG.get('upgrade_check') or not online_url():
        return
    if time.time() - float(ONLINE_WORK['at'] or 0) < 300:
        return
    ONLINE_WORK['at'] = time.time()
    store = daemon.store
    last = _meta_json(store, 'upgrade:online') or {}
    # Asked again once the address changed, or a day after the last look.
    if last.get('url') == online_url() and \
            time.time() - float(last.get('at') or 0) < ONLINE_EVERY_S:
        return
    with ONLINE_LOCK:
        if ONLINE_WORK['busy']:
            return
        ONLINE_WORK['busy'] = True

    def go():
        try:
            online_look(store)
        except Exception as e:                          # noqa: BLE001
            log('looking for a new version: %s' % e, 'warn')
        finally:
            ONLINE_WORK['busy'] = False
    threading.Thread(target=go, name='otp-online', daemon=True).start()


def online_view(store):
    row = _meta_json(store, 'upgrade:online') or {}
    if row:
        n = row.get('newest') or {}
        row['newer'] = bool(n and _ver_tuple(n.get('version')) > _ver_tuple(__version__))
        row['here'] = __version__
        # Every version there newer than this one, newest first (1.0.142): with
        # more than one the page lets you choose which to go to.
        row['newer_list'] = sorted(
            (p for p in row.get('packages') or []
             if _ver_tuple(p.get('version')) > _ver_tuple(__version__)),
            key=lambda p: _ver_tuple(p.get('version')), reverse=True)
    return {'online': row, 'url': online_url(),
            'check': bool(CONFIG.get('upgrade_check'))}


def online_fetch(store, version, by, older=False):
    """The package of `version` fetched from where it was found, checked and
    kept as one sent by hand would be: its meta. `older`: one to go back to
    (1.0.143), kept only if downgrade_take finds nothing in its way."""
    pk = [p for p in online_list(online_url())
          if p['version'] == str(version)]
    if not pk:
        raise ValueError('otp %s is not at %s any more' % (version, online_url()))
    pk = pk[0]
    if older and _ver_tuple(pk['version']) >= _ver_tuple(__version__):
        raise ValueError('otp %s is not older than %s, which runs here' % (pk['version'],
                                                                           __version__))
    if not older and _ver_tuple(pk['version']) <= _ver_tuple(__version__):
        raise ValueError('otp %s is not newer than %s, which runs here' % (pk['version'], __version__))
    UPGRADE_DIR.mkdir(mode=0o750, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix='online-', suffix='.tar.gz', dir=str(UPGRADE_DIR))
    os.close(fd)
    tmp = Path(tmp)
    try:
        data, _ct, final = _online_get(pk['url'], limit=UPGRADE_MOST, timeout=300)
        tmp.write_bytes(data)
        try:
            info = upgrade_inspect(tmp)
        except ValueError as e:
            store.add_event('starting and stopping', 'otp %s from %s was refused: %s'
                            % (version, final, e), 'warn', who=by)
            raise ValueError('the package from %s was refused: %s' % (final, e))
        if older:
            if not info.get('older') and _ver_tuple(info['version']) >= _ver_tuple(__version__):
                raise ValueError('%s is not older than %s' % (info['version'], __version__))
            return downgrade_take(store, tmp, info, by)
        if info.get('older'):
            raise ValueError('%s is older than %s, which runs here' % (info['version'],
                                                                         info.get('installed')))
        meta = upgrade_store_package(store, tmp, info, by)
        store.add_event('starting and stopping', '%s fetched otp %s from %s (signed by %s), '
                        'ready to be put in' % (by, meta['version'], final, meta.get('signed_by')),
                        'warn', who=by)
        return meta
    finally:
        try:
            tmp.unlink()
        except OSError:
            pass

# ---- going back to an older version (1.0.143) ---------------------------------------
# Never by putting a database back: the tables stay as they are - every column
# a newer version added is one an older one leaves alone (they are all added
# NULL) - and the older program runs on them. That is safe only for a version
# that reads what the newer ones wrote, so each version says how far back it
# may go (DOWNGRADE_FLOOR), and going back is refused below the highest floor
#   * of any version that ran on this database (each node keeps its own in
#     'downgrade:floor:NODE' - one writer a row, as replication wants), and
#   * of any version installed on this machine (install.sh keeps it in
#     /usr/local/lib/otp/downgrade-floor, root's alone: the otp account cannot
#     lower it, so it cannot take the server back to a version with a hole);
# and the package itself is looked at before anything is put in: a column the
# database has as NOT NULL with no default that the older version does not
# know would make every row it writes there fail. Then it goes the road of an
# upgrade - one node at a time, each in maintenance while it is done.
DOWNGRADE_FLOOR_FILE = UPGRADE_HELPER.parent / 'downgrade-floor'


def downgrade_floor_note(store):
    """This node's floor in the database: the highest of what it had and what
    this version says."""
    k = 'downgrade:floor:' + node_name()
    had = _meta_json(store, k) or {}
    if had and _ver_tuple(had.get('floor')) >= _ver_tuple(DOWNGRADE_FLOOR):
        return
    store.set_meta(k, json.dumps({'floor': DOWNGRADE_FLOOR, 'version': __version__,
                                  'at': time.time()}))


def downgrade_db_floor(store):
    """(floor, set by): the highest floor of any version that ran on this
    database, on any node."""
    best, by = DOWNGRADE_FLOOR, '%s (%s)' % (__version__, node_name())
    for r in store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'downgrade:floor:%'"):
        try:
            got = json.loads(r['v'] or '{}')
        except ValueError:
            continue
        if isinstance(got, dict) and _ver_tuple(got.get('floor')) > _ver_tuple(best):
            best, by = str(got['floor']), '%s (%s)' % (got.get('version'),
                                                      r['k'][len('downgrade:floor:'):])
    return best, by


def downgrade_root_floor():
    """The floor root keeps, or None where no version that knows it was ever
    installed here."""
    try:
        text = DOWNGRADE_FLOOR_FILE.read_text().strip()
    except OSError:
        return None
    return text if re.match(r'^\d+\.\d+\.\d+\Z', text) else None


def downgrade_why_not(store, version):
    """What stands in the way of going back to `version` - before the package
    is fetched: [] when nothing does."""
    why = []
    v = _ver_tuple(version)
    if v >= _ver_tuple(__version__):
        why.append('%s is not older than %s, which runs here - that is an upgrade'
                   % (version, __version__))
        return why
    floor, by = downgrade_db_floor(store)
    if v < _ver_tuple(floor):
        why.append('older than %s: otp %s, which ran on this database, wrote what older '
                   'versions do not read the same (or have holes it fixed)' % (floor, by))
    root = downgrade_root_floor()
    if root is None:
        why.append('this machine was never upgraded on the command line to a version that '
                   'can go back (install.sh --upgrade once)')
    elif v < _ver_tuple(root):
        why.append('older than %s, the oldest the versions installed on this machine allow'
                   % root)
    return why


def downgrade_live_strict(db):
    """{table: [column]} - the columns of this database that are NOT NULL and
    have no default: a row written without one of them fails."""
    out = {}
    if db.engine == 'sqlite':
        for t in TABLES:
            for r in db.rows('PRAGMA table_info(%s)' % t):
                if r['notnull'] and r['dflt_value'] is None and not r['pk']:
                    out.setdefault(t, []).append(str(r['name']).lower())
        return out
    if db.engine == 'postgres':
        rows = db.rows("SELECT table_name AS t, column_name AS c FROM information_schema.columns "
                       "WHERE table_schema = current_schema() AND is_nullable = 'NO' "
                       "AND column_default IS NULL")
    else:
        rows = db.rows("SELECT table_name AS t, column_name AS c FROM information_schema.columns "
                       "WHERE table_schema = DATABASE() AND is_nullable = 'NO' "
                       "AND column_default IS NULL AND extra NOT LIKE '%auto_increment%'")
    for r in rows:
        t, c = str(r['t']).lower(), str(r['c']).lower()
        if t in TABLES and c != 'id':
            out.setdefault(t, []).append(c)
    return out


# Run in a process of its own, on the package's own otp.py: its tables as it
# makes them, made in a database in memory and read back.
_DOWNGRADE_SCHEMA_PY = r'''
import json, sqlite3, sys
sys.path.insert(0, sys.argv[1])
sys.argv = ['otp']
import otp
c = sqlite3.connect(':memory:')
out = {}
for name, ddl in otp.SCHEMA:
    c.execute(ddl.format(**otp.TYPES['sqlite']))
    out[name] = [str(r[1]).lower() for r in c.execute('PRAGMA table_info(%s)' % name)]
print(json.dumps({'version': otp.__version__, 'tables': out}))
'''


def downgrade_package_schema(path):
    """The tables and columns the package's version knows, read off its own
    otp.py (the package checked and signed first)."""
    work = Path(tempfile.mkdtemp(prefix='otp-down-', dir=str(UPGRADE_DIR)))
    try:
        with tarfile.open(str(path), 'r:gz') as tf:
            member = next((m for m in tf.getmembers()
                           if re.match(r'^otp-[0-9.]+/otp\.py\Z', m.name) and m.isfile()), None)
            if member is None:
                raise ValueError('the package has no otp.py')
            with tf.extractfile(member) as src, open(str(work / 'otp.py'), 'wb') as dst:
                shutil.copyfileobj(src, dst)
        env = {'PATH': os.environ.get('PATH', '/usr/bin:/bin'), 'LANG': 'C.UTF-8',
               'OTP_STATE': str(work), 'OTP_CONFIG': str(work / 'none.json'),
               'OTP_LOGDIR': str(work), 'OTP_RUN': str(work)}
        try:
            r = subprocess.run([sys.executable, '-I', '-c', _DOWNGRADE_SCHEMA_PY, str(work)],
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=120,
                               env=env, cwd=str(work))
        except subprocess.TimeoutExpired:
            raise ValueError('the tables of the package could not be read in 2 minutes')
        try:
            return json.loads(r.stdout.decode('utf-8', 'replace').strip().splitlines()[-1])
        except (ValueError, IndexError):
            raise ValueError('the tables of the package could not be read: %s'
                             % r.stderr.decode('utf-8', 'replace').strip()[-300:])
    finally:
        shutil.rmtree(str(work), ignore_errors=True)


def downgrade_schema_why(store, path):
    """What in this database the package's version could not live with: []
    when nothing."""
    got = downgrade_package_schema(path)
    knows = got.get('tables') or {}
    why = []
    for t, cols in sorted(downgrade_live_strict(store.db).items()):
        if t not in knows:
            continue                    # a table it never writes
        lack = [c for c in cols if c not in knows[t]]
        if lack:
            why.append('the table %s has %s, which otp %s does not know and every row needs'
                       % (t, ', '.join(lack), got.get('version')))
    return why


def downgrade_list(store):
    """The older versions at upgrade_url, each with what stands in its way."""
    url = online_url()
    if not url:
        raise ValueError('no upgrade_url is set (Settings → Upgrades)')
    out = []
    for p in online_list(url):
        if _ver_tuple(p['version']) >= _ver_tuple(__version__):
            continue
        out.append(dict(p, why=downgrade_why_not(store, p['version'])))
    out.sort(key=lambda p: _ver_tuple(p['version']), reverse=True)
    floor, by = downgrade_db_floor(store)
    root = downgrade_root_floor()
    # A few words a version for the list (1.0.145) - the reasons in full once.
    lowest = max([floor] + ([root] if root else []), key=_ver_tuple)
    for p in out:
        if not p['why']:
            p['short'] = ''
        elif _ver_tuple(p['version']) < _ver_tuple(lowest):
            p['short'] = 'below %s' % lowest
        elif root is None:
            p['short'] = 'this machine cannot go back yet'
        else:
            p['short'] = p['why'][0][:80]
    return {'url': url, 'here': __version__, 'versions': out, 'floor': floor,
            'floor_by': by, 'root_floor': root, 'lowest': lowest}


def downgrade_take(store, path, info, by):
    """A checked package of an older version kept for going back: refused
    when anything stands in its way. Its meta."""
    why = downgrade_why_not(store, info['version'])
    if not why:
        why = downgrade_schema_why(store, path)
    if why:
        store.add_event('starting and stopping', 'going back to otp %s was refused: %s'
                        % (info['version'], '; '.join(why)), 'warn', who=by)
        raise ValueError('otp %s cannot be gone back to: %s' % (info['version'], '; '.join(why)))
    meta = upgrade_store_package(store, path, info, by)
    meta['downgrade'] = True
    store.set_meta('upgrade:pkg', json.dumps(meta))
    store.add_event('starting and stopping', '%s made otp %s ready to go back to (signed by %s; '
                    'the database checked for it)' % (by, meta['version'], meta.get('signed_by')),
                    'warn', who=by)
    return meta


def downgrade_fetch(store, version, by):
    """The older package from upgrade_url, checked, and kept for going back."""
    why = downgrade_why_not(store, version)
    if why:
        raise ValueError('otp %s cannot be gone back to: %s' % (version, '; '.join(why)))
    return online_fetch(store, version, by, older=True)


def downgrade_file(store, path, by):
    """An older package from a file (the command line), checked and kept."""
    info = upgrade_inspect(path)
    if not info.get('older'):
        raise ValueError('otp %s is not older than %s, which runs here - that is an upgrade'
                         % (info['version'], info.get('installed') or __version__))
    return downgrade_take(store, path, info, by)


def changelog_sections(text):
    """{version: its section of CHANGELOG.md, heading and all}."""
    out = {}
    for m in re.finditer(r'^## (\d+\.\d+\.\d+)\b.*?(?=^## |\Z)', text or '', re.M | re.S):
        out[m.group(1)] = m.group(0).strip()[:20000]
    return out


def downgrade_changelog(version):
    """What came in `version`, and what going back to it from here gives up -
    the sections of the versions after it, up to this one (1.0.144). From the
    CHANGELOG.md installed beside otp.py; where that does not have it, from
    the package at upgrade_url (read, not yet checked)."""
    version = str(version or '')
    if not re.match(r'^\d+\.\d+\.\d+\Z', version):
        raise ValueError('which version?')
    try:
        here = changelog_sections((Path(__file__).resolve().parent / 'CHANGELOG.md')
                                  .read_text(encoding='utf-8', errors='replace'))
    except OSError:
        here = {}
    lost = [{'version': v, 'text': here[v]} for v in sorted(
        here, key=_ver_tuple, reverse=True)
        if _ver_tuple(version) < _ver_tuple(v) <= _ver_tuple(__version__)]
    entry, src = here.get(version), 'here'
    if entry is None:
        src = 'package'
        pk = next((p for p in online_list(online_url()) if p['version'] == version), None)
        if not pk:
            raise ValueError('otp %s is not at %s' % (version, online_url()))
        data, _ct, _final = _online_get(pk['url'], limit=UPGRADE_MOST, timeout=120)
        with tarfile.open(fileobj=io.BytesIO(data), mode='r:gz') as tf:
            m = next((x for x in tf.getmembers() if x.isfile() and
                      x.name == 'otp-%s/CHANGELOG.md' % version), None)
            text = tf.extractfile(m).read(4 << 20).decode('utf-8', 'replace') if m else ''
        entry = changelog_sections(text).get(version) or ''
    return {'version': version, 'here': __version__, 'entry': entry, 'from': src,
            'lost': lost}


# ---------------------------------------------------------------------------
# The web side (1.0.47): TLS of each node and of the cluster's web address,
# and that address itself (VIP, active/standby, held by keepalived).
#
# Everything is kept in the database, so both nodes know all of it:
#   web:vip          the address, its name, the VRRP id, the node it is meant
#                    to be on, each node's interface
#   web:tls:NODE     a node's own certificate, chain, root and TLS settings
#   web:tls:vip      the same for the web address's own name
# Keys are sealed with the tokens' key. Each node then asks root for its own
# part of it (otp_web.py, through /var/lib/otp/web/request.json) and keeps
# /run/otp/vip-state up to date for keepalived: whether this node is healthy
# enough to hold the address - its own pages answering /healthz end to end
# (nginx, PHP, the daemon, the database), RADIUS listening, not in
# maintenance, not being upgraded or rebuilt - and whether it is the one the
# address is meant to be on.
# ---------------------------------------------------------------------------
WEB_DIR = STATE_DIR / 'web'
VIP_STATE = RUN_DIR / 'vip-state'
VIP_ROLE = RUN_DIR / 'vip-role'
WEB_HELPER = Path(__file__).parent / 'otp_web.py'
VIP_FAILS_BEFORE = 2
VIP_HEALTH_URL = os.environ.get('OTP_VIP_HEALTH_URL', 'https://127.0.0.1/healthz')                    # checks in a row before it is said unhealthy
TLS_PRESETS = {
    # The ciphers otp has always used: ECDHE only, AEAD only.
    'standard': {'protocols': ['TLSv1.2', 'TLSv1.3'], 'ciphers': (
        'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:'
        'ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:'
        'ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305')},
    # Mozilla's "intermediate": the same and the DHE ones (DH parameters).
    'intermediate': {'protocols': ['TLSv1.2', 'TLSv1.3'], 'ciphers': (
        'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:'
        'ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:'
        'ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:'
        'DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384:DHE-RSA-CHACHA20-POLY1305')},
    # Mozilla's "modern": TLS 1.3 alone - its ciphers are not chosen.
    'modern': {'protocols': ['TLSv1.3'], 'ciphers': ''},
}
DH_WORDS = {'none': 'none (ECDHE only needs none)',
            'ffdhe2048': 'RFC 7919 ffdhe2048', 'ffdhe3072': 'RFC 7919 ffdhe3072',
            'ffdhe4096': 'RFC 7919 ffdhe4096', 'gen2048': 'made here, 2048 bits',
            'gen3072': 'made here, 3072 bits (a minute or so)',
            'gen4096': 'made here, 4096 bits (several minutes)'}
WEB_LOCK = threading.Lock()
VIP_HEALTH = {'ok': None, 'why': '', 'fails': 0, 'at': 0.0}


def _json_meta(store, k):
    try:
        got = json.loads(store.get_meta(k) or 'null')
        return got if isinstance(got, dict) else None
    except ValueError:
        return None


def vip_conf(store):
    return _json_meta(store, 'web:vip') or {'on': False}


def tls_profile(store, target):
    return _json_meta(store, 'web:tls:' + target)


def vip_auth():
    """The VRRP password: the same on every node, from the tokens' key."""
    key = sealing_key() or b''
    raw = hmac.new(key, b'otp-vip-vrrp', hashlib.sha256).digest()
    abc = string.ascii_letters + string.digits
    return ''.join(abc[b % len(abc)] for b in raw[:8])


VIP_MOVE_S = 60          # a move asked for by hand, in 'stays' mode, is wanted this long


def vip_moving(conf):
    """The node a move by hand is going to, while it is still under way."""
    to = str(conf.get('move_to') or '')
    if to and time.time() - float(conf.get('move_at') or 0) < VIP_MOVE_S:
        return to
    return ''


def vip_prefer_me(store, conf=None):
    """Is this node the one the address should be on - asked every 3 s.

    'back' (the default): the chosen node, always; the address goes back to it
    as soon as it is healthy. 'stays' (1.0.52): no preference - the node that
    holds it keeps it (keepalived's own state says which: MASTER), until it is
    unhealthy or gone, or until it is moved by hand."""
    conf = conf or vip_conf(store)
    me = node_name()
    if conf.get('mode') != 'stays':
        return vip_prefer(store, conf) == me
    moving = vip_moving(conf)
    if moving:
        return moving == me
    try:
        role = VIP_ROLE.read_text().split()[0]
    except (OSError, IndexError):
        role = ''
    return role == 'MASTER' or (role == '' and vip_here(conf.get('address')))


def vip_prefer(store, conf=None):
    conf = conf or vip_conf(store)
    if conf.get('mode') == 'stays':
        # Whoever holds it now (or is getting it).
        moving = vip_moving(conf)
        if moving:
            return moving
        for n in ha_nodes(store):
            w = web_state(store) if n['me'] else (n.get('web') or {})
            if w.get('vip_here'):
                return n['name']
        return ''
    want = str(conf.get('prefer') or '')
    if want:
        return want
    # Nobody chosen: the first node of the cluster by name - the same answer
    # on both nodes (1.0.59); "this one if it is slot 1" let both pick
    # themselves where the other's name sorted first.
    names = sorted(n['name'] for n in ha_nodes(store))
    return names[0] if names else node_name()


# ---- certificates: read, taken apart, made -----------------------------------
def _openssl(args, data=None, env=None, what='openssl'):
    e = dict(os.environ)
    e.update(env or {})
    got = subprocess.run(['openssl'] + args, input=data, capture_output=True, env=e,
                         timeout=120)
    if got.returncode != 0:
        said = (got.stderr or got.stdout or b'').decode('utf-8', 'replace').strip()
        raise ValueError('%s: %s' % (what, (said.splitlines() or ['openssl said no'])[-1][:200]))
    return got.stdout


PEM_CERT = re.compile(r'-----BEGIN CERTIFICATE-----[A-Za-z0-9+/=\s]+?-----END CERTIFICATE-----')
PEM_KEY = re.compile(r'-----BEGIN ((?:RSA |EC |ENCRYPTED )?PRIVATE KEY)-----[A-Za-z0-9+/=\s:,-]+?'
                     r'-----END \1-----')


def cert_info(pem):
    """What a certificate says of itself, for the pages."""
    out = _openssl(['x509', '-noout', '-subject', '-issuer', '-startdate', '-enddate',
                    '-fingerprint', '-sha256', '-ext', 'subjectAltName', '-nameopt',
                    'RFC2253'], pem.encode(), what='the certificate').decode()
    info = {'san': []}
    lines = out.splitlines()
    for i, line in enumerate(lines):
        if line.startswith('subject='):
            info['subject'] = line[8:].strip()
        elif line.startswith('issuer='):
            info['issuer'] = line[7:].strip()
        elif line.startswith('notBefore='):
            info['not_before'] = _cert_time(line[10:])
        elif line.startswith('notAfter='):
            info['not_after'] = _cert_time(line[9:])
        elif 'Fingerprint=' in line:
            info['fingerprint'] = line.split('=', 1)[1].strip()
        elif 'Subject Alternative Name' in line and i + 1 < len(lines):
            info['san'] = [x.strip().split(':', 1)[-1] for x in lines[i + 1].split(',')
                           if x.strip()]
    info['self_signed'] = info.get('subject') == info.get('issuer')
    cn = re.search(r'(?:^|,)CN=([^,]+)', info.get('subject') or '')
    info['cn'] = cn.group(1) if cn else ''
    try:
        pub = _openssl(['x509', '-noout', '-pubkey'], pem.encode()).decode()
        txt = _openssl(['pkey', '-pubin', '-noout', '-text'], pub.encode()).decode()
        m = re.search(r'\((\d+) bit\)', txt)
        info['key'] = ('%s %s bit' % ('EC' if 'ASN1 OID' in txt or 'NIST' in txt else 'RSA',
                                      m.group(1))) if m else ''
    except ValueError:
        info['key'] = ''
    return info


def _cert_time(text):
    try:
        return datetime.strptime(text.strip().replace('  ', ' '),
                                 '%b %d %H:%M:%S %Y %Z').replace(
            tzinfo=timezone.utc).timestamp()
    except ValueError:
        return None


def _pub_of_cert(pem):
    return _openssl(['x509', '-noout', '-pubkey'], pem.encode(), what='the certificate')


def _pub_of_key(pem):
    return _openssl(['pkey', '-pubout'], pem.encode(), what='the key')


def key_plain(pem, password=''):
    """A private key without its passphrase, as PEM."""
    return _openssl(['pkey', '-passin', 'env:OTP_PW'], pem.encode(),
                    {'OTP_PW': password or ''},
                    what='the key (a wrong or missing password?)').decode()


def cert_bundle(cert='', key='', chain='', root='', pfx=b'', password='', pending_key=''):
    """Whatever was sent - one PEM with everything in it, separate parts, or
    a PFX / PKCS#12 with or without a password - as the parts nginx needs:
    the certificate, its key, the chain up from it, the root. The key is the
    certificate's own or nothing is taken."""
    certs, keys = [], []
    if pfx:
        got = None
        for extra in ([], ['-legacy']):
            try:
                got = _openssl(['pkcs12', '-nodes', '-passin', 'env:OTP_PW'] + extra, pfx,
                               {'OTP_PW': password or ''}, what='the PFX / PKCS#12 file')
                break
            except ValueError as e:
                last = e
        if got is None:
            raise ValueError('%s - is the password right?' % last)
        text = got.decode('utf-8', 'replace')
        certs += [m.group(0) for m in PEM_CERT.finditer(text)]
        keys += [m.group(0) for m in PEM_KEY.finditer(text)]
    for part in (cert, chain, root, key):
        part = str(part or '')
        certs += [m.group(0) for m in PEM_CERT.finditer(part)]
        keys += [m.group(0) for m in PEM_KEY.finditer(part)]
    if not certs:
        raise ValueError('no certificate was found in what was sent (PEM, or a PFX / PKCS#12 '
                         'file)')
    if len(keys) > 1:
        raise ValueError('more than one private key was sent')
    if keys:
        key_pem = key_plain(keys[0], password)
    elif pending_key:
        key_pem = pending_key
    else:
        raise ValueError('no private key came with it: send the key too (or the PFX), or make '
                         'the request here first so the key is waiting')
    want = _pub_of_key(key_pem)
    leaf = next((c for c in certs if _pub_of_cert(c) == want), None)
    if not leaf:
        raise ValueError('none of the certificates is the one of this key')
    others = [c for c in certs if c != leaf]
    infos = {c: cert_info(c) for c in others}
    roots = [c for c in others if infos[c]['self_signed']]
    roots += [m.group(0) for m in PEM_CERT.finditer(str(root or '')) if m.group(0) not in roots]
    inter = [c for c in others if c not in roots]
    # The chain in order: each the issuer of the one before it.
    chain_out, at = [], cert_info(leaf)
    while inter:
        nxt = next((c for c in inter if infos[c].get('subject') == at.get('issuer')), None)
        if not nxt:
            chain_out += inter
            break
        chain_out.append(nxt)
        inter.remove(nxt)
        at = infos[nxt]
    info = cert_info(leaf)
    verify = ''
    if roots:
        with tempfile.TemporaryDirectory(prefix='otp-cert-') as t:
            def put(name, text):
                p = os.path.join(t, name)
                with open(p, 'w') as f:
                    f.write(text)
                return p
            args = ['verify', '-CAfile', put('root.pem', '\n'.join(roots) + '\n')]
            if chain_out:
                args += ['-untrusted', put('chain.pem', '\n'.join(chain_out) + '\n')]
            args.append(put('leaf.pem', leaf + '\n'))
            try:
                _openssl(args, what='the chain')
                verify = 'ok'
            except ValueError as e:
                verify = str(e)
    return {'cert': leaf + '\n', 'chain': ''.join(c + '\n' for c in chain_out),
            'root': ''.join(c + '\n' for c in roots), 'key': key_pem, 'info': info,
            'chain_info': [cert_info(c) for c in chain_out],
            'root_info': [cert_info(c) for c in roots], 'verify': verify}


def _san_ext(names):
    out = []
    for n in names:
        n = str(n).strip()
        if not n:
            continue
        try:
            plain_ip(n, 'address')
            out.append('IP:' + n)
        except ValueError:
            if not re.match(r'^(\*\.)?[A-Za-z0-9.-]{1,253}\Z', n):
                raise ValueError('%r is not a name or an address' % n)
            out.append('DNS:' + n)
    return ','.join(out)


def _subject(cn, org='', unit='', country='', city=''):
    def esc(v):
        return re.sub(r'([/\\=+,])', r'\\\1', str(v).strip())
    if not cn or not re.match(r'^[A-Za-z0-9*.-]{1,64}\Z', cn):
        raise ValueError('the common name is a host name')
    s = '/CN=' + esc(cn)
    if org:
        s += '/O=' + esc(org)
    if unit:
        s += '/OU=' + esc(unit)
    if city:
        s += '/L=' + esc(city)
    if country:
        if not re.match(r'^[A-Za-z]{2}\Z', country):
            raise ValueError('the country is two letters (CZ)')
        s += '/C=' + country.upper()
    return s


def new_key(kind):
    if kind == 'ec':
        return _openssl(['genpkey', '-algorithm', 'EC', '-pkeyopt',
                         'ec_paramgen_curve:P-256']).decode()
    bits = {'rsa2048': 2048, 'rsa3072': 3072, 'rsa4096': 4096}.get(kind)
    if not bits:
        raise ValueError('the key is ec, rsa2048, rsa3072 or rsa4096')
    return _openssl(['genpkey', '-algorithm', 'RSA', '-pkeyopt',
                     'rsa_keygen_bits:%d' % bits]).decode()


def make_csr(cn, names, kind='rsa2048', **subject):
    key = new_key(kind)
    with tempfile.TemporaryDirectory(prefix='otp-csr-') as t:
        kf = os.path.join(t, 'k.pem')
        with open(kf, 'w') as f:
            f.write(key)
        csr = _openssl(['req', '-new', '-key', kf, '-subj', _subject(cn, **subject),
                        '-addext', 'subjectAltName=' + _san_ext([cn] + list(names))],
                       what='the request').decode()
    return key, csr


def make_selfsigned(cn, names, days=825, kind='rsa2048', **subject):
    key = new_key(kind)
    with tempfile.TemporaryDirectory(prefix='otp-crt-') as t:
        kf = os.path.join(t, 'k.pem')
        with open(kf, 'w') as f:
            f.write(key)
        crt = _openssl(['req', '-new', '-x509', '-key', kf, '-days', str(int(days)), '-subj',
                        _subject(cn, **subject), '-addext',
                        'subjectAltName=' + _san_ext([cn] + list(names))],
                       what='the certificate').decode()
    return key, crt


# ---- the TLS of a target, kept ---------------------------------------------------------
def tls_targets(store):
    names = sorted(set([node_name()] + [n['name'] for n in ha_nodes(store)]))
    return names + ['vip']


def tls_save(store, target, prof, by):
    prof = dict(prof)
    prof['at'] = time.time()
    prof['by'] = by
    store.set_meta('web:tls:' + target, json.dumps(prof))


def tls_view(prof):
    """A profile as the pages may see it: no key."""
    if not prof:
        return None
    out = {k: v for k, v in prof.items() if k not in ('key', 'pending_key')}
    out['has_key'] = bool(prof.get('key'))
    out['pending'] = bool(prof.get('pending_key'))
    return out


def tls_policy_checked(b):
    preset = str(b.get('preset') or 'standard')
    if preset not in list(TLS_PRESETS) + ['custom']:
        raise ValueError('the TLS settings are standard, intermediate, modern or custom')
    out = {'preset': preset}
    if preset == 'custom':
        prot = b.get('protocols') or []
        if not isinstance(prot, list) or not prot or \
                any(p not in ('TLSv1.2', 'TLSv1.3') for p in prot):
            raise ValueError('the protocols are TLSv1.2 and/or TLSv1.3')
        out['protocols'] = [p for p in ('TLSv1.2', 'TLSv1.3') if p in prot]
        ciphers = str(b.get('ciphers') or '').strip()
        if ciphers:
            if not re.match(r'^[A-Za-z0-9_+!@=:.-]{1,2000}\Z', ciphers):
                raise ValueError('the ciphers are an OpenSSL cipher list')
            _openssl(['ciphers', ciphers], what='OpenSSL does not know that cipher list')
        out['ciphers'] = ciphers
    dh = str(b.get('dh') or 'none')
    if dh not in DH_WORDS:
        raise ValueError('the DH parameters are one of %s' % ', '.join(DH_WORDS))
    out['dh'] = dh
    out['prefer'] = bool(b.get('prefer'))
    try:
        # Not said is the two years nginx is shipped with (1.0.94), not none:
        # the first TLS change on the pages dropped HSTS without a word.
        hv = b.get('hsts')
        out['hsts'] = max(0, min(63072000, int(hv) if hv not in (None, '') else 63072000))
    except (TypeError, ValueError):
        raise ValueError('HSTS is a number of seconds')
    return out


def tls_resolved(prof):
    """What root is handed for a profile: the parts and the lines."""
    if not prof:
        return None
    preset = prof.get('preset') or 'standard'
    p = TLS_PRESETS.get(preset) or {'protocols': prof.get('protocols') or ['TLSv1.2', 'TLSv1.3'],
                                    'ciphers': prof.get('ciphers') or ''}
    out = {'protocols': p['protocols'], 'ciphers': p['ciphers'], 'prefer': bool(prof.get('prefer')),
           'dh': prof.get('dh') or 'none',
           'hsts': int(prof['hsts']) if prof.get('hsts') not in (None, '') else 63072000}
    if prof.get('cert') and prof.get('key'):
        out.update(cert=prof['cert'], chain=prof.get('chain') or '', root=prof.get('root') or '',
                   key=unseal_secret(prof['key'], 'web:tls'))
    return out


# ---- what this node asks of root, and how it went -------------------------------------
def web_desired(store):
    me = node_name()
    v = vip_conf(store)
    vip = {'on': False}
    many = bool(CONFIG.get('ha_mode'))
    if v.get('on') and many:
        vip = {'on': True, 'address': v.get('address'), 'fqdn': v.get('fqdn') or '',
               'address6': v.get('address6') or '',
               'vrid': int(v.get('vrid') or 51), 'auth': vip_auth(),
               'own': CONFIG.get('ha_address') or node_address(),
               'peer': CONFIG.get('ha_peer') or '',
               'iface': (v.get('ifaces') or {}).get(me, '')}
    tls = {'node': tls_resolved(tls_profile(store, me)),
           'vip': tls_resolved(tls_profile(store, 'vip')) if vip['on'] else None}
    out = {'node': me, 'vip': vip, 'tls': tls}
    # Asked only once set on the pages (1.0.52): a request from before had
    # neither, and its hash stays what it was.
    fw, access = fw_desired(store), access_desired(store)
    if fw is not None:
        out['fw'] = fw
    if access is not None:
        out['access'] = access
    return out


def web_hash(desired):
    return hashlib.sha256(json.dumps(desired, sort_keys=True).encode()).hexdigest()


def web_status():
    try:
        fd = os.open(str(WEB_DIR / 'status.json'), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, 'rb') as f:
            got = json.loads(f.read(1 << 20).decode('utf-8'))
        return got if isinstance(got, dict) else {}
    except (OSError, ValueError):
        return {}


def web_tick(store):
    """Asks root for this node's part when what is wanted has changed."""
    if HA_REBUILDING.is_set() or not WEB_DIR.is_dir():
        return
    desired = web_desired(store)
    # Nothing ever asked and nothing to ask: no request at all.
    st = web_status()
    if not st and not desired['vip']['on'] and not desired['tls']['node'] and \
            'fw' not in desired and 'access' not in desired:
        return
    h = web_hash(desired)
    if st.get('hash') == h:
        if st.get('state') == 'done':
            # Done, by root's last word - and nginx really has it (1.0.104):
            # a machine put back from its own backup, nginx set up again or
            # a file changed by hand is given what the database says again.
            drift = web_drift(desired)
            if not drift or time.time() - WEB_DRIFT['at'] < 1800:
                return
            WEB_DRIFT['at'] = time.time()
            log('the web certificate in place is not the one wanted (%s): asked again' % drift,
                'warn')
            store.add_event('settings', 'the certificate nginx has on %s is not the one saved '
                            '(%s): put in again' % (node_name(), drift), 'warn')
        # Failed with exactly this: asked again only when somebody says so.
        # Or once after a restart (1.0.120): it may have failed on what the
        # machine did not have yet - its new address, say.
        if float(store.get_meta('web:retry:' + node_name()) or 0) <= float(st.get('at') or 0):
            if st.get('state') != 'failed' or WEB_DRIFT.get('boot_retried') or \
                    boot_time() <= float(st.get('at') or 0):
                return
            WEB_DRIFT['boot_retried'] = True
            log('the web part failed before this restart (%s): asked again' % '; '.join(
                st.get('said') or [])[:200], 'warn')
    # Root at work on it (1.0.59): while it holds request.taken the status
    # still has the old hash, and the same request was written again - every
    # change applied twice.
    taken = WEB_DIR / 'request.taken'
    if (taken.exists() and time.time() - taken.stat().st_mtime < 600) or (
            WEB_ASKED.get('hash') == h and time.time() - float(WEB_ASKED.get('at') or 0) < 600
            and float(st.get('at') or 0) < float(WEB_ASKED.get('at') or 0)):
        return
    req = WEB_DIR / 'request.json'
    if req.exists() and time.time() - req.stat().st_mtime < 600:
        # Waiting for root: left as it is when it asks for this very thing,
        # replaced when what is wanted changed meanwhile.
        try:
            if json.loads(req.read_text()).get('hash') == h:
                return
        except (OSError, ValueError):
            return
    body = dict(desired, id=secrets.token_hex(8), hash=h)
    tmp = WEB_DIR / 'request.part'
    try:
        tmp.unlink()
    except OSError:
        pass
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, 'w') as f:
        json.dump(body, f)
    os.replace(str(tmp), str(req))
    WEB_ASKED['hash'] = h
    WEB_ASKED['at'] = time.time()


WEB_ASKED = {'hash': '', 'at': 0.0}
WEB_DRIFT = {'at': 0.0}
NGINX_CERT_FILES = {'node': '/etc/nginx/certs/otp.pem', 'vip': '/etc/nginx/certs/otp-vip.pem'}


def _first_pem(text):
    m = PEM_CERT.search(text or '')
    return re.sub(r'\s+', '', m.group(0)) if m else ''


def web_drift(desired):
    """Why the certificates nginx has are not the ones wanted - '' when they
    are, or when that cannot be told (a file not readable here)."""
    for target in ('node', 'vip'):
        t = (desired.get('tls') or {}).get(target)
        if not t or not t.get('cert'):
            continue
        path = NGINX_CERT_FILES[target]
        try:
            with open(path) as f:
                have = _first_pem(f.read(200000))
        except FileNotFoundError:
            return '%s is not there' % path
        except OSError:
            continue
        if have and have != _first_pem(t['cert']):
            return '%s holds another certificate' % path
    return ''


def web_progress():
    """What root is doing now, if anything (1.0.50)."""
    try:
        fd = os.open(str(WEB_DIR / 'progress.json'), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, 'rb') as f:
            got = json.loads(f.read(65536).decode('utf-8'))
    except (OSError, ValueError):
        return None
    if not isinstance(got, dict) or time.time() - float(got.get('at') or 0) > 3 * 3600:
        return None
    got['now'] = time.time()
    return got


def web_state(store):
    """This node's web side, for its heartbeat: what root said last, whether
    that is what is wanted now, and the address."""
    st = web_status()
    desired_hash = ''
    try:
        desired_hash = web_hash(web_desired(store))
    except Exception:                                   # noqa: BLE001
        pass
    role = ''
    try:
        role = VIP_ROLE.read_text().split()[0]
    except (OSError, IndexError):
        pass
    v = vip_conf(store)
    return {'cert_now': cert_now('/etc/nginx/certs/otp.pem'),
            'vip_cert_now': cert_now('/etc/nginx/certs/otp-vip.pem'),
            'state': st.get('state') or '', 'said': (st.get('said') or [])[-6:],
            'at': st.get('at'), 'current': bool(st) and st.get('hash') == desired_hash,
            'waiting': (WEB_DIR / 'request.json').exists(),
            'progress': web_progress(),
            'iface': (st.get('applied') or {}).get('iface') or '',
            'vip_here': vip_here(v.get('address')) if v.get('on') else False,
            'role': role, 'health': dict(VIP_HEALTH),
            'fw': dict(st.get('fw') or {}, **fw_now_read()), 'access': st.get('access') or {},
            'ifaces': sorted(os.listdir('/sys/class/net')) if os.path.isdir('/sys/class/net')
            else []}


def fw_now_read():
    """The whole firewall as root last read it (1.0.67): {'full': {4, 6},
    'full_at'}."""
    try:
        fd = os.open(str(WEB_DIR / 'fwnow.json'), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, 'rb') as f:
            got = json.loads(f.read(4 << 20).decode('utf-8'))
        full = got.get('full') or {}
        return {'full': {str(k): [str(x)[:400] for x in (v or [])][:1500] for k, v in full.items()},
                'full_at': got.get('at'), 'full_backend': got.get('backend')}
    except (OSError, ValueError, AttributeError):
        return {}


def fw_now_ask(wait=6.0):
    """Root asked to read the firewall again, and waited for (1.0.67)."""
    if not WEB_DIR.is_dir():
        return False
    t0 = time.time()
    try:
        (WEB_DIR / 'fw.ask').write_text(json.dumps({'at': t0}))
    except OSError:
        return False
    while time.time() - t0 < wait:
        if float(fw_now_read().get('full_at') or 0) >= t0:
            return True
        time.sleep(0.3)
    return False


CERT_NOW = {}


def cert_now(path):
    """What the certificate nginx has in `path` says - read again only
    when the file changes."""
    try:
        st = os.stat(path)
    except OSError:
        return None
    had = CERT_NOW.get(path)
    if had and had[0] == (st.st_mtime, st.st_size):
        return had[1]
    try:
        with open(path) as f:
            text = f.read(200000)
        m = PEM_CERT.search(text)
        info = cert_info(m.group(0)) if m else None
        if info:
            info['chain'] = max(0, len(PEM_CERT.findall(text)) - 1)
    except (OSError, ValueError):
        return None             # not kept: read again next time (1.0.57)
    CERT_NOW[path] = ((st.st_mtime, st.st_size), info)
    return info


def local_addresses():
    """Every address on this machine's interfaces, read from the kernel.

    Not by binding to it (1.0.55): with net.ipv4.ip_nonlocal_bind on - which
    the web address turns on since 1.0.51, so nginx can listen on it - a bind
    succeeds for an address the machine does not hold, and both nodes said
    they had the web address."""
    out = set()
    try:
        # IPv4: the local table of the FIB, "/32 host LOCAL" under each address.
        last = None
        with open('/proc/net/fib_trie') as f:
            for line in f:
                m = re.match(r'^\s*\|--\s+([0-9.]+)\s*\Z', line)
                if m:
                    last = m.group(1)
                elif last and '/32 host LOCAL' in line:
                    out.add(last)
    except OSError:
        pass
    try:
        with open('/proc/net/if_inet6') as f:
            for line in f:
                h = line.split()[0]
                if len(h) == 32:
                    out.add(str(ipaddress.IPv6Address(int(h, 16))))     # ::1 too (1.0.59)
    except (OSError, ValueError, IndexError):
        pass
    if not out and shutil.which('ip'):
        got = subprocess.run(['ip', '-o', 'addr', 'show'], capture_output=True, text=True)
        for m in re.finditer(r'\binet6?\s+([0-9a-fA-F:.]+)/', got.stdout or ''):
            out.add(str(ipaddress.ip_address(m.group(1))))
    return out


def vip_here(address):
    """Does this machine hold the address now? Its interfaces say so."""
    try:
        ip = ipaddress.ip_interface(str(address or '')).ip
    except ValueError:
        return False
    return str(ip) in local_addresses()


# ---- may this node hold the address? ---------------------------------------------------
def vip_health_check(daemon):
    """One look at everything the pages need, from outside the daemon: its
    own /healthz through nginx and PHP to the daemon and the database - and
    RADIUS listening, and no maintenance, upgrade or rebuild. A node that is
    not healthy lets the address go to the other."""
    store = daemon.store
    why = ''
    if HA_REBUILDING.is_set():
        why = 'being rebuilt from the other node'
    elif maintenance_now(store).get('on'):
        why = 'in maintenance'
    elif not getattr(getattr(daemon, 'radius', None), 'bound', None):
        why = 'RADIUS is not listening'
    elif VIP_HEALTH_URL == 'none':
        pass                            # a test bed whose nginx is another node's
    else:
        try:
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_NONE
            req = urllib.request.Request(VIP_HEALTH_URL,
                                         headers={'User-Agent': 'otp-vip-check'})
            with urllib.request.urlopen(req, timeout=4, context=ctx) as r:
                body = r.read(200).decode('utf-8', 'replace')
                if r.status != 200 or not body.startswith('ok'):
                    why = 'its pages say: %s' % body.strip()[:80]
        except urllib.error.HTTPError as e:
            try:
                why = 'its pages say %d: %s' % (e.code, e.read(200).decode('utf-8',
                                                                           'replace').strip()[:80])
            except Exception:                           # noqa: BLE001
                why = 'its pages say %d' % e.code
        except Exception as e:                          # noqa: BLE001
            why = 'its pages do not answer (%s)' % str(e)[:80]
    return why


def vip_watch(daemon):
    """Every three seconds: /run/otp/vip-state for keepalived."""
    while not daemon.stop_flag.wait(3):
        try:
            store = daemon.store
            v = vip_conf(store)
            if not v.get('on') or not CONFIG.get('ha_mode'):
                try:
                    VIP_STATE.unlink()
                except OSError:
                    pass
                continue
            why = vip_health_check(daemon)
            if why:
                VIP_HEALTH['fails'] += 1
            else:
                VIP_HEALTH['fails'] = 0
            ok = VIP_HEALTH['fails'] < VIP_FAILS_BEFORE
            if not why or not ok or VIP_HEALTH['ok'] is None:
                VIP_HEALTH.update(ok=ok, why=why if not ok else '')
            VIP_HEALTH['at'] = time.time()
            prefer = vip_prefer_me(store, v)
            line = ('ok prefer' if prefer else 'ok') if ok else 'fail ' + (why or '?')
            tmp = RUN_DIR / '.vip-state'
            tmp.write_text(line + '\n')
            os.chmod(str(tmp), 0o640)
            os.replace(str(tmp), str(VIP_STATE))
        except Exception as e:                          # noqa: BLE001
            log_sparing('vip-watch:' + str(e)[:80], 'the web address: %s' % e, 'warn', 600)
            daemon.stop_flag.wait(10)


# ---- what the pages and the command line change ----------------------------------------
def vip_checked(b, store):
    try:
        net = plain_ip(b.get('address'), 'interface')
    except ValueError:
        raise ValueError('the web address is an address with its prefix, e.g. 192.0.2.10/24')
    if '/' not in str(b.get('address') or ''):
        raise ValueError('give the prefix with the address, e.g. 192.0.2.10/24')
    if net.ip.is_loopback or net.ip.is_multicast or net.ip.is_unspecified:
        raise ValueError('%s cannot be the web address' % net.ip)
    nodes = [n for n in ha_nodes(store)]
    for n in nodes:
        if str(n.get('address') or '') == str(net.ip):
            raise ValueError('%s is the address of %s: the web address is a third one'
                             % (net.ip, n['name']))
    fqdn = str(b.get('fqdn') or '').strip().lower().rstrip('.')
    if fqdn and not re.match(r'^(?=.{1,253}$)[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?'
                             r'(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)*$', fqdn):
        raise ValueError('%r is not a host name' % fqdn)
    try:
        vrid = int(b.get('vrid') or 51)
    except (TypeError, ValueError):
        raise ValueError('the VRRP id is a number')
    if not 1 <= vrid <= 255:
        raise ValueError('the VRRP id is 1 to 255 - one no other VRRP on that network uses')
    ifaces = {}
    for k, val in (b.get('ifaces') or {}).items():
        val = str(val or '').strip()
        if val and not re.match(r'^[A-Za-z0-9_.:-]{1,15}\Z', val):
            raise ValueError('%r is not the name of a network interface' % val)
        if val:
            ifaces[str(k)] = val
    a6 = str(b.get('address6') or '').strip()
    if a6:
        if '/' not in a6:
            raise ValueError('give the prefix with the IPv6 web address, e.g. 2001:db8::10/64')
        try:
            n6 = plain_ip(a6, 'interface')
        except ValueError:
            raise ValueError('the IPv6 web address is an address with its prefix, e.g. '
                             '2001:db8::10/64')
        if n6.version != 6 or n6.ip.is_link_local or n6.ip.is_loopback:
            raise ValueError('the IPv6 web address is a global IPv6 address')
        a6 = str(n6)
    return {'address': str(net), 'fqdn': fqdn, 'vrid': vrid, 'ifaces': ifaces, 'address6': a6}


def vip_set(store, by, **changes):
    v = vip_conf(store)
    v.update(changes)
    v['at'] = time.time()
    v['by'] = by
    store.set_meta('web:vip', json.dumps(v))
    return v


# ---- a node renamed (1.0.48) ---------------------------------------------------------
NODE_NAME_FILE = STATE_DIR / 'node-name'


def node_carry(store, old, new, by='the daemon'):
    """What belongs to a node by its name, carried to its new name: its own
    settings (key@node), its maintenance, its TLS, its place as the web
    address's preferred node and its interface - and the old name off the
    list of nodes. Nothing the new name has already is overwritten."""
    if not old or old == new:
        return []
    said = []
    for r in store.db.rows('SELECT k, v FROM settings'):
        k = str(r['k'])
        if k.endswith('@' + old):
            want = k[:-len(old)] + new
            if store.db.value('SELECT 1 FROM settings WHERE k = ?', (want,)) is None:
                store.db.run('UPDATE settings SET k = ? WHERE k = ?', (want, k))
                said.append('its own setting %s' % k.split('@')[0])
            else:
                store.db.run('DELETE FROM settings WHERE k = ?', (k,))
    old_maint = _json_meta(store, 'maint:' + old)
    if old_maint and old_maint.get('on') and not (maintenance_row(store, new) or {}).get('on'):
        maintenance_set(store, True, old_maint.get('why') or 'carried over from %s' % old,
                        old_maint.get('by') or '', name=new)
        said.append('its maintenance')
    prof = store.get_meta('web:tls:' + old)
    if prof and store.get_meta('web:tls:' + new) is None:
        store.set_meta('web:tls:' + new, prof)
        said.append('its certificate and TLS settings')
    v = vip_conf(store)
    changed = False
    if v.get('prefer') == old:
        v['prefer'] = new
        changed = True
    ifaces = v.get('ifaces') or {}
    if old in ifaces and new not in ifaces:
        ifaces[new] = ifaces.pop(old)
        v['ifaces'] = ifaces
        changed = True
    if changed:
        store.set_meta('web:vip', json.dumps(v))
        said.append('its place in the web address')
    for k in ('node:', 'maint:', 'upgrade:node:', 'web:tls:', 'web:retry:', 'db_job:', 'fw:now:',
              'db_sizes:', 'hatls:node:'):
        store.db.run('DELETE FROM meta WHERE k = ?', (k + old,))
    store.add_event('settings', 'the node %s is called %s now; carried over: %s' % (
        old, new, ', '.join(said) or 'nothing (it had nothing of its own)'), 'warn', who=by)
    return said


def node_name_check(store):
    """At the start: was this node called something else last time?"""
    me = node_name()
    try:
        before = NODE_NAME_FILE.read_text().strip()
    except OSError:
        before = ''
    if before and before != me:
        # The new name is another machine's, answering now (1.0.110): carried
        # over, this node's own settings would land on that one - and with the
        # name put back, that one's on this one. Nothing is carried.
        try:
            taken = [n for n in ha_nodes(store) if n['name'] == me and n.get('alive') and
                     n.get('mid') and n['mid'] != machine_id()]
        except Exception:                               # noqa: BLE001
            taken = []
        if taken:
            log('this node was %s and is called %s now - but %s (%s) is %s and answering: '
                'nothing carried over; give this node its own name (otp --set node_name=%s, '
                'then systemctl restart otp)' % (before, me, taken[0].get('address') or '?',
                                                 taken[0].get('host') or '?', me, before), 'error')
            return
        try:
            said = node_carry(store, before, me)
            log('this node was %s and is %s now; carried over: %s'
                % (before, me, ', '.join(said) or 'nothing'), 'warn')
        except Exception as e:                          # noqa: BLE001
            log('carrying %s over to %s: %s' % (before, me, e), 'warn')
            return
    if before != me:
        try:
            NODE_NAME_FILE.write_text(me + '\n')
        except OSError:
            pass


# ---- the local firewall and who may reach which pages (1.0.52) -------------------------
# Kept for the whole cluster in meta, put in by each node's root helper with
# the rest of the web side (one request, one status). What otp's functions
# need is worked out here from what is set up; the rules somebody adds by
# hand come first, so a DROP or REJECT of theirs wins over what otp opens.
FW_AUTO_OPTIONAL = ('ssh', 'icmp', 'dhcpv6', 'web', 'radius', 'ntp')
ACCESS_WORDS = {'portal': 'the enrolment pages', 'admin': 'the administration pages',
                'health': 'the health check (/healthz)'}


def fw_conf(store):
    c = _json_meta(store, 'fw:conf') or {}
    c.setdefault('on', False)
    c.setdefault('off', [])
    c.setdefault('rules', [])
    return c


def access_conf(store):
    return _json_meta(store, 'web:access') or {}


def cluster_addresses(store, node):
    """The other nodes' addresses, seen from `node`: what must always get in."""
    me = node_name()
    out = set()
    for n in ha_nodes(store):
        if n['name'] != node and n.get('address'):
            out.add(n['address'])
    if CONFIG.get('ha_mode'):
        if node == me and CONFIG.get('ha_peer'):
            out.add(CONFIG['ha_peer'])
        if node != me:
            out.add(CONFIG.get('ha_address') or node_address())
    v = vip_conf(store)
    if v.get('on') and v.get('address'):
        out.add(str(v['address']).split('/')[0])
    good = set()
    for a in out:
        try:
            good.add(str(plain_ip(a, 'address')))
        except ValueError:
            # A host name (ha_peer may be one, 1.0.59): its addresses, not
            # left out of the rules and the lists.
            try:
                for info in socket.getaddrinfo(str(a), None, 0, socket.SOCK_STREAM)[:4]:
                    good.add(str(plain_ip(info[4][0], 'address')))
            except (OSError, ValueError, UnicodeError):
                pass
    return sorted(good)


def _fam(addr):
    try:
        return ipaddress.ip_network(addr, strict=False).version
    except ValueError:
        return 0


def access_desired(store, node=None):
    """The three lists as nginx gets them: what was set, the cluster added."""
    a = access_conf(store)
    if not a:
        return None
    inner = cluster_addresses(store, node or node_name())
    out = {}
    for k in ACCESS_WORDS:
        one = a.get(k) or {'any': True, 'from': []}
        nets = list(one.get('from') or [])
        if not one.get('any'):
            # The cluster first (1.0.59): a list cut at its length cut the
            # other node and the web address off, not one of somebody's.
            nets = list(inner) + [x for x in nets if x not in inner]
        out[k] = {'any': bool(one.get('any')), 'from': nets}
    return out


def fw_auto(store, node):
    """What otp's functions need on `node`: [{key, title, why, fixed, rules}]."""
    peers = cluster_addresses(store, node)
    v = vip_conf(store)
    out = [{'key': 'ssh', 'title': 'SSH', 'why': 'to manage the machine - turned off, '
            'take care to keep a rule of your own for it',
            'rules': [{'family': f, 'proto': 'tcp', 'port': '22', 'source': ''} for f in (4, 6)]},
           {'key': 'icmp', 'title': 'ICMP / ICMPv6', 'why': 'ping, and IPv6 cannot work without '
            'ICMPv6 (neighbour discovery)',
            'rules': [{'family': f, 'proto': 'icmp', 'port': '', 'source': ''} for f in (4, 6)]},
           {'key': 'dhcpv6', 'title': 'DHCPv6 client', 'why': 'answers of a DHCPv6 server, for '
            'an address given that way', 'rules': [{'family': 6, 'proto': 'udp', 'port': '546',
                                                     'source': 'fe80::/10'}]}]
    # The pages: from everybody when one of the three is for everybody, else
    # from the networks of the three lists (nginx then says who sees which).
    a = access_conf(store)
    srcs = ['']
    if a and not any((a.get(k) or {}).get('any') for k in ACCESS_WORDS):
        srcs = []
        for k in ACCESS_WORDS:
            for n in (a.get(k) or {}).get('from') or []:
                if n not in srcs:
                    srcs.append(n)
    web = []
    for s in srcs:
        for f in ((4, 6) if not s else (_fam(s),)):
            web.append({'family': f, 'proto': 'tcp', 'port': '80,443', 'source': s})
    out.append({'key': 'web', 'title': 'HTTP / HTTPS', 'why': 'the enrolment and '
                'administration pages and the health check; who sees which is under '
                '"Who may reach the pages"', 'rules': web})
    ports = str(int(CONFIG.get('radius_auth_port') or 1812))
    if int(CONFIG.get('radius_acct_port') or 0):
        ports += ',%d' % int(CONFIG.get('radius_acct_port'))
    rad = []
    for c in store.clients():
        if not c.get('enabled'):
            continue
        try:
            net = address_net(c['address'])
        except (ValueError, KeyError):
            continue
        if net is None:
            continue
        rad.append({'family': net.version, 'proto': 'udp', 'port': ports, 'source': str(net),
                    'note': 'RADIUS %s' % c.get('name', '')})
    out.append({'key': 'radius', 'title': 'RADIUS', 'why': 'from each RADIUS client set up '
                '(Clients), and only from them', 'rules': rad})
    # Time served to the networks set in Settings → Time (1.0.120).
    nc = _meta_json(store, 'ntp:conf') or {}
    if nc.get('manage') and nc.get('allow'):
        out.append({'key': 'ntp', 'title': 'NTP (time served)', 'why': 'this node serves the '
                    'time to the networks set under Settings → Time',
                    'rules': [{'family': _fam(a.split('/')[0]), 'proto': 'udp', 'port': '123',
                               'source': a} for a in nc['allow']]})
    # Inside the cluster: always, never turned off.
    if CONFIG.get('ha_mode') and peers:
        nodes_only = [p for p in peers if p != str(v.get('address') or '').split('/')[0]]
        out.append({'key': 'cluster', 'title': 'The other node', 'fixed': True,
                    'why': 'replication (PostgreSQL), its pages and the health check - inside '
                    'the cluster everything has to work',
                    # Everything from it (1.0.59): its answers to this node's
                    # own asking came from other ports and were dropped.
                    'rules': [{'family': _fam(p), 'proto': 'any', 'port': '',
                               'source': p} for p in nodes_only]})
        if v.get('on'):
            out.append({'key': 'vrrp', 'title': 'VRRP (the web address)', 'fixed': True,
                        'why': 'keepalived of the other node says it is there',
                        'rules': [{'family': _fam(p), 'proto': 'vrrp', 'port': '', 'source': p}
                                  for p in nodes_only]})
    off = set(fw_conf(store).get('off') or [])
    for item in out:
        item['fixed'] = bool(item.get('fixed'))
        item['on'] = item['fixed'] or item['key'] not in off
        for r in item['rules']:
            r.setdefault('note', item['title'])
            r['action'] = 'accept'
    return out


def fw_rules_for(store, node):
    """Everything the chain of `node` holds, in order."""
    c = fw_conf(store)
    auto = fw_auto(store, node)
    # The cluster first (1.0.52): nothing of anybody's can shut the other
    # node out; then the rules of your own; then the rest otp needs.
    rules = [r for item in auto if item['fixed'] for r in item['rules']]
    for r in c.get('rules') or []:
        if r.get('scope', 'all') not in ('all', node) or r.get('disabled'):
            continue
        for f in ((4, 6) if not r.get('family') else (int(r['family']),)):
            if r.get('source') and _fam(r['source']) != f:
                continue
            rules.append({'family': f, 'proto': r.get('proto') or 'any',
                          'port': r.get('port') or '', 'source': r.get('source') or '',
                          'action': r.get('action') or 'accept', 'note': r.get('note') or 'manual'})
    for item in auto:
        if item['on'] and not item['fixed']:
            rules += item['rules']
    return rules


def fw_desired(store):
    c = fw_conf(store)
    if not c.get('set'):
        return None
    return {'on': bool(c.get('on')), 'rules': fw_rules_for(store, node_name()) if c.get('on')
            else []}


FW_PROTOS = ('tcp', 'udp', 'icmp', 'vrrp', 'any')


def fw_rule_checked(b, store):
    """A rule somebody adds by hand, as it is kept."""
    fam = int(b.get('family') or 0)
    if fam not in (0, 4, 6):
        raise ApiError(400, 'IPv4, IPv6 or both')
    proto = str(b.get('proto') or 'any')
    if proto not in FW_PROTOS:
        raise ApiError(400, 'the protocol is one of %s' % ', '.join(FW_PROTOS))
    port = str(b.get('port') or '').replace(' ', '')
    if port:
        if proto not in ('tcp', 'udp'):
            raise ApiError(400, 'a port is for TCP or UDP')
        for p in port.split(','):
            m = re.fullmatch(r'([0-9]{1,5})(?:-([0-9]{1,5}))?', p)    # ASCII only (1.0.61)
            if not m or not 1 <= int(m.group(1)) <= 65535 or \
                    (m.group(2) and not int(m.group(1)) <= int(m.group(2)) <= 65535):
                raise ApiError(400, '%s is not a port or a range (80, 1812-1813, 80,443)' % p)
        if sum(2 if '-' in p else 1 for p in port.split(',')) > 15:
            raise ApiError(400, 'fifteen ports at most in one rule (a range counts as two)')
    src = str(b.get('source') or '').strip()
    if src:
        try:
            net = plain_ip(src, 'network')
        except ValueError:
            raise ApiError(400, '%s is not an address or a network' % src[:60])
        if fam and net.version != fam:
            raise ApiError(400, '%s is not an IPv%d address' % (src, fam))
        src, fam = str(net), net.version
    action = str(b.get('action') or 'accept')
    if action not in ('accept', 'drop', 'reject'):
        raise ApiError(400, 'accept, drop or reject')
    scope = str(b.get('scope') or 'all')
    if scope != 'all' and scope not in {n['name'] for n in ha_nodes(store)} | {node_name()}:
        raise ApiError(400, 'there is no node called %s' % scope)
    note = re.sub(r'[^A-Za-z0-9 ._:/@()+,-]', '', str(b.get('note') or ''))[:80]
    return {'family': fam, 'proto': proto, 'port': port, 'source': src, 'action': action,
            'scope': scope, 'note': note, 'disabled': bool(b.get('disabled'))}


def fw_set(store, by, **changes):
    # On trial (1.0.137): what is there now kept, to come back unless kept.
    try:
        fw_trial_begin(store, by)
    except Exception as e:                              # noqa: BLE001
        log('the firewall change could not be put on trial: %s' % e, 'warn')
    c = fw_conf(store)
    c.update(changes)
    c.update(set=True, at=time.time(), by=by)
    store.set_meta('fw:conf', json.dumps(c))
    return c


def access_checked_api(b):
    out = {}
    for k, words in ACCESS_WORDS.items():
        one = b.get(k) or {}
        nets = []
        raw = one.get('from') or []
        if isinstance(raw, str):
            raw = re.split(r'[\s,;]+', raw)
        for x in raw[:200]:
            x = str(x).strip()
            if not x:
                continue
            try:
                n = str(plain_ip(x, 'network'))
            except ValueError:
                raise ApiError(400, '%s: %s is not an address or a network' % (words, x[:60]))
            if n not in nets:
                nets.append(n)
        if not one.get('any') and not nets:
            raise ApiError(400, '%s would be for nobody: give a network, or let everybody in'
                           % words)
        out[k] = {'any': bool(one.get('any')), 'from': nets}
    return out


# ---- what happened to the cluster, written down (1.0.52) -------------------------------
# Every five seconds this node looks at what it can see - the web address
# here or not, its own health, the other node, replication both ways - and
# writes an event (kind 'ha') whenever one of them changes. Settings -
# High availability - History shows them, with what was changed by hand.
HA_SEEN = {}
PGLOG_ASK = 'pglog.ask'
PGLOG_FILE = 'pglog.json'


def _ha_change(store, key, now, words, level='warn'):
    """An event when `key` was something else before; nothing the first time."""
    was = HA_SEEN.get(key, '__first__')
    HA_SEEN[key] = now
    if was == '__first__' or was == now:
        return False
    store.add_event('ha', words, level)
    return True


def ha_watch_tick(store):
    me = node_name()
    if not CONFIG.get('ha_mode'):
        return
    v = vip_conf(store)
    if v.get('on'):
        try:
            role = VIP_ROLE.read_text().split()[0]
        except (OSError, IndexError):
            role = ''
        held = vip_here(v.get('address')) if role else False
        why = VIP_HEALTH.get('why') or ''
        _ha_change(store, 'vip', 'here' if held else 'not',
                   ('the web address %s came to %s%s' % (v.get('address'), me,
                                                           ' (%s)' % role if role else '')) if held
                   else ('the web address %s left %s%s' % (
                       v.get('address'), me, ' - %s' % why if why else
                       (' (%s)' % role if role else ''))))
        ok = VIP_HEALTH.get('ok')
        if ok is not None:
            _ha_change(store, 'health', 'ok' if ok else 'bad',
                       ('%s is healthy again: the web address may come back to it' % me) if ok
                       else ('%s is not healthy - %s: the web address leaves it' % (me, why or '?')),
                       'info' if ok else 'bad')
    else:
        HA_SEEN.pop('vip', None)
        HA_SEEN.pop('health', None)
    for n in ha_nodes(store):
        if n['me']:
            continue
        _ha_change(store, 'node:' + n['name'], 'alive' if n.get('alive') else 'gone',
                   ('%s answers again (seen from %s)' % (n['name'], me)) if n.get('alive')
                   else ('%s stopped answering (seen from %s, last heard %d s ago)'
                         % (n['name'], me, int(n.get('age') or 0))),
                   'info' if n.get('alive') else 'bad')
        m = bool((n.get('maintenance')))
        _ha_change(store, 'maint:' + n['name'], 'on' if m else 'off',
                   '%s %s maintenance' % (n['name'], 'went into' if m else 'came out of'), 'info')
    if CONFIG.get('ha_mode') != 'replicated':
        return
    r = ha_repl_state(store)
    if r.get('trouble'):
        return
    for x in r.get('incoming') or []:
        name = x.get('name')
        state = 'running' if x.get('running') else ('paused' if not x.get('enabled') else 'stopped')
        _ha_change(store, 'in:' + name, state,
                   'replication coming in (%s): %s' % (name, {
                       'running': 'running again', 'paused': 'paused',
                       'stopped': 'stopped - the other node or its PostgreSQL is not reached, or '
                                  'an error stops it'}[state]),
                   {'running': 'info', 'paused': 'warn'}.get(state, 'bad'))
        errs = int(x.get('apply_errors') or 0) + int(x.get('sync_errors') or 0)
        was = HA_SEEN.get('err:' + name)
        HA_SEEN['err:' + name] = errs
        if was is not None and errs > was:
            store.add_event('ha', 'replication coming in (%s): %d new error(s), %d in all - '
                                  'Settings - High availability - the errors say what'
                                  % (name, errs - was, errs), 'bad')
    for x in r.get('outgoing') or []:
        _ha_change(store, 'out:' + x['name'], x.get('wal_status') or '',
                   'replication going out (%s): %s' % (x['name'], {
                       'lost': 'LOST - the other node waited too long and has to be rebuilt',
                       'unreserved': 'about to be lost - the other node is far behind',
                       'extended': 'the other node is behind', 'reserved': 'caught up'}.get(
                           x.get('wal_status'), x.get('wal_status') or '?')),
                   'bad' if x.get('wal_status') in ('lost', 'unreserved') else 'info')


def ha_history(store, limit=300, since=0, until=0):
    """The cluster's story: what this watch saw and what was done by hand."""
    span, args = '', []
    cleared = float(store.get_meta('ha:history_cleared') or 0)
    since = max(float(since or 0), cleared)
    if since:
        span += ' AND ts >= ?'
        args.append(float(since))
    if until:
        span += ' AND ts < ?'
        args.append(float(until))
    rows = store.db.rows(
        "SELECT ts, kind, node, level, who, words FROM events WHERE (kind = 'ha' OR "
        "(kind = 'settings' AND (words LIKE '%web address%' OR words LIKE '%replication%' OR "
        "words LIKE '%maintenance%' OR words LIKE '%rebuilt%' OR words LIKE '%cluster%' OR "
        "words LIKE '%upgrade%') AND words NOT LIKE '%certificate%' AND "
        "words NOT LIKE '%TLS%'))" + span +
        " ORDER BY ts DESC LIMIT " + str(int(limit)), args)
    for r in rows:
        w = (r.get('words') or '').lower()
        r['what'] = ('vip' if 'web address' in w else 'replication' if 'replication' in w
                     or 'rebuilt' in w else 'maintenance' if 'maintenance' in w or 'upgrade' in w
                     else 'node')
    return rows


# ---- replication's errors: counted since cleared, read from PostgreSQL's log -----------
def repl_errors(store, ask_log=True):
    """The errors of each subscription since they were last cleared, and what
    PostgreSQL's log says about them (root reads it: the log is postgres's)."""
    r = ha_repl_state(store)
    base = _json_meta(store, 'ha:errbase:' + node_name()) or {}
    subs = []
    for x in r.get('incoming') or []:
        b = base.get(x['name']) or {}
        subs.append({'name': x['name'], 'running': x.get('running'), 'enabled': x.get('enabled'),
                     'apply': int(x.get('apply_errors') or 0),
                     'sync': int(x.get('sync_errors') or 0),
                     'apply_new': max(0, int(x.get('apply_errors') or 0) - int(b.get('apply') or 0)),
                     'sync_new': max(0, int(x.get('sync_errors') or 0) - int(b.get('sync') or 0)),
                     'cleared': base.get('at'), 'cleared_by': base.get('by')})
    got = {}
    if ask_log and WEB_DIR.is_dir():
        ask = WEB_DIR / PGLOG_ASK
        t0 = time.time()
        try:
            ask.write_text(json.dumps({'at': t0, 'port': int(CONFIG.get('db_port') or 5432)}))
        except OSError:
            pass
        while time.time() - t0 < 8:
            got = _pglog_read()
            if float(got.get('at') or 0) >= t0:
                break
            time.sleep(0.4)
    else:
        got = _pglog_read()
    since = float(base.get('at') or 0)
    lines = [e for e in got.get('entries') or [] if float(e.get('ts') or 0) >= since or
             not e.get('ts')]
    return {'subs': subs, 'log': lines[-60:], 'log_at': got.get('at'),
            'log_file': got.get('file') or '', 'log_said': got.get('said') or '',
            'fresh': float(got.get('at') or 0) >= time.time() - 15}


def _pglog_read():
    try:
        fd = os.open(str(WEB_DIR / PGLOG_FILE), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, 'rb') as f:
            got = json.loads(f.read(1 << 20).decode('utf-8', 'replace'))
        return got if isinstance(got, dict) else {}
    except (OSError, ValueError):
        return {}


def repl_errors_clear(store, by):
    r = ha_repl_state(store)
    base = {'at': time.time(), 'by': by}
    for x in r.get('incoming') or []:
        base[x['name']] = {'apply': int(x.get('apply_errors') or 0),
                           'sync': int(x.get('sync_errors') or 0)}
    store.set_meta('ha:errbase:' + node_name(), json.dumps(base))
    return base


# ---- the link between the two databases: encrypted and checked (1.0.104) -----------
# One button on the High availability page does it on a running cluster,
# without stopping anything, on both nodes:
#   1. the cluster gets an authority of its own (kept in the database, its key
#      sealed), and each node a certificate from it for every name and address
#      the other node may reach its PostgreSQL by;
#   2. each node's root helper (otp_web.py) puts the certificate into its
#      PostgreSQL, the authority into /etc/pki/otp/ha-ca.pem (readable by
#      PostgreSQL's own workers), switches ssl on and reloads - no restart;
#   3. once both servers answer with them, each node tries the other with
#      verify-full and only then takes it for its own link (config.json:
#      ha_tls, ha_tls_ca) and moves its subscription over to it;
#   4. once both subscriptions are on it, each server takes the other node
#      only over TLS (pg_hba.conf: host -> hostssl for the other node).
# The local connection of the daemon to 127.0.0.1 is left as it is: Database
# → TLS is about a database on another machine.
# Certificates are renewed by each node by itself 45 days before they end; the
# authority is replaced two years before it ends, the old one trusted beside
# the new one until it runs out. The button also mends a link whose
# certificate has run out: the other node is then told over an encrypted but
# unchecked connection - only to start the same steps.
HA_CA_FILE = Path(os.environ.get('OTP_HA_CA', '/etc/pki/otp/ha-ca.pem'))
PGTLS_ASK = 'pgtls.ask'
PGTLS_FILE = 'pgtls.json'
HATLS_LOCK = threading.Lock()
HATLS_STEPS = ('names', 'server', 'link', 'hba', 'done')
HATLS_CERT_DAYS = 730
HATLS_RENEW_DAYS = 45
HATLS_CA_DAYS = 7300
HATLS_CA_ROLL_DAYS = 730


def hatls_version(v):
    out = []
    for x in re.split(r'[.-]', str(v or '')):
        try:
            out.append(int(x))
        except ValueError:
            out.append(0)
    return tuple(out)


def ha_link_tls(c=None):
    """(mode, authority file) of the link to the other node's PostgreSQL:
    its own when set, else the database's as before (1.0.33)."""
    c = CONFIG if c is None else c
    if c.get('ha_tls'):
        return str(c.get('ha_tls')), str(c.get('ha_tls_ca') or '')
    return str(c.get('db_tls') or ''), str(c.get('db_tls_ca') or '')


def ha_peer_conf(timeout=None, tls=None):
    c = {k: CONFIG.get(k) for k in DB_KEYS}
    c['db_host'] = CONFIG.get('ha_peer')
    c['db_port'] = CONFIG.get('ha_peer_port') or 5432
    c['db_tls'], c['db_tls_ca'] = tls if tls is not None else ha_link_tls()
    if timeout:
        c['db_timeout_s'] = timeout
    return c


def _cert_end(pem):
    out = _openssl(['x509', '-noout', '-enddate'], pem.encode(), what='the certificate')
    when = out.decode().strip().split('=', 1)[-1]
    return float(ssl.cert_time_to_seconds(when))


def hatls_ca(store):
    try:
        got = json.loads(store.get_meta('hatls:ca') or 'null')
    except ValueError:
        got = None
    return got if isinstance(got, dict) and got.get('cas') else {'cas': []}


def hatls_ca_make(store, by):
    """A new authority for the cluster, put in front of the ones it has; the
    old ones are trusted beside it until they run out."""
    key = new_key('ec')
    with tempfile.TemporaryDirectory(prefix='otp-ca-') as t:
        kf = os.path.join(t, 'k.pem')
        with open(kf, 'w') as f:
            f.write(key)
        os.chmod(kf, 0o600)
        name = re.sub(r'[^A-Za-z0-9 .-]', '', str(CONFIG.get('site_name') or 'otp'))[:40] or 'otp'
        crt = _openssl(['req', '-new', '-x509', '-key', kf, '-days', str(HATLS_CA_DAYS),
                        '-subj', '/CN=%s cluster database authority %s'
                        % (name, datetime.now().strftime('%Y-%m-%d')),
                        '-addext', 'basicConstraints=critical,CA:TRUE,pathlen:0',
                        '-addext', 'keyUsage=critical,keyCertSign,cRLSign'],
                       what='the authority').decode()
    ca = hatls_ca(store)
    now = time.time()
    cas = [{'cert': crt, 'key': seal_secret(key, bind='hatls:ca'), 'end': _cert_end(crt),
            'at': now, 'by': by}]
    cas += [x for x in ca['cas'] if float(x.get('end') or 0) > now][:3]
    store.set_meta('hatls:ca', json.dumps({'cas': cas}))
    return cas[0]


def hatls_trust(ca):
    """Every authority still good, the newest first - one file."""
    now = time.time()
    return ''.join(x['cert'].strip() + '\n' for x in ca['cas'] if float(x.get('end') or 0) > now)


def hatls_names(peer_host=''):
    names = [node_name(), 'localhost', '127.0.0.1', '::1']
    for n in (CONFIG.get('ha_address'), node_address(), socket.gethostname(), socket.getfqdn(),
              peer_host):
        n = str(n or '').strip()
        if n and n not in names:
            names.append(n)
    ok = []
    for n in names:
        try:
            _san_ext([n])
            ok.append(n)
        except ValueError:
            pass
    return ok


def hatls_san(names):
    """subjectAltName with every address twice (1.0.105): as an address, for
    libpq 14 and later, and as a name, for libpq 13 - the one RHEL/Alma 9 has
    and the daemon uses - which reads names alone and refused 192.168.42.33."""
    out = []
    for n in names:
        one = _san_ext([n])
        out.append(one)
        if one.startswith('IP:'):
            out.append('DNS:' + n)
    return ','.join(out)


def hatls_needs(store):
    """The addresses the other node reaches this one by - each must be in this
    node's certificate both ways."""
    want = set()
    peer_name = hatls_peer_name(store)
    peer = hatls_state(store, peer_name) if peer_name else {}
    for n in (CONFIG.get('ha_address'), node_address(), peer.get('peer_host'),
              peer.get('peer_lacks')):
        n = str(n or '').strip()
        if n:
            want.add(n)
    for b in ha_nodes(store):
        if b['me'] and b.get('address'):
            want.add(str(b['address']))
    return sorted(want)


def hatls_issue(store, names):
    """A key and a certificate for this node's PostgreSQL, from the newest
    authority of the cluster."""
    ca = hatls_ca(store)
    if not ca['cas']:
        raise ValueError('the cluster has no authority yet')
    top = ca['cas'][0]
    ca_key = unseal_secret(top['key'], bind='hatls:ca')
    if not ca_key or not str(ca_key).startswith('-----BEGIN'):
        raise ValueError('the authority\'s key cannot be opened on this node (is its '
                         'secrets.key the cluster\'s?)')
    key = new_key('ec')
    cn = re.sub(r'[^A-Za-z0-9.-]', '', node_name())[:64] or 'otp'
    with tempfile.TemporaryDirectory(prefix='otp-crt-') as t:
        for n, v in (('k.pem', key), ('ca.pem', top['cert']), ('cakey.pem', ca_key)):
            with open(os.path.join(t, n), 'w') as f:
                f.write(v)
            os.chmod(os.path.join(t, n), 0o600)
        with open(os.path.join(t, 'ext.cnf'), 'w') as f:
            f.write('[v3]\nbasicConstraints=critical,CA:FALSE\n'
                    'keyUsage=critical,digitalSignature,keyEncipherment\n'
                    'extendedKeyUsage=serverAuth\nsubjectAltName=%s\n' % hatls_san(names))
        csr = _openssl(['req', '-new', '-key', os.path.join(t, 'k.pem'), '-subj', '/CN=' + cn],
                       what='the request')
        crt = _openssl(['x509', '-req', '-CA', os.path.join(t, 'ca.pem'), '-CAkey',
                        os.path.join(t, 'cakey.pem'), '-set_serial',
                        str(int.from_bytes(secrets.token_bytes(12), 'big')), '-days',
                        str(HATLS_CERT_DAYS), '-sha256', '-extfile', os.path.join(t, 'ext.cnf'),
                        '-extensions', 'v3'], csr, what='the certificate').decode()
    return key, crt


def hatls_state(store, name=None):
    try:
        got = json.loads(store.get_meta('hatls:node:' + (name or node_name())) or 'null')
    except ValueError:
        got = None
    return got if isinstance(got, dict) else {}


def hatls_put(store, st):
    st['at'] = time.time()
    st['node'] = node_name()
    store.set_meta('hatls:node:' + node_name(), json.dumps(st))


def hatls_want(store):
    try:
        got = json.loads(store.get_meta('hatls:want') or 'null')
    except ValueError:
        got = None
    return got if isinstance(got, dict) else None


def hatls_peer_name(store):
    for n in ha_nodes(store):
        if not n['me']:
            return n['name']
    return ''


def hatls_view(store):
    mode, ca_file = ha_link_tls()
    ca = hatls_ca(store)
    nodes = []
    for r in store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'hatls:node:%'"):
        try:
            one = json.loads(r['v'] or '{}')
        except ValueError:
            continue
        one['name'] = r['k'][len('hatls:node:'):]
        one['me'] = one['name'] == node_name()
        one.pop('asked', None)
        nodes.append(one)
    nodes.sort(key=lambda x: (not x['me'], x['name']))
    w = hatls_want(store)
    return {'mode': mode, 'ca_file': ca_file, 'own': bool(CONFIG.get('ha_tls')),
            'want': w, 'nodes': nodes,
            'authority_end': [float(x.get('end') or 0) for x in ca['cas']],
            'off': bool(w and w.get('off')),
            'running': bool(w) and any(x.get('for') == w.get('at') and x.get('step') not in
                                       ('done', 'failed', 'off_done') for x in nodes)}


def hatls_start(store, by, here=True):
    """The button: both nodes, every step, from wherever they are."""
    if CONFIG.get('ha_mode') != 'replicated':
        raise ValueError('this node does not replicate')
    if store.db.engine != 'postgres':
        raise ValueError('the link is between two PostgreSQLs')
    peer = next((n for n in ha_nodes(store) if not n['me']), None)
    if peer and peer.get('alive') and hatls_version(peer.get('version')) < (1, 0, 104):
        raise ValueError('the other node runs otp %s: upgrade it to this version first'
                         % peer.get('version'))
    if not WEB_DIR.is_dir():
        raise ValueError('%s is not here: the root helper of this node is not installed '
                         '(install.sh --upgrade puts it in)' % WEB_DIR)
    with HATLS_LOCK:
        ca = hatls_ca(store)
        now = time.time()
        if not ca['cas'] or float(ca['cas'][0].get('end') or 0) - now < HATLS_CA_ROLL_DAYS * 86400:
            hatls_ca_make(store, by)
        w = {'at': now, 'by': by, 'from': node_name()}
        store.set_meta('hatls:want', json.dumps(w))
    said = 'both nodes are on their way'
    # The other node told straight into its own database too: with the link
    # stopped (a certificate run out) nothing would carry it over. Checked
    # first, unchecked when that is what does not work - only to say "start".
    told = False
    for tls in (None, ('require', ''), ('prefer', '')):
        try:
            far = db_open(ha_peer_conf(timeout=5, tls=tls))
        except Exception:                               # noqa: BLE001
            continue
        try:
            # The same values replication carries anyway, written in place -
            # never a delete, which would go over and take them away here.
            # Only over a row the other node has already (1.0.147): a row made
            # there and here at once is a duplicate key that stops replication
            # for good. A row new here goes over by replication.
            hits = 0
            for k, v in (('hatls:ca', store.get_meta('hatls:ca')), ('hatls:want', json.dumps(w))):
                hits += far.run('UPDATE meta SET v = ? WHERE k = ?', (v, k)) or 0
            told = hits > 0
            break
        except Exception:                               # noqa: BLE001
            continue
        finally:
            far.close()
    if not told:
        said = ('this node is on its way; the other node\'s database could not be reached '
                'just now - it starts when replication carries it over, or press the button '
                'there')
    store.add_event('settings', '%s: the link between the databases is being encrypted and '
                    'checked (verify-full) on both nodes' % by, who=by)
    if here:
        threading.Thread(target=hatls_tick, args=(store,), name='hatls', daemon=True).start()
    return {'message': said, 'link_tls': hatls_view(store)}


HATLS_OFF_STEPS = ('off_hba', 'off_link', 'off_server', 'off_done')


def hatls_off(store, by, here=True):
    """TLS between the databases switched off again (1.0.107), the steps the
    other way round so replication never stops on it: both databases let the
    other node in without TLS, then both links go back, then the cluster's
    certificates leave both PostgreSQLs (ssl as it was before otp)."""
    if CONFIG.get('ha_mode') != 'replicated':
        raise ValueError('this node does not replicate')
    now = time.time()
    w = {'at': now, 'by': by, 'from': node_name(), 'off': True}
    store.set_meta('hatls:want', json.dumps(w))
    told = False
    for tls in (None, ('require', ''), ('prefer', '')):
        try:
            far = db_open(ha_peer_conf(timeout=5, tls=tls))
        except Exception:                               # noqa: BLE001
            continue
        try:
            told = bool(far.run('UPDATE meta SET v = ? WHERE k = ?',
                                ('hatls:want', json.dumps(w))))   # see hatls_start
            break
        except Exception:                               # noqa: BLE001
            continue
        finally:
            far.close()
    store.add_event('settings', '%s: TLS between the databases is being switched off on both '
                    'nodes' % by, 'warn', who=by)
    if here:
        threading.Thread(target=hatls_tick, args=(store,), name='hatls', daemon=True).start()
    return {'message': 'both nodes are on their way' if told else
            'this node is on its way; the other node could not be reached just now - it starts '
            'when replication carries it over, or press the button there',
            'link_tls': hatls_view(store)}


def _hatls_off_tick(store, w, st):
    now = time.time()
    if st.get('for') != w.get('at'):
        st = {'for': w.get('at'), 'step': 'off_hba', 'began': now, 'off': True}
        hatls_put(store, st)
    if st.get('step') in ('off_done', 'failed'):
        return
    pn = hatls_peer_name(store)
    peer = hatls_state(store, pn) if pn else {}
    rank = {x: i for i, x in enumerate(HATLS_OFF_STEPS)}

    def peer_at(step):
        if not peer:
            return True                 # no other node known: nothing to wait for
        return peer.get('for') == st.get('for') and rank.get(peer.get('step'), -1) >= rank[step]

    def helper(what, then, said):
        if st.get('asked'):
            got = _hatls_answer(st)
            if got is None:
                if now - float(st.get('asked_at') or now) > 180:
                    _hatls_fail(store, st, 'the root helper of this node did not answer in 3 '
                                'minutes - is otp-web.path running?  systemctl status otp-web.path')
                return False
            if not got.get('ok'):
                _hatls_fail(store, st, got.get('said') or 'the root helper said no')
                return False
            st.update(step=then, asked=None, said=got.get('said') or '')
            hatls_put(store, st)
            return True
        _hatls_ask(st, what)
        st['said'] = said
        hatls_put(store, st)
        return False

    if st['step'] == 'off_hba':
        if not helper({'do': 'hba_off'}, 'off_link',
                      'this node\'s PostgreSQL lets the other node in without TLS too'):
            return
    if st['step'] == 'off_link':
        if not peer_at('off_link'):
            st['said'] = 'waiting for %s to let this node in without TLS' % (pn or 'the other node')
            hatls_put(store, st)
            return
        write_file_settings({'ha_tls': '', 'ha_tls_ca': ''})
        CONFIG['ha_tls'], CONFIG['ha_tls_ca'] = '', ''
        sub = ha_sub_here(store.db, 3 - int(CONFIG.get('ha_slot') or 1))
        if store.db.value('SELECT 1 FROM pg_subscription WHERE subname = ?', (sub,)):
            conninfo = ha_conninfo(CONFIG.get('ha_peer'), int(CONFIG.get('ha_peer_port') or 5432),
                                   CONFIG.get('db_name'), CONFIG.get('db_user'),
                                   CONFIG.get('db_password'))
            sub_connection_set(store, sub, conninfo)
        with ONCE_PEER_LOCK:
            was, ONCE_PEER['db'] = ONCE_PEER['db'], None
        if was is not None:
            try:
                was.close()
            except Exception:                           # noqa: BLE001
                pass
        st.update(step='off_server', said='this node takes the other\'s rows as before (Database '
                  '→ TLS)')
        hatls_put(store, st)
    if st['step'] == 'off_server':
        if not peer_at('off_server'):
            st['said'] = 'waiting for %s to move its link back' % (pn or 'the other node')
            hatls_put(store, st)
            return
        if not helper({'do': 'server_off'}, 'off_done',
                      'the cluster\'s certificate leaves this node\'s PostgreSQL'):
            return
        st.update(cert_end=None, done_at=now)
        hatls_put(store, st)
        store.add_event('ha', 'TLS between the databases is off on %s' % node_name(), 'warn')


PGTLS_LOCK = threading.Lock()


def pgtls_send(data):
    """A request into the root helper's pgtls.ask (1.0.139): one waiting there
    and not yet read is not written over - the change of the addresses and the
    link's TLS used the same file and the same temporary name, and one of
    them waited for an answer that never came."""
    with PGTLS_LOCK:
        end = time.time() + 30
        while (WEB_DIR / PGTLS_ASK).exists() and time.time() < end:
            time.sleep(0.5)
        tmp = WEB_DIR / ('.%s.%s' % (PGTLS_ASK, secrets.token_hex(6)))
        fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write(json.dumps(data))
        os.replace(str(tmp), str(WEB_DIR / PGTLS_ASK))


def _hatls_ask(st, what):
    """A request to this node's root helper, as a file in the folder it reads."""
    ask_id = secrets.token_hex(8)
    data = dict(what, id=ask_id, port=int(CONFIG.get('db_port') or 5432),
                db=str(CONFIG.get('db_name') or 'otp'), user=str(CONFIG.get('db_user') or 'otp'),
                peer=str(CONFIG.get('ha_peer') or ''), ca_file=str(HA_CA_FILE))
    pgtls_send(data)
    st['asked'] = ask_id
    st['asked_at'] = time.time()


def _hatls_answer(st):
    """The helper's answer to the request this node made, or None yet."""
    try:
        got = json.loads((WEB_DIR / PGTLS_FILE).read_text())
    except (OSError, ValueError):
        return None
    if isinstance(got, dict) and got.get('id') == st.get('asked'):
        return got
    return None


def _hatls_fail(store, st, why):
    st.update(step='failed', failed_step=st.get('step'), error=str(why)[:400], asked=None)
    hatls_put(store, st)
    log('encrypting the link between the databases: %s' % why, 'warn')
    store.add_event('ha', 'the link between the databases on %s: %s' % (node_name(), why), 'warn')


# When this node next looks whether what it has is what the cluster wants:
# at start, after a database is put back, and every ten minutes.
HATLS_CHECK = {'next': 0.0}


def hatls_check_soon():
    HATLS_CHECK['next'] = 0.0


def hatls_own_cert(store):
    """The certificate this node's PostgreSQL answers with, checked against
    the cluster's authorities: its end in seconds, or ValueError."""
    trust = hatls_trust(hatls_ca(store))
    if not trust:
        raise ValueError('the cluster has no authority that is still good')
    ctx = ssl.create_default_context(cadata=trust)
    ctx.check_hostname = False
    s = socket.create_connection(('127.0.0.1', int(CONFIG.get('db_port') or 5432)), timeout=5)
    try:
        s.sendall(struct.pack('!II', 8, 80877103))           # SSLRequest
        if s.recv(1) != b'S':
            raise ValueError('this node\'s PostgreSQL does not speak TLS')
        try:
            t = ctx.wrap_socket(s)
        except ssl.SSLError as e:
            raise ValueError('this node\'s PostgreSQL answers with a certificate the cluster\'s '
                             'authority did not sign (%s)' % str(e)[:120])
        try:
            got = t.getpeercert() or {}
        finally:
            t.close()
    finally:
        try:
            s.close()
        except OSError:
            pass
    return float(ssl.cert_time_to_seconds(got['notAfter'])), got.get('subjectAltName') or ()


def hatls_check(store):
    """What is in place against what the cluster wants - after a database put
    back, a node reinstalled or joined again, a config.json written anew, a
    PostgreSQL set up again or a certificate run out. Anything not right
    starts this node's steps again by itself; each one is safe to repeat."""
    now = time.time()
    w = hatls_want(store)
    if (not w and not CONFIG.get('ha_tls')) or (w and w.get('off')):
        return                          # never set up, or switched off on purpose
    st = hatls_state(store)
    stuck = st.get('step') == 'link' and now - float(st.get('link_since') or now) > 120
    if st.get('step') not in (None, 'done', 'failed') and not stuck:
        return                          # on its way
    if st.get('step') == 'failed' and now - float(st.get('at') or 0) < 3600:
        # Tried again an hour later - or at once when the other node has put
        # its side right since (1.0.105), or this node's own certificate is
        # what is wrong (looked at below, as for one stuck on the link).
        pn = hatls_peer_name(store)
        peer = hatls_state(store, pn) if pn else {}
        if float(peer.get('at') or 0) > float(st.get('at') or 0) and \
                peer.get('step') in ('link', 'hba', 'done'):
            st2 = {'for': st.get('for') or now, 'step': 'names', 'renew': True, 'began': now,
                   'peer_host': str(CONFIG.get('ha_peer') or ''), 'cert_end': st.get('cert_end'),
                   'said': 'the other node put its side right: tried again'}
            hatls_put(store, st2)
            return
        stuck = True
    ca = hatls_ca(store)
    if not ca['cas'] or not hatls_trust(ca):
        # config.json says verify-full, the database knows no authority (put
        # back from before it): one node makes a new one, both take it.
        if claim_once(store, 'hatls:remake', str(int(time.time() // 600))):
            hatls_ca_make(store, 'otp (no authority in the database)')
            store.set_meta('hatls:want', json.dumps({'at': now, 'by': 'otp (repaired)',
                                                    'from': node_name()}))
            store.add_event('ha', 'the database has no authority for the link between the '
                            'databases (put back from before it?): a new one is made and both '
                            'nodes take it', 'warn')
        return
    wrong = []
    if not st:
        wrong.append('this node has not been through the steps')
    if (CONFIG.get('ha_tls') != 'verify-full' or
            str(CONFIG.get('ha_tls_ca') or '') != str(HA_CA_FILE)) and not stuck:
        wrong.append('its link to the other node is not set to verify-full')
    try:
        end, sans = hatls_own_cert(store)
        if end - now < HATLS_RENEW_DAYS * 86400:
            wrong.append('its database\'s certificate ends %s'
                         % datetime.fromtimestamp(end).strftime('%Y-%m-%d'))
        dns = set(str(v).lower() for k, v in sans if k == 'DNS')
        ips = set()
        for k, v in sans:
            if k == 'IP Address':
                try:
                    ips.add(str(ipaddress.ip_address(str(v).strip())))
                except ValueError:
                    pass
        for n in hatls_needs(store):
            try:
                a = str(ipaddress.ip_address(n))
                ok = a in ips and n.lower() in dns
            except ValueError:
                ok = n.lower() in dns
            if not ok:
                wrong.append('its certificate does not name %s the way every PostgreSQL client '
                             'reads it' % n)
    except Exception as e:                              # noqa: BLE001
        wrong.append(str(e)[:200])
    if stuck:
        # Waiting for the other node's database to pass: only what this node's
        # own certificate lacks is put right here (1.0.105).
        wrong = [x for x in wrong if 'certificate' in x]
    try:
        have = HA_CA_FILE.read_text()
        if ca['cas'][0]['cert'].strip() not in have:
            wrong.append('%s does not hold the newest authority' % HA_CA_FILE)
    except OSError:
        wrong.append('%s is not there' % HA_CA_FILE)
    if not wrong:
        if stuck:
            log('the link between the databases waits for the other node: this node\'s own '
                'certificate names %s - nothing to put right here' % ', '.join(hatls_needs(store)))
        return
    st = {'for': (w or {}).get('at') or now, 'step': 'names', 'renew': True, 'began': now,
          'peer_host': str(CONFIG.get('ha_peer') or ''), 'cert_end': st.get('cert_end'),
          'said': 'put right by itself: ' + '; '.join(wrong)}
    hatls_put(store, st)
    log('the link between the databases is put right on this node: %s' % '; '.join(wrong))
    store.add_event('ha', 'the link between the databases on %s is put right by itself: %s'
                    % (node_name(), '; '.join(wrong)), 'warn')


def hatls_tick(store):
    """One look at where this node is; every step is safe to take again."""
    if CONFIG.get('ha_mode') != 'replicated' or getattr(store.db, 'engine', '') != 'postgres':
        return
    if not HATLS_LOCK.acquire(False):
        return
    try:
        if time.time() >= HATLS_CHECK['next']:
            HATLS_CHECK['next'] = time.time() + 600
            try:
                hatls_check(store)
            except Exception as e:                      # noqa: BLE001
                log('looking at the link between the databases: %s' % e, 'warn')
        _hatls_tick(store)
    except Exception as e:                              # noqa: BLE001
        log('encrypting the link between the databases: %s' % e, 'warn')
    finally:
        HATLS_LOCK.release()


def _hatls_tick(store):
    now = time.time()
    w = hatls_want(store)
    st = hatls_state(store)
    if w and w.get('off'):
        _hatls_off_tick(store, w, st)
        return
    # The other node says this node's certificate lacks a name it reaches it
    # by (1.0.106): a new one at once, not at the next look ten minutes on.
    pn0 = hatls_peer_name(store)
    peer0 = hatls_state(store, pn0) if pn0 else {}
    lacks = str(peer0.get('peer_lacks') or '')
    if w and lacks and peer0.get('step') == 'link' and \
            st.get('step') in ('link', 'hba', 'done', 'failed') and \
            st.get('lack_fixed') != '%s@%s' % (lacks, peer0.get('link_since')):
        st = {'for': st.get('for') or w.get('at'), 'step': 'names', 'renew': True, 'began': now,
              'peer_host': str(CONFIG.get('ha_peer') or ''), 'cert_end': st.get('cert_end'),
              'lack_fixed': '%s@%s' % (lacks, peer0.get('link_since')),
              'said': '%s reaches this node as %s, which its certificate did not name: a new '
                      'one is made' % (pn0, lacks)}
        hatls_put(store, st)
        log('the link between the databases: %s reaches this node as %s - a new certificate'
            % (pn0, lacks))
    # Renewed by itself: a certificate of this node ending within 45 days,
    # or the authority within two years (one node makes the new one).
    if not w or (st.get('for') == w.get('at') and st.get('step') == 'done'):
        if st.get('step') == 'done' and float(st.get('cert_end') or 0) - now < \
                HATLS_RENEW_DAYS * 86400:
            ca = hatls_ca(store)
            if ca['cas'] and float(ca['cas'][0].get('end') or 0) - now < \
                    HATLS_CA_ROLL_DAYS * 86400:
                if claim_once(store, 'hatls:roll', datetime.now().strftime('%Y-%m')):
                    hatls_ca_make(store, 'otp (the authority ends soon)')
                    w = {'at': now, 'by': 'otp (renewed)', 'from': node_name()}
                    store.set_meta('hatls:want', json.dumps(w))
                    st = {}
            else:
                ends = float(st.get('cert_end') or now)
                st = {'for': w.get('at') if w else now, 'step': 'names', 'renew': True,
                      'began': now, 'peer_host': str(CONFIG.get('ha_peer') or '')}
                hatls_put(store, st)
                store.add_event('ha', 'the certificate of %s\'s database ends %s: renewed'
                                % (node_name(), datetime.fromtimestamp(ends).strftime('%Y-%m-%d')))
        if not w or st.get('step') == 'done':
            return
    if st.get('for') != w.get('at') and not st.get('renew'):
        st = {'for': w.get('at'), 'step': 'names', 'began': now,
              'peer_host': str(CONFIG.get('ha_peer') or ''), 'cert_end': st.get('cert_end')}
        hatls_put(store, st)
    if st.get('step') in ('done', 'failed'):
        return
    peer_name = hatls_peer_name(store)
    peer = hatls_state(store, peer_name) if peer_name else {}
    peer_here = peer.get('for') == st.get('for') or peer.get('renew') or \
        peer.get('step') == 'done'
    rank = {s: i for i, s in enumerate(HATLS_STEPS)}

    def peer_at(step):
        return bool(peer) and (peer.get('step') == 'done' or
                               (peer_here and rank.get(peer.get('step'), -1) >= rank[step]))

    if st['step'] == 'names':
        # The names the other node reaches this one by come with its state;
        # a minute is waited for them, then this node goes on with its own.
        if not peer_here and now - float(st.get('began') or now) < 60 and not st.get('renew'):
            st['said'] = 'waiting for %s to start' % (peer_name or 'the other node')
            hatls_put(store, st)
            return
        st['names'] = hatls_names(peer.get('peer_host') if peer_here else '')
        for n in hatls_needs(store):
            if n not in st['names']:
                try:
                    _san_ext([n])
                    st['names'].append(n)
                except ValueError:
                    pass
        st['step'] = 'server'
        st['said'] = 'the certificate of this node\'s database is made'
        hatls_put(store, st)
    if st['step'] == 'server':
        if st.get('asked'):
            got = _hatls_answer(st)
            if got is None:
                if now - float(st.get('asked_at') or now) > 180:
                    _hatls_fail(store, st, 'the root helper of this node did not answer in 3 '
                                'minutes - is otp-web.path running?  systemctl status otp-web.path')
                return
            if not got.get('ok'):
                _hatls_fail(store, st, got.get('said') or 'the root helper said no')
                return
            st.update(step='link', asked=None, said=got.get('said') or '',
                      cert_end=got.get('cert_end') or st.get('cert_end'),
                      data_dir=got.get('data_dir') or '')
            hatls_put(store, st)
        else:
            if not hatls_ca(store)['cas']:
                # Gone meanwhile (a database put back from before it): one node
                # makes a new one; the other waits for it to come over.
                if claim_once(store, 'hatls:remake', str(int(time.time() // 600))):
                    hatls_ca_make(store, 'otp (no authority in the database)')
                else:
                    st['said'] = 'waiting for the cluster\'s authority to come over'
                    hatls_put(store, st)
                    return
            key, crt = hatls_issue(store, st.get('names') or hatls_names())
            st['cert_end'] = _cert_end(crt)
            _hatls_ask(st, {'do': 'server', 'cert': crt, 'key': key,
                            'trust': hatls_trust(hatls_ca(store))})
            st['said'] = 'this node\'s PostgreSQL is being given its certificate (root helper)'
            hatls_put(store, st)
            return
    if st['step'] == 'link':
        if not peer_at('link'):
            st['said'] = 'waiting for %s to give its database a certificate' % (
                peer_name or 'the other node')
            hatls_put(store, st)
            return
        if now < float(st.get('retry_at') or 0):
            return
        try:
            far = db_open(ha_peer_conf(timeout=5, tls=('verify-full', str(HA_CA_FILE))))
            try:
                far.value('SELECT 1')
            finally:
                far.close()
        except Exception as e:                          # noqa: BLE001
            why = scrub_secret(str(e).split('\n')[0])[:300]
            if now - float(st.get('link_since') or now) > 900:
                _hatls_fail(store, st, 'the other node\'s database does not pass verify-full: '
                            + why)
                return
            st.setdefault('link_since', now)
            # The other node's certificate lacks the name this node reaches it
            # by: said in this node's state, where the other node reads it and
            # makes itself a new one at once (1.0.106).
            m = re.search(r'does not match host name "([^"]+)"', why)
            if m:
                st['peer_lacks'] = m.group(1)
            st.update(retry_at=now + 20, said='the other node\'s database does not pass '
                      'verify-full yet: ' + why)
            hatls_put(store, st)
            return
        write_file_settings({'ha_tls': 'verify-full', 'ha_tls_ca': str(HA_CA_FILE)})
        CONFIG['ha_tls'], CONFIG['ha_tls_ca'] = 'verify-full', str(HA_CA_FILE)
        sub = ha_sub_here(store.db, 3 - int(CONFIG.get('ha_slot') or 1))
        if store.db.value('SELECT 1 FROM pg_subscription WHERE subname = ?', (sub,)):
            conninfo = ha_conninfo(CONFIG.get('ha_peer'), int(CONFIG.get('ha_peer_port') or 5432),
                                   CONFIG.get('db_name'), CONFIG.get('db_user'),
                                   CONFIG.get('db_password'))
            sub_connection_set(store, sub, conninfo)
        with ONCE_PEER_LOCK:
            was, ONCE_PEER['db'] = ONCE_PEER['db'], None
        if was is not None:
            try:
                was.close()
            except Exception:                           # noqa: BLE001
                pass
        st.update(step='hba', said='this node takes the other\'s rows over TLS, its '
                  'certificate checked (verify-full)', retry_at=0, link_since=None,
                  peer_lacks=None)
        hatls_put(store, st)
    if st['step'] == 'hba':
        if st.get('asked'):
            got = _hatls_answer(st)
            if got is None:
                if now - float(st.get('asked_at') or now) > 180:
                    _hatls_fail(store, st, 'the root helper of this node did not answer in 3 '
                                'minutes - is otp-web.path running?  systemctl status otp-web.path')
                return
            if not got.get('ok'):
                _hatls_fail(store, st, got.get('said') or 'the root helper said no')
                return
            st.update(step='done', asked=None, said=got.get('said') or 'done', done_at=now,
                      error=None, renew=None)
            hatls_put(store, st)
            store.add_event('ha', 'the link between the databases is encrypted and checked on '
                            '%s (verify-full); its certificate ends %s' % (
                                node_name(), datetime.fromtimestamp(
                                    float(st.get('cert_end') or now)).strftime('%Y-%m-%d')))
            return
        if not peer_at('hba'):
            st['said'] = 'waiting for %s to move its link over' % (peer_name or 'the other node')
            hatls_put(store, st)
            return
        _hatls_ask(st, {'do': 'hba'})
        st['said'] = 'this node\'s PostgreSQL is told to take the other node over TLS only'
        hatls_put(store, st)


# ---- a node's address changed: the cluster put right in place (1.0.106) ----------
# Replication remembers the other node's address in three places on each node:
# config.json (ha_peer, and ha_address - its own, as the other reaches it), its
# subscription's connection, and the line of pg_hba.conf that lets the other
# node in. Changing an address used to mean taking the pair apart and building
# it again. Now one node is told the new address(es) - on its pages or with
# otp --ha-readdress - and puts its three places right; then it tells the other
# node straight into that one's database, which does its part by itself.
#
# Which node to do it on: the one whose address did NOT change. Its own line
# in the other's pg_hba.conf still matches, so it can reach the other at the
# new address and tell it; the other cannot reach it yet. When both changed,
# do it on both (each says what it could not do).
READDRESS_LOCK = threading.Lock()


def _readdress_ip(text, what):
    text = str(text or '').strip()
    if not text:
        return ''
    try:
        return str(peer_address(text))
    except ValueError:
        raise ValueError('%s is one plain address (192.0.2.10), not %r' % (what, text[:60]))


def _readdress_hba(old_peer, new_peer, root_now, keep_old=False, drop_old=False):
    """This node's pg_hba.conf: the other node's line moved to its new
    address (host or hostssl kept), by the root helper."""
    ask_id = secrets.token_hex(8)
    data = {'id': ask_id, 'do': 'peer', 'port': int(CONFIG.get('db_port') or 5432),
            'db': str(CONFIG.get('db_name') or 'otp'), 'user': str(CONFIG.get('db_user') or 'otp'),
            'peer': new_peer, 'old_peer': old_peer, 'ca_file': str(HA_CA_FILE),
            # On trial (1.0.137): the old address let in beside the new one,
            # so the other node can still be told if it goes back; and taken
            # out once the new one is kept.
            'keep_old': bool(keep_old), 'drop_old': bool(drop_old)}
    pgtls_send(data)
    if root_now:
        # On the command line, as root: the helper run here and now.
        helper = Path(__file__).resolve().parent / 'otp_web.py'
        if not helper.exists():
            helper = Path('/usr/local/lib/otp/otp_web.py')
        subprocess.run(['/usr/bin/python3', '-I', str(helper)], capture_output=True,
                       timeout=120, env=dict(os.environ, OTP_STATE=str(STATE_DIR)))
    end = time.time() + 60
    while time.time() < end:
        try:
            got = json.loads((WEB_DIR / PGTLS_FILE).read_text())
        except (OSError, ValueError):
            got = None
        if isinstance(got, dict) and got.get('id') == ask_id:
            if not got.get('ok'):
                raise ValueError('pg_hba.conf: %s' % (got.get('said') or 'the root helper said no'))
            return got.get('said') or 'pg_hba.conf changed'
        time.sleep(0.5)
    raise ValueError('the root helper of this node did not answer in a minute - is otp-web.path '
                     'running?  systemctl status otp-web.path')


def ha_readdress(store, mine='', peer='', by='', root_now=False, tell=True, daemon=None,
                 keep_old=False):
    """This node told its own new address (`mine`, as the other node reaches
    it) and/or the other node's (`peer`). Returns what was done and what is
    left, in words."""
    if CONFIG.get('ha_mode') != 'replicated':
        raise ValueError('this node does not replicate')
    mine = _readdress_ip(mine, 'this node\'s address')
    peer = _readdress_ip(peer, 'the other node\'s address')
    had_mine = str(CONFIG.get('ha_address') or node_address() or '')
    had_peer = str(CONFIG.get('ha_peer') or '')
    if mine == had_mine:
        mine = ''
    if peer == had_peer:
        peer = ''
    if not mine and not peer:
        return {'message': 'nothing to change: both addresses are as this node has them',
                'done': [], 'left': []}
    if peer and peer in (mine or had_mine):
        raise ValueError('the two nodes cannot have one address')
    done, left = [], []
    with READDRESS_LOCK:
        if peer:
            done.append(_readdress_hba(had_peer, peer, root_now, keep_old=keep_old))
            write_file_settings({'ha_peer': peer})
            CONFIG['ha_peer'] = peer
            done.append('ha_peer = %s (was %s)' % (peer, had_peer))
            sub = ha_sub_here(store.db, 3 - int(CONFIG.get('ha_slot') or 1))
            if store.db.value('SELECT 1 FROM pg_subscription WHERE subname = ?', (sub,)):
                conninfo = ha_conninfo(peer, int(CONFIG.get('ha_peer_port') or 5432),
                                       CONFIG.get('db_name'), CONFIG.get('db_user'),
                                       CONFIG.get('db_password'))
                try:
                    sub_connection_set(store, sub, conninfo)
                except ValueError as e:
                    raise ValueError('the subscription %s could not be pointed at %s: %s'
                                     % (sub, peer, str(e).split(': ', 1)[-1]))
                done.append('this node takes the other\'s rows from %s now' % peer)
            with ONCE_PEER_LOCK:
                was, ONCE_PEER['db'] = ONCE_PEER['db'], None
            if was is not None:
                try:
                    was.close()
                except Exception:                       # noqa: BLE001
                    pass
        if mine:
            write_file_settings({'ha_address': mine})
            CONFIG['ha_address'] = mine
            done.append('ha_address = %s (was %s)' % (mine, had_mine))
        # The other node told, straight into its database: it is reached at
        # its address as this node now has it.
        if tell:
            d2, l2 = readdress_tell(peer or had_peer, mine or had_mine, by, keep_old)
            done += d2
            left += l2
    hatls_check_soon()
    store.add_event('settings', '%s: the addresses of the cluster changed on %s - %s%s' % (
        by or 'command line', node_name(), '; '.join(done),
        (' - left: ' + '; '.join(left)) if left else ''), 'warn', who=by or 'command line')
    log('the addresses of the cluster changed: %s' % '; '.join(done + left), 'warn')
    if daemon is not None:
        try:
            daemon.reload_all('the addresses of the cluster changed')
        except Exception:                               # noqa: BLE001
            pass
    return {'message': '; '.join(done + left), 'done': done, 'left': left}


def readdress_tell(peer, mine, by, keep_old=False):
    """The other node (at `peer`) told this node is at `mine`, straight into
    its database. (done, left) in words."""
    done, left = [], []
    ask = {'at': time.time(), 'by': by, 'from': node_name(), 'mine': peer, 'peer': mine,
           'keep_old': bool(keep_old)}
    told = False
    # As the link is set; where its certificate names the old address, by the
    # cluster's authority alone (1.0.139) - not unchecked, nor in the clear:
    # whoever stood between could have written this request themselves.
    mode, ca = ha_link_tls()
    tries = [None] + ([('verify-ca', ca)] if mode == 'verify-full' else [])
    for tls in tries:
        try:
            far = db_open(ha_peer_conf(timeout=5, tls=tls))
        except Exception:                               # noqa: BLE001
            continue
        try:
            far.run('INSERT INTO meta (k, v) VALUES (?, ?) ON CONFLICT (k) DO UPDATE '
                    'SET v = EXCLUDED.v', ('readdress:ask', json.dumps(ask)))
            told = True
            break
        except Exception:                               # noqa: BLE001
            continue
        finally:
            far.close()
    if told:
        done.append('the other node was told and puts its side right by itself '
                    '(within seconds)')
    else:
        left.append('the other node could not be reached at %s to be told: do the same '
                    'there - its pages (Settings → High availability → The addresses of '
                    'the two nodes) or  otp --ha-readdress --ha-address %s --ha-peer %s  on it'
                    % (peer, peer, mine))
    return done, left


def readdress_tick(store, daemon=None):
    """A request the other node wrote into this database: this node's part."""
    raw = store.get_meta('readdress:ask')
    if not raw:
        return
    try:
        ask = json.loads(raw)
    except ValueError:
        return
    if not isinstance(ask, dict) or ask.get('from') == node_name() or ask.get('done'):
        return
    try:
        got = ha_readdress(store, ask.get('mine') or '', ask.get('peer') or '',
                           by='%s (told by %s)' % (ask.get('by') or 'otp', ask.get('from')),
                           tell=False, daemon=daemon, keep_old=bool(ask.get('keep_old')))
        ask.update(done=time.time(), said=got['message'])
    except Exception as e:                              # noqa: BLE001
        ask.update(done=time.time(), error=str(e)[:300])
        log('putting the addresses of the cluster right as %s asked: %s'
            % (ask.get('from'), e), 'warn')
        store.add_event('settings', 'the addresses of the cluster could not be put right on %s '
                        'as %s asked: %s' % (node_name(), ask.get('from'), e), 'bad')
    store.set_meta('readdress:ask', json.dumps(ask))


def readdress_view(store):
    """What the pages show: the addresses as this node has them, what it
    seems to have now, and whether the other node is reached there."""
    said = node_address()
    out = {'mine': str(CONFIG.get('ha_address') or ''), 'peer': str(CONFIG.get('ha_peer') or ''),
           'detected': said, 'addresses': readdress_addresses()}
    out['mine_here'] = not out['mine'] or out['mine'] in out['addresses'] or \
        out['mine'].startswith('127.') or out['mine'] == '::1' or not out['addresses']
    try:
        raw = json.loads(store.get_meta('readdress:ask') or 'null')
        if isinstance(raw, dict):
            out['last'] = raw
    except ValueError:
        pass
    return out


def readdress_addresses():
    """The addresses this machine has, without loopback and link-local - from
    local_addresses() (88w_web), never a second function of that name: one
    here (1.0.106) took its place everywhere, found no `ip` in the service's
    PATH, and the web address showed "on no node" though a node held it."""
    out = []
    for a in sorted(local_addresses()):
        try:
            ip = ipaddress.ip_address(a)
        except ValueError:
            continue
        if ip.is_loopback or ip.is_link_local:
            continue
        out.append(str(ip))
    return out
# ---- the machine's network, its name, and switching it off (1.0.119) ------------------
# Settings → Network: each node's IPv4 address, gateway, DNS, host name and -
# switched on - IPv6, set from the pages of either node. Settings → Restart and
# power off: a reboot or a power-off of one node, the other or both.
#
# Who does what. The page asks through whichever node answers it (the web
# address, or a node's own address); what is asked is written into the
# database for the node it is about - 'net:want:NODE' or 'power:plan' - and
# that node's daemon does it, writing how far it got into a row only it
# writes ('net:job:NODE', 'power:node:NODE'). Replication brings both to the
# other node, so either node's pages show the progress, and a page whose node
# restarts goes on with the other - or waits for its own to come back.
#
# A new address in a cluster is done in this order, so nothing is cut off:
#   1. the other node is told the new address (ha_readdress): its pg_hba.conf,
#      its subscription and its ha_peer move to it - it waits for this node
#      there;
#   2. this node's ha_address, its own settings that name the old address or
#      name (RADIUS's address, the mail greeting, the isemon name), and its
#      self-made certificate are made again with the new ones;
#   3. maintenance: the web address goes to the other node;
#   4. NetworkManager, the host name and /etc/hosts, then a reboot;
#   5. back up: the new address checked, the link between the databases made
#      again for it (hatls), replication both ways, keepalived and nginx
#      rewritten from the database (web_tick) - then out of maintenance.
NET_ASK_NAME = 'net.ask'
NET_ANSWER_NAME = 'net.json'
NET_READ_S = 300                # how often each node says what its network is
NET_JOB_LIVE_S = 1800           # a job not moving for this long is over
NET_WORK = {'busy': False, 'read_at': 0.0}
NET_WORK_LOCK = threading.Lock()


def boot_time():
    """When this machine started (the kernel's btime) - a restart of the
    service is not a reboot."""
    fake = os.environ.get('OTP_BTIME_FILE')         # tests: a reboot without one
    if fake:
        try:
            return float(Path(fake).read_text().strip() or 0)
        except (OSError, ValueError):
            pass
    try:
        with open('/proc/stat') as f:
            for line in f:
                if line.startswith('btime '):
                    return float(line.split()[1])
    except (OSError, ValueError, IndexError):
        pass
    return 0.0


NET_ROOT_LOCK = threading.Lock()


def net_root(data, wait=60):
    """One request to the root helper (otp_web.py) and its answer - one at a
    time (1.0.146): "Read it again" on the pages during a job wrote over the
    job's request, or took its answer, and the job waited for nothing."""
    with NET_ROOT_LOCK:
        ask_id = secrets.token_hex(8)
        data = dict(data, id=ask_id)
        tmp = WEB_DIR / ('.%s.%s' % (NET_ASK_NAME, secrets.token_hex(6)))
        fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
        with os.fdopen(fd, 'w') as f:
            f.write(json.dumps(data))
        os.replace(str(tmp), str(WEB_DIR / NET_ASK_NAME))
        end = time.time() + wait
        while time.time() < end:
            try:
                got = json.loads((WEB_DIR / NET_ANSWER_NAME).read_text())
            except (OSError, ValueError):
                got = None
            if isinstance(got, dict) and got.get('id') == ask_id:
                if not got.get('ok'):
                    raise ValueError(got.get('said') or 'the root helper said no')
                return got.get('data') or {}
            time.sleep(0.4)
    raise ValueError('the root helper of this node did not answer in %d s - is otp-web.path '
                     'running?  systemctl status otp-web.path' % wait)


def net_publish(store):
    """This node's network as root reads it, into the database for the pages
    of either node."""
    data = net_root({'do': 'read'}, 30)
    now = {'at': time.time(), 'data': data, 'boot': boot_time(),
           'radius_bind': str(CONFIG.get('radius_bind') or '0.0.0.0'),
           'ha_address': str(CONFIG.get('ha_address') or ''),
           'node_name_pinned': bool(str(FILE_CONFIG.get('node_name') or '').strip())}
    store.set_meta('net:now:' + node_name(), json.dumps(now))
    NET_WORK['read_at'] = time.time()
    return now


# ---- what is asked, checked ---------------------------------------------------------
def _net_list(v, most=4):
    if isinstance(v, str):
        v = re.split(r'[\s,;]+', v)
    return [str(x).strip() for x in (v or []) if str(x).strip()][:most]


def net_node_now(store, node):
    return _meta_json(store, 'net:now:' + node) or {}


def net_current_ip(now):
    """This node's IPv4 address as NetworkManager has it (or the one on its
    default route)."""
    d = now.get('data') or {}
    conf = d.get('conf') or {}
    for a in conf.get('ipv4_addresses') or []:
        return str(a)
    dev = d.get('dev')
    for a in (d.get('live') or {}).get('addrs4') or []:
        if not dev or a.get('dev') == dev:
            return str(a.get('addr') or '')
    return ''


def net_check(store, node, want, rollback=False):
    """What the page asked for, made whole and checked against the node as it
    said it is; with the plan in words. Raises ValueError."""
    now = net_node_now(store, node)
    d = now.get('data') or {}
    if not d:
        raise ValueError('%s has not said what its network is yet - press Read it again and '
                         'wait a few seconds' % node)
    if not d.get('nm'):
        raise ValueError('NetworkManager (nmcli) is not on %s: its network is set by hand '
                         'there' % node)
    con = str(want.get('con') or d.get('con') or '')
    if not con or con not in [x.get('con') for x in d.get('devices') or []]:
        raise ValueError('which connection of %s? It has: %s' % (node, ', '.join(
            '%s (%s)' % (x.get('con'), x.get('dev')) for x in d.get('devices') or []
            if x.get('con')) or 'none'))
    v4 = want.get('ipv4') or {}
    try:
        a4 = ipaddress.ip_interface(str(v4.get('addr') or '').strip())
    except ValueError:
        raise ValueError('the IPv4 address is an address with its prefix: 192.0.2.10/24')
    if a4.version != 4 or '/' not in str(v4.get('addr')):
        raise ValueError('the IPv4 address is an address with its prefix: 192.0.2.10/24')
    if (a4.ip.is_loopback and not os.environ.get('OTP_NET_LOOPBACK_OK')) or \
            a4.ip.is_multicast or a4.ip.is_unspecified or \
            a4.ip == a4.network.network_address or a4.ip == a4.network.broadcast_address:
        raise ValueError('%s cannot be the address of a machine in %s' % (a4.ip, a4.network))
    gw = str(v4.get('gw') or '').strip()
    if gw:
        try:
            g = ipaddress.ip_address(gw)
        except ValueError:
            raise ValueError('the gateway is one IPv4 address')
        if g.version != 4 or g not in a4.network or g == a4.ip:
            raise ValueError('the gateway %s is not another address in %s' % (g, a4.network))
    dns = _net_list(v4.get('dns'))
    for x in dns:
        try:
            ipaddress.ip_address(x)
        except ValueError:
            raise ValueError('%r is not the address of a DNS server' % x)
    search = _net_list(v4.get('search'), 6)
    v6 = want.get('ipv6') or {}
    on6 = bool(v6.get('on'))
    mode6 = 'off'
    a6 = None
    if on6:
        mode6 = 'manual' if str(v6.get('mode') or 'manual') == 'manual' else 'auto'
        if mode6 == 'manual':
            try:
                a6 = ipaddress.ip_interface(str(v6.get('addr') or '').strip())
            except ValueError:
                raise ValueError('the IPv6 address is an address with its prefix: '
                                 '2001:db8::10/64')
            if a6.version != 6 or a6.ip.is_link_local or '/' not in str(v6.get('addr')):
                raise ValueError('the IPv6 address is a global one with its prefix: '
                                 '2001:db8::10/64')
        g6 = str(v6.get('gw') or '').strip()
        if g6:
            try:
                if ipaddress.ip_address(g6).version != 6:
                    raise ValueError
            except ValueError:
                raise ValueError('the IPv6 gateway is one IPv6 address')
    dns6 = _net_list(v6.get('dns')) if on6 else []
    for x in dns6:
        try:
            ipaddress.ip_address(x)
        except ValueError:
            raise ValueError('%r is not the address of a DNS server' % x)
    host = str(want.get('hostname') or '').strip().rstrip('.').lower()
    # The name the node has now, kept as it is, may be a short one - and going
    # back after a trial asks for the old one again: refused, the new network
    # stayed (1.0.139). Still a name, one part or more.
    same = rollback or host == str(d.get('hostname') or '').strip().rstrip('.').lower()
    if not re.match(r'^(?=.{1,253}$)[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?'
                    r'(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)%s$' % ('*' if same else '+'), host):
        raise ValueError('the host name is the whole name: otp1.example.cz')
    old_ip = net_current_ip(now).split('/')[0]
    new_ip = str(a4.ip)
    many = bool(CONFIG.get('ha_mode'))
    others = [n for n in ha_nodes(store) if n['name'] != node]
    for n in others:
        if str(n.get('address') or '') == new_ip:
            raise ValueError('%s is the address of %s' % (new_ip, n['name']))
    v = vip_conf(store)
    if v.get('on') and many:
        try:
            vnet = ipaddress.ip_interface(v.get('address'))
        except ValueError:
            vnet = None
        if vnet and vnet.ip == a4.ip:
            raise ValueError('%s is the web address of the cluster' % new_ip)
        if vnet and vnet.ip not in a4.network and not want.get('vip_elsewhere'):
            raise ValueError('the web address %s is not in %s: the node could not hold it. '
                             'Change the web address first (High availability), or tick that '
                             'it is meant to be so' % (vnet.ip, a4.network))
    plan = []
    ip_changed = bool(old_ip) and old_ip != new_ip
    host_old = str(d.get('hostname') or '')
    conf = d.get('conf') or {}
    was6 = conf.get('ipv6_method') not in (None, '', 'disabled', 'ignore')
    if ip_changed and many and CONFIG.get('ha_mode') == 'replicated':
        plan.append('the other node is told %s: its pg_hba.conf, its subscription and its '
                    'ha_peer move to it' % new_ip)
    if ip_changed:
        plan.append('this node\'s settings that name %s - and its own certificate, where it was '
                    'made here - are made again for %s' % (old_ip, new_ip))
    if host and host != host_old:
        plan.append('the host name %s → %s (the node keeps its name in otp: %s)'
                    % (host_old or '?', host, node))
    if on6 != was6:
        plan.append('IPv6 %s: RADIUS listens %s' % (
            'on' if on6 else 'off', 'on IPv4 and IPv6 (::)' if on6 else 'on IPv4 only'))
    if many:
        plan.append('maintenance on %s - the web address goes to the other node' % node)
    plan.append('NetworkManager (%s): %s via %s, DNS %s%s' % (
        con, a4, gw or 'no gateway', ', '.join(dns) or 'none',
        '' if not on6 else ', IPv6 %s' % (a6 if a6 else 'automatic')))
    plan.append('a reboot of %s; back up, it checks the new address%s and comes out of '
                'maintenance by itself' % (node, ', replication and the link between the '
                                           'databases' if many else ''))
    return {'con': con, 'dev': next((x.get('dev') for x in d.get('devices') or []
                                     if x.get('con') == con), ''),
            'ipv4': {'addr': str(a4), 'gw': gw, 'dns': dns, 'search': search},
            'ipv6': {'on': on6, 'mode': mode6, 'addr': str(a6) if a6 else '',
                     'gw': str(v6.get('gw') or '').strip() if on6 else '', 'dns': dns6},
            'hostname': host, 'old_ip': old_ip, 'new_ip': new_ip, 'old_hostname': host_old,
            'ip_changed': ip_changed, 'was6': was6, 'plan': plan}


def net_job_active(job):
    return bool(job) and job.get('state') in ('asked', 'running', 'rebooting') and \
        time.time() - float(job.get('moved') or job.get('at') or 0) < NET_JOB_LIVE_S


def net_ask(store, node, want, by, rollback=False, maint=False, snap=''):
    """The page asks: written for the node, which does it. `rollback`: the
    old network asked back by the node itself - not put on trial again."""
    if net_job_active(_meta_json(store, 'net:job:' + node)):
        raise ValueError('%s is changing its network already' % node)
    if power_busy(store):
        raise ValueError('a restart or a power-off is under way')
    checked = net_check(store, node, want, rollback=rollback)
    ask = {'id': secrets.token_hex(6), 'node': node, 'want': checked, 'by': by,
           'at': time.time(), 'from': node_name(), 'rollback': bool(rollback),
           'maint': bool(maint), 'snap': str(snap or '')}
    store.set_meta('net:want:' + node, json.dumps(ask))
    store.add_event('settings', '%s asked %s for a new network: %s' % (
        by, node, '; '.join(checked['plan'])), 'warn', who=by)
    return ask


# ---- the job, on the node it is about -------------------------------------------------
def _job_put(store, job, words=None, pct=None, ok=True, state=None):
    if words:
        job.setdefault('steps', []).append({'at': time.time(), 'what': str(words)[:400],
                                            'ok': bool(ok)})
        log('network: %s' % words, 'info' if ok else 'warn')
    if pct is not None:
        job['pct'] = int(pct)
    if state:
        job['state'] = state
    job['moved'] = time.time()
    store.set_meta('net:job:' + node_name(), json.dumps(job))


def _cert_names_swap(names, swap):
    out = []
    for n in names:
        n = swap.get(n, n)
        if n and n not in out:
            out.append(n)
    return out


def net_cert_again(store, w, by):
    """This node's own certificate, made here, made again with the new
    address and name where it named the old ones. One from an authority is
    said, not changed."""
    me = node_name()
    prof = tls_profile(store, me)
    if not prof or not prof.get('cert'):
        return ''
    info = prof.get('info') or {}
    try:
        info = cert_info(prof['cert'])
    except ValueError:
        pass
    names = list(info.get('san') or [])
    cn = info.get('cn') or ''
    swap = {}
    if w['ip_changed'] and w['old_ip']:
        swap[w['old_ip']] = w['new_ip']
    if w['hostname'] and w['old_hostname'] and w['hostname'] != w['old_hostname']:
        swap[w['old_hostname']] = w['hostname']
        swap[w['old_hostname'].split('.')[0]] = w['hostname'].split('.')[0]
    if not any(k in names or k == cn for k in swap):
        return ''
    if not info.get('self_signed'):
        return ('this node\'s certificate is from an authority and names %s - get one for %s'
                % (', '.join(k for k in swap if k in names or k == cn),
                   ', '.join(swap[k] for k in swap if k in names or k == cn)))
    kind = 'rsa2048'
    k = str(info.get('key') or '')
    if k.startswith('EC'):
        kind = 'ec'
    elif '4096' in k:
        kind = 'rsa4096'
    elif '3072' in k:
        kind = 'rsa3072'
    new_names = _cert_names_swap(names, swap)
    if w['ipv6'].get('addr'):
        ip6 = w['ipv6']['addr'].split('/')[0]
        if ip6 not in new_names:
            new_names.append(ip6)
    new_cn = swap.get(cn, cn) or w['hostname']
    key, crt = make_selfsigned(new_cn, [x for x in new_names if x != new_cn], 825, kind)
    got = cert_bundle(crt, key)
    prof.update(cert=got['cert'], chain=got['chain'], root=got['root'],
                key=seal_secret(got['key'], 'web:tls'), info=got['info'],
                chain_info=got['chain_info'], root_info=got['root_info'],
                verify=got['verify'], how='self-signed, made here (the network changed)')
    tls_save(store, me, prof, by)
    return 'this node\'s own certificate made again for %s' % ', '.join(new_names[:6])


NET_UNDO_KEYS = ('radius_bind', 'mail_helo', 'isemon_hostname')
NET_UNDO_FILE_KEYS = ('db_host', 'ha_address')


def net_undo_keep(store, snap):
    """This node's own settings and certificate as they are before a change on
    trial (1.0.139) - not in the job, which the pages read."""
    store.set_meta('net:undo:' + node_name(), json.dumps({
        'snap': snap, 'at': time.time(),
        'settings': {k: CONFIG.get(k) for k in NET_UNDO_KEYS},
        'file': {k: FILE_CONFIG.get(k) for k in NET_UNDO_FILE_KEYS if k in FILE_CONFIG},
        'tls': store.get_meta('web:tls:' + node_name()) or ''}))


def net_undo_get(store, snap):
    got = _meta_json(store, 'net:undo:' + node_name()) or {}
    return got if snap and got.get('snap') == snap else None


def net_job_undo_told(daemon, job, by):
    """A job stopped before the network changed, after the other node was told
    the new address (1.0.146): its pg_hba.conf, its subscription and its
    ha_peer - and this node's ha_address - moved back to the address the node
    still has. Left, the cluster pointed at an address that never came."""
    w = job.get('want') or {}
    if not job.get('told') or not w.get('ip_changed') or not w.get('old_ip'):
        return
    store = daemon.store
    try:
        got = ha_readdress(store, mine=w['old_ip'], by='%s (put back)' % by, daemon=daemon)
        _job_put(store, job, 'the other node told the address again: %s' % (
            got.get('message') or w['old_ip']), job.get('pct'), ok=not got.get('left'))
    except Exception as e:                              # noqa: BLE001
        _job_put(store, job, 'the other node could not be told the address again (%s): '
                 'Settings → High availability → The addresses of the two nodes' % e,
                 job.get('pct'), ok=False)
    job['told'] = False


def net_job_run(daemon, ask):
    store = daemon.store
    me = node_name()
    w = ask['want']
    by = '%s (network)' % (ask.get('by') or 'otp')
    job = {'id': ask['id'], 'node': me, 'state': 'running', 'at': time.time(), 'pct': 0,
           'by': ask.get('by'), 'want': w, 'steps': [], 'boot': boot_time()}
    many = bool(CONFIG.get('ha_mode'))
    # On trial (1.0.137): what the node has now kept, to go back to unless the
    # new one is kept in time.
    if net_trial_min() and not ask.get('rollback'):
        job['back'], job['back_why'] = net_back_want(net_node_now(store, me))
        job['trial_min'] = net_trial_min() if job['back'] else 0
        if job['trial_min']:
            # Going back puts back exactly what is here now (1.0.139): the root
            # helper keeps the network whole, this node its own settings and
            # certificate - not worked out again the other way round.
            job['snap'] = secrets.token_hex(8)
            net_undo_keep(store, job['snap'])
    job['rollback'] = bool(ask.get('rollback'))
    undo = net_undo_get(store, ask.get('snap')) if ask.get('rollback') else None
    # Maintenance put on by the job it goes back from: taken off by this one.
    if ask.get('maint'):
        job['maint'] = True
    job['keep_old'] = bool(job.get('trial_min')) and CONFIG.get('ha_mode') == 'replicated'
    try:
        _job_put(store, job, 'started - %s' % '; '.join(w['plan'][:2]), 3)
        if job.get('trial_min'):
            _job_put(store, job, 'on trial: unless it is kept within %d min of coming back up, '
                     'the network it has now comes back by itself' % job['trial_min'], 4)
        elif job.get('back_why'):
            _job_put(store, job, job['back_why'], 4, ok=False)
        # 1. The node keeps its name, whatever the machine is called.
        if not str(FILE_CONFIG.get('node_name') or '').strip():
            write_file_settings({'node_name': me})
            CONFIG['node_name'] = me
            _job_put(store, job, 'the node\'s name %s kept in config.json, whatever the host '
                     'name' % me, 8)
        # 2. The other node told the new address.
        if w['ip_changed'] and CONFIG.get('ha_mode') == 'replicated':
            _job_put(store, job, 'telling the other node %s' % w['new_ip'], 12)
            # From here the other node (and ha_address) may have the new one:
            # stopped before the network changed, they are told back (1.0.146).
            job['told'] = True
            asked_at = time.time()
            got = ha_readdress(store, mine=w['new_ip'], by=by, daemon=daemon,
                               keep_old=job.get('keep_old'))
            if got.get('left'):
                if not job.get('rollback'):
                    raise ValueError('; '.join(got['left']))
                # Going back from an address the other node cannot reach:
                # told once this node is back at its old one (1.0.137).
                job['tell_after'] = True
                _job_put(store, job, 'the other node is told once this node is back at %s'
                         % w['new_ip'], 25, ok=False)
            end = time.time() + (0 if job.get('tell_after') else 90)
            done = None
            while time.time() < end:
                a = _meta_json(store, 'readdress:ask') or {}
                # This job's request, not one answered before (1.0.146).
                if a.get('from') == me and a.get('done') and \
                        float(a.get('at') or 0) >= asked_at - 1:
                    done = a
                    break
                time.sleep(2)
            if done and done.get('error'):
                raise ValueError('the other node: %s' % done['error'])
            if not job.get('tell_after'):
                _job_put(store, job, 'the other node expects %s now%s' % (
                    w['new_ip'], '' if done else ' (it had not said so yet - it does it by '
                    'itself)'), 25)
        elif w['ip_changed'] and CONFIG.get('ha_address'):
            write_file_settings({'ha_address': w['new_ip']})
            CONFIG['ha_address'] = w['new_ip']
        # 3. This node's own settings that name the old address or name.
        changes = {}
        rb = str(CONFIG.get('radius_bind') or '0.0.0.0')
        if undo:
            # Back to the values it had, as they were.
            changes = {k: v for k, v in (undo.get('settings') or {}).items()
                       if str(CONFIG.get(k) or '') != str(v or '')}
        elif w['ip_changed'] and rb == w['old_ip']:
            changes['radius_bind'] = w['new_ip']
        elif w['ipv6']['on'] and rb in ('0.0.0.0', ''):
            changes['radius_bind'] = '::'
        elif not w['ipv6']['on'] and rb == '::':
            changes['radius_bind'] = '0.0.0.0'
        if not undo and w['hostname'] and w['old_hostname'] and \
                w['hostname'] != w['old_hostname']:
            for k in ('mail_helo', 'isemon_hostname'):
                if str(CONFIG.get(k) or '') in (w['old_hostname'], w['old_hostname'].split('.')[0]):
                    changes[k] = w['hostname']
        if changes:
            daemon.save_settings(changes, by=by, node=me)
            _job_put(store, job, 'this node\'s settings: %s' % ', '.join(
                '%s = %s' % kv for kv in sorted(changes.items())), 35)
        if undo:
            files = {k: v for k, v in (undo.get('file') or {}).items()
                     if str(FILE_CONFIG.get(k) or '') != str(v or '')}
            if files:
                write_file_settings(files)
                CONFIG.update(files)
                _job_put(store, job, 'config.json as it was: %s' % ', '.join(
                    '%s = %s' % kv for kv in sorted(files.items())), 37)
        elif w['ip_changed'] and str(CONFIG.get('db_host') or '') == w['old_ip']:
            write_file_settings({'db_host': w['new_ip']})
            _job_put(store, job, 'db_host = %s' % w['new_ip'], 37)
        # 4. Its own certificate - going back, the one it had.
        if undo and undo.get('tls') is not None:
            if (store.get_meta('web:tls:' + me) or '') != undo['tls']:
                if undo['tls']:
                    store.set_meta('web:tls:' + me, undo['tls'])
                else:
                    store.db.run('DELETE FROM meta WHERE k = ?', ('web:tls:' + me,))
                _job_put(store, job, 'this node\'s certificate as it was before', 45)
        else:
            try:
                said = net_cert_again(store, w, by)
                if said:
                    _job_put(store, job, said, 45, ok='authority' not in said)
            except ValueError as e:
                _job_put(store, job, 'this node\'s certificate could not be made again: %s' % e,
                         45, ok=False)
        # 5. Out of the way: the web address to the other node.
        if many:
            if not (maintenance_row(store) or {}).get('on'):
                maintenance_set(store, True, 'the network is being changed', by)
                job['maint'] = True
            _job_put(store, job, 'maintenance on - the web address goes to the other node', 55)
            v = vip_conf(store)
            end = time.time() + 30
            while v.get('on') and vip_here(v.get('address')) and time.time() < end:
                time.sleep(1)
        # 6. The network, the name - and the reboot.
        job['down_at'] = time.time()
        job['wait_from'] = time.time()      # how long the restart is waited for (1.0.147)
        _job_put(store, job, 'NetworkManager, the host name and /etc/hosts', 70, state='rebooting')
        got = None
        if ask.get('rollback') and ask.get('snap'):
            try:
                got = net_root({'do': 'restore', 'snapshot': ask['snap'], 'reboot_in': 8}, 90)
            except ValueError as e:
                _job_put(store, job, 'what was kept could not be put back (%s) - the old '
                         'addresses are asked for instead' % e, 72, ok=False)
        if got is None:
            got = net_root({'do': 'apply', 'con': w['con'], 'ipv4': w['ipv4'],
                            'ipv6': {'mode': w['ipv6']['mode'] if w['ipv6']['on'] else 'off',
                                     'addr': w['ipv6']['addr'], 'gw': w['ipv6']['gw'],
                                     'dns': w['ipv6']['dns']},
                            'hostname': w['hostname'],
                            'old': [w['old_ip']] if w['old_ip'] else [],
                            'old_hostname': w['old_hostname'], 'reboot_in': 8,
                            'snapshot': job.get('snap') or '',
                            'rollback': bool(ask.get('rollback'))}, 90)
        job['before'] = got.get('before') or {}
        job['down_at'] = time.time() + 8
        _job_put(store, job, '; '.join(got.get('said') or []) or 'set', 80)
        _job_put(store, job, 'restarting %s - back in a minute or two at %s' % (
            me, w['new_ip']), 85)
    except Exception as e:                              # noqa: BLE001
        job['error'] = str(e)[:400]
        if job.get('state') == 'rebooting' and 'did not answer' in str(e):
            # Root may still put it in and restart (1.0.146): waited for, and
            # checked after the restart as any other - not left failed.
            _job_put(store, job, 'root did not answer in time - it may still put the network '
                     'in and restart; waiting for that', job.get('pct'), ok=False)
            return
        net_job_undo_told(daemon, job, by)
        if job.get('maint'):
            try:
                maintenance_set(store, False, '', by)
            except Exception:                           # noqa: BLE001
                pass
        _job_put(store, job, 'stopped: %s - nothing of the network was changed' % e
                 if job.get('state') != 'rebooting' else 'stopped: %s' % e, job.get('pct'),
                 ok=False, state='failed')
        store.add_event('settings', 'the new network of %s was not put in: %s' % (me, e),
                        'bad', who=by)


def net_job_after(daemon, job):
    """Back up after the reboot: is it what was asked, and is the cluster
    whole again."""
    store = daemon.store
    me = node_name()
    w = job.get('want') or {}
    by = '%s (network)' % (job.get('by') or 'otp')
    many = bool(CONFIG.get('ha_mode'))
    _job_put(store, job, '%s is back up' % me, 88)
    have = set(a for a in local_addresses() if not a.startswith('fe80'))
    if w.get('new_ip') and w['new_ip'] not in have:
        if job.get('trial_min') and job.get('back'):
            # Not even the address: back at once, not after the trial.
            _job_put(store, job, '%s came up without %s (it has %s)' % (
                me, w['new_ip'], ', '.join(sorted(have)) or 'none'), 90, ok=False)
            net_go_back(daemon, job, 'it came up without its new address')
            return
        _job_put(store, job, '%s came up without %s (it has %s) - look at its console; it stays '
                 'in maintenance' % (me, w['new_ip'], ', '.join(sorted(have)) or 'none'),
                 90, ok=False, state='failed')
        store.add_event('settings', '%s came up without its new address %s' % (me, w['new_ip']),
                        'bad', who=by)
        return
    words = ['%s is at %s' % (me, w.get('new_ip'))]
    if w.get('ipv6', {}).get('on'):
        six = [a for a in have if ':' in a]
        words.append('IPv6: %s' % (', '.join(six) or 'none yet'))
    if w.get('hostname') and socket.gethostname().split('.')[0] != w['hostname'].split('.')[0]:
        words.append('the host name is %s, not %s' % (socket.gethostname(), w['hostname']))
    _job_put(store, job, '; '.join(words), 90)
    try:
        net_publish(store)
    except Exception:                                   # noqa: BLE001
        pass
    if job.get('tell_after') and CONFIG.get('ha_mode') == 'replicated':
        d2, l2 = readdress_tell(str(CONFIG.get('ha_peer') or ''), w.get('new_ip') or '', by)
        _job_put(store, job, '; '.join(d2 + l2), 91, ok=not l2)
    if CONFIG.get('ha_mode') == 'replicated':
        hatls_check_soon()
        good = net_repl_wait(store, 240)
        _job_put(store, job, 'replication both ways: running' if good else
                 'replication is not running both ways yet - Settings → High availability '
                 'says why; the link between the databases puts itself right within minutes',
                 96, ok=good)
    if CONFIG.get('ha_mode') == 'replicated' and (hatls_want(store) or CONFIG.get('ha_tls')) \
            and not (hatls_want(store) or {}).get('off'):
        # The link between the databases encrypted and checked again for the
        # address the node has now (1.0.139) - both nodes' steps done, and this
        # node's certificate naming every address the other reaches it by.
        hatls_check_soon()
        end = time.time() + 300
        ok, said = False, ''
        while time.time() < end:
            ok, said = net_hatls_ok(store)
            if ok:
                break
            time.sleep(5)
        _job_put(store, job, 'the link between the databases: %s' % said, 97, ok=ok)
        if ok and not good:
            good = net_repl_wait(store, 120)
            _job_put(store, job, 'replication both ways: running' if good else
                     'replication is still not running both ways - Settings → High '
                     'availability says why', 97, ok=good)
    if many and vip_conf(store).get('on'):
        # keepalived set up for the new address (1.0.120): asked before the
        # restart it failed - the machine did not have the address yet - and a
        # failed request is asked again only when somebody says so.
        ok, said = net_vip_again(store)
        _job_put(store, job, 'the web address (keepalived) set up for %s: %s' % (
            w.get('new_ip') or me, said) if ok else 'the web address (keepalived) on this node: %s - '
            'Settings → High availability, Try again' % said, 97, ok=ok)
    if many and job.get('maint'):
        maintenance_set(store, False, '', by)
        _job_put(store, job, 'out of maintenance - the web address may come back', 98)
    if job.get('trial_min') and job.get('back'):
        net_trial_start(store, job, by)
        return
    _job_put(store, job, 'done', 100, state='done')
    store.add_event('settings', 'the network of %s is changed: %s' % (
        me, '; '.join(words)), 'warn', who=by)


def net_repl_wait(store, secs):
    """Replication running both ways within `secs`."""
    end = time.time() + secs
    while True:
        rep = ha_repl_state(store)
        inc = rep.get('incoming') or []
        outg = rep.get('outgoing') or []
        if inc and all(r.get('enabled') and r.get('running') for r in inc) and \
                outg and all(r.get('active') for r in outg):
            return True
        if time.time() >= end:
            return False
        time.sleep(5)


def net_hatls_ok(store):
    """(ok, words): the link between the databases encrypted and checked, on
    this node and the other."""
    st = hatls_state(store)
    if st.get('step') != 'done':
        return False, 'this node is at the step %s%s' % (
            st.get('step') or 'none', (' (%s)' % st['error'][:200]) if st.get('error') else '')
    pn = hatls_peer_name(store)
    peer = hatls_state(store, pn) if pn else {}
    if pn and peer.get('step') != 'done':
        return False, '%s is at the step %s' % (pn, peer.get('step') or 'none')
    if CONFIG.get('ha_tls') != 'verify-full':
        return False, 'the link is not set to verify-full'
    try:
        _end, sans = hatls_own_cert(store)
    except Exception as e:                              # noqa: BLE001
        return False, str(e)[:200]
    named = set(str(v).lower() for _k, v in sans)
    lack = [n for n in hatls_needs(store) if n.lower() not in named]
    if lack:
        return False, 'this node\'s certificate does not name %s yet' % ', '.join(lack)
    return True, 'encrypted and checked (verify-full) both ways; this node\'s certificate ' \
                 'names %s' % ', '.join(hatls_needs(store))


def _net_thread(fn, *args):
    def go():
        try:
            fn(*args)
        except Exception as e:                          # noqa: BLE001
            log('network: %s' % e, 'warn')
        finally:
            with NET_WORK_LOCK:
                NET_WORK['busy'] = False
    with NET_WORK_LOCK:
        if NET_WORK['busy']:
            return False
        NET_WORK['busy'] = True
    threading.Thread(target=go, name='otp-net', daemon=True).start()
    return True


NET_REBOOT_GIVE_UP_S = 3600


def net_job_stalled(daemon, job, by):
    store = daemon.store
    net_job_undo_told(daemon, job, by)
    if job.get('maint'):
        try:
            maintenance_set(store, False, '', by)
        except Exception:                               # noqa: BLE001
            pass
    _job_put(store, job, 'it stopped half way (the service restarted?)%s' % (
        ' - out of maintenance' if job.get('maint') else ''), job.get('pct'),
        ok=False, state='failed')


def net_job_give_up(daemon, job):
    """A restart waited for an hour that never came (1.0.147). Where the new
    address is on the machine all the same, it is checked as after a
    restart; where it is not, the other node gets this one's address back,
    maintenance ends and the job is failed."""
    w = job.get('want') or {}
    new_ip = str(w.get('new_ip') or '')
    if new_ip and new_ip in set(local_addresses()):
        net_job_after(daemon, job)
        return
    by = '%s (network)' % (job.get('by') or 'otp')
    store = daemon.store
    net_job_undo_told(daemon, job, by)
    if job.get('maint'):
        try:
            maintenance_set(store, False, '', by)
        except Exception:                               # noqa: BLE001
            pass
    _job_put(store, job, 'the machine did not restart in an hour and the new address is not '
             'on it: the other node was given this one\'s address back%s' % (
                 ' and maintenance ended' if job.get('maint') else ''), job.get('pct'),
             ok=False, state='failed')
    store.add_event('settings', 'the new network of %s was not put in: no restart in an hour'
                    % node_name(), 'bad', who=by)


def net_tick(daemon):
    """Every few seconds: something asked of this node, a job to finish after
    a reboot, the network said again now and then."""
    if HA_REBUILDING.is_set() or not WEB_DIR.is_dir():
        return
    store = daemon.store
    me = node_name()
    job = _meta_json(store, 'net:job:' + me)
    ask = _meta_json(store, 'net:want:' + me)
    if job and job.get('state') == 'trial':
        net_trial_tick(daemon, job)
        return
    if job and job.get('state') == 'rebooting':
        late = time.time() - float(job.get('wait_from') or job.get('moved') or 0)
        if boot_time() > float(job.get('boot') or 0) + 1:
            _net_thread(net_job_after, daemon, job)
        elif late > NET_REBOOT_GIVE_UP_S:
            # Not for ever (1.0.147): no restart in an hour, and nothing else
            # of the network, the restart or power off went on meanwhile.
            _net_thread(net_job_give_up, daemon, job)
        elif late > 900 and not job.get('late_said'):
            # Still waited for (1.0.146): marked failed, the restart by hand
            # was never followed - no check, no trial, maintenance left on.
            job['late_said'] = True
            _job_put(store, job, 'the machine did not restart in 15 minutes - restart it by '
                     'hand; the network starts as set, and is checked when it is back',
                     job.get('pct'), ok=False)
        return
    if ask and ask.get('node') == me and (not job or job.get('id') != ask.get('id')) and \
            time.time() - float(ask.get('at') or 0) < 600:
        _net_thread(net_job_run, daemon, ask)
        return
    if job and job.get('state') == 'running' and not NET_WORK['busy'] and \
            time.time() - float(job.get('moved') or 0) > 300:
        by = '%s (network)' % (job.get('by') or 'otp')
        if job.get('down_at'):
            # Root was asked already: it may restart with the new network - then
            # it is checked as after any restart (1.0.146).
            job['wait_from'] = time.time()
            _job_put(store, job, 'it stopped while root put the network in (the service '
                     'restarted?) - waiting for the restart', job.get('pct'), ok=False,
                     state='rebooting')
            return
        # On the network's own thread (1.0.147): telling the other node
        # waits for its database.
        _net_thread(net_job_stalled, daemon, job, by)
        return
    if power_tick(daemon):
        return
    wanted = float(store.get_meta('net:read:' + me) or 0)
    if time.time() - NET_WORK['read_at'] > NET_READ_S or wanted > NET_WORK['read_at']:
        _net_thread(net_publish, store)


# ---- restart and power off ------------------------------------------------------------
POWER_LIVE_S = 1800


def power_plan(store):
    return _meta_json(store, 'power:plan') or {}


def power_busy(store):
    p = power_plan(store)
    if not p or time.time() - float(p.get('at') or 0) > POWER_LIVE_S:
        return False
    for n in p.get('targets') or []:
        row = _meta_json(store, 'power:node:' + n) or {}
        if row.get('id') != p.get('id') or row.get('state') in ('asked', 'going'):
            if p.get('how') == 'poweroff' and row.get('state') == 'going':
                continue
            return True
    return False


def power_ask(store, how, targets, order, by):
    if how not in ('reboot', 'poweroff'):
        raise ValueError('reboot or poweroff')
    known = [node_name()] + [n['name'] for n in ha_nodes(store) if n['name'] != node_name()]
    targets = [t for t in known if t in (targets or [])]
    if not targets:
        raise ValueError('which node?')
    if order not in ('one', 'rolling', 'together'):
        order = 'one' if len(targets) == 1 else 'rolling'
    if how == 'poweroff' and order == 'rolling':
        order = 'together'
    if power_busy(store):
        raise ValueError('a restart or a power-off is under way already')
    for t in targets:
        if net_job_active(_meta_json(store, 'net:job:' + t)):
            raise ValueError('%s is changing its network' % t)
    if order == 'rolling':
        # The node this page is not on last: the page stays with the other
        # while the first restarts.
        targets.sort(key=lambda n: n == node_name())
    plan = {'id': secrets.token_hex(6), 'how': how, 'targets': targets, 'order': order,
            'by': by, 'at': time.time(), 'from': node_name()}
    store.set_meta('power:plan', json.dumps(plan))
    store.add_event('starting and stopping', '%s asked for a %s of %s%s' % (
        by, 'restart' if how == 'reboot' else 'power-off', ', '.join(targets),
        ' one after the other' if order == 'rolling' and len(targets) > 1 else
        (' at once' if len(targets) > 1 else '')), 'warn', who=by)
    return plan


def _power_put(store, row, state, words=''):
    row.update(state=state, moved=time.time())
    if words:
        row['said'] = str(words)[:300]
    store.set_meta('power:node:' + node_name(), json.dumps(row))


def power_go(daemon, plan):
    store = daemon.store
    row = {'id': plan['id'], 'how': plan['how'], 'at': time.time(), 'boot': boot_time()}
    try:
        many = bool(CONFIG.get('ha_mode'))
        if many and plan.get('order') != 'together' and not (maintenance_row(store) or {}).get('on'):
            maintenance_set(store, True, 'a %s asked by %s' % (
                'restart' if plan['how'] == 'reboot' else 'power-off', plan.get('by')),
                plan.get('by') or '')
            row['maint'] = True
            v = vip_conf(store)
            end = time.time() + 20
            while v.get('on') and vip_here(v.get('address')) and time.time() < end:
                time.sleep(1)
        row['down_at'] = time.time() + 5
        _power_put(store, row, 'going', 'going down')
        net_root({'do': 'power', 'how': plan['how'], 'in': 5}, 30)
        log('starting and stopping: %s in 5 s, asked by %s' % (plan['how'], plan.get('by')),
            'warn')
    except Exception as e:                              # noqa: BLE001
        if row.get('maint'):
            try:
                maintenance_set(store, False, '', plan.get('by') or '')
            except Exception:                           # noqa: BLE001
                pass
        _power_put(store, row, 'failed', str(e))


def power_back(daemon, row):
    store = daemon.store
    if row.get('maint'):
        maintenance_set(store, False, '', 'after the restart')
    _power_put(store, row, 'back', 'up again')
    store.add_event('starting and stopping', '%s is up again after the restart' % node_name())


def power_tick(daemon):
    """This node's part of a restart or power-off: its turn, and after it."""
    store = daemon.store
    me = node_name()
    plan = power_plan(store)
    row = _meta_json(store, 'power:node:' + me) or {}
    if row.get('state') == 'going' and row.get('how') == 'reboot':
        if boot_time() > float(row.get('boot') or 0) + 1:
            _net_thread(power_back, daemon, row)
            return True
        if time.time() - float(row.get('moved') or 0) > 900:
            _power_put(store, row, 'failed', 'it did not restart in 15 minutes')
        return False
    if not plan or me not in (plan.get('targets') or []) or row.get('id') == plan.get('id'):
        return False
    if time.time() - float(plan.get('at') or 0) > POWER_LIVE_S:
        return False
    if plan.get('order') == 'rolling':
        for t in plan['targets']:
            if t == me:
                break
            other = _meta_json(store, 'power:node:' + t) or {}
            if other.get('id') != plan['id'] or other.get('state') not in ('back', 'failed'):
                return False                # not my turn yet
    _net_thread(power_go, daemon, plan)
    return True


def power_view(store):
    plan = power_plan(store)
    nodes = []
    hb = {n['name']: n for n in ha_nodes(store)}
    names = [node_name()] + [n for n in hb if n != node_name()]
    for n in names:
        b = hb.get(n) or {}
        row = _meta_json(store, 'power:node:' + n) or {}
        nodes.append({'name': n, 'me': n == node_name(), 'alive': bool(b.get('alive', True)
                                                                      if n == node_name() else
                                                                      b.get('alive')),
                      'started': b.get('started'), 'age': b.get('age'),
                      'address': b.get('address') or '', 'version': b.get('version') or '',
                      'row': row if row.get('id') == plan.get('id') else {}})
    # Hidden from the page by whoever pressed Hide this (1.0.123).
    seen = store.get_meta('power:seen') == str(plan.get('id') or '')
    return {'plan': plan if plan and not seen and time.time() - float(plan.get('at') or 0) < POWER_LIVE_S
            else {}, 'nodes': nodes, 'now': time.time(), 'cluster': len(nodes) > 1,
            'busy': power_busy(store)}


def net_vip_again(store, wait=120):
    """This node's part of the web address asked of root again, and waited
    for."""
    h = web_hash(web_desired(store))
    st = web_status()
    if st.get('hash') == h and st.get('state') == 'done':
        return True, 'as it was'
    store.set_meta('web:retry:' + node_name(), repr(time.time()))
    end = time.time() + wait
    while time.time() < end:
        st = web_status()
        if st.get('hash') == h and float(st.get('at') or 0) > 0 and \
                st.get('state') in ('done', 'failed'):
            if st.get('state') == 'done':
                return True, 'in place'
            if float(store.get_meta('web:retry:' + node_name()) or 0) <= float(st.get('at') or 0):
                said = st.get('said') or ['failed']
                return False, ('; '.join(said) if isinstance(said, list) else str(said))[:300]
        time.sleep(3)
    return False, 'root had not said yet'


def net_view(store):
    hb = {n['name']: n for n in ha_nodes(store)}
    names = [node_name()] + sorted(n for n in hb if n != node_name())
    out = []
    for n in names:
        b = hb.get(n) or {}
        job = _meta_json(store, 'net:job:' + n) or {}
        # A finished change is shown until somebody hides it (1.0.120), or for
        # 6 hours when it went through, a day when it did not.
        if job and job.get('state') in ('done', 'failed'):
            keep = 6 * 3600 if job.get('state') == 'done' else 86400
            if store.get_meta('net:seen:' + n) == str(job.get('id')) or \
                    time.time() - float(job.get('moved') or job.get('at') or 0) > keep:
                job = {}
        out.append({'name': n, 'me': n == node_name(),
                    'alive': True if n == node_name() else bool(b.get('alive')),
                    'address': b.get('address') or '', 'now': net_node_now(store, n),
                    'job': job if job and time.time() - float(job.get('moved') or 0) < 86400
                    else {}})
    v = vip_conf(store)
    return {'nodes': out, 'cluster': len(out) > 1, 'now': time.time(),
            'vip': {'on': bool(v.get('on')), 'address': v.get('address') or '',
                    'address6': v.get('address6') or ''} if CONFIG.get('ha_mode') else {}}
# ---- changes that could cut the server off: kept, or taken back (1.0.137) -------------
# A node's new network and a change of the firewall (or of who may reach the
# pages) are put in on trial: unless somebody presses Keep it - on the pages
# of either node, `otp --change-keep`, or the console - within net_confirm_min
# / fw_confirm_min minutes, what was there before comes back by itself. A typo
# in a gateway, a prefix, or a DROP rule in front of SSH no longer leaves the
# machine to be put right at its console.
#
# The network: the node keeps what it had (its NetworkManager settings, its
# host name) in its job; back up after the reboot the job waits as 'trial'.
# Not kept in time - or come up without the new address at all - the node
# asks itself for the old network, which is the same job the other way round
# (a reboot, the other node told the old address again). So that the other
# node can still be told, its pg_hba.conf keeps letting the old address in
# while the new one is on trial; kept, it lets only the new one in again.
# Who asks to keep or to go back writes 'net:keep:NODE' / 'net:back:NODE'; the
# node itself writes its job, as before.
#
# The firewall: what was set before the first change of a trial is kept in
# 'fw:trial'; later changes in the same trial move its deadline on. Not kept in
# time, one node (claim_once) puts it back; every node puts that in as usual.

def net_back_want(now):
    """What the node has now, as a request for the network page would say it -
    what it goes back to. None (and why) where it cannot be said so. The root
    helper keeps the network itself whole as well (1.0.139) and puts that back;
    this is what the other node is told, and what is asked where nothing was
    kept."""
    d = (now or {}).get('data') or {}
    conf = d.get('conf') or {}
    live = d.get('live') or {}
    addr = net_current_ip(now or {})
    if not addr or '/' not in addr:
        return None, 'what the node has now could not be read (%s) - it cannot be put back ' \
                     'by itself' % (conf.get('ipv4_method') or '?')
    m6 = conf.get('ipv6_method')
    on6 = m6 not in (None, '', 'disabled', 'ignore')
    manual = conf.get('ipv4_method') == 'manual'
    return {'con': d.get('con') or '',
            'ipv4': {'addr': addr, 'gw': conf.get('ipv4_gateway') or ('' if manual else
                                                                       live.get('gw4') or ''),
                     'dns': list(conf.get('ipv4_dns') or [x for x in live.get('dns') or []
                                                          if ':' not in x][:4]),
                     'search': list(conf.get('ipv4_search') or [])},
            'ipv6': {'on': on6, 'mode': 'manual' if m6 == 'manual' else 'auto',
                     'addr': (conf.get('ipv6_addresses') or [''])[0] if m6 == 'manual' else '',
                     'gw': conf.get('ipv6_gateway') or '', 'dns': list(conf.get('ipv6_dns') or [])},
            'hostname': str(d.get('hostname') or ''), 'vip_elsewhere': True}, ''


def net_trial_min():
    return int(CONFIG.get('net_confirm_min') or 0)


def net_trial_start(store, job, by):
    """Back up after the reboot, all well: the job waits to be kept."""
    n = int(job.get('trial_min') or 0)
    job['trial_until'] = time.time() + n * 60
    _job_put(store, job, 'it waits to be kept: Keep it within %d min (Settings - Network, '
             'the banner on every page, or  otp --change-keep net --node %s), or the old '
             'network comes back by itself at %s' % (
                 n, node_name(), time.strftime('%H:%M', time.localtime(job['trial_until']))),
             99, state='trial')
    store.add_event('settings', 'the new network of %s is on trial: kept within %d min, or it '
                    'goes back to %s' % (node_name(), n, (job.get('want') or {}).get('old_ip')),
                    'warn', who=by)


def net_go_back(daemon, job, why):
    """The old network asked for, on this node - the same job the other way."""
    store = daemon.store
    me = node_name()
    back = job.get('back')
    job['back_asked'] = time.time()
    if not back:
        _job_put(store, job, 'not kept (%s), and it cannot go back by itself: %s' % (
            why, job.get('back_why') or '?'), job.get('pct'), ok=False, state='failed')
        return
    # The network as it is now read first: going back is planned from what
    # the node has (the new address), so the other node is told the old one.
    try:
        net_publish(store)
    except Exception as e:                              # noqa: BLE001
        log('network: read before going back: %s' % e, 'warn')
    _job_put(store, job, 'not kept: %s - the old network (%s) comes back' % (
        why, (back.get('ipv4') or {}).get('addr')), job.get('pct'), ok=False,
        state='going back')
    try:
        net_ask(store, me, back, 'otp (%s)' % why, rollback=True, maint=bool(job.get('maint')),
                snap=job.get('snap') or '')
    except Exception as e:                              # noqa: BLE001
        _job_put(store, job, 'the old network could not be asked for: %s' % e, job.get('pct'),
                 ok=False, state='failed')
        store.add_event('settings', 'the old network of %s could not be put back: %s' % (me, e),
                        'bad')


def net_trial_tick(daemon, job):
    """A job on trial: kept, asked to go back, or out of time."""
    store = daemon.store
    me = node_name()
    keep = _meta_json(store, 'net:keep:' + me) or {}
    back = _meta_json(store, 'net:back:' + me) or {}
    if keep.get('id') == job.get('id'):
        job['kept'] = keep.get('by')
        _job_put(store, job, 'kept by %s' % keep.get('by'), 100, state='done')
        store.add_event('settings', '%s kept the new network of %s' % (keep.get('by'), me),
                        who=keep.get('by'))
        w = job.get('want') or {}
        if job.get('keep_old') and w.get('old_ip') and w.get('new_ip'):
            # The other node may let only the new address in again.
            store.set_meta('readdress:dropold:' + me, json.dumps({
                'id': job.get('id'), 'from': me, 'old': w['old_ip'], 'new': w['new_ip'],
                'at': time.time()}))
        return
    if back.get('id') == job.get('id'):
        net_go_back(daemon, job, 'put back by %s' % back.get('by'))
        return
    if time.time() > float(job.get('trial_until') or 0):
        net_go_back(daemon, job, 'not kept within %d min' % int(job.get('trial_min') or 0))


def net_trial_answer(store, node, act, by):
    """The pages (of either node) or the command line: keep it, or go back."""
    job = _meta_json(store, 'net:job:' + node) or {}
    if job.get('state') != 'trial':
        raise ValueError('the network of %s is not waiting to be kept' % node)
    store.set_meta('net:%s:%s' % ('keep' if act == 'keep' else 'back', node),
                   json.dumps({'id': job.get('id'), 'by': by, 'at': time.time()}))
    return ('kept - %s says so within a few seconds' % node if act == 'keep' else
            'the old network comes back - %s restarts with it' % node)


def readdress_dropold_tick(store):
    """The other node's new address kept: its old one no longer let in."""
    me = node_name()
    for r in store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'readdress:dropold:%'"):
        try:
            ask = json.loads(r['v'] or '{}')
        except ValueError:
            continue
        if not isinstance(ask, dict) or ask.get('from') in (me, None):
            continue
        done_key = 'readdress:dropold:done:' + me
        if (store.get_meta(done_key) or '') == str(ask.get('id')):
            continue
        try:
            said = _readdress_hba(ask['old'], ask['new'], False, drop_old=True)
            log('the other node kept its new address %s: %s' % (ask['new'], said), 'info')
        except Exception as e:                          # noqa: BLE001
            log('the old address of the other node could not be taken out of pg_hba.conf: %s'
                % e, 'warn')
        store.set_meta(done_key, str(ask.get('id')))


# ---- the firewall --------------------------------------------------------------------
def fw_trial_min():
    return int(CONFIG.get('fw_confirm_min') or 0)


def fw_trial_begin(store, by):
    """Before a change of the firewall or of who may reach the pages: what is
    there now kept, for going back to."""
    n = fw_trial_min()
    if not n:
        return None
    t = time.time()
    trial = _meta_json(store, 'fw:trial') or {}
    if not trial or trial.get('done'):
        trial = {'id': secrets.token_hex(6), 'was': fw_conf(store),
                 'access': access_conf(store), 'at': t, 'by': by}
    trial.update(until=t + n * 60, last_by=by, min=n)
    store.set_meta('fw:trial', json.dumps(trial))
    # The key the put-back is claimed by made now, by this node alone (1.0.139):
    # made by both at the moment it ran out, it came over to each as a second
    # row with the same key, and replication stopped.
    if store.get_meta('fw_trial_back') is None:
        store.set_meta('fw_trial_back', '')
    return trial


def fw_trial_answer(store, act, by):
    trial = _meta_json(store, 'fw:trial') or {}
    if not trial or trial.get('done'):
        raise ValueError('no change of the firewall waits to be kept')
    if act == 'keep':
        trial.update(done='kept', done_by=by, done_at=time.time())
        store.set_meta('fw:trial', json.dumps(trial))
        store.add_event('settings', '%s kept the change of the firewall and access' % by,
                        who=by)
        return 'kept'
    fw_put_back(store, trial, 'put back by %s' % by)
    return 'what was there before comes back - each node puts it in within a few seconds'


def fw_put_back(store, trial, why):
    was = trial.get('was') or {}
    # Put back as something said (1.0.146): a firewall never set before went
    # back as "not set", which root reads as "leave it as it is" - and the
    # rules of the trial stayed; so did the lists of who may reach the pages.
    store.set_meta('fw:conf', json.dumps(dict(was, set=True, at=time.time(),
                                              by='otp (%s)' % why)))
    store.set_meta('web:access', json.dumps(trial.get('access') or {
        k: {'any': True, 'from': []} for k in ACCESS_WORDS}))
    trial.update(done='back', done_by=why, done_at=time.time())
    store.set_meta('fw:trial', json.dumps(trial))
    store.add_event('settings', 'the firewall and access went back to what they were before '
                    '%s: %s' % (time.strftime('%H:%M', time.localtime(trial.get('at') or 0)),
                                why), 'warn')
    log('the firewall went back: %s' % why, 'warn')


def fw_trial_tick(store):
    trial = _meta_json(store, 'fw:trial') or {}
    if not trial or trial.get('done') or time.time() <= float(trial.get('until') or 0):
        return
    # One node puts it back (both would write the same rows at once).
    if claim_once(store, 'fw_trial_back', trial.get('id')):
        fw_put_back(store, trial, 'not kept within %d min' % int(trial.get('min') or 0))


def trials_view(store):
    """What waits to be kept, for the banner of every page and --status."""
    out = []
    t = time.time()
    for r in store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'net:job:%'"):
        try:
            job = json.loads(r['v'] or '{}')
        except ValueError:
            continue
        if isinstance(job, dict) and job.get('state') == 'trial':
            w = job.get('want') or {}
            out.append({'kind': 'net', 'node': job.get('node') or r['k'][8:],
                        'until': float(job.get('trial_until') or 0), 'by': job.get('by'),
                        'words': 'the new network of %s (%s)' % (
                            job.get('node') or r['k'][8:], w.get('new_ip') or '?'),
                        'back': (w.get('old_ip') or '')})
    trial = _meta_json(store, 'fw:trial') or {}
    if trial and not trial.get('done') and float(trial.get('until') or 0) > t - 60:
        out.append({'kind': 'fw', 'node': '', 'until': float(trial.get('until') or 0),
                    'by': trial.get('last_by') or trial.get('by'),
                    'words': 'the change of the firewall and access', 'back': ''})
    return out


def trial_problem_words(trials):
    return ['%s waits to be kept: %d min left, then it goes back by itself (Keep it on the '
            'banner, or  otp --change-keep %s%s)' % (
                x['words'], max(0, int((x['until'] - time.time()) // 60)), x['kind'],
                (' --node %s' % x['node']) if x.get('node') else '') for x in trials]
# ---- the time: chrony on every node (1.0.120) ----------------------------------------
# Codes from the app are worked out from the clock: a node whose clock is off by
# more than half a period refuses codes that are right. Settings → Time shows
# each node's clock as chrony sees it (offset, stratum, its sources) and sets
# the time servers for the whole cluster: kept in meta 'ntp:conf', put in by
# each node's root helper when it changes ('ntp:applied:NODE'), and in a
# cluster each node also takes the other as one more source.
NTP_READ_S = 60
NTP_WORK = {'busy': False, 'read_at': 0.0, 'last': {}}
NTP_WORK_LOCK = threading.Lock()
NTP_DEFAULT = {'manage': False, 'servers': [], 'peers': True, 'allow': [],
               'makestep': [1.0, 3], 'minsources': 1, 'timezone': ''}


def root_ask(ask_name, answer_name, data, wait=60):
    ask_id = secrets.token_hex(8)
    data = dict(data, id=ask_id)
    tmp = WEB_DIR / ('.%s.%d.%d' % (ask_name, os.getpid(), threading.get_ident() % 100000))
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_TRUNC | os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, 'w') as f:
        f.write(json.dumps(data))
    os.replace(str(tmp), str(WEB_DIR / ask_name))
    end = time.time() + wait
    while time.time() < end:
        try:
            got = json.loads((WEB_DIR / answer_name).read_text())
        except (OSError, ValueError):
            got = None
        if isinstance(got, dict) and got.get('id') == ask_id:
            if not got.get('ok'):
                raise ValueError(got.get('said') or 'the root helper said no')
            return got.get('data') or {}
        time.sleep(0.4)
    raise ValueError('the root helper of this node did not answer in %d s - is otp-web.path '
                     'running?  systemctl status otp-web.path' % wait)


def ntp_conf(store):
    c = dict(NTP_DEFAULT)
    c.update(_meta_json(store, 'ntp:conf') or {})
    return c


def ntp_desired(store):
    c = ntp_conf(store)
    peers = []
    if c.get('manage') and c.get('peers') and CONFIG.get('ha_mode') and CONFIG.get('ha_peer'):
        try:
            peers = [str(ipaddress.ip_address(str(CONFIG['ha_peer'])))]
        except ValueError:
            peers = []
    return {'manage': bool(c.get('manage')), 'servers': c.get('servers') or [],
            'peers': peers, 'allow': c.get('allow') or [],
            'makestep': c.get('makestep') or [1.0, 3], 'minsources': c.get('minsources') or 1,
            'timezone': c.get('timezone') or ''}


def ntp_checked(b):
    """The settings from the page, made whole - the root helper checks them
    again."""
    out = dict(NTP_DEFAULT)
    out['manage'] = bool(b.get('manage'))
    servers = []
    for x in (b.get('servers') or [])[:12]:
        if not isinstance(x, dict):
            continue
        host = str(x.get('host') or '').strip().lower().rstrip('.')
        if not host:
            continue
        try:
            host = str(ipaddress.ip_address(host))
        except ValueError:
            if not re.match(r'^(?=.{1,253}$)[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?'
                            r'(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)*$', host):
                raise ValueError('%r is not a host name or an address' % host)
        servers.append({'host': host, 'pool': bool(x.get('pool')),
                        'iburst': bool(x.get('iburst', True)), 'prefer': bool(x.get('prefer')),
                        'nts': bool(x.get('nts'))})
    if out['manage'] and not servers:
        raise ValueError('at least one time server - or let the machines keep their own')
    out['servers'] = servers
    out['peers'] = bool(b.get('peers', True))
    allow = []
    for a in re.split(r'[\s,;]+', b.get('allow') if isinstance(b.get('allow'), str)
                      else ' '.join(b.get('allow') or [])):
        if not a:
            continue
        try:
            allow.append(str(ipaddress.ip_network(a, strict=False)))
        except ValueError:
            raise ValueError('%r is not a network (192.0.2.0/24)' % a)
    out['allow'] = allow[:20]
    try:
        th = float(b.get('step_s', 1.0))
        lim = int(b.get('step_n', 3))
    except (TypeError, ValueError):
        raise ValueError('the step: seconds, and how many updates')
    if not (0.001 <= th <= 3600) or not (-1 <= lim <= 1000):
        raise ValueError('the step: 0.001 to 3600 s; -1 (always) to 1000 updates')
    out['makestep'] = [th, lim]
    try:
        out['minsources'] = max(1, min(10, int(b.get('minsources') or 1)))
    except (TypeError, ValueError):
        raise ValueError('how many sources have to agree is a number')
    tz = str(b.get('timezone') or '').strip()
    if tz and not re.match(r'^[A-Za-z0-9_+-]{1,40}(/[A-Za-z0-9_+-]{1,40}){0,3}\Z', tz):
        raise ValueError('%r is not a time zone' % tz)
    out['timezone'] = tz
    return out


def ntp_save(store, b, by):
    c = ntp_checked(b)
    c.update(at=time.time(), by=by)
    store.set_meta('ntp:conf', json.dumps(c))
    what = ('the servers %s%s' % (', '.join(x['host'] for x in c['servers']),
                                  '; the nodes take each other too' if c['peers'] and
                                  CONFIG.get('ha_mode') else '')) if c['manage'] \
        else 'each machine keeps its own servers'
    if c['timezone']:
        what += '; time zone %s' % c['timezone']
    store.add_event('settings', '%s set the time: %s' % (by, what), 'warn', who=by)
    return c


def ntp_publish(store, zones=False):
    data = root_ask('ntp.ask', 'ntp.json', {'do': 'read', 'zones': zones}, 30)
    now = {'at': time.time(), 'data': {k: v for k, v in data.items() if k != 'zones'}}
    store.set_meta('ntp:now:' + node_name(), json.dumps(now))
    NTP_WORK['read_at'] = time.time()
    NTP_WORK['last'] = now
    if zones and data.get('zones'):
        store.set_meta('ntp:zones', json.dumps(data['zones']))
    return now


def ntp_apply(store):
    want = ntp_desired(store)
    h = hashlib.sha256(json.dumps(want, sort_keys=True).encode()).hexdigest()[:24]
    row = {'hash': h, 'at': time.time()}
    try:
        got = root_ask('ntp.ask', 'ntp.json', dict(want, do='apply'), 300)
        row.update(ok=True, said='; '.join(got.get('said') or []) or 'as it was')
        log('the time: %s' % row['said'])
    except ValueError as e:
        row.update(ok=False, said=str(e)[:300])
        log('the time servers could not be set: %s' % e, 'warn')
    store.set_meta('ntp:applied:' + node_name(), json.dumps(row))
    try:
        ntp_publish(store)
    except Exception:                                   # noqa: BLE001
        pass


def _ntp_thread(fn, *args):
    def go():
        try:
            fn(*args)
        except Exception as e:                          # noqa: BLE001
            log('the time: %s' % e, 'warn')
        finally:
            with NTP_WORK_LOCK:
                NTP_WORK['busy'] = False
    with NTP_WORK_LOCK:
        if NTP_WORK['busy']:
            return False
        NTP_WORK['busy'] = True
    threading.Thread(target=go, name='otp-ntp', daemon=True).start()
    return True


def ntp_sync(store):
    got = root_ask('ntp.ask', 'ntp.json', {'do': 'sync'}, 60)
    store.add_event('settings', '%s: the clock stepped to the time servers now (%s)' % (
        node_name(), '; '.join(got.get('said') or [])), 'warn')
    time.sleep(3)
    ntp_publish(store)


def ntp_tick(daemon):
    if HA_REBUILDING.is_set() or not WEB_DIR.is_dir():
        return
    store = daemon.store
    me = node_name()
    if NTP_WORK['busy']:
        return
    conf = _meta_json(store, 'ntp:conf')
    if conf:
        want = ntp_desired(store)
        h = hashlib.sha256(json.dumps(want, sort_keys=True).encode()).hexdigest()[:24]
        done = _meta_json(store, 'ntp:applied:' + me) or {}
        if done.get('hash') != h and time.time() - float(done.get('at') or 0) > 30:
            _ntp_thread(ntp_apply, store)
            return
    sync_at = float(store.get_meta('ntp:sync:' + me) or 0)
    if sync_at > float(NTP_WORK.get('synced') or 0) and time.time() - sync_at < 300:
        NTP_WORK['synced'] = sync_at
        _ntp_thread(ntp_sync, store)
        return
    wanted = float(store.get_meta('ntp:read:' + me) or 0)
    if time.time() - NTP_WORK['read_at'] > NTP_READ_S or wanted > NTP_WORK['read_at']:
        _ntp_thread(ntp_publish, store, wanted > NTP_WORK['read_at'] or
                    not store.get_meta('ntp:zones'))


def ntp_problem():
    """Words for the status when this node's clock is not to be trusted."""
    now = NTP_WORK.get('last') or {}
    d = now.get('data') or {}
    if not d or time.time() - float(now.get('at') or 0) > 600:
        return ''
    t = d.get('tracking') or {}
    if d.get('chrony') and t:
        if t.get('leap') == 'Not synchronised' or not t.get('stratum'):
            return ('the clock is not synchronised to a time server (chrony) - codes from the '
                    'app are worked out from it: Settings → Time')
        if abs(float(t.get('offset') or 0)) > 1.0:
            return ('the clock is %.1f s off the time servers - codes from the app are worked '
                    'out from it: Settings → Time' % abs(float(t['offset'])))
    elif d.get('ntpsynchronized') == 'no':
        return 'the clock is not synchronised (timedatectl): Settings → Time'
    return ''


def ntp_view(store):
    hb = {n['name']: n for n in ha_nodes(store)}
    names = [node_name()] + sorted(n for n in hb if n != node_name())
    nodes = []
    for n in names:
        nodes.append({'name': n, 'me': n == node_name(),
                      'alive': True if n == node_name() else bool((hb.get(n) or {}).get('alive')),
                      'now': _meta_json(store, 'ntp:now:' + n) or {},
                      'applied': _meta_json(store, 'ntp:applied:' + n) or {}})
    try:
        zones = json.loads(store.get_meta('ntp:zones') or '[]')
    except ValueError:
        zones = []
    conf = ntp_conf(store)
    want = ntp_desired(store)
    h = hashlib.sha256(json.dumps(want, sort_keys=True).encode()).hexdigest()[:24]
    return {'nodes': nodes, 'conf': conf, 'zones': zones, 'cluster': len(nodes) > 1,
            'hash': h if _meta_json(store, 'ntp:conf') else '', 'now': time.time()}


# ---------------------------------------------------------------------------
# From opt to otp (1.0.37): the database's own names
# ---------------------------------------------------------------------------
# Until 1.0.37 this program was called opt, and so were the database and the
# account it made, and its replication. install.sh --upgrade moves the files,
# folders and system accounts; this (otp --rename-from-opt, as root) does the
# databases on this machine:
#
#   * PostgreSQL here: the database opt and the account opt are renamed otp,
#     and pg_hba.conf with them;
#   * MariaDB here: the tables are moved into a database otp, the account is
#     renamed and given that database;
#   * replicated: the publication, this node's subscription, and the slot on
#     this node with the other node's subscription to it - renamed without a
#     row lost: the other node's subscription is paused, the slot copied
#     under its new name at the same place, the subscription pointed at it
#     (and at the renamed database and account), resumed, and the old slot
#     dropped. Whichever node goes first, the second finishes the job.
#
# A database on another machine is left as it is (that takes its own
# administrator): its names are written into config.json, so nothing breaks.
RENAME_OLD, RENAME_NEW = 'opt', 'otp'


def _local_host(c):
    h = str(c.get('db_host') or '').strip()
    return h in ('', '127.0.0.1', 'localhost', '::1') or h.startswith('/')


def _pg_hba_rename(port, say):
    """'opt' as a database or an account in pg_hba.conf becomes 'otp'."""
    path = pg_admin('SHOW hba_file', port)
    try:
        lines = Path(path).read_text().splitlines(True)
    except OSError as e:
        say('pg_hba.conf could not be read (%s): look at it by hand' % e)
        return
    out, changed = [], 0
    for line in lines:
        bare = line.split('#', 1)[0]
        bits = bare.split()
        if bits and bits[0] in ('local', 'host', 'hostssl', 'hostnossl', 'hostgssenc',
                                'hostnogssenc') and len(bits) >= 3:
            def fix(field):
                return ','.join(RENAME_NEW if x == RENAME_OLD else x for x in field.split(','))
            db_f, user_f = fix(bits[1]), fix(bits[2])
            if (db_f, user_f) != (bits[1], bits[2]):
                rest = line[len(line) - len(line.lstrip()):]
                head = line[:len(line) - len(rest)]
                parts = re.split(r'(\s+)', rest)
                # parts: word, space, word, space, word, ... - fields 1 and 2
                words = [i for i, p in enumerate(parts) if p and not p.isspace()]
                parts[words[1]], parts[words[2]] = db_f, user_f
                line = head + ''.join(parts)
                changed += 1
        out.append(line)
    if changed:
        shutil.copy2(path, path + '.before-otp')
        Path(path).write_text(''.join(out))
        pg_admin('SELECT pg_reload_conf()', port)
        say('pg_hba.conf: %d line(s) now name otp (the old one is %s.before-otp)'
            % (changed, path))


def _pg_rename_local(c, say, new=None):
    port = int(c.get('db_port') or 5432)
    name, user = str(c.get('db_name') or RENAME_OLD), str(c.get('db_user') or RENAME_OLD)
    # Names this goes on to put into SQL run as root (1.0.101): a config file
    # the otp group may write is no place to take anything else from.
    for what, v in (('db_name', name), ('db_user', user)):
        if not DB_IDENT.fullmatch(v):
            raise ValueError('%s in %s is not a plain name: %r' % (what, CONFIG_FILE, v))
    # Each rename written down as it is done (1.0.59): one that fails half
    # way still leaves the names that changed in the caller's hands.
    new = {} if new is None else new
    before = dict(new)

    def exists(sql):
        return pg_admin(sql, port) == '1'
    if name == RENAME_OLD:
        if exists("SELECT 1 FROM pg_database WHERE datname = '%s'" % RENAME_NEW):
            say('PostgreSQL already has a database otp: the database opt keeps its name')
        elif exists("SELECT 1 FROM pg_database WHERE datname = '%s'" % RENAME_OLD):
            pg_admin("SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = "
                     "'%s' AND pid <> pg_backend_pid()" % RENAME_OLD, port)
            time.sleep(1)
            pg_admin('ALTER DATABASE %s RENAME TO %s' % (RENAME_OLD, RENAME_NEW), port)
            new['db_name'] = RENAME_NEW
            say('PostgreSQL: the database opt is now otp')
    if user == RENAME_OLD:
        if exists("SELECT 1 FROM pg_roles WHERE rolname = '%s'" % RENAME_NEW):
            say('PostgreSQL already has an account otp: the account opt keeps its name')
        elif exists("SELECT 1 FROM pg_roles WHERE rolname = '%s'" % RENAME_OLD):
            pg_admin('ALTER ROLE %s RENAME TO %s' % (RENAME_OLD, RENAME_NEW), port)
            new['db_user'] = RENAME_NEW
            if c.get('db_password'):
                # An MD5 password does not survive a rename; it is set again.
                pg_admin("ALTER ROLE %s PASSWORD '%s'" % (
                    RENAME_NEW, str(c['db_password']).replace("'", "''")), port, secret=True)
            new['db_user'] = RENAME_NEW
            say('PostgreSQL: the account opt is now otp')
    if new != before:
        _pg_hba_rename(port, say)
    return new


def _mariadb(sql):
    for cmd in ('mariadb', 'mysql'):
        if shutil.which(cmd):
            got = subprocess.run([cmd, '-uroot', '-N', '-B', '-e', sql], capture_output=True,
                                 text=True, timeout=300)
            if got.returncode == 0:
                return got.stdout.strip()
            raise ValueError((got.stderr or got.stdout).strip()[:300] or 'mariadb failed')
    raise ValueError('the mariadb client is not on this machine')


def _mariadb_rename_local(c, say, new=None):
    name, user = str(c.get('db_name') or RENAME_OLD), str(c.get('db_user') or RENAME_OLD)
    # Names this goes on to put into SQL run as root (1.0.101): a config file
    # the otp group may write is no place to take anything else from.
    for what, v in (('db_name', name), ('db_user', user)):
        if not DB_IDENT.fullmatch(v):
            raise ValueError('%s in %s is not a plain name: %r' % (what, CONFIG_FILE, v))
    # Each rename written down as it is done (1.0.59): one that fails half
    # way still leaves the names that changed in the caller's hands.
    new = {} if new is None else new
    before = dict(new)
    if name == RENAME_OLD:
        if _mariadb("SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME = "
                    "'%s'" % RENAME_NEW) != '0':
            say('MariaDB already has a database otp: the database opt keeps its name')
        else:
            tables = [t for t in _mariadb("SELECT TABLE_NAME FROM information_schema.TABLES "
                                          "WHERE TABLE_SCHEMA = '%s'" % RENAME_OLD).split('\n')
                      if t.strip()]
            _mariadb('CREATE DATABASE `%s` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci'
                     % RENAME_NEW)
            if tables:
                _mariadb('RENAME TABLE ' + ', '.join('`%s`.`%s` TO `%s`.`%s`' % (
                    RENAME_OLD, t, RENAME_NEW, t) for t in tables))
            new['db_name'] = RENAME_NEW
            _mariadb('DROP DATABASE `%s`' % RENAME_OLD)
            say('MariaDB: the database opt is now otp (%d tables moved)' % len(tables))
    target_db = new.get('db_name', name)
    hosts = [h for h in _mariadb("SELECT Host FROM mysql.user WHERE User = '%s'"
                                 % (RENAME_OLD if user == RENAME_OLD else user)).split('\n')
             if h.strip()]
    if user == RENAME_OLD and hosts:
        if _mariadb("SELECT COUNT(*) FROM mysql.user WHERE User = '%s'" % RENAME_NEW) != '0':
            say('MariaDB already has an account otp: the account opt keeps its name')
        else:
            for h in hosts:
                _mariadb("RENAME USER '%s'@'%s' TO '%s'@'%s'" % (RENAME_OLD, h, RENAME_NEW, h))
            new['db_user'] = RENAME_NEW
            say('MariaDB: the account opt is now otp')
    who = new.get('db_user', user)
    if new != before:
        for h in hosts:
            _mariadb("GRANT ALL PRIVILEGES ON `%s`.* TO '%s'@'%s'" % (target_db, who, h))
            try:
                _mariadb("REVOKE ALL PRIVILEGES ON `%s`.* FROM '%s'@'%s'" % (RENAME_OLD, who, h))
            except ValueError:
                pass
        _mariadb('FLUSH PRIVILEGES')
    return new


def _ha_rename(c, say):
    """The replication's objects, on this node and the other one's
    subscription to it. Run with this node's daemon stopped."""
    port = int(c.get('db_port') or 5432)
    db = str(c.get('db_name') or RENAME_NEW)
    slot = int(c.get('ha_slot') or 1)
    peer_slot = 3 - slot
    if pg_admin("SELECT 1 FROM pg_publication WHERE pubname = '%s'" % HA_PUB_OLD, port, db) == '1':
        if pg_admin("SELECT 1 FROM pg_publication WHERE pubname = '%s'" % HA_PUB, port, db) != '1':
            pg_admin('ALTER PUBLICATION %s RENAME TO %s' % (HA_PUB_OLD, HA_PUB), port, db)
            say('replication: the publication is now %s' % HA_PUB)
    # This node's subscription, bringing the other's rows: its name.
    old_in, new_in = 'opt_from_%d' % peer_slot, ha_sub_name(peer_slot)
    if pg_admin("SELECT 1 FROM pg_subscription WHERE subname = '%s'" % old_in, port, db) == '1':
        pg_admin('ALTER SUBSCRIPTION %s RENAME TO %s' % (old_in, new_in), port, db)
        say('replication: this node\'s subscription is now %s' % new_in)
    # The slot here, and the other node's subscription that reads it.
    old_slot, new_slot = 'opt_from_%d' % slot, ha_sub_name(slot)
    have_old = pg_admin("SELECT 1 FROM pg_replication_slots WHERE slot_name = '%s'" % old_slot,
                        port) == '1'
    far = None
    for name, user in ((RENAME_NEW, RENAME_NEW), (RENAME_OLD, RENAME_OLD),
                       (c.get('db_name'), c.get('db_user'))):
        try:
            tls, tls_ca = ha_link_tls(c)
            far = db_open(dict(c, db_host=c.get('ha_peer'), db_port=c.get('ha_peer_port') or 5432,
                               db_name=name, db_user=user, db_tls=tls, db_tls_ca=tls_ca))
            far.value('SELECT 1')
            break
        except Exception:                               # noqa: BLE001
            far = None
    if far is None:
        say('the other node\'s PostgreSQL could not be reached: its subscription to this node '
            'is put right when it is upgraded too')
        return
    try:
        sub = None
        for one in ha_sub_names(slot):
            if far.value('SELECT 1 FROM pg_subscription WHERE subname = ?', (one,)):
                sub = one
                break
        if not sub:
            say('the other node has no subscription to this one: nothing to put right there')
            return
        conninfo = ha_conninfo(c.get('ha_address') or node_address(), port, db,
                               str(c.get('db_user') or RENAME_NEW), c.get('db_password') or '')
        far.run('ALTER SUBSCRIPTION %s DISABLE' % sub)
        time.sleep(2)
        try:
            if have_old and pg_admin("SELECT 1 FROM pg_replication_slots WHERE slot_name = "
                                     "'%s'" % new_slot, port) != '1':
                # Copied at the same place: what the other node had not yet
                # taken is still there for it under the new name.
                pg_admin("SELECT pg_copy_logical_replication_slot('%s', '%s')"
                         % (old_slot, new_slot), port, db)
            for quiet in ("SET log_statement = 'none'",):
                try:
                    far.run(quiet)
                except Exception:                       # noqa: BLE001
                    pass
            far.run(RawSql("ALTER SUBSCRIPTION %s CONNECTION '%s'" % (sub, conninfo.replace("'", "''"))))
            far.run('ALTER SUBSCRIPTION %s SET PUBLICATION %s WITH (refresh = false)'
                    % (sub, HA_PUB))
            far.run("ALTER SUBSCRIPTION %s SET (slot_name = '%s')" % (sub, new_slot))
            if sub != new_slot:
                far.run('ALTER SUBSCRIPTION %s RENAME TO %s' % (sub, new_slot))
                sub = new_slot
        finally:
            far.run('ALTER SUBSCRIPTION %s ENABLE' % sub)
        if have_old:
            pg_admin("SELECT pg_drop_replication_slot('%s') FROM pg_replication_slots WHERE "
                     "slot_name = '%s' AND NOT active" % (old_slot, old_slot), port)
        say('replication: the other node reads this one as %s, from where it was' % new_slot)
    finally:
        far.close()


def rename_from_opt(say=print):
    """otp --rename-from-opt, as root, with the service stopped."""
    if os.geteuid() != 0:
        raise SystemExit('otp: --rename-from-opt is for root (install.sh runs it)')
    load_config()
    c = dict(CONFIG)
    eng = c.get('db_engine') or 'sqlite'
    changes = {}
    if eng != 'sqlite':
        # Whatever happens below, the names in use are written down: the
        # defaults are otp now, and a database still called opt must be
        # found under that name.
        for k in ('db_name', 'db_user'):
            if k not in FILE_KEYS:
                changes[k] = c.get(k) if c.get(k) != DEFAULTS[k] else RENAME_OLD
                c[k] = changes[k]
        if _local_host(c):
            try:
                if eng == 'postgres':
                    _pg_rename_local(c, say, changes)
                else:
                    _mariadb_rename_local(c, say, changes)
            except Exception as e:                      # noqa: BLE001
                say('the database could not be renamed (%s): the names it has now are '
                    'written into %s' % (str(e).split('\n')[0][:200], CONFIG_FILE))
                # Half done (1.0.59): what follows a rename is still done for
                # the part that was renamed, so the daemon can come in.
                try:
                    if eng == 'postgres' and (changes.get('db_name') == RENAME_NEW or
                                              changes.get('db_user') == RENAME_NEW):
                        _pg_hba_rename(int(c.get('db_port') or 5432), say)
                    elif eng != 'postgres' and changes.get('db_name') == RENAME_NEW:
                        who = changes.get('db_user') or RENAME_OLD
                        for h in [x for x in _mariadb("SELECT Host FROM mysql.user WHERE "
                                                      "User = '%s'" % who).split('\n')
                                  if x.strip()]:
                            _mariadb("GRANT ALL PRIVILEGES ON `%s`.* TO '%s'@'%s'"
                                     % (RENAME_NEW, who, h))
                        _mariadb('FLUSH PRIVILEGES')
                except Exception as e2:                 # noqa: BLE001
                    say('and what follows it could not be done either (%s): see the '
                        'database\'s access by hand' % str(e2).split('\n')[0][:200])
        else:
            say('the database is on %s, not here: it keeps its names (%s, %s)'
                % (c.get('db_host'), c['db_name'], c['db_user']))
        c.update(changes)
        if eng == 'postgres' and CONFIG.get('ha_mode') == 'replicated':
            try:
                _ha_rename(c, say)
            except Exception as e:                      # noqa: BLE001
                say('replication could not be renamed (%s): it goes on under its old names'
                    % str(e).split('\n')[0][:200])
    if changes:
        # Written as given: the old names stay explicit, the new are the
        # defaults and drop out.
        write_file_settings(changes)
    return 0


# ---------------------------------------------------------------------------
# The API the web pages ask
# ---------------------------------------------------------------------------
# On 127.0.0.1 only, and only for whoever holds the token in /run/otp - which
# is the web server's group and nobody else. The PHP pages relay to it and
# add nothing: the session travels as a header, and this decides what that
# session may have. Two kinds of session: an administrator's (`admin`) and a
# person enrolling their own token (`portal`), which can reach nothing but
# its own token.

ROLE_RANK = {'readonly': 1, 'tokenadmin': 2, 'fulladmin': 3}


class ApiError(Exception):
    def __init__(self, status, words, detail=''):
        Exception.__init__(self, words)
        self.status = status
        self.detail = detail


def api_token(make=False):
    if make:
        RUN_DIR.mkdir(parents=True, exist_ok=True)
        token = secrets.token_urlsafe(32)
        write_replacing(TOKEN_FILE, token + '\n', 0o640)
        try:
            import grp
            gid = grp.getgrnam(WEB_GROUP).gr_gid
            os.chown(str(TOKEN_FILE), -1, gid)
            os.chmod(str(RUN_DIR), 0o750)
            os.chown(str(RUN_DIR), -1, gid)
        except (KeyError, OSError, ImportError):
            pass
        return token
    try:
        return TOKEN_FILE.read_text().strip()
    except OSError:
        return ''


def _int_id(v):
    """An id from a request: a whole number, or ValueError said plainly."""
    try:
        return int(v or 0)
    except (TypeError, ValueError):
        raise ValueError('an id is a number')


BODY_WORDS = ('name', 'to', 'mail_to', 'dest', 'note', 'code', 'password', 'passphrase', 'lang',
              'kind', 'action', 'mail_fmt', 'display', 'user', 'old', 'new', 'q',
              'state', 'via', 'mode', 'fingerprint', 'label')


def _no_constant(word):
    raise ValueError('%s is not a number' % word)


class ApiHandler(BaseHTTPRequestHandler):
    server_version = 'otp'
    protocol_version = 'HTTP/1.1'
    # A connection that says nothing for a minute is closed (1.0.101): each
    # held a thread for ever, and any program on this machine could open
    # thousands without the key.
    timeout = 60

    def log_message(self, fmt, *args):
        if debugging('api'):
            log('api %s' % (fmt % args), 'debug')

    # ---- the plumbing ---------------------------------------------------------
    @property
    def d(self):
        return self.server.daemon

    @property
    def store(self):
        return self.server.daemon.store

    @property
    def reader(self):
        """The long lists' own connection (1.0.101)."""
        return self.server.daemon.reader()

    def client_ip(self):
        said = str(self.headers.get('X-Otp-Client') or '').strip()
        return said if re.match(r'^[0-9a-fA-F:.]{2,45}\Z', said) else self.client_address[0]

    def send_json(self, data, status=200):
        body = json.dumps(data, default=str, ensure_ascii=False).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(body)

    def body(self):
        if hasattr(self, '_body'):
            return self._body
        try:
            n = int(self.headers.get('Content-Length') or 0)
        except ValueError:
            raise ApiError(400, 'the length of the body is not a number')
        if n < 0:
            raise ApiError(400, 'the length of the body is not a number')
        if n > 8 * 1024 * 1024:
            raise ApiError(413, 'that is more than this takes')
        raw = self.rfile.read(n) if n else b''
        try:
            # NaN and Infinity are not numbers anybody means (1.0.103).
            self._body = json.loads(raw.decode('utf-8'), parse_constant=_no_constant) \
                if raw else {}
        except (ValueError, RecursionError):            # [[[[... too (1.0.139)
            raise ApiError(400, 'the body is not JSON')
        if not isinstance(self._body, dict):
            raise ApiError(400, 'the body is not an object')
        # What is a word is a word (1.0.103): a list where a name belongs was
        # made into the text "['x']" - a token by that name, a mail to it.
        for k in BODY_WORDS:
            v = self._body.get(k)
            if isinstance(v, (list, dict, bool)):
                raise ApiError(400, '%s is a piece of text here' % k)
            if isinstance(v, float) and k != 'code':
                raise ApiError(400, '%s is a piece of text here' % k)
        return self._body

    def body_to_file(self, path, most):
        """A request body that is a file, written down a lump at a time."""
        n = int(self.headers.get('Content-Length') or 0)
        if n <= 0:
            raise ApiError(400, 'no file arrived')
        if n > most:
            raise ApiError(413, 'that file is bigger than this takes')
        left = n
        with open(str(path), 'wb') as out:
            while left > 0:
                lump = self.rfile.read(min(left, 1 << 20))
                if not lump:
                    raise ApiError(400, 'the file did not arrive whole')
                out.write(lump)
                left -= len(lump)
        self._body = {}
        return n

    def send_bytes(self, data, name, kind='application/octet-stream'):
        self.send_response(200)
        self.send_header('Content-Type', kind)
        self.send_header('Content-Disposition', 'attachment; filename="%s"' % name)
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(data)

    def send_file(self, path, name):
        # Opened before a header is sent (1.0.61): a file it may not read -
        # a copy root made on the command line - went out as "200" and then
        # a 500 in the middle of the download.
        try:
            f = open(str(path), 'rb')
        except PermissionError:
            raise ApiError(403, '%s cannot be read by the service (made by root on the command '
                                'line?): chown otp:otp it, then again' % name)
        except FileNotFoundError:
            raise ApiError(404, 'there is no such file: %s' % name)
        with f:
            self._send_open_file(f, name)

    def _send_open_file(self, f, name):
        size = os.fstat(f.fileno()).st_size
        self.send_response(200)
        self.send_header('Content-Type', 'application/octet-stream')
        self.send_header('Content-Disposition', 'attachment; filename="%s"' % name)
        self.send_header('Content-Length', str(size))
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        shutil.copyfileobj(f, self.wfile, 1 << 18)

    def do_GET(self):
        self.route('GET')

    def do_POST(self):
        self.route('POST')

    def route(self, method):
        # A body of its own for each request (1.0.146): on a kept-alive
        # connection the handler is the same, and the last one's was read again.
        self.__dict__.pop('_body', None)
        url = urlparse(self.path)
        self.args = {k: v[-1] for k, v in parse_qs(url.query).items()}
        path = url.path.rstrip('/')
        self.route_path = path
        if path != '/api/health':
            want = api_token()
            given = str(self.headers.get('X-Otp-Token') or '')
            # As bytes (1.0.149): a token with a letter beyond ASCII raised
            # TypeError there, and the connection was dropped with a trace.
            if not want or not hmac.compare_digest(want.encode('utf-8'),
                                                   given.encode('utf-8', 'replace')):
                return self.send_json({'ok': False, 'error': 'not this API’s token'}, 403)
        fn = ROUTES.get((method, path))
        if not fn:
            return self.send_json({'ok': False, 'error': 'no such endpoint: %s %s'
                                   % (method, path)}, 404)
        self._held = None
        self._failed = False
        try:
            got = fn(self)
            if got is not None:
                self.send_json(got if 'ok' in got else dict(ok=True, **got))
        except ApiError as e:
            # What went wrong in detail - a domain controller's name, a bind
            # DN - only to somebody signed in (1.0.33); the rest is in the log.
            detail = e.detail if self._signed_in() else None
            if e.detail and not detail:
                log('%s %s: %s (%s)' % (method, path, e, e.detail), 'info')
            self.send_json({'ok': False, 'error': str(e), 'detail': detail}, e.status)
        except (ValueError, BadSetting, RadiusError) as e:
            said = str(e)
            if said.startswith(('invalid literal for int()', 'could not convert string to float',
                                'cannot convert float')):
                # Python's words for a field that is not a number (1.0.103).
                said = 'a field that is a number holds something else'
            self.send_json({'ok': False, 'error': said}, 400)
        except LdapError as e:
            # The domain controller's name and its TLS - only to somebody
            # signed in (1.0.136), as an ApiError's detail is.
            if self._signed_in():
                self.send_json({'ok': False, 'error': str(e), 'detail': e.detail}, 502)
            else:
                log('%s %s: the directory: %s (%s)' % (method, path, e, e.detail), 'warn')
                self.send_json({'ok': False, 'error': 'the directory could not be asked just '
                                'now - try again in a moment', 'detail': None}, 502)
        except DbError as e:
            # Where the database is, only to somebody signed in (1.0.146).
            if self._signed_in():
                self.send_json({'ok': False, 'error': str(e)}, 503)
            else:
                log('%s %s: the database: %s' % (method, path, e), 'warn')
                self.send_json({'ok': False, 'error': 'the database cannot be reached just now '
                                                      '- try again in a moment'}, 503)
        except (TypeError, AttributeError, KeyError) as e:
            # A field of the wrong kind - null where a number goes, a list
            # where an object does (1.0.44): the request's fault, said so,
            # and the trace kept in case it was not.
            log('%s %s could not be read: %s\n%s' % (method, path, e, traceback.format_exc()),
                'warn')
            self.send_json({'ok': False, 'error': 'the request is not in the shape this '
                                                  'takes (a field of the wrong kind)'}, 400)
        except (BrokenPipeError, ConnectionResetError):
            # The page went away before its answer did (1.0.61): nothing broke.
            pass
        except Exception as e:
            # A value the database cannot keep - a number out of its range, a
            # text too long for its column (1.0.103): the request's fault.
            kind = type(e).__name__
            if kind in ('DataError', 'NumericValueOutOfRange', 'StringDataRightTruncation',
                        'InvalidTextRepresentation', 'OverflowError') or \
                    (kind == 'OperationalError' and 'out of range' in str(e).lower()):
                log('%s %s: a value the database cannot keep: %s' % (method, path, e), 'info')
                self.send_json({'ok': False, 'error': 'a value is too big or of the wrong kind '
                                                      'for the database'}, 400)
                return
            log('the API broke on %s %s: %s\n%s' % (method, path, e, traceback.format_exc()),
                'error')
            # The words of the exception stay in the log (1.0.33).
            self.send_json({'ok': False, 'error': 'it broke - the reason is in the log of the '
                                                  'service (/var/log/otp/otp.log)'}, 500)
        finally:
            self._release()

    def _signed_in(self):
        token = str(self.headers.get('X-Otp-Session') or '')
        if not token:
            return False
        try:
            # Only a look: an error must not keep a session alive. (1.0.36)
            # An administrator past the second step only (1.0.149): a portal
            # user, or a password without its code, was told the directory's
            # and the database's addresses with every error.
            s = self.store.session_get(
                token, 'admin', int(CONFIG.get('session_idle_min') or 120) * 60, touch=False)
            return bool(s) and not mfa_pending(s)
        except Exception:                               # noqa: BLE001
            return False

    def arg(self, name, default=''):
        return self.args.get(name, default)

    def num(self, name, default, lo=0, hi=10 ** 9):
        try:
            return max(lo, min(hi, int(float(self.args.get(name, default)))))
        except (TypeError, ValueError, OverflowError):
            return default

    # ---- who is asking ----------------------------------------------------------
    def session(self, kind):
        token = str(self.headers.get('X-Otp-Session') or '')
        if kind == 'admin':
            idle = int(CONFIG.get('session_idle_min') or 120) * 60
        else:
            idle = int(CONFIG.get('portal_session_min') or 15) * 60
        return self.store.session_get(token, kind, idle)

    def me(self, role='readonly'):
        s = self.session('admin')
        if not s:
            raise ApiError(401, 'not signed in, or the sign-in has run out')
        acc = self.store.account(s['name'])
        if not acc or acc.get('disabled'):
            self.store.session_end(self.headers.get('X-Otp-Session'))
            raise ApiError(401, 'that account may no longer sign in')
        if acc.get('source') == 'directory':
            acc = self.directory_recheck(acc)
        s['role'] = acc['role']
        # The second step first (1.0.125): until it is given, the sign-in may
        # do that and nothing else.
        if mfa_pending(s) and getattr(self, 'route_path', '') not in MFA_ALLOWED:
            raise ApiError(401, 'the second step of signing in is not done yet')
        if acc.get('must_change') and getattr(self, 'route_path', '') not in MUST_CHANGE_ALLOWED:
            raise ApiError(403, 'change the password first')
        if ROLE_RANK.get(s['role'], 0) < ROLE_RANK[role]:
            raise ApiError(403, {'fulladmin': 'only a full administrator may do that',
                                 'tokenadmin': 'only a token administrator may do that'}
                           .get(role, 'that account may not do that'))
        s['account'] = acc
        return s

    def portal_link(self):
        """The enrolment pages' address, for a token's mail: from the name the
        pages were reached by, never from what the page sent (1.0.33)."""
        host = str(self.headers.get('X-Otp-Host') or '')
        if not re.fullmatch(r'([A-Za-z0-9.-]{1,253}|\[[0-9A-Fa-f:.]{2,45}\])(:[0-9]{1,5})?', host):
            return ''
        return 'https://%s/' % host

    DIR_CHECKED = {}
    DIR_CHECK_S = 600

    def directory_recheck(self, acc):
        """Somebody signed in from the directory, asked about again every ten
        minutes (1.0.33): switched off there, or out of every group that gives
        a role, and the sign-in ends - not hours later when it runs out. A
        directory that cannot be reached leaves them as they are."""
        name = acc['name']
        t = time.time()
        if t - self.DIR_CHECKED.get(name.lower(), 0) < self.DIR_CHECK_S:
            return acc
        ad = self.d.dirs.get(str(CONFIG.get('admin_directory') or '').lower())
        if not ad:
            self.end_all(name, 'the directory administrators sign in against is gone')
        try:
            who, how = admin_name_parts(name)
            entry = ad.find_user(who, how)
            role = None
            if entry and not entry_unusable(entry, locked=False):
                role = admin_role_for(ad.groups_of(entry, True), ad)
        except Exception as e:                          # noqa: BLE001
            # Asked again in a minute, not on every click: a directory that
            # does not answer would hold each page for its whole timeout. (1.0.36)
            self.DIR_CHECKED[name.lower()] = t - self.DIR_CHECK_S + 60
            log('the directory could not be asked about %s: %s' % (name, e), 'warn')
            return acc
        self.DIR_CHECKED[name.lower()] = t
        if not role:
            self.end_all(name, 'the directory no longer gives %s a role here' % name)
        if role != acc.get('role'):
            self.store.set_account(name, role=role)
            self.store.add_event('accounts', 'the directory gives %s the role %s now (was %s)'
                                 % (name, role, acc.get('role')), 'warn')
            acc = self.store.account(name)
        return acc

    def end_all(self, name, why):
        self.store.db.run('DELETE FROM sessions WHERE kind = ? AND LOWER(name) = ?',
                          ('admin', name.lower()))
        self.store.add_event('accounts', '%s: signed out everywhere' % why, 'warn')
        raise ApiError(401, 'that account may no longer sign in')

    THROTTLE_LOCK = threading.Lock()
    THROTTLE_TIDIED = [0.0]

    def throttle(self, kind, tries, wait_min, name='', ip_tries=None, name_tries=None,
                 what='wrong passwords'):
        """A sign-in attempt, counted before the password is asked (1.0.33):
        thirty at once from one address all slipped past a count made after
        the slow check. The attempt holds a place until it is known to have
        gone well, and gives it back then. Counted per address and, more
        loosely, per name, so many addresses cannot share out the guessing
        of one password."""
        ip = self.client_ip()
        try:
            a = ipaddress.ip_address(str(ip).split('%')[0])
            if a.version == 6 and not a.ipv4_mapped:
                # One /64 is one machine's to choose from (1.0.101): counted
                # per address, each guess came from a new one.
                ip = str(ipaddress.ip_network('%s/64' % a, strict=False))
        except ValueError:
            pass
        keys = [(kind, ip)]
        if name:
            # Counted per person, not per spelling (1.0.44): DOMAIN\\novak,
            # novak@anything and Novak are all novak here.
            who = str(name).strip().lower()
            # "admin>person" (a test of somebody's sign-in) keeps its admin
            # (1.0.146): CORP\\novak made it novak alone, one count for all.
            # Only for those tests (1.0.147): a name typed at a sign-in is
            # never split there - a>CORP\\novak, b>CORP\\novak... was a fresh
            # count each time for novak's password.
            pre = sep = ''
            if kind in ('code-test', 'radtest'):
                pre, sep, who = who.rpartition('>')
            who = who.split('\\', 1)[-1].rsplit('@', 1)[0].strip()
            keys.append((kind + '-name', (pre + sep + who)[:190]))
        t = time.time()
        span = wait_min * 60
        with self.THROTTLE_LOCK:
            for i, key in enumerate(keys):
                # Each limit its own where asked (1.0.103): a code typed on the
                # enrolment pages is one person's, and five typos of one
                # person locked the whole office behind its address out.
                limit = (ip_tries or tries) if i == 0 else (name_tries or tries * 4)
                fails = [x for x in self.d.login_fails[key] if t - x < span]
                self.d.login_fails[key] = fails
                info = self.d.login_info.setdefault(key, {'others': []})
                info.update(limit=limit, span=span, what=what, at=t)
                other = (str(name).strip()[:120] if i == 0 else str(ip)) if name or i else ''
                if other:
                    if other in info['others']:
                        info['others'].remove(other)
                    info['others'] = (info['others'] + [other])[-6:]
                if len(fails) >= limit:
                    raise ApiError(429, 'too many %s %s: try again in %s'
                                   % (what, 'from %s' % ip if i == 0 else 'for this name',
                                      human_span(span - (t - fails[0]))))
            for key in keys:
                self.d.login_fails[key].append(t)
            # Tidied at most every 30 s (1.0.59): past 20 000 names all still
            # waiting, every sign-in scanned the whole map under this lock.
            # Past 50 000 the oldest half goes - memory has an end.
            fl = self.d.login_fails
            if len(fl) > 20000 and t - self.THROTTLE_TIDIED[0] > 30:
                self.THROTTLE_TIDIED[0] = t
                # Kept for the longest wait of any kind (1.0.61), not this
                # kind's: a 5 min kind tidied away 15 min lockouts.
                keep_s = max(span, 6 * 3600)
                for k in [k for k, v in fl.items() if not v or t - v[-1] > keep_s]:
                    fl.pop(k, None)
                    self.d.login_info.pop(k, None)
                if len(fl) > 50000:
                    # Addresses go before names (1.0.61): many addresses must
                    # not flush the count of the one name being guessed.
                    order = sorted(fl, key=lambda k: (str(k[0]).endswith('-name'),
                                                      fl[k][-1] if fl[k] else 0))
                    for k in order[:len(fl) // 2]:
                        if k not in keys:
                            fl.pop(k, None)
                            self.d.login_info.pop(k, None)
        self._held = (keys, t)
        return keys

    def failed(self, key):
        """The attempt went wrong: the place it holds stays taken."""
        self._failed = True

    def _release(self):
        held = getattr(self, '_held', None)
        if not held or getattr(self, '_failed', False):
            return
        keys, t = held
        with self.THROTTLE_LOCK:
            for key in keys:
                got = self.d.login_fails.get(key)
                if got and t in got:
                    got.remove(t)
        self._held = None


ROUTES = {}
# What an administrator who still has to change their password may do.
MUST_CHANGE_ALLOWED = ('/api/auth/password', '/api/auth/logout', '/api/auth/whoami')


def route(method, path):
    def wrap(fn):
        ROUTES[(method, path)] = fn
        return fn
    return wrap


# ---- health and signing in -------------------------------------------------------
HEALTH_SEEN = {}


# ---- who is locked out (1.0.112) ---------------------------------------------------
# Each node counts the wrong passwords that reach it, in memory. Every node
# writes its list into meta when it changes, so the pages of either show both;
# a lockout is cleared by the node that holds it - asked through meta when it
# is the other one.
LOCKOUT_KINDS = {
    'admin': 'signing in to these pages',
    'portal': 'signing in to the enrolment pages',
    'portal-verify': 'a code typed on the enrolment pages',
    'portal-send': 'codes sent from the enrolment pages',
    'portal-confirm': 'confirming a token on the enrolment pages',
    'portal-reissue': 'a new token on the enrolment pages',
    'portal-codes': 'recovery codes shown on the enrolment pages',
    # Kept in the database for the whole cluster (1.0.116), not in a node's
    # memory: codes sent to a person, and a token locked by wrong codes.
    'codes-sent': 'codes sent by e-mail or SMS',
    'token-locked': 'the token, after wrong codes',
    'password': 'changing a password',
    'code-test': 'trying a code (Tokens)',
    'radtest': 'a RADIUS test (Test)',
    'texts-test': 'a test message (Message texts)',
    'radius-src': 'signing in to the VPN, from one place',
}
LOCKOUTS_SENT = {'sig': None, 'at': 0.0}
THROTTLE_GUARD = threading.Lock()


def lockouts_view(d):
    """What this node counts now: one line per address or name with a wrong
    attempt still counted, locked or not yet."""
    t = time.time()
    rows = []
    for key, fails in list(d.login_fails.items()):
        info = d.login_info.get(key) or {}
        span = float(info.get('span') or 0)
        if not span:
            continue
        fails = [x for x in fails if t - x < span]
        kind, who = key
        if info.get('guard'):
            # A place counted by the sign-in protection (1.0.137): blocked
            # for its own time, by its refusals or by its names.
            until = float(info.get('blocked_until') or 0)
            blocked = until > t
            if not fails and not blocked:
                # Forgotten once nothing of it counts (1.0.149): every new
                # place stayed for good - 50 000 /64s were 45 MB, and the
                # list published every few seconds 18 MB.
                if t - float(info.get('at') or 0) > span and t - until > span:
                    d.login_fails.pop(key, None)
                    d.login_info.pop(key, None)
                continue
            names = [n for n, ts in (info.get('names') or {}).items() if t - ts < span]
            last = max(fails[-1] if fails else 0, float(info.get('blocked_at') or 0))
            rows.append({
                'kind': kind, 'who': who, 'by': 'place', 'what': LOCKOUT_KINDS.get(kind, kind),
                'base': kind, 'words': info.get('what') or 'wrong sign-ins',
                'fails': len(fails), 'limit': int(info.get('limit') or 0),
                'names': len(names), 'names_limit': int(info.get('names_limit') or 0),
                'locked': blocked, 'until': until if blocked else None,
                'why': info.get('blocked_why') if blocked else '',
                'forgets': max(until, (fails[-1] + span) if fails else 0),
                'first': fails[0] if fails else last, 'last': last,
                'others': list(info.get('others') or [])})
            continue
        if not fails:
            continue
        by_name = kind.endswith('-name')
        base = kind[:-5] if by_name else kind
        limit = int(info.get('limit') or 0)
        locked = bool(limit) and len(fails) >= limit
        rows.append({
            'kind': kind, 'who': who, 'by': 'name' if by_name else 'address',
            'what': LOCKOUT_KINDS.get(base, base), 'base': base,
            'words': info.get('what') or 'wrong passwords',
            'fails': len(fails), 'limit': limit, 'locked': locked,
            'until': (fails[0] + span) if locked else None,
            'forgets': fails[-1] + span, 'first': fails[0], 'last': fails[-1],
            'others': list(info.get('others') or [])})
    rows.sort(key=lambda r: (not r['locked'], -r['last']))
    return rows


def lockouts_clear(d, which=None):
    """Forget counts: which is a list of (kind, who); None - every one."""
    n = 0
    with ApiHandler.THROTTLE_LOCK:
        keys = list(d.login_fails) if which is None else \
            [tuple(k) for k in which if tuple(k) in d.login_fails]
        for k in keys:
            if d.login_fails.pop(k, None):
                n += 1
            d.login_info.pop(k, None)
    LOCKOUTS_SENT['sig'] = None
    return n


LOCKOUTS_PUBLISHED_MOST = 500


def lockouts_publish(d, force=False):
    rows = lockouts_view(d)
    if len(rows) > LOCKOUTS_PUBLISHED_MOST:
        # The locked ones and the busiest (1.0.149), not every place.
        rows = sorted(rows, key=lambda r: (not r.get('locked'), -int(r.get('fails') or 0)))[
            :LOCKOUTS_PUBLISHED_MOST]
    sig = json.dumps([(r['kind'], r['who'], r['fails'], r['locked']) for r in rows])
    now = time.time()
    if not force and sig == LOCKOUTS_SENT['sig'] and now - LOCKOUTS_SENT['at'] < 60:
        return rows
    many = bool(CONFIG.get('ha_mode')) or len(d.cluster_nodes()) > 1
    if many:
        d.store.set_meta('lockouts:' + node_name(), json.dumps({'at': now, 'rows': rows}))
    LOCKOUTS_SENT.update(sig=sig, at=now)
    return rows


def lockouts_tick(d):
    """Asked by the other node's pages to clear something here? Then the list."""
    key = 'lockouts:ask:' + node_name()
    raw = d.store.get_meta(key)
    if raw:
        d.store.db.run('DELETE FROM meta WHERE k = ?', (key,))
        try:
            asks = json.loads(raw)
        except ValueError:
            asks = []
        for a in asks if isinstance(asks, list) else []:
            if not isinstance(a, dict):
                continue
            n = lockouts_clear(d, None if a.get('all') else [a.get('key') or []])
            lockouts_said(d.store, a, n)
        lockouts_publish(d, force=True)
        return
    lockouts_publish(d)


def lockouts_said(store, a, n):
    by = str(a.get('by') or '?')
    if a.get('all'):
        words = '%s cleared every lockout and count of wrong attempts on %s (%d)' % (
            by, node_name(), n)
    else:
        k = a.get('key') or ['', '']
        base = str(k[0])[:-5] if str(k[0]).endswith('-name') else str(k[0])
        words = '%s cleared the count of wrong attempts of %s %s (%s) on %s' % (
            by, 'the name' if str(k[0]).endswith('-name') else 'the address', k[1],
            LOCKOUT_KINDS.get(base, base), node_name())
    store.add_event('sign-ins', words, 'warn', who=by)


def lockouts_shared(store):
    """What the database holds for every node (1.0.116): the codes sent to a
    person within the window, and tokens locked after wrong codes."""
    t = time.time()
    rows = []
    span = 60 * int(CONFIG.get('code_send_window_min') or 15)
    limit = int(CONFIG.get('code_send_max') or 5)
    per = {}
    for r in store.db.rows("SELECT k, v FROM meta WHERE k LIKE 'codesent:%'"):
        try:
            per.setdefault(node_key_name('codesent', r['k']), []).extend(
                float(x) for x in json.loads(r['v'] or '[]'))
        except (ValueError, TypeError):
            continue
    for who, times in per.items():          # every node's row of a person together (1.0.146)
        times = sorted(x for x in times if t - x < span)
        if not times:
            continue
        locked = len(times) >= limit
        rows.append({'kind': 'codes-sent', 'who': who, 'by': 'name',
                     'what': LOCKOUT_KINDS['codes-sent'], 'base': 'codes-sent',
                     'words': 'codes sent', 'fails': len(times), 'limit': limit,
                     'locked': locked,
                     'until': (times[len(times) - limit] + span) if locked else None,
                     'forgets': times[-1] + span, 'first': times[0], 'last': times[-1],
                     'others': []})
    after = int(CONFIG.get('lockout_after') or 0)
    for r in store.db.rows('SELECT name, locked_until, failures, fail_times, last_from FROM '
                           'tokens WHERE locked_until > ?', (t,)):
        try:
            fails = [float(x) for x in json.loads(r['fail_times'] or '[]')]
        except (ValueError, TypeError):
            fails = []
        until = float(r['locked_until'])
        rows.append({'kind': 'token-locked', 'who': r['name'], 'by': 'token',
                     'what': LOCKOUT_KINDS['token-locked'], 'base': 'token-locked',
                     'words': 'wrong codes', 'fails': int(r['failures'] or 0),
                     'limit': after, 'locked': True, 'until': until, 'forgets': until,
                     'first': min(fails) if fails else until, 'last': max(fails) if fails
                     else until, 'others': []})
    rows.sort(key=lambda r: (not r['locked'], -r['last']))
    return rows


def lockouts_shared_clear(store, kind, who, by):
    if kind == 'codes-sent':
        n = node_key_drop(store, 'codesent', who)
        store.add_event('sign-ins', '%s cleared the count of codes sent to %s' % (by, who),
                        'warn', who=by)
        return n
    if kind == 'token-locked':
        if not store.token(who):
            return 0
        store.token_write(who, {'failures': 0, 'fail_times': '[]', 'locked_until': None})
        node_key_drop(store, 'scratchguard', who)
        scratch_guard_clear(who)
        store.add_event('tokens', '%s let %s try again at once' % (by, who), who=by)
        return 1
    return 0


RADTEST_NAME_TRIES = 5


@route('GET', '/api/lockouts')
def _lockouts(h):
    h.me('fulladmin')
    me = node_name()
    out = [{'node': me, 'me': True, 'fresh': True, 'rows': lockouts_view(h.d)}]
    now = time.time()
    for n in h.d.cluster_nodes():
        if n == me:
            continue
        try:
            got = json.loads(h.store.get_meta('lockouts:' + n) or '{}')
        except ValueError:
            got = {}
        rows = [r for r in (got.get('rows') or []) if float(r.get('forgets') or 0) > now]
        for r in rows:
            if r.get('locked') and float(r.get('until') or 0) <= now:
                r['locked'] = False
        out.append({'node': n, 'me': False, 'fresh': now - float(got.get('at') or 0) < 120,
                    'at': got.get('at'), 'rows': rows})
    out.append({'node': '*', 'me': False, 'fresh': True, 'shared': True,
                'rows': lockouts_shared(h.store)})
    return {'nodes': out, 'now': now, 'cluster': len(out) > 2}


@route('POST', '/api/lockouts')
def _lockouts_do(h):
    s = h.me('fulladmin')
    b = h.body()
    act = b.get('action')
    nodes = [node_name()] + [n for n in h.d.cluster_nodes() if n != node_name()]
    if act == 'clear' and str(b.get('kind') or '') in ('codes-sent', 'token-locked'):
        n = lockouts_shared_clear(h.store, str(b.get('kind')), norm_name(b.get('who') or ''),
                                  s['name'])
        if not n:
            raise ApiError(404, 'that is not counted any more')
        return {'message': 'cleared', 'told': []}
    if act == 'clear_all':
        want = nodes
        ask = {'all': 1, 'by': s['name']}
        shared = lockouts_shared(h.store)
        for r in shared:
            lockouts_shared_clear(h.store, r['kind'], r['who'], s['name'])
    elif act == 'clear':
        kind, who = str(b.get('kind') or ''), str(b.get('who') or '')
        base = kind[:-5] if kind.endswith('-name') else kind
        if base not in LOCKOUT_KINDS or not who:
            raise ApiError(400, 'which lockout?')
        node = str(b.get('node') or node_name())
        if node not in nodes:
            raise ApiError(400, 'there is no node %s' % node)
        want = [node]
        ask = {'key': [kind, who], 'by': s['name']}
    else:
        raise ApiError(400, 'no such thing to do')
    told = []
    for n in want:
        if n == node_name():
            got = lockouts_clear(h.d, None if ask.get('all') else [ask['key']])
            lockouts_said(h.store, ask, got)
            lockouts_publish(h.d, force=True)
        else:
            # The other node clears it within five seconds.
            with THROTTLE_GUARD:
                try:
                    pending = json.loads(h.store.get_meta('lockouts:ask:' + n) or '[]')
                except ValueError:
                    pending = []
                pending = (pending if isinstance(pending, list) else [])[-50:] + [ask]
                h.store.set_meta('lockouts:ask:' + n, json.dumps(pending))
            told.append(n)
    return {'message': 'cleared', 'told': told}


@route('GET', '/api/health')
def _health(h):
    """Asked without the API token, so it says only what the pages need
    before anybody is signed in: that the database opens, whether any
    account exists at all (the sign-in page says how to make the first one
    otherwise), the language and this node's name. No version, no count."""
    # The database asked at most once a second (1.0.57): /healthz is public,
    # and every load balancer, monitor and the web address's own check ask it.
    got = HEALTH_SEEN.get('db')
    if got and time.time() - got[0] < 1.0:
        users, db_ok, maint = got[1]
    else:
        try:
            users = 1 if h.store.db.value('SELECT 1 FROM accounts LIMIT 1') else 0
            db_ok = True
        except Exception:
            users, db_ok = 0, False
        try:
            maint = bool(maintenance_now(h.store).get('on'))
        except Exception:                               # noqa: BLE001
            maint = False
        HEALTH_SEEN['db'] = (time.time(), (users, db_ok, maint))
    out = {'ok': True, 'users': users, 'database': {'ok': db_ok},
           'lang': CONFIG.get('ui_lang') or 'cs', 'node': node_name(),
           'maintenance': maint,
           # For a balancer of RADIUS and for monitoring (1.0.47): whether
           # RADIUS listens, and - asked for - whether replication runs.
           'radius': bool(getattr(getattr(h.d, 'radius', None), 'bound', None))}
    if h.arg('check') == 'all' and CONFIG.get('ha_mode') == 'replicated':
        try:
            rep = ha_repl_state(h.store)
            out['replication'] = {'ok': bool(rep.get('healthy')), 'lost': bool(rep.get('lost'))}
        except Exception:                               # noqa: BLE001
            out['replication'] = {'ok': False}
    return out


DUMMY_PW_HASH = password_hash(secrets.token_urlsafe(18))

ROLE_GROUP_KEYS = (('admin_group_full', 'fulladmin'), ('admin_group_token', 'tokenadmin'),
                   ('admin_group_readonly', 'readonly'))


def admin_role_for(have, ad=None):
    """Which role these groups earn - full administrator first - or None.
    Only a group named for a role lets anybody in (1.0.33): with none named,
    nobody from the directory gets in at all. Before, being anywhere in the
    directory was then enough to read every log and every token."""
    for key, role in ROLE_GROUP_KEYS:
        wanted = dn_list(CONFIG.get(key))
        if wanted and group_matches(wanted, have, ad):
            return role
    return None


def admin_name_parts(name):
    """`DOMAIN\\novak`, `novak@example.cz` or `novak`, as the directory is asked."""
    name = name.strip()
    if '\\' in name:
        name = name.split('\\', 1)[1]
    return name, ('upn' if '@' in name else 'sam')


def admin_ask_directory(h, name, password):
    """One sign-in, asked of the directory in `admin_directory`, and what it
    earns here. Nothing is made and no session is opened."""
    ad = h.d.dirs.get(str(CONFIG.get('admin_directory') or '').lower())
    if not ad:
        return None
    who, how = admin_name_parts(name)
    try:
        entry = ad.find_user(who, how)
    except LdapUnreachable as e:
        raise ApiError(503, 'the directory cannot be reached', str(e))
    if not entry:
        return {'ok': False, 'missing': True, 'said': 'the directory has nobody called %s' % who,
                'directory': ad.name}
    if entry_unusable(entry):
        return {'ok': False, 'said': 'the account may not sign in: %s' % entry_unusable(entry),
                'dn': entry['dn'], 'directory': ad.name}
    try:
        ad.password_ok(entry, password)
    except LdapUnreachable as e:
        raise ApiError(503, 'the directory cannot be reached', str(e))
    except LdapError as e:
        return {'ok': False, 'said': str(e) or 'the password is not right', 'dn': entry['dn'],
                'directory': ad.name}
    have = ad.groups_of(entry, True)
    return {'ok': True, 'name': who, 'role': admin_role_for(have, ad), 'dn': entry['dn'],
            'display': entry.get('display') or '', 'directory': ad.name, 'entry': entry,
            'groups': sorted({cn for _, cn in have}, key=str.lower)}


def admin_from_directory(h, name, password):
    """An administrator signed in against the directory named in
    `admin_directory`: the role is that of the first group they are in."""
    said = admin_ask_directory(h, name, password)
    if said is None:
        return None
    if not said['ok']:
        # What the directory said goes into the log only: the answer must not
        # tell the caller whether the name exists there.
        h.store.add_event('sign-ins', 'the directory did not sign %s in from %s: %s'
                          % (name, h.client_ip(), said.get('said') or '?'), 'warn')
        raise ApiError(401, 'the name or the password is not right')
    if not said['role']:
        # Said as a wrong password is (1.0.101): a 403 told anybody trying
        # names and passwords that this one was right.
        h.store.add_event('sign-ins', 'the directory knows %s, and none of the groups given a '
                          'role here holds them (from %s)' % (said['name'], h.client_ip()), 'warn')
        raise ApiError(401, 'the name or the password is not right')
    name, role, entry = said['name'], said['role'], said['entry']
    bad = name_letters_problem(name)
    if bad:
        # Said as a wrong password is, and written down (1.0.154).
        h.store.add_event('sign-ins', 'the directory signed %s in, refused here: %s'
                          % (name, bad), 'warn')
        raise ApiError(401, 'the name or the password is not right')
    # One person, one account, whatever way the name was typed (1.0.101):
    # novak, novak@corp.cz and CORP\novak are the same entry in the
    # directory - found by its DN. Kept under their typed name, each
    # spelling was an account of its own, and switching one off left the
    # others to sign in with.
    same = [a for a in h.store.db.rows("SELECT * FROM accounts WHERE source = 'directory'")
            if str(a.get('dn') or '').lower() == str(entry['dn']).lower()]
    off = [a for a in same if a.get('disabled')]
    if off:
        return off[0]
    if same:
        name = same[0]['name']
    acc = h.store.account(name)
    groups = '; '.join(said['groups'])[:2000]
    if acc:
        if acc.get('source') != 'directory':
            return None
        h.store.set_account(name, role=role, display=entry.get('display') or '',
                            dn=entry['dn'], group_list=groups)
    elif CONFIG.get('ha_mode') == 'replicated' and not ha_lead(h.store):
        # Made by one node of the two only (1.0.149): a first sign-in on both
        # at once - or while replication was stopped - put the name in twice,
        # and replication stopped on it for good. The other node's database
        # gets it; replication brings it here.
        dir_account_far(h.store, name, role, said, entry, groups)
    else:
        h.store.add_account(name, role, None, source='directory',
                            note='signed in from %s' % said['directory'],
                            display=entry.get('display') or '', dn=entry['dn'], groups=groups)
    return h.store.account(name)


def dir_account_far(store, name, role, said, entry, groups):
    if not ACCOUNT_NAME_RE.match(name) or role not in ROLES_ALL:
        raise ApiError(401, 'the name or the password is not right')
    row = {'name': name, 'role': role, 'pw': '', 'source': 'directory', 'disabled': 0,
           'must_change': 0, 'note': ('signed in from %s' % said['directory'])[:400],
           'created': time.time(), 'last_in': None, 'last_from': '', 'prefs': '{}',
           'display': entry.get('display') or '', 'dn': entry['dn'], 'group_list': groups}
    mode, ca = ha_link_tls()
    done = False
    for tls in [None] + ([('verify-ca', ca)] if mode == 'verify-full' else []):
        try:
            far = db_open(ha_peer_conf(timeout=5, tls=tls))
        except Exception:                               # noqa: BLE001
            continue
        try:
            if not far.row('SELECT id FROM accounts WHERE LOWER(name) = ?', (name.lower(),)):
                far.insert('accounts', row)
            done = True
            break
        except Exception:                               # noqa: BLE001
            continue
        finally:
            far.close()
    if done:
        for _ in range(40):
            if store.account(name):
                return
            time.sleep(0.25)
    raise ApiError(503, 'the first sign-in of %s is made on the other node of the cluster, '
                        'which could not be reached or has not passed it on yet - try again in '
                        'a minute, or sign in there' % name)


@route('POST', '/api/auth/login')
def _login(h):
    b = h.body()
    # No account has a longer name (1.0.146): megabytes typed went into the log.
    name = str(b.get('name') or '').strip()[:190]
    password = str(b.get('password') or '')
    key = h.throttle('admin', int(CONFIG.get('login_tries') or 5),
                     int(CONFIG.get('login_wait_min') or 15), name=name)
    acc = h.store.account(name) or (h.store.account(admin_name_parts(name)[0])
                                    if CONFIG.get('admin_directory') else None)
    ok = None
    if acc and acc.get('source') != 'directory':
        ok = acc if (acc.get('pw') and password_ok(password, acc['pw'])) else None
    elif not acc and not CONFIG.get('admin_directory'):
        # As long as for a name that is there (1.0.33): how long the answer
        # took told which names exist.
        password_ok(password, DUMMY_PW_HASH)
    elif CONFIG.get('admin_directory') and password:
        if not acc:
            # The time of a password hash spent here too (1.0.101): a wrong
            # password of a local account took a hash longer than a name that
            # is not there, which went straight to the directory.
            password_ok(password, DUMMY_PW_HASH)
        try:
            ok = admin_from_directory(h, name, password)
        except ApiError as e:
            h.failed(key)
            h.store.add_event('sign-ins', '%s could not sign in from %s: %s'
                              % (name, h.client_ip(), e), 'warn')
            raise
    if not ok:
        h.failed(key)
        h.store.add_event('sign-ins', 'a wrong password for %s from %s'
                          % (name or '(nobody)', h.client_ip()), 'warn')
        raise ApiError(401, 'the name or the password is not right')
    if ok.get('disabled'):
        # Said as a wrong password is, and counted as one (1.0.57): the
        # difference told that the password was right.
        h.failed(key)
        h.store.add_event('sign-ins', '%s, switched off, tried to sign in from %s'
                          % (ok['name'], h.client_ip()), 'warn')
        raise ApiError(401, 'the name or the password is not right')
    # The second step, when it is asked for (1.0.125): the sign-in is made,
    # and may do nothing but give it.
    stage = mfa_stage(h.store, ok['name']) if CONFIG.get('admin_2fa') else ''
    token = h.store.session_new('admin', ok['name'], ok['role'], h.client_ip(),
                                CONFIG.get('session_hours') or 12,
                                data={'mfa': stage} if stage else None)
    h.store.set_account(ok['name'], last_in=time.time(), last_from=h.client_ip())
    h.store.add_event('sign-ins', '%s signed in from %s%s' % (
        ok['name'], h.client_ip(), {'check': ' - the second step to give',
                                     'enrol': ' - the second step to set up'}.get(stage, '')),
                      who=ok['name'])
    return {'token': token, 'who': {'name': ok['name'], 'role': ok['role'] if not stage else ''},
            'must_change': bool(ok.get('must_change')), 'mfa': stage}


# ---- editing the columns, switched on for one sign-in --------------------------
# Held here in memory, as on isemon: signing out, a sign-in running out and a
# restart of the service all switch it off again. Off, a layout already kept
# is drawn just the same; nothing can be changed.
COLS_EDITING = {}
COLS_EDITING_LOCK = threading.Lock()


def _cols_key(token):
    return hashlib.sha256(str(token or '').encode('utf-8', 'replace')).hexdigest()


# Kept with the sign-in's own row since 1.0.13 - in memory it was this node's
# alone, and behind a load balancer the next request found it switched off.
def _session_row(token):
    store = HA_STORE.get('store')
    if not store or not token:
        return None, None
    row = store.db.row('SELECT id, data FROM sessions WHERE token_hash = ?',
                       (hashlib.sha256(str(token).encode()).hexdigest(),))
    if not row:
        return store, None
    try:
        row['data'] = json.loads(row.get('data') or '{}')
    except ValueError:
        row['data'] = {}
    return store, row


def cols_editing(token):
    _, row = _session_row(token)
    return bool(row and row['data'].get('cols_edit'))


def set_cols_editing(token, on):
    store, row = _session_row(token)
    if not row:
        return False
    data = row['data']
    if on:
        data['cols_edit'] = 1
    else:
        data.pop('cols_edit', None)
    store.session_set_data(row['id'], data)
    return bool(on)


SETTINGS_FILE_KIND = 'otp-user-settings'


@route('POST', '/api/auth/logout')
def _logout(h):
    token = h.headers.get('X-Otp-Session')
    h.store.session_end(token)
    set_cols_editing(token, False)
    return {}


@route('POST', '/api/auth/columns')
def _columns(h):
    """Anybody signed in, a read-only account as well: this is how the page
    looks to that one person and changes nothing anybody else sees."""
    s = h.me()
    b = h.body()
    token = h.headers.get('X-Otp-Session') or ''
    if 'edit' in b:
        set_cols_editing(token, bool(b.get('edit')))
        if 'cols' not in b:
            return {'edit': cols_editing(token)}
    reset = bool(b.get('reset'))
    # Putting them back is always allowed; changing them only with the switch
    # on, so a page that misbehaves cannot rearrange somebody's tables while
    # they are only reading them.
    if not reset and not cols_editing(token):
        raise ApiError(409, 'switch on "Edit the columns" under your name first: the columns '
                       'are not being edited from this sign-in')
    try:
        kept = h.store.put_user_cols(s['name'], {} if reset else (b.get('cols') or {}))
    except ValueError as e:
        raise ApiError(400, str(e))
    if reset:
        h.store.add_event('accounts', '%s put the columns of every table back as they come'
                          % s['name'], who=s['name'])
    return {'tables': len(kept), 'edit': cols_editing(token)}


@route('GET', '/api/auth/settings')
def _my_settings(h):
    """What a person has set for themselves on the page, as one object that
    can be saved to a file and read back - here or on another machine. Never
    the password, the role or anything else about the account."""
    s = h.me()
    return {'name': s['name'], 'version': __version__, 'kind': SETTINGS_FILE_KIND,
            'settings': {'columns': h.store.user_cols(s['name']),
                         'prefs': h.store.user_prefs(s['name'])}}


@route('POST', '/api/auth/settings')
def _my_settings_put(h):
    s = h.me()
    b = h.body()
    got = b.get('settings')
    if not isinstance(got, dict):
        raise ApiError(400, 'that is not a file of settings: there is no "settings" in it')
    known = ('columns', 'prefs')
    ignored = sorted(k for k in got if k not in known)
    # Every section checked before any of them is written.
    for section, check, words in (('columns', h.store.clean_cols, 'the columns'),
                                  ('prefs', h.store.clean_prefs, 'the choices')):
        if section in got:
            try:
                check(got[section] if got[section] is not None else {})
            except (ValueError, TypeError, AttributeError) as e:
                raise ApiError(400, '%s in that file: %s' % (words, e))
    took = {}
    if 'columns' in got:
        took['columns'] = len(h.store.put_user_cols(s['name'], got['columns'] or {}))
    if 'prefs' in got:
        took['prefs'] = len(h.store.put_user_prefs(s['name'], got['prefs'] or {}))
    if not took:
        raise ApiError(400, 'nothing in that file is a setting this version keeps'
                       + (' (it holds: %s)' % ', '.join(ignored) if ignored else ''))
    h.store.add_event('accounts', '%s read their own settings back from a file (%s)'
                      % (s['name'], ', '.join('%s: %d' % kv for kv in took.items())),
                      who=s['name'])
    return {'took': took, 'ignored': ignored}


@route('GET', '/api/auth/whoami')
def _whoami(h):
    s = h.session('admin')
    if not s:
        return {'who': None}
    acc = h.store.account(s['name'])
    if not acc or acc.get('disabled'):
        return {'who': None}
    if mfa_pending(s):
        # No role until the second step is given: the pages that ask who it
        # is (a database or a package sent) refuse it.
        return {'who': {'name': acc['name'], 'role': '', 'display': acc.get('display') or '',
                        'mfa': mfa_pending(s)}}
    try:
        prefs = json.loads(acc.get('prefs') or '{}')
    except ValueError:
        prefs = {}
    # The page is drawn with the person's own layout of the tables from the
    # first frame, rather than as it comes and then again.
    return {'idle_min': int(CONFIG.get('session_idle_min') or 120),
            'who': {'name': acc['name'], 'role': acc['role'], 'source': acc.get('source'),
                    'display': acc.get('display') or '', 'must_change': bool(
                        acc.get('must_change')), 'prefs': prefs,
                    'cols': h.store.user_cols(acc['name']),
                    'cols_edit': cols_editing(h.headers.get('X-Otp-Session') or '')}}


@route('POST', '/api/auth/password')
def _password(h):
    s = h.me()
    b = h.body()
    acc = s['account']
    if acc.get('source') == 'directory':
        raise ApiError(400, 'this account signs in with its directory password, which is '
                       'changed in the directory')
    # Counted as sign-ins are (1.0.57): a session left open was a way to
    # guess the password without end.
    key = h.throttle('password', int(CONFIG.get('login_tries') or 5), 5, name=acc['name'])
    if not password_ok(str(b.get('old') or ''), acc.get('pw')):
        h.failed(key)
        raise ApiError(400, 'the password you have now is not right')
    h.store.set_account(acc['name'], password=str(b.get('new') or ''), must_change=0)
    # Every other sign-in with the old password ends (1.0.33).
    h.store.db.run('DELETE FROM sessions WHERE kind = ? AND LOWER(name) = ? AND token_hash <> ?',
                   ('admin', acc['name'].lower(), hashlib.sha256(
                       str(h.headers.get('X-Otp-Session') or '').encode()).hexdigest()))
    h.store.add_event('accounts', '%s changed their own password' % acc['name'],
                      who=acc['name'])
    # The first password, written down by the installer, is no use to anybody
    # now - and stays readable no longer (1.0.33).
    first = STATE_DIR / 'first-login.txt'
    try:
        if first.exists() and ('name: %s\n' % acc['name']) in first.read_text():
            first.unlink()
    except OSError:
        pass
    return {'message': 'the password is changed'}


@route('POST', '/api/auth/prefs')
def _prefs(h):
    s = h.me()
    acc = s['account']
    try:
        prefs = json.loads(acc.get('prefs') or '{}')
    except ValueError:
        prefs = {}
    b = h.body()
    if 'lang' in b:
        if str(b['lang']) not in ('cs', 'en'):
            raise ApiError(400, 'no such language here')
        prefs['lang'] = str(b['lang'])
    h.store.set_account(acc['name'], prefs=json.dumps(prefs))
    return {'prefs': prefs}


# ---- what it is doing --------------------------------------------------------------
@route('GET', '/api/status')
def _status(h):
    s = h.me()
    out = h.d.status()
    out['role'] = s['role']
    # The outgoing mail at a glance (1.0.95): what waits and what failed,
    # for the badge beside Mail. Counted at most every 10 s.
    now = time.time()
    if now - MAILQ_COUNT_CACHE[0] > 10:
        try:
            MAILQ_COUNT_CACHE[1] = mailq_counts(h.store)
        except Exception:                               # noqa: BLE001
            pass
        MAILQ_COUNT_CACHE[0] = now
    out['mailq'] = MAILQ_COUNT_CACHE[1]
    return out


MAILQ_COUNT_CACHE = [0.0, {}]
MAILQ_SEARCH_COLS = ('to_addr', 'state', 'kind', 'name', 'by_who', 'said', 'subject', 'tries',
                     'node')
MAILQ_SEARCH_TABLE = ('CREATE TABLE t (i INTEGER, to_addr TEXT, state TEXT, kind TEXT, '
                      'name TEXT, by_who TEXT, said TEXT, subject TEXT, tries INTEGER, node TEXT)')


def mailq_search_row(r):
    return {'to_addr': ' '.join(r.get('to') or []), 'state': r.get('state') or '',
            'kind': r.get('kind') or '', 'name': r.get('name') or '', 'by_who': r.get('by') or '',
            'said': r.get('said') or '', 'subject': mailq_subject_kept(r.get('subject'), r.get('kind')),
            'tries': int(r.get('tries') or 0), 'node': r.get('node') or ''}


@route('GET', '/api/software')
def _software(h):
    """What every node runs on (1.0.99): this one asked now, the others as
    their last heartbeat said."""
    h.me()
    me = node_name()
    out = [{'name': me, 'me': True, 'alive': True, 'software': software_info(h.store)}]
    try:
        for n in ha_nodes(h.store):
            if n['name'] != me:
                out.append({'name': n['name'], 'me': False, 'alive': bool(n.get('alive')),
                            'age': int(n.get('age') or 0), 'software': n.get('software') or {}})
    except Exception:                                   # noqa: BLE001
        pass
    return {'nodes': out}


@route('GET', '/api/mailq')
def _mailq(h):
    """The outgoing mail (1.0.95): what waits, what went, what failed."""
    h.me()
    q = h.arg('q')
    state = h.arg('state')
    every = mailq_all(h.store)
    rows = [r for r in every
            if (not state or r.get('state') == state or
                (state == 'open' and r.get('state') in ('waiting', 'sending', 'failed')))]
    # The same words as every list (1.0.96): fields, values, OR, NOT, ~.
    try:
        keep = memory_search('mailq', MAILQ_SEARCH_TABLE, MAILQ_SEARCH_COLS,
                             [mailq_search_row(r) for r in rows], q) if q.strip() else None
    except ListQueryError as e:
        return {'rows': [], 'total': 0, 'q_error': str(e),
                'counts': {k: 0 for k in MAILQ_STATES}, 'node': node_name(),
                'retry_hours': int(CONFIG.get('mail_retry_hours') or 24),
                'keep_days': int(CONFIG.get('mail_keep_days') or 14),
                'mode': CONFIG.get('mail_mode') or 'off'}
    if keep is not None:
        rows = [rows[i] for i in sorted(keep)]
    limit, offset = h.num('limit', 100, 1, 1000), h.num('offset', 0)
    counts = collections.Counter(r.get('state') for r in every)
    MAILQ_COUNT_CACHE[0] = 0
    return {'rows': [mailq_view(r) for r in rows[offset:offset + limit]], 'total': len(rows),
            'counts': {k: int(counts.get(k, 0)) for k in MAILQ_STATES},
            'node': node_name(), 'retry_hours': int(CONFIG.get('mail_retry_hours') or 24),
            'keep_days': int(CONFIG.get('mail_keep_days') or 14),
            'mode': CONFIG.get('mail_mode') or 'off'}


@route('GET', '/api/mailq/one')
def _mailq_one(h):
    h.me()
    rec, _raw = mailq_read(h.store, h.arg('id'))
    if not rec:
        raise ApiError(404, 'that mail is not in the outgoing mail any more')
    out = mailq_view(rec)
    out['history'] = rec.get('history') or []
    out['steps'] = rec.get('steps') or []
    out['has_body'] = bool(h.store.get_meta(MAILB_PREFIX + h.arg('id')))
    return out


@route('POST', '/api/mailq')
def _mailq_do(h):
    s = h.me('tokenadmin')
    b = h.body()
    act = str(b.get('action') or '')
    ids = b.get('ids') or []
    if not isinstance(ids, list) or not all(isinstance(x, str) and
                                            re.fullmatch(r'[0-9]{13}-[0-9a-f]{8}', x)
                                            for x in ids):
        raise ApiError(400, 'ids is a list of the mails\' own ids')
    if act in ('retry_all', 'drop_sent', 'drop_failed'):
        want = {'retry_all': ('waiting', 'failed'), 'drop_sent': ('sent',),
                'drop_failed': ('failed', 'expired')}[act]
        ids = [r['qid'] for r in mailq_all(h.store) if r.get('state') in want]
        act = 'retry' if act == 'retry_all' else 'drop'
    MAILQ_COUNT_CACHE[0] = 0
    if act == 'retry':
        if (CONFIG.get('mail_mode') or 'off') == 'off':
            raise ApiError(409, 'sending mail is switched off - Settings → Mail')
        done, skipped = mailq_retry(h.store, ids, s['name'])
        codes = MAILQ_RETRY_WHY.get('code', 0)
        rest = len(skipped) - codes
        msg = '%d mail(s) are being sent again now' % len(done)
        if codes:
            # Said for what it is (1.0.103): a code past its time.
            msg += ' - %d code(s) to sign in with are past their time and no good any more' % codes
        if rest:
            msg += ' - %d could not be (sent already, or what they held is gone)' % rest
        return {'done': len(done), 'skipped': len(skipped), 'message': msg}
    if act == 'drop':
        n = mailq_drop(h.store, ids, s['name'])
        return {'done': n, 'message': '%d mail(s) taken out of the outgoing mail' % n}
    raise ApiError(400, 'no such thing to do with the outgoing mail')


@route('GET', '/api/dashboard')
def _dashboard(h):
    h.me()
    return h.store.overview(h.num('hours', 24, 1, 24 * 400),
                            since=h.num('since', 0, 0, 10 ** 11) or None,
                            until=h.num('until', 0, 0, 10 ** 11) or None)


def list_query(listname, text):
    """(query, error words): what a search box asked, read as fields."""
    try:
        return ListQuery(listname, text), ''
    except ListQueryError as e:
        return None, str(e)


@route('GET', '/api/suggest')
def _suggest(h):
    """The fields of one list, or what one of them holds - what the search
    box over the list offers as somebody types (1.0.19)."""
    h.me()
    name = h.arg('list')
    if name not in LIST_FIELDS:
        raise ApiError(400, 'no such list')
    field = h.arg('field').lower()
    if not field:
        said = LIST_FIELD_SAYS.get(name) or LIST_FIELD_SAYS.get('radius')
        return {'fields': [list(f) for f in said]}
    hours = h.num('hours', 0, 0, 24 * 3650)
    # What the log held in the last 90 days when no time is given (1.0.101):
    # the whole log counted again on every key pressed was seconds a time.
    since = time.time() - (hours or 24 * 90) * 3600 if name in ('radius', 'otp', 'events') \
        else (time.time() - hours * 3600 if hours else 0)
    typed = h.arg('typed')[:120]
    if name == 'mailq':
        # Its rows are in no table: what the field holds, counted here.
        col = (LIST_FIELDS['mailq'].get(field) or ('', ''))[0]
        got = collections.Counter()
        for r in mailq_all(h.store):
            v = str(mailq_search_row(r).get(col) or '')
            for one in (v.split() if col == 'to_addr' else [v]):
                if one and (not typed or typed.strip('*').lower() in one.lower()):
                    got[one] += 1
        return {'values': [{'val': v, 'n': n} for v, n in got.most_common(15)]}
    if name == 'radius':
        # The Log is two lists in one: a field either of them holds.
        got = h.reader.list_values('radius', field, typed, since)
        more = h.reader.list_values('otp', field, typed, since)
        seen = {g['val'].lower(): g for g in got}
        for m in more:
            if m['val'].lower() in seen:
                seen[m['val'].lower()]['n'] += m['n']
            else:
                got.append(m)
        got.sort(key=lambda x: -x['n'])
        return {'values': got[:15]}
    return {'values': h.reader.list_values(name, field, typed, since)}


@route('GET', '/api/radius')
def _radius(h):
    h.me()
    lq, bad = list_query('radius', h.arg('q'))
    if bad:
        return {'rows': [], 'total': 0, 'q_error': bad, 'clients': []}
    rows, total = h.reader.radius_rows(
        hours=h.num('hours', 24, 1, 24 * 3650), q=lq.words, extra=(lq.sql, lq.args),
        result=h.arg('result'),
        client=h.arg('client'), limit=h.num('limit', 100, 1, 1000),
        offset=h.num('offset', 0), sort=h.arg('sort', 'ts'),
        desc=h.arg('desc', '1') != '0', user=h.arg('user'))
    return {'rows': rows, 'total': total,
            'clients': [c['name'] for c in h.store.clients()]}


@route('GET', '/api/activity')
def _activity(h):
    """The one log of the pages: every RADIUS request - with what the token
    said about its code - and every code checked anywhere else (the
    enrolment pages, a test, the command line), newest first."""
    h.me()
    hours = h.num('hours', 24, 1, 24 * 3650)
    q, kind, result = h.arg('q'), h.arg('kind'), h.arg('result')
    client = h.arg('client')
    limit, offset = h.num('limit', 100, 1, 1000), h.num('offset', 0, 0, 10 ** 9)
    if offset > 20000:
        # Said, not quietly turned into page 200 again (1.0.57).
        raise ApiError(400, 'that is further back than these pages go: narrow the time window '
                            'or the search')
    want = offset + limit
    out, total = [], 0
    rq, bad = list_query('radius', q)
    oq, bad2 = list_query('otp', q)
    if bad or bad2:
        return {'rows': [], 'total': 0, 'q_error': bad or bad2,
                'clients': [c['name'] for c in h.store.clients()]}
    # One hour of the chart, counted and paged here (1.0.36): picked out of
    # the first page in the browser, the count was the day's, and an older
    # hour came out empty.
    since, until = h.num('since', 0, 0, 10 ** 11), h.num('until', 0, 0, 10 ** 11)

    def span(sql, args):
        parts, args = ([sql] if sql else []), list(args or [])
        if since:
            parts.append('ts >= ?')
            args.append(since)
        if until:
            parts.append('ts < ?')
            args.append(until)
        return ' AND '.join('(%s)' % x for x in parts), args
    rq.sql, rq.args = span(rq.sql, rq.args)
    oq.sql, oq.args = span(oq.sql, oq.args)
    if kind != 'codes':
        rows, n = h.reader.radius_rows(hours=hours, q=rq.words, extra=(rq.sql, rq.args),
                                      result=result, client=client, limit=want, offset=0)
        total += n
        for r in rows:
            out.append({'kind': 'radius', 'id': r['id'], 'ts': r['ts'], 'name': r.get('username'),
                        'realm': r.get('realm'), 'result': r.get('result'),
                        'why': r.get('reason') or r.get('otp') or '',
                        'code': r.get('otp') or '', 'source': r.get('client') or '',
                        'from': r.get('calling') or r.get('src') or '',
                        'device': r.get('device') or '', 'ms': r.get('took_ms'),
                        'node': r.get('node') or ''})
    if kind != 'radius' and not client and result in ('', 'access', 'accept', 'reject'):
        ok = None if result in ('', 'access') else result == 'accept'
        rows, n = h.reader.otp_rows(hours=hours, q=oq.words, ok=ok, limit=want, offset=0,
                                   not_how='radius', extra=(oq.sql, oq.args))
        total += n
        for r in rows:
            out.append({'kind': 'code', 'id': r['id'], 'ts': r['ts'], 'name': r.get('name'),
                        'result': 'accept' if r.get('ok') else 'reject',
                        'why': r.get('said') or '', 'code': r.get('said') or '',
                        'source': r.get('how') or '', 'from': r.get('src') or '',
                        'device': '', 'ms': None, 'rid': r.get('rid') or '',
                        'node': r.get('node') or ''})
    out.sort(key=lambda x: (x['ts'] or 0, x['id']), reverse=True)
    return {'rows': out[offset:offset + limit], 'total': min(total, 20000 + limit),
            'more_than': total > 20000 + limit,
            'clients': [c['name'] for c in h.store.clients()]}


@route('GET', '/api/radius/row')
def _radius_row(h):
    h.me()
    r = h.store.radius_row(h.num('id', 0))
    if not r:
        raise ApiError(404, 'there is no such request')
    return {'row': r}


@route('GET', '/api/otp')
def _otp(h):
    h.me()
    ok = h.arg('ok')
    rows, total = h.store.otp_rows(hours=h.num('hours', 24, 1, 24 * 3650), q=h.arg('q'),
                                   ok=None if ok == '' else ok == '1',
                                   limit=h.num('limit', 100, 1, 1000),
                                   offset=h.num('offset', 0), name=h.arg('name'))
    return {'rows': rows, 'total': total}


# ---- the tokens -----------------------------------------------------------------------
@route('GET', '/api/tokens')
def _tokens(h):
    h.me()
    lq, bad = list_query('tokens', h.arg('q'))
    if bad:
        return {'rows': [], 'total': 0, 'q_error': bad, 'counts': h.store.token_counts()}
    rows, total = h.store.tokens(q=lq.words, extra=(lq.sql, lq.args), state=h.arg('state'),
                                 limit=h.num('limit', 100, 1, 5000), offset=h.num('offset', 0),
                                 sort=h.arg('sort', 'name'), desc=h.arg('desc') == '1',
                                 kind=h.arg('kind'))
    for r in rows:
        r['last_client'] = h.store.client_name_of(r)
    # What "as the setting" is, for the table to show (1.0.85).
    return {'rows': rows, 'total': total, 'counts': h.store.token_counts(),
            'lang_default': code_lang(),
            'fmt_default': 'text' if CONFIG.get('code_mail_fmt') == 'text' else 'html'}


def totp_file_text(tok):
    """One token as the file totpcgi (google-authenticator) keeps for it:
    the key, its options, the recovery codes not used yet - what the import
    reads back (1.0.20)."""
    secret = unseal_secret(tok.get('secret') or '', token_bind(tok.get('name')))
    if not secret:
        return None
    lines = [secret]
    tries = int(CONFIG.get('rate_limit_tries') or 0)
    if tries:
        lines.append('" RATE_LIMIT %d %d' % (tries, int(CONFIG.get('rate_limit_s') or 30)))
    w = tok.get('window_steps')
    w = Tokens.window(tok)     # the same as the check uses: 0 is 0 (1.0.36)
    lines.append('" WINDOW_SIZE %d' % (w * 2 + 1))
    if CONFIG.get('totp_disallow_reuse'):
        lines.append('" DISALLOW_REUSE')
    lines.append('" TOTP_AUTH')
    for c in codes_open(tok) or []:
        if isinstance(c, dict):
            if not c.get('used'):
                lines.append(str(c.get('c')))
        else:
            lines.append(str(c))
    return '\n'.join(lines) + '\n'


@route('GET', '/api/tokens/export')
def _tokens_export(h):
    """Tokens as totpcgi files: one token as its .totp, several as a ZIP of
    them. Every key in it signs its owner in, so: a full administrator only,
    where showing keys is allowed, and every export written down."""
    s = h.me('fulladmin')
    if not CONFIG.get('admin_show_key'):
        raise ApiError(403, 'showing the keys of tokens is switched off (Settings - Tokens)')
    one = norm_name(h.arg('name'))
    if one:
        tok = h.store.token(one)
        if not tok:
            raise ApiError(404, 'there is no token for %s' % one)
        if token_kind(tok) != 'totp':
            raise ApiError(400, '%s gets its codes by mail or SMS: there is no key to export' % one)
        text = totp_file_text(tok)
        if text is None:
            raise ApiError(409, 'the key of this token cannot be opened on this machine')
        h.store.add_event('tokens', '%s exported the token of %s as a .totp file' % (
            s['name'], one), 'warn', who=s['name'])
        h.send_bytes(text.encode('utf-8'), totp_file_name(one),
                     'text/plain; charset=utf-8')
        return None
    lq, bad = list_query('tokens', h.arg('q'))
    if bad:
        raise ApiError(400, bad)
    rows, _ = h.store.tokens(q=lq.words, extra=(lq.sql, lq.args), state=h.arg('state'),
                             limit=100000)
    buf = io.BytesIO()
    done, lost, odd = 0, [], []
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as z:
        for r in rows:
            tok = h.store.token(r['name'])
            if token_kind(tok) != 'totp':
                continue                # codes by mail or SMS: no key to take away (1.0.76)
            text = totp_file_text(tok or {})
            if text is None:
                lost.append(r['name'])
                continue
            if int(tok.get('digits') or 6) != 6 or int(tok.get('period') or 30) != 30 or \
                    str(tok.get('algorithm') or 'SHA1').upper() != 'SHA1':
                odd.append('%s (%s digits, %s s, %s)' % (r['name'], tok.get('digits'),
                                                         tok.get('period'), tok.get('algorithm')))
            z.writestr(totp_file_name(r['name']), text)
            done += 1
        notes = ['%d token(s) exported by %s on %s at %s.' % (
            done, s['name'], node_name(), time.strftime('%Y-%m-%d %H:%M:%S')), '',
            'Each file is what totpcgi (google-authenticator) keeps for one person: the key,',
            'its options and the recovery codes not used yet. otp reads them back under',
            'Settings - Bringing tokens over, or: otp --import-totpcgi DIR', '']
        if odd:
            notes += ['Not 6 digits, 30 s and SHA-1 - totpcgi itself cannot check these:'] + \
                     ['  ' + x for x in odd] + ['']
        if lost:
            notes += ['Left out - their keys cannot be opened on this machine:'] + \
                     ['  ' + x for x in lost] + ['']
        notes += ['Every key here signs its owner in. Keep this file as you keep passwords.']
        z.writestr('README.txt', '\n'.join(notes) + '\n')
    h.store.add_event('tokens', '%s exported %d token(s) as .totp files%s' % (
        s['name'], done, (' (filter: %s)' % h.arg('q')) if h.arg('q') else ''), 'warn',
        who=s['name'])
    h.send_bytes(buf.getvalue(), 'otp-tokens-%s.zip' % time.strftime('%Y%m%d-%H%M%S'),
                 'application/zip')
    return None


def mailq_said(e):
    """A mail that did not go now, and what happens to it (1.0.95)."""
    if getattr(e, 'queued', None) == 'waiting':
        return ('not taken yet: %s - it waits in the outgoing mail and is tried again by '
                'itself (Settings → Mail)' % e)
    return str(e)


def mail_reply_words(steps):
    """What the receiving server said when it took the message, for the
    event: its queue id is what its own log can be searched by."""
    last = (steps or [{}])[-1].get('said', '') if steps else ''
    return (' - the server said: %s' % last.split(' · ', 1)[1]) if ' · ' in last else ''


def mailed_get(store, name):
    """Where a token's mail last went, and how (1.0.27): {to, lang, codes,
    at, by}, or {} when it never was mailed."""
    try:
        got = json.loads(store.get_meta('mailed:' + norm_name(name), '') or '{}')
        return got if isinstance(got, dict) else {}
    except ValueError:
        return {}


def mailed_set(store, name, to, lang, codes, by):
    store.set_meta('mailed:' + norm_name(name), json.dumps(
        {'to': to, 'lang': lang, 'codes': bool(codes), 'at': int(time.time()), 'by': by}))


def mailed_drop(store, name):
    store.db.run('DELETE FROM meta WHERE k = ?', ('mailed:' + norm_name(name),))


@route('GET', '/api/token')
def _token(h):
    h.me()
    name = norm_name(h.arg('name'))
    tok = h.store.token(name)
    checks, _ = h.store.otp_rows(hours=24 * 365, name=name, limit=30)
    reqs, _ = h.store.radius_rows(hours=24 * 365, user=name, limit=30)
    if not reqs and '@' not in name:
        reqs, _ = h.store.radius_rows(hours=24 * 365, q=name, limit=30)
    shown = h.store.token_shown(tok) if tok else None
    if shown:
        shown['last_client'] = h.store.client_name_of(tok)
    return {'token': shown, 'checks': checks, 'requests': reqs,
            'name': name, 'mailed': mailed_get(h.store, name) if tok else {}}


SEND_TEST_LOCK = threading.Lock()
SEND_TEST_SEEN = {}


@route('POST', '/api/token')
def _token_do(h):
    s = h.me('tokenadmin')
    b = h.body()
    act = str(b.get('action') or '')
    name = norm_name(b.get('name'))
    who = s['name']
    if act == 'fill_names':
        h.me('tokenadmin')
        got = h.d.fill_names(by=who)
        return dict(got, message='%d token(s) given their owner\'s name; %d not found in the '
                    'directory, %d with no directory to ask, %d could not be asked'
                    % (got['filled'], got['not_found'], got['no_directory'], got['trouble']))
    if not name:
        raise ApiError(400, 'which token?')
    if act == 'enroll' and not h.store.token(name):
        # A new token under its realm's own suffix (1.0.117): made for
        # novak@dpmo.local, it is novak@dpmo.cz where dpmo.local is another
        # suffix of that realm - the name RADIUS looks it up by.
        main = norm_name(realm_main_name(name, h.store.realm_for(name)))
        if main != name:
            name = main
    # One at a time per name, as a confirm is (1.0.61): switching off a
    # waiting token while its owner confirmed it switched it back on; a
    # rename takes the new name's lock as well, the two in one order.
    names = sorted({name, norm_name(b.get('to'))} if act == 'rename' and b.get('to')
                   else {name})
    locks = {id(lk): lk for lk in (h.d.tokens.lock_of(one) for one in names)}
    with contextlib.ExitStack() as held:
        for key in sorted(locks):       # always in one order, whoever takes two
            held.enter_context(locks[key])
        return _token_act(h, s, b, act, name, who)


def token_same_person(store, name):
    """Another name of the same person with a token in use - one RADIUS would
    stop using once `name` has one (1.0.139): under another suffix of the
    realm, or the same account in another realm on the same directory."""
    if '@' not in name:
        return ''
    realm = store.realm_for(name)
    if not realm:
        return ''
    cands = realm_names(name, realm)[1:]
    if realm.get('lookup') == 'sam' and realm.get('directory'):
        who = name.rpartition('@')[0]
        here = str(realm.get('directory') or '').lower()
        for r in store.realms():
            if r['id'] != realm['id'] and r.get('lookup') == 'sam' and \
                    str(r.get('directory') or '').lower() == here and \
                    r.get('suffix') not in (None, '', '*'):
                cands.append(Authenticator.token_name('%s@%s' % (who, r['suffix']), r))
    for c in cands:
        c = norm_name(c)
        t = store.token(c) if c != name else None
        if t and t.get('state') != 'pending':
            return c
    return ''


def _token_act(h, s, b, act, name, who):
    tk = h.d.tokens
    if act in ('disable', 'enable', 'unlock', 'note', 'window', 'drop_staged') and \
            not h.store.token(name):
        # Written by name, these made an empty token of a name that had none.
        # (1.0.36)
        raise ApiError(404, 'there is no token %s' % name)
    if act == 'enroll':
        had = h.store.token(name)
        if had and had.get('state') != 'pending' and s['role'] != 'fulladmin':
            # Replacing a token in use hands out a working key for somebody
            # else (1.0.57): a full administrator's to do. A token
            # administrator makes new ones.
            raise ApiError(403, '%s already has a token in use: only a full administrator '
                                'replaces it (or the person, on the enrolment pages)' % name)
        other = token_same_person(h.store, name) if s['role'] != 'fulladmin' else ''
        if other:
            # The same person under another name (1.0.139): the new token
            # would be the one RADIUS takes - a working key for somebody else.
            raise ApiError(403, '%s is the same person as %s, who has a token in use: only a '
                                'full administrator replaces it' % (name, other))
        display = str(b.get('display') or '').strip()
        note = b.get('note')
        if had and not str(note or '').strip():
            note = None             # a new key keeps the note it had (1.0.36)
        kind = str(b.get('kind') or 'totp')
        if kind in ('mail', 'sms'):
            # A token that gets its codes by mail or SMS (1.0.76): where they
            # go, and recovery codes - nothing to scan.
            try:
                got = tk.enroll_sent(name, 'admin:' + who, kind, b.get('dest'), display=display,
                                     note=note, lang=b.get('lang'))
            except ValueError as e:
                raise ApiError(400, str(e))
            if not display and not (had or {}).get('display'):
                try:
                    h.d.fill_names([name], quiet=True)
                except Exception:                       # noqa: BLE001
                    pass
            h.store.add_event('tokens', '%s %s a token for %s: codes by %s to %s' % (
                who, 'replaced' if had else 'made', name, 'mail' if kind == 'mail' else 'SMS',
                got['dest']), 'warn' if had else 'info', who=who)
            return {'made': got, 'message': 'the token for %s is made: its codes go by %s to %s'
                    % (name, 'mail' if kind == 'mail' else 'SMS', got['dest'])}
        if kind != 'totp':
            raise ApiError(400, 'a token is totp, mail or sms')
        got = tk.enroll(name, 'admin:' + who, pending=bool(b.get('pending')),
                        note=note, display=display)
        if not display and not (had or {}).get('display'):
            # The person's name from the directory at once (1.0.20), not when
            # somebody next presses Names from the directory.
            try:
                h.d.fill_names([name], quiet=True)
            except Exception:                           # noqa: BLE001
                pass
        h.store.add_event('tokens', '%s %s a token for %s' % (
            who, 'replaced' if had else 'made', name), 'warn' if had else 'info', who=who)
        out = {'made': got, 'message': 'the token for %s is made' % name}
        to = str(b.get('mail_to') or '').strip()
        if b.get('mail') and to:
            # Its QR code - and the recovery codes, where asked - to the person
            # it is for (1.0.20). The token stays made whatever the mail does.
            if not re.match(r'^[^@\s<>]+@[^@\s<>]+\.[^@\s<>]+\Z', to):
                out['mail_error'] = '%s is not a mail address' % to
                return out
            lang = str(b.get('mail_lang') or CONFIG.get('mail_lang') or 'cs')
            lang = lang if lang in MAIL_WORDS else 'cs'
            tokrow = h.store.token(name) or {}
            try:
                msg = token_mail(to, name, got, codes=got.get('scratch') if b.get('mail_codes')
                                 else None, lang=lang, display=str(b.get('display') or
                                                                   tokrow.get('display') or ''),
                                 by=who, pending=bool(b.get('pending')),
                                 portal_url=h.portal_link())
                steps = mail_deliver(h.store, msg, [to], kind='token', name=name, by=who,
                                     purpose='made')
                out['mail_steps'] = steps
                out['message'] += '; the QR code was sent to %s' % to
                h.store.add_event('mail', '%s sent the token of %s to %s%s%s' % (
                    who, name, to, ' with its recovery codes' if b.get('mail_codes') else '',
                    mail_reply_words(steps)), who=who)
                mailed_set(h.store, name, to, lang, b.get('mail_codes'), who)
            except MailError as e:
                out['mail_error'] = mailq_said(e)
                out['mail_steps'] = e.steps
                out['mail_queued'] = e.queued == 'waiting'
                h.store.add_event('mail', 'the token of %s could not be sent to %s: %s' % (
                    name, to, mailq_said(e)), 'warn', who=who)
        return out
    if not h.store.token(name):
        raise ApiError(404, 'there is no token for %s' % name)
    kind_now = token_kind(h.store.token(name))
    if kind_now != 'totp' and act in ('code_now', 'show', 'mail', 'stage'):
        raise ApiError(400, '%s gets its codes by %s: there is no key or QR code to show or send'
                       % (name, 'mail' if kind_now == 'mail' else 'SMS'))
    if act == 'dest':
        # Where a mail or SMS token's codes go (1.0.76). Of a token in use,
        # a full administrator's to change (1.0.94): it sends somebody's
        # sign-in codes elsewhere, as replacing the token would.
        if (h.store.token(name) or {}).get('state') != 'pending' and s['role'] != 'fulladmin':
            raise ApiError(403, 'the codes of a token in use go elsewhere only by a full '
                                'administrator\'s hand (or the person\'s, on the enrolment pages)')
        try:
            dest = tk.dest_change(name, b.get('dest'))
        except ValueError as e:
            raise ApiError(400, str(e))
        h.store.add_event('tokens', '%s changed where the codes of %s go: %s' % (who, name, dest),
                          'warn', who=who)
        return {'message': 'the codes of %s go to %s now' % (name, dest), 'dest': dest}
    if act in ('lang', 'mail_fmt'):
        # The language of a token's codes and questions, and whether its mail
        # is HTML or plain text (1.0.82). Empty: as the settings say.
        v = str(b.get('value') or '')
        if v not in (('', 'cs', 'en') if act == 'lang' else ('', 'html', 'text')):
            raise ApiError(400, 'no such choice: %s' % v)
        h.store.token_update(h.store.token(name)['id'], {act: v})
        h.store.add_event('tokens', '%s set the %s of %s: %s' % (
            who, 'language' if act == 'lang' else 'mail format', name, v or 'as the settings say'),
            who=who)
        return {'message': 'saved'}
    if act == 'send_test':
        # A message the way a code would go, with a code that opens nothing.
        tok = h.store.token(name)
        # Not without end (1.0.136): one a token in 30 s, ten in an hour -
        # a phone flooded, or a bill run up, from the pages.
        now = time.time()
        with SEND_TEST_LOCK:
            seen = [t for t in SEND_TEST_SEEN.get(name, []) if now - t < 3600]
            if seen and now - seen[-1] < 30:
                raise ApiError(429, 'a test went to %s a moment ago - wait half a minute' % name)
            if len(seen) >= 10:
                raise ApiError(429, 'ten tests went to %s in the last hour - that is enough'
                               % name)
            SEND_TEST_SEEN[name] = seen + [now]
            if len(SEND_TEST_SEEN) > 5000:
                SEND_TEST_SEEN.clear()
        began = time.time()
        try:
            said = code_send(h.store, kind_now, tok.get('dest') or '', code_new(), 'signin',
                             name=name)
        except (MailError, SmsError, ValueError) as e:
            h.store.add_event('tokens', 'a test code for %s could not be sent: %s' % (name, e),
                              'warn', who=who)
            raise ApiError(502, 'it could not be sent: %s' % e)
        h.store.add_event('tokens', '%s sent a test message to where the codes of %s go'
                          % (who, name), who=who)
        return {'message': 'sent to %s in %.1f s - %s' % (tok.get('dest'), time.time() - began,
                                                         said)}
    if act == 'code_now':
        # The code the phone shows right now (1.0.40): a full administrator
        # only - it signs that person in for half a minute - and every look
        # written down. Not the key: the code ages out by itself.
        h.me('fulladmin')
        # As the key itself (1.0.44): the code signs that person in, so it is
        # shown only where the key may be.
        if not CONFIG.get('admin_show_key'):
            raise ApiError(403, 'showing the key of a token is switched off '
                                '(Settings -> The tokens)')
        tok = h.store.token(name)
        if not tok:
            raise ApiError(404, 'there is no token %s' % name)
        secret = unseal_secret(tok.get('secret') or '', token_bind(tok.get('name')))
        if not secret:
            raise ApiError(409, 'the key of this token cannot be opened on this machine')
        key = b32_clean(secret)
        digits = int(tok.get('digits') or 6)
        period = int(tok.get('period') or 30)
        algo = tok.get('algorithm') or 'SHA1'
        now = time.time()
        step = totp_step(now, period)
        # Written down whatever the page says (1.0.44): once per person and
        # token in five minutes, so the page asking for the next code every
        # half minute does not fill the events.
        seen_key = (who, name)
        with CODE_NOW_LOCK:
            last = CODE_NOW_SEEN.get(seen_key, 0)
            if b.get('first') or now - last > 300:
                CODE_NOW_SEEN[seen_key] = now
                fresh = True
            else:
                fresh = False
            if len(CODE_NOW_SEEN) > 2000:
                CODE_NOW_SEEN.clear()
        if fresh:
            h.store.add_event('tokens', '%s looked at the code the token of %s shows now'
                              % (who, name), 'warn', who=who)
        return {'code': hotp(key, step, digits, algo), 'next': hotp(key, step + 1, digits, algo),
                'period': period, 'digits': digits, 'now': now,
                'ends': (step + 1) * period, 'state': tok.get('state')}
    if act == 'show':
        # The key of somebody's second factor: a full administrator only,
        # where the setting allows it, and every look written down.
        h.me('fulladmin')
        if not CONFIG.get('admin_show_key'):
            raise ApiError(403, 'showing the key of a token is switched off '
                                '(Settings -> The tokens)')
        tok = h.store.token(name)
        staged = bool(tok.get('pending_secret')) and b.get('which') == 'waiting'
        secret = unseal_secret((tok.get('pending_secret') if staged else tok.get('secret')) or '',
                               token_bind(tok.get('name')))
        if not secret:
            raise ApiError(409, 'the key of this token cannot be opened (the key file of the '
                                'database is not the one it was sealed with)')
        if staged:
            # The waiting key in its own shape (1.0.32), not the old token's.
            sh = tk.staged_shape(name)
            got = tk.picture(name, secret, sh['digits'], sh['period'], sh['algorithm'],
                             sh['issuer'] or None)
        else:
            got = tk.picture(name, secret, tok.get('digits'), tok.get('period'),
                             tok.get('algorithm'), tok.get('issuer'))
        got['name'] = name
        got['scratch'] = []
        h.store.add_event('tokens', '%s looked at the key of the %stoken of %s'
                          % (who, 'waiting ' if staged else '', name), 'warn', who=who)
        return {'made': got}
    if act == 'codes':
        # The recovery codes left, shown again: the same rule as the key.
        h.me('fulladmin')
        if not CONFIG.get('admin_show_key'):
            raise ApiError(403, 'showing the key of a token is switched off '
                                '(Settings -> The tokens)')
        tok = h.store.token(name)
        codes = codes_open(tok)
        if codes is None:
            raise ApiError(409, 'the recovery codes of this token were not kept to be shown '
                                'again (it was made by an older version); make new ones')
        h.store.add_event('tokens', '%s looked at the recovery codes of %s' % (who, name),
                          'warn', who=who)
        return {'scratch': codes}
    if act == 'mail':
        # The token's QR code mailed again (1.0.27). The key leaves the
        # machine as when it is shown, so the same rule: a full administrator,
        # where showing keys is allowed.
        h.me('fulladmin')
        if not CONFIG.get('admin_show_key'):
            raise ApiError(403, 'showing - and so mailing - the key of a token is switched off '
                                '(Settings -> The tokens)')
        to = str(b.get('mail_to') or '').strip()
        if not re.match(r'^[^@\s<>]+@[^@\s<>]+\.[^@\s<>]+\Z', to):
            raise ApiError(400, '%s is not a mail address' % (to or 'nothing'))
        tok = h.store.token(name)
        secret = unseal_secret(tok.get('secret') or '', token_bind(tok.get('name')))
        if not secret:
            raise ApiError(409, 'the key of this token cannot be opened (the key file of the '
                                'database is not the one it was sealed with)')
        got = tk.picture(name, secret, tok.get('digits'), tok.get('period'),
                         tok.get('algorithm'), tok.get('issuer'))
        codes = None
        if b.get('mail_codes'):
            kept = codes_open(tok)
            if kept is None:
                raise ApiError(409, 'the recovery codes of this token were not kept to be sent '
                                    'again; send it without them, or make new ones first')
            codes = [c['c'] for c in kept if not c.get('used')]
        lang = str(b.get('mail_lang') or CONFIG.get('mail_lang') or 'cs')
        lang = lang if lang in MAIL_WORDS else 'cs'
        try:
            msg = token_mail(to, name, got, codes=codes, lang=lang,
                             display=str(tok.get('display') or ''), by=who,
                             pending=tok.get('state') == 'pending',
                             portal_url=h.portal_link())
            steps = mail_deliver(h.store, msg, [to], kind='token', name=name, by=who,
                                 purpose='again')
        except MailError as e:
            h.store.add_event('mail', 'the token of %s could not be sent to %s: %s' % (
                name, to, mailq_said(e)), 'warn', who=who)
            return {'sent': False, 'said': mailq_said(e), 'steps': e.steps,
                    'queued': e.queued == 'waiting'}
        mailed_set(h.store, name, to, lang, codes, who)
        h.store.add_event('mail', '%s sent the token of %s to %s again%s%s' % (
            who, name, to, ' with its recovery codes' if codes else '',
            mail_reply_words(steps)), 'warn', who=who)
        return {'sent': True, 'steps': steps, 'message': 'sent to %s' % to,
                'mailed': mailed_get(h.store, name)}
    if act in ('disable', 'enable'):
        if act == 'enable' and (h.store.token(name) or {}).get('state') != 'disabled':
            # Not switched off: nothing to switch on (1.0.61) - a waiting
            # token was made active by it.
            return {'message': 'it is not switched off'}
        h.store.token_write(name, {'state': token_switch_state(h.store, name, act == 'enable'),
                                   'failures': 0, 'fail_times': '[]', 'locked_until': None})
        h.store.add_event('tokens', '%s switched the token of %s %s' % (
            who, name, 'off' if act == 'disable' else 'on'), who=who)
        return {'message': 'switched %s' % ('off' if act == 'disable' else 'on')}
    if act == 'delete':
        # A token in use taken away, then made anew, was a token administrator's
        # way round the rule that only a full administrator replaces one
        # (1.0.94): switching it off is theirs, taking it away is not.
        if (h.store.token(name) or {}).get('state') not in ('pending', None) and \
                s['role'] != 'fulladmin':
            raise ApiError(403, 'only a full administrator takes away a token in use - '
                                'switch it off instead')
        h.store.token_drop(name)
        mailed_drop(h.store, name)
        tk._staged_forget(name)
        token_meta_forget(h.store, name)
        h.store.add_event('tokens', '%s took away the token of %s' % (who, name), 'warn',
                          who=who)
        return {'message': 'the token of %s is gone' % name}
    if act == 'scratch':
        # New recovery codes are working credentials of somebody else that
        # leave no trace on their phone (1.0.33): the same rule as showing a
        # key - a full administrator, where that is allowed - and a warning
        # in the events.
        h.me('fulladmin')
        if not CONFIG.get('admin_show_key'):
            raise ApiError(403, 'new recovery codes are shown to whoever makes them, and showing '
                                'codes and keys is switched off (Settings -> The tokens)')
        codes = tk.new_scratch(name, who)
        h.store.add_event('tokens', '%s made new recovery codes for %s' % (who, name), 'warn',
                          who=who)
        return {'scratch': codes, 'message': '%d new recovery codes' % len(codes)}
    if act == 'unlock':
        h.store.token_write(name, {'failures': 0, 'fail_times': '[]', 'locked_until': None})
        node_key_drop(h.store, 'scratchguard', name)
        scratch_guard_clear(name)
        h.store.add_event('tokens', '%s let %s try again at once' % (who, name), who=who)
        return {'message': 'the wrong codes are forgotten'}
    if act == 'rename':
        h.me('fulladmin')       # with a key known, a rename makes it somebody else's (1.0.57)
        # Into another realm: the part after the @ changes, and with it the
        # name the VPN has to send. The key and the history stay; the
        # recovery codes are made again under the new name where they were
        # kept to be shown, since their hashes are of the name too. (1.0.11)
        to = norm_name(b.get('to'))
        # The same rule as a new token's (1.0.44).
        if not to or not re.match(r'^[^\s@,;=\x00-\x1f\x7f]+(@[A-Za-z0-9.-]+)?\Z', to) or \
                len(to) > 180 or not isinstance(b.get('to'), str):
            raise ApiError(400, 'that is not a name: a name, or a name@realm - no spaces, '
                                'commas, semicolons or =, 180 characters at most')
        if to == norm_name(name):
            raise ApiError(400, 'that is the name it has')
        if h.store.token(to):
            raise ApiError(409, 'there is a token for %s already' % to)
        tok = h.store.token(name)
        if tok.get('pending_secret'):
            raise ApiError(409, 'a new key is waiting for a code from it: confirm it or throw it '
                                'away first')
        fields = {'name': to}
        codes = codes_open(tok)
        kept = True
        # Its sealed secrets are tied to its name: sealed again for the new
        # one (1.0.33), or they would no longer open.
        plain = unseal_secret(tok.get('secret') or '', token_bind(tok.get('name')))
        if plain:
            fields['secret'] = seal_secret(plain, token_bind(to))
        if codes is not None:
            fields['scratch'] = json.dumps([scratch_hash(to, c['c']) if isinstance(c, dict)
                                            else scratch_hash(to, c) for c in codes
                                            if not (isinstance(c, dict) and c.get('used'))])
            fields['scratch_sealed'] = seal_codes(codes, token_bind(to))
            fields['scratch_left'] = len(json.loads(fields['scratch']))     # 1.0.61
        elif tok.get('scratch_left'):
            kept = False
            fields.update(scratch='[]', scratch_left=0)
        # Moved to somebody else, the owner's name is theirs now (1.0.19).
        if norm_name(to).split('@', 1)[0] != norm_name(name).split('@', 1)[0]:
            fields['display'] = ''
        h.store.db.update('tokens', tok['id'], fields)
        h.store.db.run('UPDATE otp_log SET name = ? WHERE name = ?', (to, tok['name']))
        # What was kept aside under the old name goes with it (1.0.61).
        h.store.db.run('UPDATE meta SET k = ? WHERE k = ?',
                       ('disabled_from:' + norm_name(to), 'disabled_from:' + norm_name(name)))
        # Where its mail went goes with it - but only within the same
        # person: somebody else's token is not mailed to the old address.
        was = mailed_get(h.store, name)
        mailed_drop(h.store, name)
        if was and not fields.get('display') == '':
            mailed_set(h.store, to, was.get('to'), was.get('lang'), was.get('codes'),
                       was.get('by'))
        if fields.get('display') == '':
            h.d.fill_names_later([to])
        h.store.add_event('tokens', '%s moved the token of %s to %s' % (who, tok['name'], to),
                          'warn', who=who)
        return {'name': to, 'message': 'the token is now %s%s' % (
            to, '' if kept else '; its recovery codes were not kept to be made again under the '
                                'new name, so make new ones')}
    if act == 'note':
        h.store.token_write(name, {'note': str(b.get('note') or '')[:400]})
        h.store.add_event('tokens', '%s changed the note of %s' % (who, name), who=who)
        return {'message': 'the note is saved'}
    if act == 'window':
        w = int(b.get('window', -1))
        if not -1 <= w <= 20:
            raise ApiError(400, 'the window is -1 (the setting) or 0 to 20 steps')
        h.store.token_write(name, {'window_steps': w})
        h.store.add_event('tokens', '%s set the clock drift of %s to %s' % (
            who, name, 'the setting' if w < 0 else '%d step(s)' % w), who=who)
        return {'message': 'saved'}
    if act == 'test':
        # Counted per administrator and token (1.0.57): a dry test counts
        # nothing on the token, and so could be asked without end.
        h.throttle('code-test', 10, 5, name='%s>%s' % (who, name), name_tries=10)
        ok, said, facts = tk.check(name, str(b.get('code') or ''), how='test',
                                   src=h.client_ip(), dry=not b.get('use'))
        if not ok:
            h.failed('code-test')
        return {'good': ok, 'said': said, 'facts': facts}
    if act == 'confirm':
        ok, said = tk.confirm(name, str(b.get('code') or ''), how='admin', src=h.client_ip())
        if ok:
            h.store.add_event('tokens', '%s confirmed the token of %s' % (who, name), who=who)
        return {'good': ok, 'said': said}
    if act == 'drop_staged':
        tk.drop_staged(name)
        h.store.add_event('tokens', '%s threw away the replacement waiting for %s' % (who, name),
                          who=who)
        return {'message': 'the waiting replacement is gone; the old token stays'}
    raise ApiError(400, 'no such thing to do to a token: %s' % act)


def totp_file_name(name):
    """The file a token goes into, and its name read back from it (1.0.146):
    jan+1@x.cz and jan_1@x.cz were both jan_1@x.cz.totp - one lost in the ZIP
    - and o'neil@x.cz came back as o_neil@x.cz, which RADIUS never looks up."""
    from urllib.parse import quote
    return quote(str(name), safe='@.-_') + '.totp'


def totp_file_owner(fname):
    from urllib.parse import unquote
    fname = os.path.basename(str(fname or ''))
    return unquote(fname[:-5] if fname.endswith('.totp') else fname)


def totp_files_in_zip(b64, label, out):
    """The .totp files inside a ZIP the page sent (1.0.33) - a totpcgi
    folder zipped, or another otp's export. Read in memory with limits on
    everything: how big, how many, how far it unpacks. Nothing is written to
    disk and no name inside is used as a path."""
    try:
        raw = base64.b64decode(str(b64), validate=True)
    except (ValueError, binascii.Error):
        out.append({'name': label, 'said': 'not imported: not a ZIP the page could send'})
        return []
    got = []
    try:
        with zipfile.ZipFile(io.BytesIO(raw)) as z:
            infos = z.infolist()
            if len(infos) > 50000:
                raise ValueError('more than 50 000 files in it')
            total = 0
            for info in infos:
                base = info.filename.replace('\\', '/').rsplit('/', 1)[-1]
                if info.is_dir() or not base.endswith('.totp') or base.startswith('.') or \
                        '__MACOSX/' in info.filename:
                    continue
                if info.file_size > 64 * 1024:
                    out.append({'name': base, 'said': 'not imported: too big for a .totp file'})
                    continue
                total += info.file_size
                if total > 64 * 1024 * 1024:
                    raise ValueError('it unpacks to more than 64 MB')
                with z.open(info) as f:
                    data = f.read(64 * 1024 + 1)
                if len(data) > 64 * 1024:
                    out.append({'name': base, 'said': 'not imported: too big for a .totp file'})
                    continue
                got.append({'name': base, 'text': data.decode('utf-8', 'replace')})
    except (zipfile.BadZipFile, ValueError, RuntimeError, NotImplementedError) as e:
        out.append({'name': label, 'said': 'not imported: %s' % e})
        return []
    if not got:
        out.append({'name': label, 'said': 'not imported: no .totp file in it'})
    return got


@route('POST', '/api/tokens/backup')
def _tokens_backup(h):
    """Every token chosen, of every kind, as one file (1.0.96): locked with
    a passphrase when one is given. A full administrator's, where keys may
    be shown, and written down."""
    s = h.me('fulladmin')
    if not CONFIG.get('admin_show_key'):
        raise ApiError(403, 'showing the keys of tokens is switched off (Settings - Tokens)')
    b = h.body()
    lq, bad = list_query('tokens', str(b.get('q') or ''))
    if bad:
        raise ApiError(400, bad)
    kind = str(b.get('kind') or '')
    rows, _ = h.store.tokens(q=lq.words, extra=(lq.sql, lq.args), state=str(b.get('state') or ''),
                             limit=1000000, kind=kind if kind in ('totp', 'mail', 'sms') else '')
    data = tokens_backup(h.store, [r['name'] for r in rows], s['name'])
    phrase = str(b.get('passphrase') or '')
    # Always locked (1.0.136): every key and recovery code is in it.
    if len(phrase) < 8:
        raise ApiError(400, 'a passphrase of 8 characters at least: the file holds every key')
    text = json.dumps(bundle_lock(data, phrase, kind=TOKENS_KIND), indent=1)
    h.store.add_event('tokens', '%s backed up %d token(s)%s%s' % (
        s['name'], data['count'], ' locked with a passphrase' if phrase else ' (not locked)',
        (' - %d left out, their keys cannot be opened here' % len(data['lost']))
        if data['lost'] else ''), 'warn', who=s['name'])
    return {'file': text, 'count': data['count'], 'lost': data['lost'], 'locked': bool(phrase),
            'name': 'otp-tokens-%s-%s.json' % (re.sub(r'[^A-Za-z0-9_-]', '_', node_name()),
                                               time.strftime('%Y%m%d-%H%M'))}


@route('POST', '/api/token/import')
def _token_import(h):
    s = h.me('fulladmin')
    b = h.body()
    out = []
    files = []
    # A whole backup (1.0.96): looked into first ("peek"), then all of it
    # or the tokens picked read back. .totp files and ZIPs of them as ever.
    phrase = str(b.get('passphrase') or '')
    want = set(norm_name(x) for x in (b.get('names') or []) if isinstance(x, str))
    repl_names = set(norm_name(x) for x in (b.get('replace_names') or []) if isinstance(x, str))
    backups = []
    for one in b.get('files') or []:
        if not isinstance(one, dict) or one.get('zip'):
            continue
        try:
            got = tokens_backup_open(str(one.get('text') or ''), phrase)
        except PermissionError as e:
            raise ApiError(423, str(e))
        except ValueError as e:
            raise ApiError(400, '%s: %s' % (one.get('name') or 'the file', e))
        if got is not None:
            backups.append((one, got))
    if backups:
        if b.get('action') == 'peek':
            seen = []
            cols = sorted(set([c for c, _k in LIST_FIELDS['tokens'].values() if c] +
                              list(LIST_WORD_COLUMNS['tokens'])))
            nums = set(c for c, k in LIST_FIELDS['tokens'].values() if k == 'num')
            table = 'CREATE TABLE t (i INTEGER, %s)' % ', '.join(
                '%s %s' % (c, 'INTEGER' if c in nums else 'TEXT') for c in cols)
            mem = []
            for one, got in backups:
                for t in got['tokens']:
                    if not isinstance(t, dict):
                        continue
                    n = norm_name(t.get('name'))
                    seen.append({'name': n, 'kind': t.get('kind') or 'totp',
                                 'dest': t.get('dest') or '', 'state': t.get('state') or '',
                                 'codes': len([c for c in t.get('codes') or []
                                               if not (isinstance(c, dict) and c.get('used'))]),
                                 'display': t.get('display') or '', 'here': bool(h.store.token(n))})
                    left = len([c for c in t.get('codes') or []
                                if not (isinstance(c, dict) and c.get('used'))])
                    mem.append({'name': n, 'state': t.get('state') or '',
                                'kind': '' if (t.get('kind') or 'totp') == 'totp' else t.get('kind'),
                                'dest': t.get('dest') or '', 'lang': t.get('lang') or '',
                                'mail_fmt': t.get('mail_fmt') or '', 'note': t.get('note') or '',
                                'display': t.get('display') or '',
                                'created_by': t.get('created_by') or '',
                                'last_from': t.get('last_from') or '',
                                'last_how': t.get('last_how') or '', 'scratch_left': left,
                                'failures': 0, 'digits': int(t.get('digits') or 6)})
            # Searched with the words of the token list (1.0.96).
            q = str(b.get('q') or '')
            if q.strip():
                try:
                    keep = set(memory_search('tokens', table, cols, mem, q))
                except ListQueryError as e:
                    return {'q_error': str(e), 'backup': {'tokens': [], 'count': len(seen)}}
                seen = [x for i, x in enumerate(seen) if i in keep]
            first = backups[0][1]
            return {'backup': {'count': len(mem), 'shown': len(seen), 'made': first.get('made') or first.get('_made'),
                               'by': first.get('by'), 'node': first.get('node') or first.get('_from'),
                               'version': first.get('version'), 'lost': first.get('lost') or [],
                               'tokens': seen}}
        for one, got in backups:
            for t in got['tokens']:
                n = norm_name((t or {}).get('name') if isinstance(t, dict) else '')
                if want and n not in want:
                    continue
                try:
                    # Replaced one by one as the page chose (1.0.100), or all.
                    said = token_restore(h.store, t, 'restore:' + s['name'],
                                         replace=bool(b.get('replace')) or n in repl_names)
                except (ValueError, TypeError) as e:
                    said = 'not restored: %s' % e
                out.append({'name': n, 'said': said})
        h.store.add_event('tokens', '%s restored %d token(s) from a backup' % (
            s['name'], len([o for o in out if str(o['said']).startswith('restored')])),
            'warn', who=s['name'])
        return {'done': out}
    for one in b.get('files') or []:
        if one.get('zip'):
            files.extend(totp_files_in_zip(one.get('zip'), str(one.get('name') or 'the ZIP'),
                                           out))
        else:
            files.append(one)
    for one in files:
        fname = os.path.basename(str(one.get('name') or ''))
        name = totp_file_owner(fname)
        if want and norm_name(name) not in want:
            continue
        try:
            said = import_totp(h.store, name, str(one.get('text') or ''), 'import:' + s['name'],
                               replace=bool(b.get('replace')))
        except ValueError as e:
            said = 'not imported: %s' % e
        out.append({'name': norm_name(name), 'said': said})
    h.store.add_event('tokens', '%s imported %d token file(s)' % (s['name'], len(out)),
                      who=s['name'])
    # Their owners' names from the directory, as an enrolment on the pages
    # would have given them - in the background, the list is not kept waiting.
    h.d.fill_names_later([o['name'] for o in out if str(o['said']).startswith('imported')],
                         by=s['name'])
    return {'done': out}


# ---- clients, realms, directories -----------------------------------------------------
@route('GET', '/api/clients')
def _clients(h):
    s = h.me()
    clients = h.store.clients()
    if s['role'] != 'fulladmin':
        # Not even the last two characters to whoever cannot change it (1.0.33).
        for c in clients:
            c['secret'] = '••••••' if c.get('secret') else ''
    return {'clients': clients, 'realms': [r['name'] + ' (' + (r['suffix'] or '-')
                                                     + ')' for r in h.store.realms()],
            'suffixes': [r['suffix'] for r in h.store.realms() if r['suffix'] not in ('*', '')],
            'may_change': s['role'] == 'fulladmin'}


@route('POST', '/api/clients')
def _clients_do(h):
    s = h.me('fulladmin')
    b = h.body()
    act = b.get('action')
    if act == 'save':
        c = b.get('client') or {}
        ident = h.store.client_save(c, s['name'])
        h.store.add_event('clients', '%s saved the RADIUS client %s (%s)' % (
            s['name'], c.get('name'), c.get('address')), who=s['name'])
        h.d.changed('clients')
        return {'id': ident, 'message': 'the client %s is saved' % c.get('name')}
    if act == 'delete':
        one = next((c for c in h.store.clients() if c['id'] == _int_id(b.get('id'))), None)
        if not one:
            raise ApiError(404, 'there is no such client')     # 1.0.103
        h.store.client_drop(one['id'])
        h.store.add_event('clients', '%s took away the RADIUS client %s' % (
            s['name'], one.get('name')), 'warn', who=s['name'])
        h.d.changed('clients')
        return {'message': 'the client is gone'}
    if act == 'secret':
        h.me('fulladmin')
        one = next((c for c in h.store.clients(with_secret=True)
                    if c['id'] == int(b.get('id') or 0)), None)
        if not one:
            raise ApiError(404, 'no such client')
        h.store.add_event('clients', '%s looked at the shared secret of %s' % (
            s['name'], one['name']), who=s['name'])
        return {'secret': one['secret']}
    raise ApiError(400, 'no such thing to do to a client')


def realm_alias_tokens(store, realm):
    """Tokens kept under one of the realm's other suffixes (1.0.117) - made
    before it was one - with the name each would have now, and whether a
    token is there already under it."""
    out = []
    if realm.get('token_name') == 'bare' or realm.get('suffix') in (None, '', '*'):
        return out
    for al in realm.get('aliases') or []:
        for row in store.db.rows('SELECT name FROM tokens WHERE LOWER(name) LIKE ? '
                                 'ORDER BY name', ('%@' + al,)):
            to = norm_name(realm_main_name(row['name'], realm))
            out.append({'name': row['name'], 'to': to, 'clash': bool(store.token(to))})
            if len(out) >= 500:
                return out
    return out


@route('GET', '/api/realms')
def _realms(h):
    s = h.me()
    realms = h.store.realms()
    for r in realms:
        if r.get('aliases'):
            r['alias_tokens'] = realm_alias_tokens(h.store, r)
    return {'realms': realms, 'directories': [d['name'] for d in
                                                       h.store.directories()],
            'reply_attrs': list(REPLY_ATTRS), 'reply_catalogue': reply_catalogue(),
            'channels': code_channels(),            # mail, sms - set up (1.0.76)
            'may_change': s['role'] == 'fulladmin'}


@route('POST', '/api/realms')
def _realms_do(h):
    s = h.me('fulladmin')
    b = h.body()
    act = b.get('action')
    if act == 'save':
        r = b.get('realm') or {}
        absorb = [str(x) for x in (b.get('absorb') or []) if str(x).strip()][:10]
        before = {x['name'] for x in h.store.realms()}
        ident = h.store.realm_save(r, s['name'], absorb=absorb)
        gone = sorted(before - {x['name'] for x in h.store.realms()} - {r.get('name')})
        h.store.add_event('realms', '%s saved the realm %s%s' % (
            s['name'], r.get('name'), ('; taken into it: %s - their suffixes are its own now, '
                                       'their groups follow its own' % ', '.join(gone))
            if gone else ''), 'warn' if gone else 'info', who=s['name'])
        h.d.changed('realms')
        return {'id': ident, 'message': 'the realm %s is saved' % r.get('name')}
    if act == 'delete':
        one = next((r for r in h.store.realms() if r['id'] == _int_id(b.get('id'))), None)
        if not one:
            raise ApiError(404, 'there is no such realm')      # 1.0.103
        h.store.realm_drop(one['id'])
        h.store.add_event('realms', '%s took away the realm %s' % (s['name'], one['name']),
                          'warn', who=s['name'])
        h.d.changed('realms')
        return {'message': 'the realm is gone'}
    if act == 'move_alias_tokens':
        # Under the realm's own suffix (1.0.117), each as a rename is: the
        # key sealed again, the recovery codes kept, the log following it.
        # One that would land on a token already there is left as it is.
        one = next((r for r in h.store.realms() if r['id'] == _int_id(b.get('id'))), None)
        if not one:
            raise ApiError(404, 'there is no such realm')
        moved, left = [], []
        for t in realm_alias_tokens(h.store, one):
            if t['clash']:
                left.append(t['name'])
                continue
            names = sorted({t['name'], t['to']})
            locks = {id(lk): lk for lk in (h.d.tokens.lock_of(n) for n in names)}
            try:
                with contextlib.ExitStack() as held:
                    for key in sorted(locks):
                        held.enter_context(locks[key])
                    _token_act(h, s, {'to': t['to']}, 'rename', t['name'], s['name'])
                moved.append(t['name'])
            except ApiError as e:
                left.append('%s (%s)' % (t['name'], e))
        h.store.add_event('realms', '%s moved %d token(s) under @%s in the realm %s%s' % (
            s['name'], len(moved), one['suffix'], one['name'],
            ('; left as they are: %s' % ', '.join(left[:20])) if left else ''), who=s['name'])
        return {'moved': moved, 'left': left, 'message': '%d token(s) moved under @%s%s' % (
            len(moved), one['suffix'], ('; %d left as they are - a token is there under the '
                                       'new name already' % len(left)) if left else '')}
    if act == 'try':
        name = Authenticator.full_name(str(b.get('user') or ''), str(b.get('realm') or ''))
        realm = h.store.realm_for(name)
        return {'name': name, 'realm': realm['name'] if realm else None}
    raise ApiError(400, 'no such thing to do to a realm')


@route('GET', '/api/directories')
def _dirs(h):
    s = h.me()
    dirs = h.store.directories()
    if s['role'] != 'fulladmin':
        for d in dirs:
            if d.get('bind_pw'):
                d['bind_pw'] = '••••••'
    return {'directories': dirs, 'may_change': s['role'] == 'fulladmin'}


@route('POST', '/api/directories')
def _dirs_do(h):
    b = h.body()
    act = b.get('action')
    if act in ('save', 'delete'):
        s = h.me('fulladmin')
        if act == 'save':
            one = b.get('directory') or {}
            ident = h.store.directory_save(one, s['name'])
            h.store.add_event('directories', '%s saved the directory %s' % (
                s['name'], one.get('name')), who=s['name'])
            h.d.changed('directories')
            return {'id': ident, 'message': 'the directory %s is saved' % one.get('name')}
        one = next((x for x in h.store.directories() if x['id'] == _int_id(b.get('id'))), None)
        if not one:
            raise ApiError(404, 'there is no such directory')  # 1.0.103
        h.store.directory_drop(one['id'])
        h.store.add_event('directories', '%s took away the directory %s' % (s['name'], one['name']),
                          'warn', who=s['name'])
        h.d.changed('directories')
        return {'message': 'the directory is gone'}
    if act == 'whois':
        # What the directory says about one person - an account here (asked of
        # the directory administrators sign in against) or the owner of a
        # token (asked of the directory of the realm the name falls in).
        h.me('tokenadmin')      # as its siblings (1.0.57), not every reader
        who = str(b.get('user') or '').strip()
        if not who:
            raise ApiError(400, 'who?')
        realm = None
        if b.get('kind') == 'account':
            dname = str(CONFIG.get('admin_directory') or '')
        else:
            realm = h.store.realm_for(who)
            dname = (realm or {}).get('directory') or ''
        ad = h.d.dirs.get(dname.lower()) if dname else None
        if not ad:
            raise ApiError(404, 'no directory answers for %s' % who)
        bare, how = admin_name_parts(who)
        if realm and realm.get('lookup') in ('upn', 'sam'):
            how = realm['lookup']
            bare = who if how == 'upn' else who.split('@', 1)[0]
        t = time.time()
        try:
            entry = ad.find_user(bare, how)
            groups = ad.groups_of(entry, True) if entry else []
        except LdapUnreachable as e:
            log('the directory could not be reached: %s' % e, 'warn')
            raise ApiError(503, 'the directory cannot be reached just now')
        # Each group with where it lives and what it gives here (1.0.19, as
        # isemon's person card): an administrators' role, or the way into a
        # realm - the ones that matter are drawn first, as cards.
        listed = []
        seen = set()
        realms = [r for r in h.store.realms() if r.get('enabled')]
        for dn, cn in sorted(groups, key=lambda g: str(g[1]).lower()):
            if dn.lower() in seen:
                continue
            seen.add(dn.lower())
            gives = []
            for key, role in ROLE_GROUP_KEYS:
                if group_matches(dn_list(CONFIG.get(key)), [(dn, cn)], ad):
                    gives.append({'role': role})
            for r in realms:
                if r.get('groups') and group_matches(r['groups'], [(dn, cn)], ad):
                    gives.append({'realm': r['name']})
            listed.append({'name': cn, 'dn': dn, 'gives': gives})
        acc = h.store.account(who) if b.get('kind') == 'account' else None
        tok = h.store.token(who) if b.get('kind') != 'account' else None
        return {'entry': entry, 'groups': sorted({cn for _, cn in groups}, key=str.lower),
                'group_list': listed, 'realm': (realm or {}).get('name') or '',
                'role': (acc or {}).get('role') or '', 'token': bool(tok),
                'token_state': (tok or {}).get('state') or '',
                'directory': ad.name, 'took_ms': int((time.time() - t) * 1000)}
    if act == 'people':
        # People in the directory of a realm whose names hold what is typed -
        # what the boxes offer while somebody types a name (1.0.19).
        h.me('tokenadmin')
        like = str(b.get('like') or '').strip()
        rname = str(b.get('realm') or '').strip().lower()
        realm = next((r for r in h.store.realms() if r['name'].lower() == rname
                      or str(r.get('suffix') or '').lower() == rname.lstrip('@')), None)
        if not realm:
            realm = h.store.realm_for(like) if '@' in like else None
        dname = str(b.get('directory') or '').strip()
        if dname:
            # One directory by its name, as the Look a name up box asks it:
            # the people as that directory names them.
            ad = h.d.dirs.get(dname.lower())
            if not ad:
                return {'people': []}
            try:
                found = ad.find_users(like.split('@', 1)[0], max(1, min(50, int(b.get('limit') or 20))))
            except LdapUnreachable as e:
                log('the directory could not be reached: %s' % e, 'warn')
                raise ApiError(503, 'the directory cannot be reached just now')
            return {'people': [{'name': (u['upn'] or u['sam'] or '').lower(),
                                'display': u['display'], 'mail': u['mail'],
                                'mobile': u.get('mobile') or '',
                                'disabled': u['disabled'], 'token': ''} for u in found]}
        if not realm or not realm.get('directory'):
            return {'people': [], 'realm': (realm or {}).get('name') or ''}
        ad = h.d.dirs.get(str(realm['directory']).lower())
        if not ad:
            return {'people': [], 'realm': realm['name']}
        try:
            found = ad.find_users(like.split('@', 1)[0], max(1, min(50, int(b.get('limit') or 20))))
        except LdapUnreachable as e:
            log('the directory could not be reached: %s' % e, 'warn')
            raise ApiError(503, 'the directory cannot be reached just now')
        suffix = str(realm.get('suffix') or '')
        out = []
        for u in found:
            if realm.get('lookup') == 'upn' and u['upn']:
                name = u['upn'].lower()
            elif suffix and suffix != '*':
                name = '%s@%s' % ((u['sam'] or '').lower(), suffix.lower())
            else:
                name = (u['upn'] or u['sam'] or '').lower()
            if realm.get('token_name') == 'bare':
                name = name.split('@', 1)[0]
            # A name this realm does not take is no use (1.0.103): a UPN with
            # another suffix (pkolar@corpnet.loc for the realm corpnet.cz) made
            # a token no realm answers for, and the VPN refused it.
            if name and realm.get('token_name') != 'bare':
                took = h.store.realm_for(name)
                if not took or took.get('id') != realm.get('id'):
                    continue
            tok = h.store.token(name) if name else None
            out.append({'name': name, 'display': u['display'], 'mail': u['mail'],
                        'mobile': u.get('mobile') or '',
                        'disabled': u['disabled'], 'token': (tok or {}).get('state') or ''})
        return {'people': out, 'realm': realm['name']}
    if act == 'ca':
        s = h.me('fulladmin')
        one = next((x for x in h.store.directories() if x['id'] == int(b.get('id') or 0)), None)
        if not one:
            raise ApiError(404, 'there is no such directory')
        pem = str(b.get('ca') or '').strip()
        mode = str(b.get('mode') or ('add' if pem else 'clear'))
        before = len(one.get('ca_list') or [])
        try:
            h.store.directory_set_ca(one['id'], pem, mode, str(b.get('fingerprint') or ''))
        except ValueError as e:
            raise ApiError(400, str(e))
        after = next((x for x in h.store.directories() if x['id'] == one['id']), {})
        n = len(after.get('ca_list') or [])
        words = {'add': 'added %d certificate(s) to' % max(0, n - before),
                 'set': 'replaced', 'drop': 'took a certificate out of',
                 'clear': 'took away'}.get(mode, 'changed')
        h.store.add_event('directories', '%s %s the certificate authorities of %s (%d kept)' % (
            s['name'], words, one['name'], n), who=s['name'])
        h.d.changed('directories')
        if mode == 'add' and n == before:
            msg = 'every one of those certificates is kept already'
        else:
            msg = '%s keeps %d certificate(s)' % (one['name'], n)
        return {'message': msg, 'ca_list': after.get('ca_list') or []}
    if act == 'try':
        who = h.me('fulladmin')['name']
        if not CONFIG.get('admin_directory'):
            raise ApiError(400, 'no directory signs administrators in yet: choose one in '
                                '"Sign administrators in against the directory" and save')
        # Counted and written down (1.0.139), as a radtest is: each try is a
        # directory password, and wrong ones lock the account there.
        user = str(b.get('user') or '')
        # A person's password tried 5 times in 15 minutes at most (1.0.149):
        # 80 in 5 was a guessing tool for anybody's directory password.
        key = h.throttle('radtest', 20, 15, name='%s>%s' % (who, user[:120]), ip_tries=100,
                         name_tries=RADTEST_NAME_TRIES)
        said = admin_ask_directory(h, user, str(b.get('password') or ''))
        if said is None:
            raise ApiError(404, 'the directory %s is not set up' % CONFIG.get('admin_directory'))
        said.pop('entry', None)
        if not said.get('ok'):
            h.failed(key)
        h.store.add_event('accounts', '%s tried the directory sign-in of %s: %s' % (
            who, user[:120], 'it would sign in' if said.get('ok') else 'refused'), who=who)
        return {'tried': said}
    h.me('tokenadmin')
    if act not in ('check', 'groups', 'lookup'):
        raise ApiError(400, 'no such thing to do with a directory')     # 1.0.103
    ad = h.d.dirs.get(str(b.get('name') or '').lower())
    if not ad:
        raise ApiError(404, 'there is no directory called %s (switched on)' % b.get('name'))
    if act == 'check':
        return {'check': ad.check()}
    if act == 'groups':
        groups = ad.find_groups(str(b.get('like') or ''), limit=5000)
        return {'groups': groups, 'capped': len(groups) >= 5000}
    if act == 'lookup':
        who = str(b.get('user') or '').strip()
        how = str(b.get('how') or ('upn' if '@' in who else 'sam'))
        t = time.time()
        entry = ad.find_user(who, how)
        groups = ad.groups_of(entry, True) if entry else []
        return {'entry': entry, 'groups': [cn for _, cn in groups],
                'took_ms': int((time.time() - t) * 1000)}
    raise ApiError(400, 'no such thing to do with a directory')


# ---- trying it --------------------------------------------------------------------------
@route('POST', '/api/radtest')
def _radtest(h):
    s = h.me('tokenadmin')
    b = h.body()
    node = str(b.get('node') or '').strip()
    if node and node != node_name():
        # Asked on another node of the cluster (1.0.45): through the
        # database both open, the password sealed with the key both have.
        # Counted here too (1.0.94): it tries a directory password as well.
        rkey = h.throttle('radtest', 20, 15, name='%s>%s' % (s['name'], str(b.get('user') or '')[:120]),
                      ip_tries=100, name_tries=RADTEST_NAME_TRIES)
        got = radtest_elsewhere(h.store, node, s['name'], h.client_ip(), b)
        if not (isinstance(got, dict) and got.get('result') in ('accept', 'challenge')):
            h.failed(rkey)
        return got
    server = str(b.get('server') or '127.0.0.1')
    if server not in ('127.0.0.1', '::1', 'localhost'):
        h.me('fulladmin')
    # Counted per administrator and person tried (1.0.57): each test tries a
    # directory password, and nothing else limited how many.
    rkey = h.throttle('radtest', 20, 15, name='%s>%s' % (s['name'], str(b.get('user') or '')[:120]),
                      ip_tries=100, name_tries=RADTEST_NAME_TRIES)
    got = radtest_do(h.store, h.d, s['name'], h.client_ip(), b)
    # The first step of a mail or SMS token is a challenge, not a wrong
    # password (1.0.103): counted as one here (not on the other node), it
    # locked every administrator of the address out after a few tests.
    if not (isinstance(got, dict) and got.get('result') in ('accept', 'challenge')):
        h.failed(rkey)
    return got


def radtest_do(store, daemon, by, src, b):
    """One test of a name and a password, on this node - asked on its pages,
    or by another node of the cluster for its pages."""
    user = str(b.get('user') or '')
    password = str(b.get('password') or '')
    how = str(b.get('how') or 'udp')
    # The answer to a second window (1.0.81): the code, with the State the
    # first answer carried.
    state = str(b.get('state') or '').strip().lower()
    if state.startswith('0x'):
        state = state[2:]
    if state and not re.fullmatch(r'[0-9a-f]{2,500}', state):
        raise ApiError(400, 'the State is hex')
    if how == 'direct':
        client = next((c for c in store.clients() if c['id'] == int(b.get('client') or 0)),
                      None)
        realm = (client or {}).get('realm') or str(b.get('realm') or '')
        if state:
            d = daemon.auth.answer(user, password, bytes.fromhex(state), realm, src=src,
                                   rid='', how='test')
        else:
            d = daemon.auth.decide(user, password, realm, src=src, rid='', how='test')
        store.radius_add({
            'ts': d.began, 'client': '%s (a test by %s)' % ((client or {}).get('name') or
                                                            'no client', by),
            'nas_ip': '', 'src': src, 'packet': 'Access-Request',
            'username': d.user or user, 'realm': d.realm, 'calling': '', 'called': '',
            'result': d.result, 'reason': d.reason, 'otp': d.otp, 'rid': '',
            'took_ms': int((time.time() - d.began) * 1000), 'attrs': '[]',
            'reply': json.dumps(d.reply), 'steps': json.dumps(d.steps), 'device': '',
            'tunnel': ''})
        return {'result': d.result, 'reason': d.reason, 'steps': d.steps, 'reply': d.reply,
                'user': d.user, 'realm': d.realm, 'how': 'direct', 'node': node_name(),
                'state': bytes(d.state).hex() if d.state else '', 'message': d.message}
    secret = str(b.get('secret') or '')
    server = str(b.get('server') or '127.0.0.1')
    if not secret and server not in ('127.0.0.1', '::1', 'localhost'):
        # The localhost client's secret only to this machine (1.0.149): sent
        # to a server anybody typed, it could be cracked from the packet there.
        raise ApiError(400, 'give the secret of that server - the one of this machine\'s own '
                       'client is only used for 127.0.0.1')
    if not secret:
        local = store.client_for('127.0.0.1')
        if not local:
            raise ApiError(400, 'there is no client for 127.0.0.1 to send the test from: add '
                           'one (the installer makes "localhost"), or give the secret')
        secret = local['_secret']
    port = int(b.get('port') or CONFIG.get('radius_auth_port') or 1812)
    code, words, took = radius_ask(server, port, secret, user, password,
                                   extra=[('State', '0x' + state)] if state else ())
    got_state = next((v for k, v in words if k == 'State'), '')
    row = store.db.row("SELECT id FROM radius_log WHERE username = ? ORDER BY id DESC "
                       "LIMIT 1", (Authenticator.full_name(
                           user, (store.client_for('127.0.0.1') or {}).get('realm', '')),))
    return {'result': {2: 'accept', 3: 'reject', 11: 'challenge'}.get(code, str(code)),
            'answer': words, 'took_ms': took, 'row': row['id'] if row else None,
            'how': 'udp', 'node': node_name(), 'cli': 'radtest %s %s %s %d <secret>' % (
                user, '******', server, port),
            'state': str(got_state)[2:] if str(got_state).startswith('0x') else '',
            'message': next((v for k, v in words if k == 'Reply-Message'), '')}


RADTEST_WAIT_S = 25


def radtest_elsewhere(store, node, by, src, b):
    alive = {n['name']: n for n in ha_nodes(store)}
    if node not in alive:
        raise ApiError(404, 'there is no node called %s' % node)
    if not alive[node].get('alive'):
        raise ApiError(409, '%s has not been heard from for %d s' % (
            node, int(alive[node].get('age') or 0)))
    ident = secrets.token_hex(8)
    ask = {'by': by, 'src': src, 'at': time.time(), 'from': node_name(),
           'user': str(b.get('user') or ''), 'how': str(b.get('how') or 'udp'),
           'client': b.get('client'), 'realm': str(b.get('realm') or ''),
           # The second window's answer goes with its State (1.0.84).
           'state': str(b.get('state') or '')[:600],
           'password': seal_secret(str(b.get('password') or ''), 'radtest:' + ident)}
    # Written straight into the other node's database (1.0.87), not left to
    # replication: one direction of it stopped, or behind, and the test was
    # never seen there. Replication only when that database cannot be
    # reached from here.
    k_ask = 'radtest:ask:%s:%s' % (node, ident)
    k_ans, k_took = 'radtest:answer:' + ident, 'radtest:taken:' + ident
    far, far_err = None, ''
    if CONFIG.get('ha_mode') == 'replicated':
        try:
            far = ha_peer_db()
        except Exception as e:                          # noqa: BLE001
            far_err = str(e).split('\n')[0][:200]
    where = far or store.db
    # Two tests waiting on the other node at most (1.0.101): each holds a
    # worker of the pages while it waits.
    if not RADTEST_PEER.acquire(False):
        if far:
            far.close()
        raise ApiError(429, 'tests on the other node are running already - try again in a '
                            'moment')
    try:
        where.run('INSERT INTO meta (k, v) VALUES (?, ?)', (k_ask, json.dumps(ask)))
    except Exception:
        RADTEST_PEER.release()
        if far:
            far.close()
        raise
    t0 = time.time()

    def look(k):
        got = where.value('SELECT v FROM meta WHERE k = ?', (k,))
        return got if got is not None or where is store.db else store.get_meta(k)
    try:
        while time.time() - t0 < RADTEST_WAIT_S:
            got = look(k_ans)
            if got:
                out = json.loads(got)
                if out.get('error'):
                    raise ApiError(int(out.get('status') or 400), out['error'])
                return out
            time.sleep(0.3)
        raise ApiError(504, radtest_why_not(store, node, where, far_err, look(k_took), t0,
                                            look(k_ask) is not None))
    finally:
        RADTEST_PEER.release()
        for db in ((far, store.db) if far else (store.db,)):
            try:
                db.run('DELETE FROM meta WHERE k IN (?, ?, ?)', (k_ask, k_ans, k_took))
            except Exception:                           # noqa: BLE001
                pass
        if far:
            try:
                far.close()
            except Exception:                           # noqa: BLE001
                pass


RADTEST_PEER = threading.BoundedSemaphore(2)


def radtest_why_not(store, node, where, far_err, took, t0, still_there):
    """What the page says when the other node did not answer (1.0.87)."""
    beat = next((n for n in ha_nodes(store) if n['name'] == node), {})
    ver = str(beat.get('version') or '')
    if took:
        try:
            at = float(took) - t0
        except ValueError:
            at = 0
        return ('%s took the test %.1f s after it was asked, but did not finish it within %d s: '
                'the directory or the RADIUS port there answer slowly or not at all - its Log '
                'and Events say more' % (node, max(at, 0), RADTEST_WAIT_S))
    if where is not store.db:
        if still_there:
            return ('%s has the test in its database but did not take it within %d s: is otp '
                    'running there%s? (systemctl status otp, journalctl -u otp)' % (
                        node, RADTEST_WAIT_S, ' - it is %s, this is %s' % (ver, __version__)
                        if ver and ver != __version__ else ''))
        return '%s took the test but its answer did not come back within %d s' % (
            node, RADTEST_WAIT_S)
    rep = {}
    try:
        rep = ha_repl_state(store)
    except Exception:                                   # noqa: BLE001
        pass
    why = []
    if far_err:
        why.append('its database could not be reached from here (%s)' % far_err)
    if rep.get('mode') == 'replicated' and not rep.get('healthy'):
        why.append('the replication between the nodes is not running as it should - see '
                   'Settings → High availability')
    return '%s did not answer the test within %d s%s' % (
        node, RADTEST_WAIT_S, ': ' + '; '.join(why) if why else '')


def radtest_serve(daemon):
    """Tests the other node's pages asked of this one (1.0.45)."""
    store = daemon.store
    me = node_name()
    # The first characters of the key compared as they are (1.0.89). The
    # range k >= 'radtest:ask:otp2:' AND k < 'radtest:ask:otp2;' of 1.0.57
    # was empty in a database with a language's collation (en_US.UTF-8,
    # cs_CZ.UTF-8 - what PostgreSQL takes from the system), which leaves
    # ':' and ';' out of the first comparison: the other node never saw a
    # test asked of it. substr compares the characters, in both engines.
    lo = 'radtest:ask:%s:' % me
    rows = [r for r in store.db.rows('SELECT k, v FROM meta WHERE substr(k, 1, %d) = ?'
                                     % len(lo), (lo,))
            if r['k'].startswith(lo)]
    for r in rows:
        ident = r['k'].rsplit(':', 1)[1]
        # Taken once: the row out first, so a second look does not run it again.
        store.db.run('DELETE FROM meta WHERE k = ?', (r['k'],))
        try:
            # Seen and taken (1.0.87): the asking node says so if it waits too long.
            store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)',
                         ('radtest:taken:' + ident, repr(time.time())))
        except Exception:                               # noqa: BLE001
            pass
        try:
            ask = json.loads(r['v'] or '{}')
            if time.time() - float(ask.get('at') or 0) > RADTEST_WAIT_S:
                continue
            ask['password'] = unseal_secret(ask.get('password') or '', 'radtest:' + ident)
            out = radtest_do(store, daemon, '%s on %s' % (ask.get('by'), ask.get('from')),
                             ask.get('src') or '', ask)
        except ApiError as e:
            out = {'error': str(e), 'status': e.status}
        except Exception as e:                          # noqa: BLE001
            out = {'error': 'the test could not be made on %s: %s' % (me, e), 'status': 500}
        try:
            store.db.run('INSERT INTO meta (k, v) VALUES (?, ?)',
                         ('radtest:answer:' + ident, json.dumps(out, default=str)))
        except Exception as e:                          # noqa: BLE001
            log('the answer to a test asked by the other node could not be written: %s' % e,
                'warn')


# ---- settings, accounts, events, the database --------------------------------------------
@route('GET', '/api/settings')
def _settings(h):
    s = h.me()
    full = s['role'] == 'fulladmin'
    return {'settings': h.d.settings_state(full), 'may_change': full, 'panes': PANES,
            'only_when': ONLY_WHEN, 'config_file': str(CONFIG_FILE),
            'database': h.store.db.where(), 'directories': [d['name'] for d in
                                                            h.store.directories()],
            'realms': [r['suffix'] for r in h.store.realms()
                       if r.get('suffix') and r['suffix'] != '*'],
            'isemon': h.d.shipper.state() if h.d.shipper else {},
            'node': node_name(), 'nodes': h.d.cluster_nodes(),
            'cluster': bool(CONFIG.get('ha_mode')) or len(h.d.cluster_nodes()) > 1}


@route('POST', '/api/settings')
def _settings_do(h):
    s = h.me('fulladmin')
    b = h.body()
    asked = b.get('settings') or {}
    moved = [k for k in asked if k in ('db_engine', 'db_host', 'db_port', 'db_name', 'db_user',
                                         'db_password') and
             not (k == 'db_password' and is_masked(asked[k])) and
             str(asked[k]) != str(CONFIG.get(k) if CONFIG.get(k) is not None else '')]
    ha = [k for k in asked if k in ('ha_mode', 'ha_slot', 'ha_peer', 'ha_peer_port', 'ha_address',
                                    'ha_tls', 'ha_tls_ca')
          and str(asked[k]) != str(CONFIG.get(k) if CONFIG.get(k) is not None else '')]
    if ha:
        # The cluster is made and taken apart by its own steps (1.0.57).
        raise ApiError(400, 'the cluster is changed on Settings - High availability or with '
                            'otp --ha-setup / --ha-join / --ha-standalone (%s not saved)'
                       % ', '.join(ha))
    if moved:
        # Saved here, the next restart opened a database nothing had been
        # carried into (1.0.37). The way to another one is the four steps.
        raise ApiError(400, 'the database is changed on Settings - The database with its own '
                            'steps: Try it, Set it up, Carry everything across, Start using it '
                            '(%s not saved)' % ', '.join(moved))
    was_2fa = bool(CONFIG.get('admin_2fa'))
    try:
        got = h.d.save_settings(asked, by=s['name'], node=b.get('node'),
                                drawn_by=b.get('drawn_by'))
        if not was_2fa and CONFIG.get('admin_2fa'):
            # The second step for those signed in already too (1.0.149): their
            # sessions, opened with the password alone, stayed whole for hours.
            # The one saving it stays - it is how it was switched on.
            gone = h.store.db.run('DELETE FROM sessions WHERE kind = ? AND id <> ?',
                                  ('admin', int(s.get('id') or 0)))
            if gone:
                h.store.add_event('accounts', 'the second step was switched on: %d other '
                                  'sign-in(s) to the pages ended' % gone, 'warn', who=s['name'])
        return got
    except NodeMoved as e:
        raise ApiError(409, str(e))
    except BadSetting as e:
        raise ApiError(400, str(e))


@route('POST', '/api/isemon')
def _isemon_do(h):
    s = h.me('fulladmin')
    if not h.d.shipper:
        raise ApiError(503, 'nothing is being sent from this process')
    h.d.shipper.put('otp', 'daemon', 'a test from otp %s, sent by %s - isemon reads nothing '
                    'from this line' % (__version__, s['name']))
    h.d.shipper.flush(3)
    time.sleep(0.3)
    return {'isemon': h.d.shipper.state()}


@route('GET', '/api/users')
def _users(h):
    s = h.me()
    mfa = mfa_all(h.store)
    users = h.store.accounts()
    for u in users:
        u['mfa'] = mfa.get(str(u.get('name') or '').lower())
    return {'users': users, 'may_change': s['role'] == 'fulladmin',
            'mfa_on': bool(CONFIG.get('admin_2fa')),
            'roles': [{'role': r, 'words': ROLE_WORDS[r]} for r in ROLES_ALL]}


@route('POST', '/api/users')
def _users_do(h):
    s = h.me('fulladmin')
    b = h.body()
    act, name = b.get('action'), str(b.get('name') or '').strip()
    who = s['name']
    if act == 'add':
        h.store.add_account(name, b.get('role') or 'readonly', b.get('password'),
                            note=b.get('note') or '', must_change=b.get('must_change', 1))
        h.store.add_event('accounts', '%s made the account %s (%s)' % (who, name,
                                                                         b.get('role')), who=who)
        return {'message': 'the account %s is made' % name}
    acc = h.store.account(name)
    if not name:
        raise ApiError(400, 'which account?')                          # 1.0.103
    if not acc:
        raise ApiError(404, 'there is no account called %s' % name)
    if act in ('delete', 'disable') or (act == 'role' and b.get('role') != 'fulladmin'):
        if acc['role'] == 'fulladmin' and not h.store.fulladmins_left(but=name):
            raise ApiError(400, 'that is the last full administrator who can sign in')
    if act == 'delete':
        h.store.drop_account(name)
        h.store.add_event('accounts', '%s removed the account %s' % (who, name), 'warn', who=who)
        return {'message': 'the account %s is gone' % name}
    if act == 'role':
        h.store.set_account(name, role=b.get('role'))
        h.store.add_event('accounts', '%s made %s %s' % (who, name,
                                                         ROLE_WORDS.get(b.get('role'))), who=who)
        return {'message': 'saved'}
    if act == 'mfa_reset':
        had = mfa_reset(h.store, acc['name'], who)
        h.store.db.run('DELETE FROM sessions WHERE kind = ? AND LOWER(name) = ?',
                       ('admin', acc['name'].lower()))
        return {'message': ('the second step of %s is reset: they set it up again at the next '
                            'sign-in; their sign-ins are ended' if had else
                            '%s had no second step set up') % acc['name']}
    if act == 'reset_cols':
        h.store.put_user_cols(acc['name'], {})
        h.store.add_event('accounts', '%s put the columns of every table back as they come '
                          'for %s' % (who, acc['name']), who=who)
        return {'message': 'the columns of %s are back as they come; they see it at their '
                           'next page load' % acc['name']}
    if act == 'password':
        h.store.set_account(name, password=b.get('password'), must_change=int(bool(
            b.get('must_change', 1))))
        h.store.db.run('DELETE FROM sessions WHERE kind = ? AND LOWER(name) = ?',
                       ('admin', name.lower()))
        h.store.add_event('accounts', '%s set a new password for %s; their sign-ins are ended'
                          % (who, name), 'warn', who=who)
        return {'message': 'the password is set'}
    if act in ('disable', 'enable'):
        h.store.set_account(name, disabled=1 if act == 'disable' else 0)
        if act == 'disable':
            h.store.db.run('DELETE FROM sessions WHERE kind = ? AND LOWER(name) = ?',
                           ('admin', name.lower()))
        h.store.add_event('accounts', '%s switched %s %s' % (who, name, 'off' if
                                                            act == 'disable' else 'on'), who=who)
        return {'message': 'saved'}
    raise ApiError(400, 'no such thing to do to an account')


@route('GET', '/api/sessions')
def _sessions(h):
    h.me('fulladmin')
    # The list is of who could still ask: the ones that sat too long are
    # tidied first (1.0.15), not shown as signed in for hours.
    h.store.sessions_tidy(int(CONFIG.get('session_idle_min') or 120) * 60,
                          int(CONFIG.get('portal_session_min') or 15) * 60)
    return {'sessions': h.store.sessions()}


@route('POST', '/api/sessions')
def _sessions_do(h):
    s = h.me('fulladmin')
    ident = int(h.body().get('id') or 0)
    row = h.store.db.row('SELECT kind, name, ip FROM sessions WHERE id = ?', (ident,))
    if not row:
        # Gone already (1.0.61): not written down as "ended the sign-in of ?".
        raise ApiError(404, 'that sign-in has ended already')
    h.store.session_drop(ident)
    h.store.add_event('sign-ins', '%s ended the sign-in of %s%s' % (
        s['name'], (row or {}).get('name') or '?', (' from %s' % row['ip']) if row and
        row.get('ip') else ''), 'warn', who=s['name'])
    return {'message': 'ended'}


def time_span(h, lq):
    """The time picker's window (1.0.53), `from` and `to` as seconds since
    1970, added to what the search box asked."""
    since, until = h.num('from', 0, 0, 10 ** 11), h.num('to', 0, 0, 10 ** 11)
    parts, args = ([lq.sql] if lq.sql else []), list(lq.args or [])
    if since:
        parts.append('ts >= ?')
        args.append(since)
    if until:
        parts.append('ts < ?')
        args.append(until)
    lq.sql, lq.args = ' AND '.join('(%s)' % x for x in parts), args
    return since, until


@route('GET', '/api/events')
def _events(h):
    h.me()
    lq, bad = list_query('events', h.arg('q'))
    if bad:
        return {'rows': [], 'total': 0, 'q_error': bad, 'kinds': h.reader.event_kinds()}
    time_span(h, lq)
    rows, total = h.reader.events(h.num('limit', 100, 1, 1000), h.num('offset', 0),
                                 lq.words, h.arg('kind'), extra=(lq.sql, lq.args))
    return {'rows': rows, 'total': total, 'kinds': h.reader.event_kinds()}


@route('GET', '/api/enrolment')
def _enrolment(h):
    h.me()
    since = h.num('since', 0, 0, 10 ** 9)
    lq, bad = list_query('enrolment', h.arg('q'))
    if bad:
        return {'rows': [], 'total': 0, 'q_error': bad, 'counts': {}, 'on': True}
    t_from, t_to = time_span(h, lq)
    rows, total = h.store.enrolment(h.num('limit', 100, 1, 1000), h.num('offset', 0),
                                    lq.words, h.arg('step'), since, extra=(lq.sql, lq.args))
    return {'rows': rows, 'total': total,
            'counts': h.store.enrolment_counts(since, t_from, t_to),
            'on': bool(CONFIG.get('portal'))}


@route('GET', '/api/mail')
def _mail(h):
    h.me()
    return {'mode': CONFIG.get('mail_mode') or 'off', 'ca_list': describe_certificates(
        mail_ca_pem(h.store)), 'from': CONFIG.get('mail_from') or '',
        'sms_ca_list': describe_certificates(sms_ca_pem(h.store)),
        'lang': CONFIG.get('mail_lang') or 'cs', 'codes': bool(CONFIG.get('mail_codes'))}


@route('POST', '/api/mail')
def _mail_do(h):
    b = h.body()
    act = str(b.get('action') or '')
    if act == 'test':
        s = h.me('fulladmin')
        to = str(b.get('to') or '').strip()
        if not re.match(r'^[^@\s<>]+@[^@\s<>]+\.[^@\s<>]+\Z', to):
            raise ApiError(400, 'a mail address to send it to')
        began = time.time()
        try:
            lang = str(b.get('lang') or 'cs')
            if b.get('kind') == 'token':
                # A token's mail as it would go, with a key made up for it
                # (1.0.27): whether that gets through - pictures, codes and
                # all - is not the same question as whether a line of text
                # does. The key opens nothing.
                fake = base64.b32encode(secrets.token_bytes(20)).decode().rstrip('=')
                pic = h.d.tokens.picture('novak@example.cz', fake)
                msg = token_mail(to, 'novak@example.cz', pic,
                                 codes=['%08d' % secrets.randbelow(10 ** 8) for _ in range(5)],
                                 lang=lang if lang in MAIL_WORDS else 'cs',
                                 display='Jan Novák' if lang == 'cs' else 'John Doe',
                                 by=s['name'])
            elif b.get('kind') in ('code', 'verify'):
                # The mail of a sign-in code, or of checking an address on
                # the enrolment pages (1.0.78) - with a code that opens nothing.
                msg = code_message('mail', to, code_new(),
                                   'signin' if b.get('kind') == 'code' else 'verify',
                                   lang=lang if lang in CODE_TEXTS else None,
                                   name='novak@example.cz',
                                   display='Jan Novák' if lang == 'cs' else 'John Doe')
            else:
                msg = test_mail(to, lang)
            # Through the outgoing mail, as codes go (1.0.103): tried now, and
            # if the other side does not take it yet (greylisting) tried again
            # by itself - or straight, once, with every step said here.
            queued = str(b.get('via') or '') == 'queue'
            if queued:
                steps = mail_deliver(h.store, msg, [to], kind='test', by=s['name'],
                                     purpose='test')
            else:
                steps = mail_send(h.store, msg, [to])
        except MailError as e:
            h.store.add_event('mail', 'a test mail to %s failed: %s' % (to, e), 'warn',
                              who=s['name'])
            return {'sent': False, 'said': str(e), 'steps': e.steps,
                    'queued': getattr(e, 'queued', None) if str(b.get('via') or '') == 'queue'
                    else None,
                    'took_ms': int((time.time() - began) * 1000)}
        h.store.add_event('mail', '%s sent a test mail%s to %s%s' % (
            s['name'], {'token': ' shaped as a token\'s', 'code': ' shaped as a sign-in code\'s',
                        'verify': ' shaped as an address check\'s'}.get(b.get('kind'), ''), to,
            mail_reply_words(steps)), who=s['name'])
        return {'sent': True, 'said': 'sent to %s' % to, 'steps': steps,
                'queued': 'sent' if str(b.get('via') or '') == 'queue' else None,
                'took_ms': int((time.time() - began) * 1000)}
    if act == 'sms_test':
        # An SMS the way a sign-in code goes (1.0.76), with a code that opens
        # nothing, and what the gateway said.
        s = h.me('fulladmin')
        try:
            to = phone_checked(b.get('to'))
        except ValueError as e:
            raise ApiError(400, str(e))
        began = time.time()
        try:
            said = sms_send(to, code_message('sms', to, code_new(), 'verify'))
        except SmsError as e:
            h.store.add_event('settings', 'a test SMS to %s failed: %s' % (to, e), 'warn',
                              who=s['name'])
            return {'sent': False, 'said': str(e), 'took_ms': int((time.time() - began) * 1000)}
        h.store.add_event('settings', '%s sent a test SMS to %s' % (s['name'], to), who=s['name'])
        return {'sent': True, 'said': said, 'to': to,
                'took_ms': int((time.time() - began) * 1000)}
    if act == 'sms_ca':
        # The Teltonika gateway's certificates (1.0.89).
        s = h.me('fulladmin')
        mode = str(b.get('mode') or 'add')
        try:
            got = sms_ca_set(h.store, b.get('ca'), mode, str(b.get('fingerprint') or ''))
        except ValueError as e:
            raise ApiError(400, str(e))
        h.store.add_event('settings', '%s %s the certificates of the SMS gateway'
                          % (s['name'], {'add': 'added to', 'drop': 'took one out of'}.get(
                              mode, 'emptied')), who=s['name'])
        return {'ca_list': got, 'message': 'the SMS gateway is checked against %d certificate(s)'
                % len(got)}
    if act == 'tel_test':
        # The Teltonika tried without sending anything (1.0.113).
        s = h.me('fulladmin')
        began = time.time()
        got = tel_test()
        got['took_ms'] = int((time.time() - began) * 1000)
        bad = [x for x in got['steps'] if not x['ok']]
        h.store.add_event('settings', '%s tried the SMS gateway %s: %s' % (
            s['name'], got.get('host') or '?', 'it answers' if got['ok'] else
            (bad[0]['said'] if bad else 'it did not answer')), 'info' if got['ok'] else 'warn',
            who=s['name'])
        return got
    if act == 'sms_ca_fetch':
        # What the gateway shows, for the administrator to look at and trust.
        h.me('fulladmin')
        try:
            pem = tel_peer_chain()
        except SmsError as e:
            raise ApiError(502, str(e))
        return {'pem': pem, 'certs': describe_certificates(pem)}
    if act == 'ca':
        s = h.me('fulladmin')
        mode = str(b.get('mode') or 'add')
        try:
            got = mail_ca_set(h.store, b.get('ca'), mode, str(b.get('fingerprint') or ''))
        except ValueError as e:
            raise ApiError(400, str(e))
        h.store.add_event('settings', '%s %s the certificate authorities of the mail server'
                          % (s['name'], {'add': 'added to', 'drop': 'took one out of'}.get(
                              mode, 'emptied')), who=s['name'])
        return {'ca_list': got, 'message': 'the mail server keeps %d certificate(s)' % len(got)}
    if act == 'mail_of':
        # A person's mail address out of the directory of their realm, for
        # the box beside "Make a token" (1.0.20).
        h.me('tokenadmin')
        who = str(b.get('user') or '').strip()
        realm = h.store.realm_for(who)
        ad = h.d.dirs.get(str((realm or {}).get('directory') or '').lower())
        if not ad:
            return {'mail': '', 'display': ''}
        how = realm.get('lookup') if realm.get('lookup') in ('upn', 'sam') else (
            'upn' if '@' in who else 'sam')
        try:
            entry = ad.find_user(who if how == 'upn' else who.split('@', 1)[0], how)
        except Exception:
            entry = None
        return {'mail': (entry or {}).get('mail') or '', 'display': (entry or {}).get('display')
                or '', 'mobile': (entry or {}).get('mobile') or ''}
    raise ApiError(400, 'no such thing to do')


